(function(){if(!window.__hermes_register_book)return;window.__hermes_register_book("pausanias-4-e", [{"sp": "HDR", "t": "Ἑλλάδος Περιήγησις"}, {"sp": "HDR", "t": "Βιβλίον Ζʹ — Ἀχαϊκά", "st": "7"}, {"sp": "N", "t": "ἡ δὲ τῆς Ἠλείας μέση καὶ Σικυωνίας, καθήκουσα μὲν ἐπὶ τὴν πρὸς ἕω θάλασσαν, Ἀχαΐαν δὲ ὄνομα τὸ ἐφ’ ἡμῶν ἔχουσα ἀπὸ τῶν ἐνοικούντων, αὐτή τε Αἰγιαλὸς τὸ ἀρχαῖον καὶ οἱ νεμόμενοι τὴν γῆν ἐκαλοῦντο Αἰγιαλεῖς, λόγῳ μὲν τῷ Σικυωνίων ἀπὸ Αἰγιαλέως βασιλεύσαντος ἐν τῇ νῦν Σικυωνίᾳ, εἰσὶ δὲ οἵ φασιν ἀπὸ τῆς χώρας, εἶναι γὰρ τὰ πολλὰ αὐτῆς αἰγιαλόν.", "st": "7.1"}, {"sp": "N", "t": "χρόνῳ δὲ ὕστερον ἀποθανόντος Ἕλληνος Ξοῦθον οἱ λοιποὶ τοῦ Ἕλληνος παῖδες διώκουσιν ἐκ Θεσσαλίας, ἐπενεγκόντες αἰτίαν ὡς ἰδίᾳ χρήματα ὑφελόμενος ἔχοι τῶν πατρῴων· ὁ δὲ ἐς Ἀθήνας φυγὼν θυγατέρα Ἐρεχθέως ἠξιώθη λαβεῖν καὶ παῖδας Ἀχαιὸν καὶ Ἴωνα ἔσχεν ἐξ αὐτῆς. ἀποθανόντος δὲ Ἐρεχθέως τοῖς παισὶν αὐτοῦ δικαστὴς Ξοῦθος ἐγένετο ὑπὲρ τῆς ἀρχῆς, καὶ—ἔγνω γὰρ τὸν πρεσβύτατον Κέκροπα βασιλέα εἶναι—οἱ λοιποὶ τοῦ Ἐρεχθέως παῖδες ἐξελαύνουσιν ἐκ τῆς χώρας αὐτόν·", "st": "7.1"}, {"sp": "N", "t": "ἀφικομένῳ δὲ ἐς τὸν Αἰγιαλὸν καὶ οἰκήσαντι αὐτῷ μὲν ἐγένετο ἐνταῦθα ἡ τελευτή, τῶν δέ οἱ παίδων Ἀχαιὸς μὲν ἐκ τοῦ Αἰγιαλοῦ παραλαβὼν καὶ ἐξ Ἀθηνῶν ἐπικούρους κατῆλθεν ἐς Θεσσαλίαν καὶ ἔσχε τὴν πατρῴαν ἀρχήν, Ἴωνι δὲ ἐπὶ τοὺς Αἰγιαλεῖς στρατιὰν καὶ ἐπὶ Σελινοῦντα τὸν βασιλέα αὐτῶν ἀθροίζοντι ἀγγέλους ἔπεμπεν ὁ Σελινοῦς, τὴν θυγατέρα Ἑλίκην, ἣ μόνη οἱ παῖς ἦν, γυναῖκα αὐτῷ διδοὺς καὶ αὐτὸν Ἴωνα ἐπὶ τῇ ἀρχῇ παῖδα ποιούμενος.", "st": "7.1"}, {"sp": "N", "t": "καί πως ταῦτα τῷ Ἴωνι ἐγένετο οὐκ ἄπο γνώμης, καὶ τῶν Αἰγιαλέων τὴν ἀρχὴν Ἴων ἔσχεν ἀποθανόντος Σελινοῦντος, καὶ Ἑλίκην τε ἀπὸ τῆς γυναικὸς ᾤκισεν ἐν τῷ Αἰγιαλῷ πόλιν καὶ τοὺς ἀνθρώπους ἐκάλεσεν Ἴωνας ἀφ’ αὑτοῦ. τοῦτο οὐ μεταβολὴ τοῦ ὀνόματος, προσθήκη δέ σφισιν ἐγένετο· Αἰγιαλεῖς γὰρ ἐκαλοῦντο Ἴωνες. τῇ χώρᾳ δὲ ἔτι καὶ μᾶλλον διέμεινεν ὄνομα τὸ ἐξ ἀρχῆς· Ὁμήρῳ γοῦν ἐν καταλόγῳ τῶν μετὰ Ἀγαμέμνονος ἐξήρκεσε τὸ ἀρχαῖον δηλῶσαι τῆς γῆς ὄνομα·<br>Αἰγιαλόν τ’ ἀνὰ πάντα καὶ ἀμφ’ Ἑλίκην εὐρεῖαν.", "st": "7.1"}, {"sp": "N", "t": "τότε δὲ ἐπὶ τῆς Ἴωνος βασιλείας πολεμησάντων Ἀθηναίοις Ἐλευσινίων καὶ Ἀθηναίων Ἴωνα ἐπαγαγομένων ἐπὶ ἡγεμονίᾳ τοῦ πολέμου, τὸν μὲν ἐν τῇ Ἀττικῇ τὸ χρεὼν ἐπιλαμβάνει, καὶ Ἴωνος ἐν τῷ δήμῳ μνῆμα τῷ Ποταμίων ἐστίν· οἱ δὲ ἀπόγονοι τοῦ Ἴωνος τὸ Ἰώνων ἔσχον κράτος, ἐς ὃ ὑπ’ Ἀχαιῶν ἐξέπεσον καὶ αὐτοὶ καὶ ὁ δῆμος. τοῖς δὲ Ἀχαιοῖς τηνικαῦτα ὑπῆρξε καὶ αὐτοῖς ἐκ Λακεδαίμονος καὶ Ἄργους ὑπὸ Δωριέων ἐξεληλάσθαι·", "st": "7.1"}, {"sp": "N", "t": "τὰ δὲ ἐς Ἴωνας καὶ Ἀχαιούς, ὁπόσα ἐπράχθη σφίσιν ἐπ’ ἀλλήλους, ἐπέξεισιν αὐτίκα ὁ λόγος μοι προδιηγησαμένῳ καθ’ ἥντινα αἰτίαν τοῖς Λακεδαίμονα οἰκοῦσι καὶ Ἄργος πρὸ τῆς τῶν Δωριέων καθόδου μόνοις Πελοποννησίων ὑπῆρξεν Ἀχαιοῖς καλεῖσθαι. Ἄρχανδρος Ἀχαιοῦ καὶ Ἀρχιτέλης ἐς Ἄργος ἀφίκοντο ἐκ τῆς Φθιώτιδος, ἐλθόντες δὲ ἐγένοντο Δαναοῦ γαμβροί, καὶ Αὐτομάτην μὲν Ἀρχιτέλης, Σκαιὰν δὲ ἔλαβεν Ἄρχανδρος. δηλοῦσι δὲ ἐν Ἄργει καταμείναντες οὐχ ἥκιστα ἐν τῷδε· Μετανάστην γὰρ τῷ παιδὶ ὄνομα ἔθετο Ἄρχανδρος.", "st": "7.1"}, {"sp": "N", "t": "δυνηθέντων δὲ ἔν τε Ἄργει καὶ Λακεδαίμονι τῶν Ἀχαιοῦ παίδων, τοὺς ἀνθρώπους τοὺς ἐνταῦθα ἐξενίκησεν Ἀχαιοὺς κληθῆναι· τοῦτο μέν σφισιν ὄνομα ἦν ἐν κοινῷ, Δαναοὶ δὲ Ἀργείοις ἰδίᾳ. τότε δὲ ὑπὸ Δωριέων ἐκπεπτωκότες ἔκ τε Ἄργους καὶ ἐκ Λακεδαίμονος ἐπεκηρυκεύοντο Ἴωσιν αὐτοί τε καὶ ὁ βασιλεὺς Τισαμενὸς ὁ Ὀρέστου γενέσθαι σύνοικοί σφισιν ἄνευ πολέμου· τῶν δὲ Ἰώνων τοὺς βασιλέας ὑπῄει δέος, μὴ Ἀχαιῶν ἀναμιχθέντων αὐτοῖς Τισαμενὸν ἐν κοινῷ βασιλέα ἕλωνται κατά τε ἀνδραγαθίαν καὶ γένους δόξαν.", "st": "7.1"}, {"sp": "N", "t": "Ἰώνων δὲ οὐ προσεμένων τοὺς Ἀχαιῶν λόγους ἀλλὰ ἐπεξελθόντων σὺν ὅπλοις, Τισαμενὸς μὲν ἔπεσεν ἐν τῇ μάχῃ, Ἴωνας δὲ Ἀχαιοὶ κρατήσαντες ἐπολιόρκουν καταπεφευγότας ἐς Ἑλίκην καὶ ὕστερον ἀφιᾶσιν ἀπελθεῖν ὑποσπόνδους. Τισαμενοῦ δὲ τὸν νεκρὸν Ἀχαιῶν ἐν Ἑλίκῃ θαψάντων, ὕστερον χρόνῳ Λακεδαιμόνιοι τοῦ ἐν Δελφοῖς σφισιν ἀνειπόντος χρηστηρίου κομίζουσι τὰ ὀστᾶ ἐς Σπάρτην, καὶ ἦν καὶ ἐς ἐμὲ ἔτι αὐτῷ τάφος, ἔνθα τὰ δεῖπνα Λακεδαιμονίοις ἐστὶ τὰ Φειδίτια καλούμενα.", "st": "7.1"}, {"sp": "N", "t": "Ἴωνας δὲ ἀφικομένους ἐς τὴν Ἀττικὴν Ἀθηναῖοι καὶ ὁ βασιλεὺς αὐτῶν Μέλανθος Ἀνδροπόμπου συνοίκους ἐξεδέξαντο Ἴωνός τε δὴ ἕνεκα καὶ ἔργων ἃ ἔπραξε πολεμαρχῶν Ἀθηναίοις· λέγεται δὲ ὡς ἐν ὑπονοίᾳ ποιούμενοι τοὺς Δωριέας οἱ Ἀθηναῖοι, μὴ οὐδὲ αὐτῶν ἐθέλωσιν ἀπέχεσθαι, ἰσχύος μᾶλλον οἰκείας ἕνεκα ἢ εὐνοίᾳ τῇ ἐς τοὺς Ἴωνας συνοίκους σφᾶς ἐδέξαντο.", "st": "7.1"}, {"sp": "N", "t": "ἔτεσι δὲ οὐ πολλοῖς ὕστερον Μέδων καὶ Νειλεὺς πρεσβύτατοι τῶν Κόδρου παίδων ἐστασίασαν ὑπὲρ τῆς ἀρχῆς, καὶ οὐκ ἔφασκεν ὁ Νειλεὺς ἀνέξεσθαι βασιλευόμενος ὑπὸ τοῦ Μέδοντος, ὅτι ὁ Μέδων τὸν ἕτερον ἦν τῶν ποδῶν χωλός· δόξαν δέ σφισιν ἀνενεγκεῖν ἐς τὸ χρηστήριον τὸ ἐν Δελφοῖς, δίδωσι Μέδοντι ἡ Πυθία βασιλείαν τὴν Ἀθηναίων. οὕτω δὴ ὁ Νειλεὺς καὶ οἱ λοιποὶ τῶν Κόδρου παίδων ἐς ἀποικίαν ἀπεστάλησαν, ἀγαγόντες μὲν καὶ αὐτῶν Ἀθηναίων τὸν βουλόμενον, τὸ δὲ πλεῖστόν σφισιν ἦσαν τοῦ στρατεύματος οἱ Ἴωνες.", "st": "7.2"}, {"sp": "N", "t": "ἐκ δὲ τῆς Ἑλλάδος τρίτος δὴ οὗτος στόλος ὑπὸ βασιλεῦσιν ἀλλοίοις ὄχλοις τε ἀλλοίοις ἐστάλησαν. τὰ μὲν γὰρ ἀρχαιότατα Ἰόλαος Θηβαῖος, ἀδελφιδοῦς ὁ Ἡρακλέους, Ἀθηναίοις ἐς Σαρδὼ καὶ Θεσπιεῦσιν ἡγήσατο· γενεᾷ δὲ μιᾷ πρότερον ἢ ἐξέπλευσαν ἐξ Ἀθηνῶν Ἴωνες, Λακεδαιμονίους τε καὶ Μινύας τοὺς ἐκβληθέντας ὑπὸ Πελασγῶν ἐκ Λήμνου Θήρας ὁ Αὐτεσίωνος Θηβαῖος ἤγαγεν ἐς τὴν νῆσον τὴν νῦν μὲν ἀπὸ τοῦ Θήρα τούτου, πρότερον δὲ ὀνομαζομένην Καλλίστην.", "st": "7.2"}, {"sp": "N", "t": "τρίτον δὲ τότε οἱ Κόδρου παῖδες ἐπετάχθησαν Ἴωσιν ἄρχοντες, οὐδέν σφισι γένους τοῦ Ἴωνος μετόν, ἀλλὰ Μεσσήνιοι μὲν τῶν ἐκ Πύλου τὰ πρὸς Κόδρου καὶ Μελάνθου, Ἀθηναῖοι δὲ ὄντες τὰ πρὸς μητρός. Ἴωσι δὲ τοῦ στόλου μετασχόντες ⟨ἦσαν⟩ οἵδε Ἑλλήνων, Θηβαῖοί τε οἱ ὁμοῦ Φιλώτᾳ γεγονότι ἀπογόνῳ Πηνέλεω καὶ Ὀρχομένιοι Μινύαι συγγενείᾳ τῶν Κόδρου παίδων·", "st": "7.2"}, {"sp": "N", "t": "μετέσχον δὲ καὶ Φωκεῖς οἱ ἄλλοι πλὴν Δελφῶν καὶ Ἄβαντες ἐξ Εὐβοίας. τοῖς δὲ Φωκεῦσι Φιλογένης καὶ Δάμων οἱ Εὐκτήμονος Ἀθηναῖοι ναῦς τε διδόασιν ἐς τὸν πλοῦν καὶ αὐτοί σφισιν ἐς τὴν ἀποικίαν ἐγένοντο ἡγεμόνες· ὡς δὲ ταῖς ναυσὶν ἐς τὴν Ἀσίαν κατῆραν, ἐπ’ ἄλλην ἐτρέποντο ἄλλοι τῶν ἐπὶ θαλάσσῃ πόλεων, Νειλεὺς δὲ καὶ ἡ σὺν αὐτῷ μοῖρα ἐς Μίλητον.", "st": "7.2"}, {"sp": "N", "t": "Μιλήσιοι δὲ αὐτοὶ τοιάδε τὰ ἀρχαιότατά σφισιν εἶναι λέγουσιν· ἐπὶ γενεὰς μὲν δύο Ἀνακτορίαν καλεῖσθαι τὴν γῆν Ἄνακτός τε αὐτόχθονος καὶ Ἀστερίου βασιλεύοντος τοῦ Ἄνακτος, Μιλήτου δὲ κατάραντος στόλῳ Κρητῶν ἥ τε γῆ τὸ ὄνομα μετέβαλεν ἀπὸ τοῦ Μιλήτου καὶ ἡ πόλις. ἀφίκετο δὲ ἐκ Κρήτης ὁ Μίλητος καὶ ὁ σὺν αὐτῷ στρατὸς Μίνω τὸν Εὐρώπης φεύγοντες, οἱ δὲ Κᾶρες οἱ πρότερον νεμόμενοι τὴν χώραν σύνοικοι τοῖς Κρησὶν ἐγένοντο·", "st": "7.2"}, {"sp": "N", "t": "τότε δὲ ὡς ἐκράτησαν τῶν ἀρχαίων Μιλησίων οἱ Ἴωνες, τὸ μὲν γένος πᾶν τὸ ἄρσεν ἀπέκτειναν πλὴν ὅσοι τῆς πόλεως ἁλισκομένης ἐκδιδράσκουσι, γυναῖκας δὲ καὶ θυγατέρας τὰς ἐκείνων γαμοῦσι. τοῦ δὲ Νειλέως ὁ τάφος ἰόντων ἐς Διδύμους ἐστὶν οὐ πόρρω τῶν πυλῶν ἐν ἀριστερᾷ τῆς ὁδοῦ· τὸ δὲ ἱερὸν τὸ ἐν Διδύμοις τοῦ Ἀπόλλωνος καὶ τὸ μαντεῖόν ἐστιν ἀρχαιότερον ἢ κατὰ τὴν Ἰώνων ἐσοίκησιν, πολλῷ δὲ πρεσβύτερα ἔτι ἢ κατὰ Ἴωνας ⟨τὰ⟩ ἐς τὴν Ἄρτεμιν τὴν Ἐφεσίαν ἐστίν.", "st": "7.2"}, {"sp": "N", "t": "οὐ μὴν πάντα γε τὰ ἐς τὴν θεὸν ἐπύθετο ἐμοὶ δοκεῖν Πίνδαρος, ὃς Ἀμαζόνας τὸ ἱερὸν ἔφη τοῦτο ἱδρύσασθαι στρατευομένας ἐπὶ Ἀθήνας τε καὶ Θησέα. αἱ δὲ ἀπὸ Θερμώδοντος γυναῖκες ἔθυσαν μὲν καὶ τότε τῇ Ἐφεσίᾳ θεῷ, ἅτε ἐπιστάμεναι [τε] ἐκ παλαιοῦ τὸ ἱερόν, καὶ ἡνίκα Ἡρακλέα ἔφυγον, αἱ δὲ καὶ Διόνυσον τὰ ἔτι ἀρχαιότερα, ἱκέτιδες ἐνταῦθα ἐλθοῦσαι· οὐ μὴν ὑπὸ Ἀμαζόνων γε ἱδρύθη, Κόρησος δὲ αὐτόχθων καὶ Ἔφεσος—Καΰστρου δὲ τοῦ ποταμοῦ τὸν Ἔφεσον παῖδα εἶναι νομίζουσιν—, οὗτοι τὸ ἱερόν εἰσιν οἱ ἱδρυσάμενοι, καὶ ἀπὸ τοῦ Ἐφέσου τὸ ὄνομά ἐστι τῇ πόλει.", "st": "7.2"}, {"sp": "N", "t": "Λέλεγες δὲ τοῦ Καρικοῦ μοῖρα καὶ Λυδῶν τὸ πολὺ οἱ νεμόμενοι τὴν χώραν ἦσαν· ᾤκουν δὲ καὶ περὶ τὸ ἱερὸν ἄλλοι τε ἱκεσίας ἕνεκα καὶ γυναῖκες τοῦ Ἀμαζόνων γένους. Ἄνδροκλος δὲ ὁ Κόδρου—οὗτος γὰρ δὴ ἀπεδέδεικτο Ἰώνων τῶν ἐς Ἔφεσον πλευσάντων βασιλεύς—Λέλεγας μὲν καὶ Λυδοὺς τὴν ἄνω πόλιν ἔχοντας ἐξέβαλεν ἐκ τῆς χώρας· τοῖς δὲ περὶ τὸ ἱερὸν οἰκοῦσι δεῖμα ἦν οὐδέν, ἀλλὰ Ἴωσιν ὅρκους δόντες καὶ ἀνὰ μέρος παρ’ αὐτῶν λαβόντες ἐκτὸς ἦσαν πολέμου. ἀφείλετο δὲ καὶ Σάμον Ἄνδροκλος Σαμίους, καὶ ἔσχον Ἐφέσιοι χρόνον τινὰ Σάμον καὶ τὰς προσεχεῖς νήσους·", "st": "7.2"}, {"sp": "N", "t": "Σαμίων δὲ ἤδη κατεληλυθότων ἐπὶ τὰ οἰκεῖα Πριηνεῦσιν ἤμυνεν ἐπὶ τοὺς Κᾶρας ὁ Ἄνδροκλος, καὶ νικῶντος τοῦ Ἑλληνικοῦ ἔπεσεν ἐν τῇ μάχῃ. Ἐφέσιοι δὲ ἀνελόμενοι τοῦ Ἀνδρόκλου τὸν νεκρὸν ἔθαψαν τῆς σφετέρας ἔνθα δείκνυται καὶ ἐς ἐμὲ ἔτι τὸ μνῆμα κατὰ τὴν ὁδὸν τὴν ἐκ τοῦ ἱεροῦ παρὰ τὸ Ὀλυμπιεῖον καὶ ἐπὶ πύλας τὰς Μαγνήτιδας· ἐπίθημα δὲ τῷ μνήματι ἀνήρ ἐστιν ὡπλισμένος.", "st": "7.2"}, {"sp": "N", "t": "οἱ δὲ Ἴωνες ⟨οἱ⟩ Μυοῦντα ἐσοικισάμενοι καὶ Πριήνην, Κᾶρας μὲν καὶ οὗτοι τὰς πόλεις ἀφείλοντο· οἰκισταὶ δὲ Μυοῦντος μὲν Κυάρητος ἐγένετο ὁ Κόδρου, Πριηνεῖς δὲ Ἴωσιν ἀναμεμιγμένοι Θηβαῖοι Φιλώταν τε τὸν ἀπόγονον Πηνέλεω καὶ Αἴπυτον Νειλέως παῖδα ἔσχον οἰκιστάς. Πριηνεῖς μὲν δὴ ὑπὸ Ταβούτου τε τοῦ Πέρσου καὶ ὕστερον ὑπὸ Ἱέρωνος ἀνδρὸς ἐπιχωρίου κακωθέντες ἐς τὸ ἔσχατον ὅμως τελοῦσιν ἐς Ἴωνας· Μυοῦντος δὲ οἱ οἰκήτορες ἐπὶ τύχῃ τοιᾷδε ἐξέλιπον τὴν πόλιν.", "st": "7.2"}, {"sp": "N", "t": "κατὰ τὴν Μυουσίαν χώραν θαλάσσης κόλπος ἐσεῖχεν οὐ μέγας· τοῦτον λίμνην ὁ ποταμὸς ἐποίησεν ὁ Μαίανδρος, ἀποτεμόμενος τὸν ἔσπλουν τῇ ἰλύι· ὡς δὲ ἐνόστησε τὸ ὕδωρ καὶ οὐκέτι ἦν θάλασσα, οἱ κώνωπες ἄπειρον πλῆθος ἐγίνοντο ἐκ τῆς λίμνης, ἐς ὃ τοὺς ἀνθρώπους ἠνάγκασαν ἐκλιπεῖν τὴν πόλιν. ἀπεχώρησαν δὲ ἐς Μίλητον Μυούσιοι τά τε ἄλλα ἀγώγιμα καὶ τῶν θεῶν φερόμενοι τὰ ἀγάλματα, καὶ ἦν κατ’ ἐμὲ οὐδὲν ἐν Μυοῦντι ὅτι μὴ Διονύσου ναὸς λίθου λευκοῦ· Μυουσίοις δέ γε κατέλαβεν ἐοικότα καὶ Ἀταρνείτας παθεῖν τοὺς ὑπὸ Περγάμῳ.", "st": "7.2"}, {"sp": "N", "t": "Κολοφώνιοι δὲ τὸ μὲν ἱερὸν τὸ ἐν Κλάρῳ καὶ τὸ μαντεῖον ἐκ παλαιοτάτου γενέσθαι νομίζουσιν· ἐχόντων δὲ ἔτι τὴν γῆν Καρῶν ἀφικέσθαι φασὶν ἐς αὐτὴν πρώτους τοῦ Ἑλληνικοῦ Κρῆτας, Ῥάκιον καὶ ὅσον εἵπετο ἄλλο τῷ Ῥακίῳ [καὶ ὅσον ἔτι] πλῆθος, ἔχον τὰ ἐπὶ θαλάσσῃ καὶ ναυσὶν ἰσχῦον· τῆς δὲ χώρας τὴν πολλὴν ἐνέμοντο ἔτι οἱ Κᾶρες. Θερσάνδρου δὲ τοῦ Πολυνείκους καὶ Ἀργείων ἑλόντων Θήβας [καὶ] ἄλλοι τε αἰχμάλωτοι καὶ ἡ Μαντὼ τῷ Ἀπόλλωνι ἐκομίσθησαν ἐς Δελφούς· Τειρεσίαν δὲ κατὰ τὴν πορείαν τὸ χρεὼν ἐπέλαβεν ἐν τῇ Ἁλιαρτίᾳ.", "st": "7.3"}, {"sp": "N", "t": "ἐκπέμψαντος δὲ σφᾶς ἐς ἀποικίαν τοῦ θεοῦ, περαιοῦνται ναυσὶν ἐς τὴν Ἀσίαν, καὶ ὡς κατὰ τὴν Κλάρον ἐγένοντο, ἐπεξίασιν αὐτοῖς οἱ Κρῆτες μετὰ ὅπλων καὶ ἀνάγουσιν ὡς τὸν Ῥάκιον· ὁ δὲ—μανθάνει γὰρ παρὰ τῆς Μαντοῦς οἵτινές τε ἀνθρώπων ὄντες καὶ κατὰ αἰτίαν ἥντινα ἥκουσι— λαμβάνει μὲν γυναῖκα τὴν Μαντώ, ποιεῖται δὲ καὶ τοὺς σὺν αὐτῇ συνοίκους. Μόψος δὲ ὁ Ῥακίου καὶ Μαντοῦς καὶ τὸ παράπαν τοὺς Κᾶρας ἐξέβαλεν ἐκ τῆς γῆς.", "st": "7.3"}, {"sp": "N", "t": "Ἴωνες δὲ ὅρκους ποιησάμενοι πρὸς τοὺς ἐν Κολοφῶνι Ἕλληνας συνεπολιτεύοντο, οὐδὲν ἔχοντες πλέον· βασιλείαν δὲ Ἰώνων ἡγεμόνες Δαμασίχθων λαμβάνει καὶ Πρόμηθος Κόδρου παῖδες. Πρόμηθος δὲ ὕστερον τὸν ἀδελφὸν Δαμασίχθονα ἀποκτείνας ἔφυγεν ἐς Νάξον, καὶ ἀπέθανε μὲν αὐτόθι ἐν τῇ Νάξῳ, τὸν νεκρὸν δὲ οἴκαδε ἀπαχθέντα κατεδέξαντο οἱ Δαμασίχθονοε παῖδες· καὶ ἔνθα ὁ τοῦ Προμήθου τάφος, Πολυτειχίδες ὄνομά ἐστι τῷ χωρίῳ.", "st": "7.3"}, {"sp": "N", "t": "Κολοφωνίοις δὲ ὅπως μὲν τὴν πόλιν συνέπεσεν ἐρημωθῆναι, προεδήλωσέ μοι τοῦ λόγου τὰ ἐς Λυσίμαχον· ἐμαχέσαντο δὲ Λυσιμάχῳ καὶ Μακεδόσι Κολοφώνιοι τῶν ἀνοικισθέντων ἐς Ἔφεσον μόνοι, τοῖς δὲ ἀποθανοῦσιν ἐν τῇ μάχῃ Κολοφωνίων τε αὐτῶν καὶ Σμυρναίων ἐστὶν ὁ τάφος ἰόντι ἐς Κλάρον ἐν ἀριστερᾷ τῆς ὁδοῦ.", "st": "7.3"}, {"sp": "N", "t": "Λεβεδίοις δὲ ἐποίησε μὲν Λυσίμαχος ἀνάστατον τὴν πόλιν, ἵνα δὴ συντέλεια ἐς μέγεθος τῇ Ἐφέσῳ γένοιτο· χώρα δέ σφισιν ἔς τε τὰ λοιπά ἐστιν εὐδαίμων καὶ λουτρὰ παρέχεται θερμὰ πλεῖστα τῶν ἐπὶ θαλάσσῃ καὶ ἥδιστα. τὸ δὲ ἐξ ἀρχῆς καὶ τὴν Λέβεδον ἐνέμοντο οἱ Κᾶρες, ἐς ὃ Ἀνδραίμων σφᾶς ὁ Κόδρου καὶ Ἴωνες ἐλαύνουσι. τῷ δὲ Ἀνδραίμονι ὁ τάφος ἐκ Κολοφῶνος ἰόντι ἐστὶν ἐν ἀριστερᾷ τῆς ὁδοῦ, διαβάντι τὸν Καλάοντα ποταμόν.", "st": "7.3"}, {"sp": "N", "t": "Τέων δὲ ᾤκουν μὲν Ὀρχομένιοι Μινύαι σὺν Ἀθάμαντι ἐς αὐτὴν ἐλθόντες· λέγεται δὲ ὁ Ἀθάμας οὗτος ἀπόγονος Ἀθάμαντος εἶναι τοῦ Αἰόλου. ἀναμεμιγμένοι μὲν τῷ Ἑλληνικῷ καὶ ἐνταῦθα ἦσαν οἱ Κᾶρες· ἐσήγαγε δὲ Ἴωνας ἐς τὴν Τέων Ἄποικος ἀπόγονος Μελάνθου τέταρτος, ὃς τοῖς Ὀρχομενίοις οὐδὲ τοῖς Τηίοις νεώτερον ἐβούλευσεν οὐδέν. ἔτεσι δὲ οὐ πολλοῖς ὕστερον ἔκ τε Ἀθηναίων καὶ ἐκ Βοιωτίας ἀφίκοντο ἄνδρες· ἡγοῦντο δὲ τοῦ μὲν Ἀττικοῦ Δάμασος καὶ Νάοκλος Κόδρου παῖδες, τῶν δὲ Βοιωτῶν Γέρης Βοιωτός· καὶ σφᾶς συναμφοτέρους ὅ τε Ἄποικος καὶ οἱ Τήιοι συνοίκους ἐδέξαντο.", "st": "7.3"}, {"sp": "N", "t": "Ἐρυθραῖοι δὲ τὸ μὲν ἐξ ἀρχῆς ἀφικέσθαι σὺν Ἐρύθρῳ τῷ Ῥαδαμάνθυός φασιν ἐκ Κρήτης καὶ οἰκιστὴν τῇ πόλει γενέσθαι τὸν Ἔρυθρον· ἐχόντων δὲ αὐτὴν ὁμοῦ τοῖς Κρησὶ Λυκίων καὶ Καρῶν τε καὶ Παμφύλων, Λυκίων μὲν κατὰ συγγένειαν τὴν Κρητῶν —καὶ γὰρ οἱ Λύκιοι τὸ ἀρχαῖόν εἰσιν ἐκ Κρήτης, οἳ Σαρπηδόνι ὁμοῦ ἔφυγον—, Καρῶν δὲ κατὰ φιλίαν ἐκ παλαιοῦ πρὸς Μίνω, Παμφύλων δὲ ὅτι γένους μέτεστιν Ἑλληνικοῦ καὶ τούτοις—εἰσὶ γὰρ δὴ καὶ οἱ Πάμφυλοι τῶν μετὰ ἅλωσιν Ἰλίου πλανηθέντων σὺν Κάλχαντι—, τούτων τῶν κατειλεγμένων ἐχόντων Ἐρυθράς, Κλέοπος ὁ Κόδρου συλλέξας ἐξ ἁπασῶν τῶν ἐν Ἰωνίᾳ πόλεων ὅσους δὴ παρὰ ἑκάστων ἐπεισήγαγεν Ἐρυθραίοις συνοίκους.", "st": "7.3"}, {"sp": "N", "t": "Κλαζομενίοις δὲ καὶ Φωκαεῦσι, πρὶν μὲν ἢ Ἴωνας ἐς τὴν Ἀσίαν ἐλθεῖν, οὐκ ᾠκοῦντο αἱ πόλεις· Ἰώνων δὲ ἀφικομένων μοῖρα ἐξ αὐτῶν πλανωμένη μετεπέμψατο ἡγεμόνα παρὰ Κολοφωνίων Πάρφορον, καὶ πόλιν κτίσαντες ὑπὸ τῇ Ἴδῃ τὴν μὲν οὐ μετὰ πολὺ ἐκλείπουσιν, ἐπανιόντες δὲ ἐς Ἰωνίαν Σκύππιον τῆς Κολοφωνίας ἔκτισαν.", "st": "7.3"}, {"sp": "N", "t": "ἀπελθόντες δὲ ἑκουσίως καὶ ἐκ τῆς Κολοφωνίας, οὕτω γῆν τε ἔσχον, ἣν καὶ νῦν ἔτι ἔχουσι, καὶ κατεσκευάσαντο ἐν τῇ ἠπείρῳ Κλαζομενὰς πόλιν· ἐς δὲ τὴν νῆσον διέβησαν δὴ κατὰ τὸ Περσῶν δέος. Ἀλέξανδρος δὲ ἀνὰ χρόνον ἔμελλεν ὁ Φιλίππου χερρόνησον Κλαζομενὰς ἐργάσεσθαι χώματι ἐς τὴν νῆσον ἐκ τῆς ἠπείρου. τούτων τῶν Κλαζομενίων τὸ πολὺ οὐκ Ἴωνες, Κλεωναῖοι δὲ ἦσαν καὶ ἐκ Φλιοῦντος, ὅσοι Δωριέων ἐς Πελοπόννησον κατελθόντων ἐξέλιπον τὰς πόλεις·", "st": "7.3"}, {"sp": "N", "t": "οἱ δὲ Φωκαεῖς γένος μὲν τὸ ἀνέκαθέν εἰσιν ἐκ τῆς ὑπὸ τῷ Παρνασσῷ καλουμένης καὶ ἐς ἡμᾶς ἔτι Φωκίδος, οἳ Φιλογένει καὶ Δάμωνι ὁμοῦ τοῖς Ἀθηναίοις διέβησαν ἐς τὴν Ἀσίαν. τὴν χώραν δὲ οὐ πολέμῳ, κατὰ δὲ ὁμολογίαν λαμβάνουσι παρὰ Κυμαίων· Ἰώνων δὲ οὐ δεχομένων σφᾶς ἐς Πανιώνιον πρὶν ἢ τοῦ γένους βασιλέας τοῦ Κοδριδῶν λάβωσιν, οὕτω παρὰ Ἐρυθραίων καὶ ἐκ Τέω Δεοίτην καὶ Πέρικλον λαμβάνουσι καὶ Ἄβαρτον.", "st": "7.3"}, {"sp": "N", "t": "αἱ δὲ ἐν ταῖς νήσοις εἰσὶν Ἰώνων πόλεις Σάμος ἡ ὑπὲρ Μυκάλης καὶ Χίος ἡ ἀπαντικρὺ τοῦ Μίμαντος. Ἄσιος δὲ ὁ Ἀμφιπτολέμου Σάμιος ἐποίησεν ἐν τοῖς ἔπεσιν ὡς Φοίνικι ἐκ Περιμήδης τῆς Οἰνέως γένοιτο Ἀστυπάλαια καὶ Εὐρώπη, Ποσειδῶνος δὲ καὶ Ἀστυπαλαίας εἶναι παῖδα Ἀγκαῖον, βασιλεύειν δὲ αὐτὸν τῶν καλουμένων Λελέγων· Ἀγκαίῳ δὲ τὴν θυγατέρα τοῦ ποταμοῦ λαβόντι τοῦ Μαιάνδρου Σαμίαν γενέσθαι Περίλαον καὶ Ἔνουδον καὶ Σάμον καὶ Ἀλιθέρσην καὶ θυγατέρα ἐπ’ αὐτῷ Παρθενόπην, Παρθενόπης δὲ τῆς Ἀγκαίου καὶ Ἀπόλλωνος Λυκομήδην γενέσθαι.", "st": "7.4"}, {"sp": "N", "t": "Ἄσιος μὲν ἐς τοσοῦτο ἐν τοῖς ἔπεσιν ἐδήλωσε· τότε δὲ οἱ τὴν νῆσον οἰκοῦντες ἀνάγκῃ πλέον ἐδέξαντο ἢ εὐνοίᾳ συνοίκους Ἴωνας. ἡγεμὼν δὲ ἦν τοῖς Ἴωσι Προκλῆς ὁ Πιτυρέως, αὐτός τε Ἐπιδαύριος καὶ Ἐπιδαυρίους [ἦν] τὸ πολὺ ἄγων, οἳ ὑπὸ Δηιφόντου καὶ Ἀργείων ἐκ τῆς Ἐπιδαυρίας ἐξεπεπτώκεσαν· τούτῳ τῷ Προκλεῖ γένος ἦν ἀπὸ Ἴωνος τοῦ Ξούθου. Ἄνδροκλος δὲ καὶ Ἐφέσιοι στρατεύουσιν ἐπὶ Λεώγορον τὸν Προκλέους, βασιλεύοντα μετὰ τὸν πατέρα ἐν Σάμῳ, καὶ μάχῃ νικήσαντες ἐξελαύνουσιν ἐκ τῆς νήσου Σαμίους· αἰτίαν δὲ ἐπέφερον μετὰ Καρῶν σφᾶς ἐπιβουλεύειν Ἴωσι.", "st": "7.4"}, {"sp": "N", "t": "Σαμίων δὲ τῶν φευγόντων οἱ μὲν ἐπὶ τῇ Θρᾴκῃ νῆσον ᾤκησαν, καὶ ἀπὸ τούτων τῆς ἐνοικήσεως Σαμοθρᾴκην τὴν νῆσον καλοῦσιν ἀντὶ Δαρδανίας· οἱ δὲ ὁμοῦ Λεωγόρῳ περὶ Ἀναίαν τὴν ἐν τῇ ἠπείρῳ τῇ πέραν βαλόμενοι τεῖχος, δέκα ἔτεσιν ὕστερον διαβάντες ἐν τῇ Σάμῳ τούς τε Ἐφεσίους ἐκβάλλουσι καὶ ἀνεσώσαντο τὴν νῆσον.", "st": "7.4"}, {"sp": "N", "t": "τὸ δὲ ἱερὸν τὸ ἐν Σάμῳ τῆς Ἥρας εἰσὶν οἳ ἱδρύσασθαί φασι τοὺς ἐν τῇ Ἀργοῖ πλέοντας, ἐπάγεσθαι δὲ αὐτοὺς τὸ ἄγαλμα ἐξ Ἄργους· Σάμιοι δὲ αὐτοὶ τεχθῆναι νομίζουσιν ἐν τῇ νήσῳ τὴν θεὸν παρὰ τῷ Ἰμβράσῳ ποταμῷ καὶ ὑπὸ τῇ λύγῳ τῇ ἐν τῷ Ἡραίῳ κατ’ ἐμὲ ἔτι πεφυκυίᾳ. εἶναι δ’ οὖν τὸ ἱερὸν τοῦτο ἐν τοῖς μάλιστα ἀρχαῖον [ὃ] οὐχ ἥκιστα ἄν τις καὶ ἐπὶ ⟨τῷ⟩ ἀγάλματι τεκμαίροιτο· ἔστι γὰρ δὴ ἀνδρὸς ἔργον Αἰγινήτου Σμίλιδος τοῦ Εὐκλείδου. οὗτος ὁ Σμῖλίς ἐστιν ἡλικίαν κατὰ Δαίδαλον, δόξης δὲ οὐκ ἐς τὸ ἴσον ἀφίκετο·", "st": "7.4"}, {"sp": "N", "t": "Δαιδάλῳ μὲν γὰρ γένους τε Ἀθήνῃσιν ὑπῆρχεν εἶναι τοῦ βασιλικοῦ τῶν καλουμένων Μητιονιδῶν καὶ ὁμοῦ τῇ τέχνῃ τῆς πλάνης τε ἕνεκα καὶ ἐπὶ ταῖς συμφοραῖς ἐπιφανέστερος ἐγένετο ἐς ἅπαντας ἀνθρώπους. ἀποκτείνας μὲν ἀδελφῆς παῖδα καὶ ἐπιστάμενος τὰ οἴκοι νόμιμα ἑκουσίως παρὰ Μίνω ἔφυγεν ἐς Κρήτην, καὶ αὐτῷ τε ἀγάλματα Μίνῳ καὶ τοῦ Μίνω ταῖς θυγατράσιν ἐποίησε, καθότι καὶ Ὅμηρος ἐν Ἰλιάδι ἐδήλωσε·", "st": "7.4"}, {"sp": "N", "t": "καταγνωσθεὶς δὲ ἀδικεῖν ὑπὸ τοῦ Μίνω καὶ ἐς δεσμωτήριον ὁμοῦ τῷ παιδὶ ἐμβληθεὶς ἐκδιδράσκει τε ἐκ Κρήτης καὶ ἐς Ἴνυκον Σικελῶν πόλιν ἀφικνεῖται παρὰ Κώκαλον, καὶ πολέμου παρέσχε τοῖς Σικελοῖς αἰτίαν πρὸς τοὺς Κρῆτας, ὅτι ἐξαιτοῦντος Μίνω μὴ πρόοιτο αὐτὸν ὁ Κώκαλος· καὶ ἐς τοσοῦτο ὑπὸ τοῦ Κωκάλου τῶν θυγατέρων ἐσπουδάσθη κατὰ τὴν τέχνην, ὡς καὶ θάνατον τῷ Μίνῳ βουλεῦσαι τὰς γυναῖκας ἐς χάριν Δαιδάλου.", "st": "7.4"}, {"sp": "N", "t": "δῆλά τε ὡς ἀνὰ πᾶσαν μὲν τὴν Σικελίαν, ἐπὶ πλεῖστον δὲ καὶ Ἰταλίας ἀφίκετο τοῦ Δαιδάλου τὸ ὄνομα. ὁ δὲ Σμῖλις, ὅτι μὴ παρὰ Σαμίους καὶ ἐς τὴν Ἠλείαν, παρ’ ἄλλους γε οὐδένας φανερός ἐστιν ἀποδημήσας· ἐς τούτους δὲ ἀφίκετο, καὶ τὸ ἄγαλμα ἐν Σάμῳ τῆς Ἥρας ὁ ποιήσας ἐστὶν οὗτος.", "st": "7.4"}, {"sp": "N", "t": "… Ἴωνι δὲ τῷ ποιήσαντι τραγῳδίαν ἐστὶν ἐν τῇ συγγραφῇ τοιάδε εἰρημένα, Ποσειδῶνα ἐς τὴν νῆσον ἔρημον οὖσαν ἀφικέσθαι καὶ νύμφῃ τε ἐνταῦθα συγγενέσθαι καὶ ὑπὸ τὰς ὠδῖνας τῆς νύμφης χιόνα ἐξ οὐρανοῦ πεσεῖν ἐς τὴν γῆν, καὶ ἀπὸ τούτου Ποσειδῶνα τῷ παιδὶ ὄνομα θέσθαι Χίον· συγγενέσθαι δὲ αὐτὸν καὶ ἑτέρᾳ νύμφῃ, καὶ γενέσθαι οἱ παῖδας Ἄγελόν τε καὶ Μέλανα· ἀνὰ χρόνον δὲ καὶ Οἰνοπίωνα ἐς τὴν Χίον κατᾶραι ναυσὶν ἐκ Κρήτης, ἕπεσθαι δέ οἱ καὶ τοὺς παῖδας Τάλον καὶ Εὐάνθην καὶ Μέλανα καὶ Σάλαγόν τε καὶ Ἀθάμαντα.", "st": "7.4"}, {"sp": "N", "t": "ἀφίκοντο δὲ καὶ Κᾶρες ἐς τὴν νῆσον ἐπὶ τῆς Οἰνοπίωνος βασιλείας καὶ Ἄβαντες ἐξ Εὐβοίας. Οἰνοπίωνος δὲ καὶ τῶν παίδων ἔλαβεν ὕστερον Ἄμφικλος τὴν ἀρχήν· ἀφίκετο δὲ ἐξ Ἱστιαίας ὁ Ἄμφικλος τῆς ἐν Εὐβοίᾳ κατὰ μάντευμα ἐκ Δελφῶν. Ἕκτωρ δὲ ἀπὸ Ἀμφίκλου τετάρτῃ γενεᾷ— βασιλείαν γὰρ ἔσχε καὶ οὗτος—ἐπολέμησεν Ἀβάντων καὶ Καρῶν τοῖς οἰκοῦσιν ἐν τῇ νήσῳ, καὶ τοὺς μὲν ἀπέκτεινεν ἐν ταῖς μάχαις, τοὺς δὲ ἀπελθεῖν ἠνάγκασεν ὑποσπόνδους.", "st": "7.4"}, {"sp": "N", "t": "γενομένης δὲ ἀπαλλαγῆς πολέμου Χίοις, ἀφικέσθαι τηνικαῦτα ἐς μνήμην Ἕκτορι ὡς σφᾶς καὶ Ἴωσι δέοι συνθύειν ἐς Πανιώνιον· τρίποδα δὲ ἆθλον λαβεῖν αὐτὸν ἐπὶ ἀνδραγαθίᾳ παρὰ τοῦ κοινοῦ φησι τοῦ Ἰώνων. τοσαῦτα εἰρηκότα ἐς Χίους Ἴωνα εὕρισκον· οὐ μέντοι ἐκεῖνό γε εἴρηκε, καθ’ ἥντινα αἰτίαν Χῖοι τελοῦσιν ἐς Ἴωνας.", "st": "7.4"}, {"sp": "N", "t": "Σμύρναν δὲ ἐν ταῖς δώδεκα πόλεσιν οὖσαν Αἰολέων καὶ οἰκουμένην τῆς χώρας, καθ’ ἃ καὶ ἐς ἐμὲ ἔτι πόλιν [ἣν] καλοῦσιν ἀρχαίαν, Ἴωνες ἐκ Κολοφῶνος ὁρμηθέντες ἀφελόμενοι τοὺς Αἰολεῖς ἔσχον· χρόνῳ δὲ ὕστερον καὶ Ἴωνες μετέδοσαν Σμυρναίοις τοῦ ἐν Πανιωνίῳ συλλόγου. Ἀλέξανδρος δὲ ὁ Φιλίππου τῆς ἐφ’ ἡμῶν πόλεως ἐγένετο οἰκιστὴς κατ’ ὄψιν ὀνείρατος·", "st": "7.5"}, {"sp": "N", "t": "Ἀλέξανδρον γὰρ θηρεύοντα ἐν τῷ ὄρει τῷ Πάγῳ, ὡς ἐγένετο ἀπὸ τῆς θήρας, ἀφικέσθαι πρὸς Νεμέσεων λέγουσιν ἱερόν, καὶ πηγῇ τε ἐπιτυχεῖν αὐτὸν καὶ πλατάνῳ πρὸ τοῦ ἱεροῦ, πεφυκυίᾳ δὲ ἐπὶ τοῦ ὕδατος. καὶ ὑπὸ τῇ πλατάνῳ καθεύδοντι κελεύειν φασὶν αὐτῷ τὰς Νεμέσεις ἐπιφανείσας πόλιν ἐνταῦθα οἰκίζειν καὶ ἄγειν ἐς αὐτὴν Σμυρναίους ἀναστήσαντα ἐκ τῆς προτέρας·", "st": "7.5"}, {"sp": "N", "t": "ἀποστέλλουσιν οὖν ἐς Κλάρον θεωροὺς οἱ Σμυρναῖοι περὶ τῶν παρόντων σφίσιν ἐρησομένους, καὶ αὐτοῖς ἔχρησεν ὁ θεός·<br>τρὶς μάκαρες κεῖνοι καὶ τετράκις ἄνδρες ἔσονται,<br>οἳ Πάγον οἰκήσουσι πέρην ἱεροῖο Μέλητος.<br>οὕτω μετῳκίσαντο ἐθελονταὶ καὶ δύο Νεμέσεις νομίζουσιν ἀντὶ μιᾶς καὶ μητέρα αὐταῖς φασιν εἶναι Νύκτα, ἐπεὶ Ἀθηναῖοί γε τῇ ἐν Ῥαμνοῦντι θεῷ πατέρα λέγουσιν εἶναι Ὠκεανόν.", "st": "7.5"}, {"sp": "N", "t": "Ἴωσι δὲ ἔχει μὲν ἐπιτηδειότατα ὡρῶν κράσεως ἡ χώρα, ἔχει δὲ καὶ ἱερὰ οἷα οὐχ ἑτέρωθι, πρῶτον μὲν ⟨τὸ⟩ τῆς Ἐφεσίας μεγέθους τε ἕνεκα καὶ ἐπὶ τῷ ἄλλῳ πλούτῳ, δύο δὲ οὐκ ἐξειργασμένα Ἀπόλλωνος, τό τε ἐν Βραγχίδαις τῆς Μιλησίας καὶ ἐν Κλάρῳ τῇ Κολοφωνίων. δύο δὲ ἄλλους ἐν Ἰωνίᾳ ναοὺς ἐπέλαβεν ὑπὸ Περσῶν κατακαυθῆναι, τόν τε ἐν Σάμῳ τῆς Ἥρας καὶ ἐν Φωκαίᾳ τῆς Ἀθηνᾶς· θαῦμα δὲ ὅμως ἦσαν καὶ ὑπὸ τοῦ πυρὸς λελυμασμένοι.", "st": "7.5"}, {"sp": "N", "t": "ἡσθείης δ’ ἂν καὶ τῷ ἐν Ἐρυθραῖς Ἡρακλείῳ καὶ Ἀθηνᾶς τῷ ἐν Πριήνῃ ναῷ, τούτῳ μὲν τοῦ ἀγάλματος ἕνεκα, Ἡρακλείῳ δὲ τῷ ἐν Ἐρυθραῖς κατὰ ἀρχαιότητα· τὸ δὲ ἄγαλμα οὔτε τοῖς καλουμένοις Αἰγιναίοις οὔτε τῶν Ἀττικῶν ⟨τοῖς⟩ ἀρχαιοτάτοις ἐμφερές, εἰ δέ τι καὶ ἄλλο, ἀκριβῶς ἐστιν Αἰγύπτιον. σχεδία γὰρ ⟨ἦν⟩ ξύλων, καὶ ἐπ’ αὐτῇ ὁ θεὸς ἐκ Τύρου τῆς Φοινίκης ἐξέπλευσε· καθ’ ἥντινα δὲ αἰτίαν, οὐδὲ αὐτοὶ τοῦτο οἱ Ἐρυθραῖοι λέγουσιν.", "st": "7.5"}, {"sp": "N", "t": "ὡς δὲ ἐς τὴν θάλασσαν ἀφίκετο ἡ σχεδία τὴν Ἰώνων, φασὶν αὐτὴν ὁρμίσασθαι πρὸς ἄκρᾳ καλουμένῃ Μεσάτῃ· ἡ δὲ ἔστι μὲν τῆς ἠπείρου, τοῖς ⟨δὲ⟩ ἐκ τοῦ Ἐρυθραίων λιμένος ἐς νῆσον τὴν Χίων πλέουσι τοῦτό ἐστι μεσαίτατον. ἐπεὶ δὲ ἡ σχεδία κατὰ τὴν ἄκραν ἔσχεν, ἐνταῦθα πολὺν μὲν οἱ Ἐρυθραῖοι πόνον, οὐκ ἐλάσσονα δὲ ἔσχον οἱ Χῖοι ποιούμενοι σπουδὴν παρὰ σφᾶς καταγαγεῖν ἑκάτεροι τὸ ἄγαλμα·", "st": "7.5"}, {"sp": "N", "t": "τέλος δὲ Ἐρυθραῖος ἄνθρωπος, ᾧ βίος μὲν ἦν ἀπὸ θαλάσσης γεγονὼς καὶ ἄγρας ἰχθύων, διέφθαρτο δὲ ὑπὸ νόσου τοὺς ὀφθαλμούς, ὄνομα δέ οἱ Φορμίων ἦν, οὗτος ὁ ἁλιεὺς εἶδεν ὄψιν ὀνείρατος ὡς τὰς Ἐρυθραίων γυναῖκας ἀποκείρασθαι δέοι τὰς κόμας καὶ οὕτω τοὺς ἄνδρας πλεξαμένους κάλον ἐκ τῶν τριχῶν τὴν σχεδίαν παρὰ σφᾶς κατάξειν. αἱ μὲν δὴ ἀσταὶ τῶν γυναικῶν οὐδαμῶς ὑπακούειν τῷ ὀνείρατι ἐβούλοντο·", "st": "7.5"}, {"sp": "N", "t": "ὁπόσαι δὲ τοῦ Θρᾳκίου γένους ἐδούλευον καὶ οὔσαις σφίσιν ἐλευθέραις ἦν ἐνταῦθα βίος, ἀποκεῖραι παρέχουσιν αὑτάς· καὶ οὕτως οἱ Ἐρυθραῖοι τὴν σχεδίαν καθέλκουσιν. ἔσοδός τε δὴ ταῖς Θρᾴσσαις ἐς τὸ Ἡράκλειόν ἐστι γυναικῶν μόναις, καὶ τὸ καλῴδιον τὸ ἐκ τῶν τριχῶν καὶ ἐς ἐμὲ ἔτι οἱ ἐπιχώριοι φυλάσσουσι· καὶ δὴ καὶ τὸν ἁλιέα οἱ αὐτοὶ οὗτοι ἀναβλέψαι τε καὶ ὁρᾶν τὸ λοιπὸν τοῦ βίου φασίν.", "st": "7.5"}, {"sp": "N", "t": "ἔστι δὲ ἐν Ἐρυθραῖς καὶ Ἀθηνᾶς Πολιάδος ναὸς καὶ ἄγαλμα ξύλου μεγέθει μέγα καθήμενόν τε ἐπὶ θρόνου καὶ ἠλακάτην ἐν ἑκατέρᾳ τῶν χειρῶν ἔχει καὶ ἐπὶ τῆς κεφαλῆς πόλον· τοῦτο Ἐνδοίου τέχνην καὶ ἄλλοις ἐτεκμαιρόμεθα εἶναι καὶ ἐς τὴν ἐργασίαν ὁρῶντες ἔνδον τοῦ ἀγάλματος καὶ οὐχ ἥκιστα ἐπὶ ταῖς Χάρισί τε καὶ Ὥραις, αἳ πρὶν ἐσελθεῖν ἑστήκασιν ἐν ὑπαίθρῳ λίθου λευκοῦ. ἐποιήθη δὲ καὶ κατ’ ἐμὲ Σμυρναίοις ἱερὸν Ἀσκληπιοῦ μεταξὺ Κορυφῆς τε ὄρους καὶ θαλάσσης ἀμιγοῦς ὕδατι ἀλλοίῳ.", "st": "7.5"}, {"sp": "N", "t": "ἡ δὲ Ἰωνία παρὲξ τῶν τε ἱερῶν καὶ τῆς τοῦ ἀέρος κράσεως παρέχεται καὶ ἄλλα ἐς συγγραφήν, ἡ μέν γε Ἐφεσία χώρα τόν τε Κέγχριον ποταμὸν καὶ τοῦ Πίονος τοῦ ὄρους τὴν φύσιν καὶ πηγὴν τὴν Ἁλιταίαν· ἐν δὲ τῇ Μιλησίᾳ πηγή τέ ἐστι Βιβλὶς καὶ ὅσα ἐς τῆς Βιβλίδος τὸν ἔρωτα ᾄδουσιν· ἐν δὲ τῇ Κολοφωνίων ἄλσος τε τοῦ Ἀπόλλωνος, δένδρα μελίαι, καὶ οὐ πόρρω τοῦ ἄλσους Ἄλης ποταμὸς ψυχρότατος τῶν ἐν Ἰωνίᾳ.", "st": "7.5"}, {"sp": "N", "t": "Λεβεδίοις δὲ τὰ λουτρὰ ἐν τῇ γῇ θαῦμα ἀνθρώποις ὁμοῦ καὶ ὠφέλεια γίνεται· ἔστι δὲ καὶ Τηίοις ἐπὶ τῇ ἄκρᾳ λουτρὰ τῇ Μακρίᾳ, τὰ μὲν ἐπὶ τῷ κλύδωνι ἐν πέτρας χηραμῷ, τὰ δὲ καὶ ἐς ἐπίδειξιν πλούτου πεποιημένα. Κλαζομενίοις δὲ λουτρά ἐστιν—ἐν δὲ αὐτοῖς Ἀγαμέμνων ἔχει τιμάς—καὶ ἄντρον μητρός σφισι Πύρρου καλούμενον, καὶ λόγον ἐπὶ τῷ Πύρρῳ λέγουσι τῷ ποιμένι·", "st": "7.5"}, {"sp": "N", "t": "Ἐρυθραίοις δὲ ἔστι μὲν χώρα Χαλκίς, ἀφ’ ἧς καὶ τῶν φυλῶν σφισιν ἡ τρίτη τὸ ὄνομα ἔσχηκεν, ἔστι δὲ τῆς Χαλκίδος κατατείνουσα ἐς τὸ πέλαγος ἄκρα καὶ ἐν αὐτῇ λουτρὰ θαλάσσια, μάλιστα τῶν ἐν Ἰωνίᾳ λουτρῶν ὠφέλιμα ἀνθρώποις. Σμυρναίοις δὲ ποταμὸς Μέλης ὕδωρ ἐστὶ κάλλιστον καὶ σπήλαιον ἐπὶ ταῖς πηγαῖς, ἔνθα Ὅμηρον ποιῆσαι τὰ ἔπη λέγουσι·", "st": "7.5"}, {"sp": "N", "t": "Χίοις δὲ ὁ τοῦ Οἰνοπίωνος τάφος θέαν τε παρέχεται καί τινας καὶ λόγους ἐς τοῦ Οἰνοπίωνος τὰ ἔργα· Σαμίοις δὲ κατὰ τὴν ὁδὸν τὴν ἐς τὸ Ἡραῖον τὸ Ῥαδίνης καὶ Λεοντίχου μνῆμά ἐστι, καὶ τοῖς ὑπὸ ἔρωτος ἀνιωμένοις εὔχεσθαι καθέστηκεν ἰοῦσιν ἐπὶ τὸ μνῆμα. τὰ μὲν δὴ ἐν Ἰωνίᾳ θαύματα πολλά τε καὶ οὐ πολλῷ τινι τῶν ἐν τῇ Ἑλλάδι ἀποδέοντά ἐστιν·", "st": "7.5"}, {"sp": "N", "t": "τότε δὲ ἀπεληλυθότων Ἰώνων τήν τε ⟨γῆν⟩ οἱ Ἀχαιοὶ τὴν Ἰώνων διελάγχανον καὶ ἐσῳκίζοντο ἐς τὰς πόλεις. αἱ δὲ δύο τε καὶ δέκα ἦσαν ἀριθμόν, ὁπόσαι γε καὶ ἐς ἅπαν τὸ Ἑλληνικὸν γνώριμοι, Δύμη μὲν πρὸς Ἤλιδος πρώτη, μετὰ δὲ αὐτὴν Ὤλενος καὶ Φαραὶ καὶ Τρίτεια καὶ Ῥύπες καὶ Αἴγιον καὶ Κερύνεια καὶ Βοῦρα, ἐπὶ ταύταις δὲ Ἑλίκη καὶ Αἰγαί τε καὶ Αἴγειρα καὶ Πελλήνη πρὸς τῆς Σικυωνίας ἐσχάτη· ἐς ταύτας οἱ Ἀχαιοὶ καὶ οἱ βασιλεῖς αὐτῶν ἐσῳκίζοντο πρότερον ἔτι ὑπὸ Ἰώνων οἰκουμένας.", "st": "7.6"}, {"sp": "N", "t": "ἦσαν δὲ οἱ τὸ μέγιστον ⟨ἐν⟩ τοῖς Ἀχαιοῖς ἔχοντες κράτος οἵ τε Τισαμενοῦ παῖδες Δαϊμένης καὶ Σπάρτων καὶ Τέλλις τε καὶ Λεοντομένης· Κομήτης δὲ ὁ πρεσβύτατος τῶν Τισαμενοῦ παίδων πρότερον ἔτι διεβεβήκει ναυσὶν ἐς τὴν Ἀσίαν. οὗτοί τε δὴ τηνικαῦτα ἐν τοῖς Ἀχαιοῖς ἐδυνάστευον καὶ Δαμασίας ὁ Πενθίλου τοῦ Ὀρέστου, τοῖς Τισαμενοῦ παισὶν ἀνεψιὸς πρὸς πατρός. ἴσχυον δὲ ἐπ’ ἴσης τοῖς κατειλεγμένοις καὶ Ἀχαιῶν τῶν ἐκ Λακεδαίμονος Πρευγένης καὶ ὁ υἱός, ὄνομα δέ οἱ ἦν Πατρεύς· καί σφισιν ὑπὸ τῶν Ἀχαιῶν ἐδόθη κτίσασθαι πόλιν ἐν τῇ χώρᾳ, καὶ τὸ ὄνομα ἀπὸ τοῦ Πατρέως ἐτέθη τῇ πόλει.", "st": "7.6"}, {"sp": "N", "t": "τὰ δὲ ἐς πόλεμον τοιάδε ἦν τοῖς Ἀχαιοῖς. κατὰ μὲν τὴν ἐς Ἴλιον ἐπιστρατείαν Ἀγαμέμνονος Λακεδαίμονα ἔτι καὶ Ἄργος οἰκοῦντες μεγίστη τοῦ Ἑλληνικοῦ μοῖρα ἦσαν· κατὰ δὲ τὴν Ξέρξου καὶ Μήδων ἐπὶ τὴν Ἑλλάδα [ὁδὸν] οὔτε Λεωνίδᾳ τῆς ἐξόδου τῆς ἐς Θερμοπύλας εἰσὶν οἱ Ἀχαιοὶ δῆλοι μετεσχηκότες οὔτε Ἀθηναίοις ὁμοῦ καὶ Θεμιστοκλεῖ πρὸς Εὐβοίᾳ καὶ Σαλαμῖνι ναυμαχήσαντες, οὐδὲ σφᾶς κατάλογος συμμάχων ἔχει Λακωνικὸς ἢ Ἀττικός.", "st": "7.6"}, {"sp": "N", "t": "ὑστέρησαν δὲ καὶ ἔργου τοῦ Πλαταιᾶσι· δῆλα γὰρ δὴ ὅτι ἐπὶ τῷ ἀναθήματι τῷ ἐν Ὀλυμπίᾳ τῶν Ἑλλήνων μετῆν ἂν καὶ Ἀχαιοῖς γεγράφθαι. δοκεῖν δέ μοι τὰς πατρίδας τε ὑπολειφθέντες ἕκαστοι τὰς αὑτῶν ἔσωζον καὶ ἅμα διὰ τὸ ἔργον τὸ πρὸς Τροίαν Λακεδαιμονίους Δωριεῖς ἀπηξίουν σφίσιν ἡγεῖσθαι. ἐδήλωσαν δὲ καὶ ἀνὰ χρόνον· Λακεδαιμονίων γὰρ ἐς τὸν πρὸς Ἀθηναίους πόλεμον καταστάντων ὕστερον, ἐς τὴν συμμαχίαν ἦσαν οἱ Ἀχαιοὶ πρόθυμοι Πατρεῦσι, καὶ ἐς τοὺς Ἀθηναίους οὐχ ἧσσον εἶχον γνώμην.", "st": "7.6"}, {"sp": "N", "t": "πολέμων δὲ τῶν πολεμηθέντων ὕστερον ὑπὸ τοῦ Ἕλλησι κοινοῦ τοῦ μὲν ἐν Χαιρωνείᾳ Φιλίππου τε ἐναντία καὶ Μακεδόνων οἱ Ἀχαιοὶ μετέσχον, ἐς δὲ τὴν Θεσσαλίαν καὶ ἐπὶ τὸν πρὸς Λαμίᾳ καλούμενον πόλεμον οὔ φασιν ἐκστρατεύσασθαι, οὐ γάρ πω μετὰ τὸ πταῖσμα ἀνενηνοχέναι τὸ ἐν Βοιωτοῖς· ὁ δὲ τῶν ἐπιχωρίων Πατρεῦσιν ἐξηγητὴς τὸν παλαιστὴν Χίλωνα Ἀχαιῶν μόνον μετασχεῖν ἔφασκε τοῦ ἔργου ⟨τοῦ⟩ περὶ Λάμιαν.", "st": "7.6"}, {"sp": "N", "t": "οἶδα δὲ καὶ ἄνδρα αὐτὸς Λυδὸν Ἄδραστον ἰδίᾳ καὶ οὐκ ἀπὸ τοῦ κοινοῦ τοῦ Λυδῶν ἀμύναντα Ἕλλησι· τοῦ δὲ Ἀδράστου τούτου χαλκῆν εἰκόνα ἀνέθεσαν οἱ Λυδοὶ πρὸ ἱεροῦ Περσικῆς Ἀρτέμιδος, καὶ ἔγραψαν ἐπίγραμμα ὡς τελευτήσειεν ὁ Ἄδραστος ἐναντίον Λεοννάτῳ μαχόμενος ὑπὲρ Ἑλλήνων.", "st": "7.6"}, {"sp": "N", "t": "ἡ δὲ ἐς Θερμοπύλας ἐπὶ τὴν Γαλατῶν στρατιὰν ἔξοδος καὶ τοῖς πᾶσιν ὁμοίως παρώφθη Πελοποννησίοις· ἅτε γὰρ πλοῖα οὐκ ἐχόντων τῶν βαρβάρων, δεινὸν ἔσεσθαί σφισιν ἀπ’ αὐτῶν οὐδὲν ἤλπιζον, εἰ τὸν Κορινθίων ἰσθμὸν ἐκ θαλάσσης τῆς κατὰ Λέχαιον ἀποτειχίσειαν ἐς τὴν ἑτέραν τὴν ἐπὶ Κεγχρέαις θάλασσαν.", "st": "7.6"}, {"sp": "N", "t": "τοῦτο μὲν δὴ Πελοποννησίων ἦν τότε ἁπάντων βούλευμα· ἐπεὶ δὲ Γαλάται ναυσὶν ὅντινα δὴ τρόπον διαβεβήκεσαν ἐς τὴν Ἀσίαν, ἐνταῦθα εἶχεν οὕτω τὰ Ἑλλήνων. προεστήκεσαν κατ’ ἰσχὺν οὐδένες ἔτι τοῦ Ἑλληνικοῦ· Λακεδαιμονίους μὲν γὰρ τὸ ἐν Λεύκτροις πταῖσμα καὶ ἅμα οἵ τε Ἀρκάδες συνεληλυθότες ἐς Μεγάλην πόλιν καὶ οἱ Μεσσήνιοι παροικοῦντες ἀνασώσασθαι τὴν προτέραν ἔτι εὐδαιμονίαν ἐκώλυον·", "st": "7.6"}, {"sp": "N", "t": "Θηβαίοις δὲ ἐς τοσοῦτο ἠρήμωσεν Ἀλέξανδρος τὴν πόλιν, ὡς ἔτεσιν ὕστερον οὐ πολλοῖς καταχθέντας ὑπὸ Κασσάνδρου μηδὲ σώζειν τὰ οἰκεῖα ἀξιόχρεως εἶναι· Ἀθηναίοις δὲ εὔνοια μὲν παρὰ τοῦ Ἑλληνικοῦ τῶν ἔργων μάλιστα ὑπῆρχε τῶν ὕστερον, ἀναπαύσασθαι δὲ οὔ ποτε ἐκ τοῦ Μακεδόνων πολέμου παρῆν αὐτοῖς.", "st": "7.6"}, {"sp": "N", "t": "Ἑλλήνων δὲ οὐ τασσομένων τηνικαῦτα ἔτι ἐν κοινῷ, ἰδίᾳ δὲ ἑκάστων κατὰ σφᾶς συνισταμένων, οἱ Ἀχαιοὶ μάλιστα ἴσχυον· τυράννων τε γὰρ πλὴν Πελλήνης αἱ ἄλλαι πόλεις τὸν χρόνον ἅπαντα ἀπείρως ἐσχήκεσαν αἵ τε ἐκ πολέμων καὶ ἀπὸ τῆς νόσου συμφοραὶ τῆς λοιμώδους οὐκ ἐς τοσοῦτο Ἀχαιοῖς ἐφ’ ὅσον τοῖς ἄλλοις ἐγένοντο Ἕλλησι. συνέδριόν τε οὖν Ἀχαϊκὸν καλούμενον καὶ ἀπὸ κοινοῦ λόγου βουλεύματά τε ἦν Ἀχαιοῖς καὶ τὰ ἔργα.", "st": "7.7"}, {"sp": "N", "t": "ἀθροίζεσθαι δὲ ἐς Αἴγιόν σφισιν ἔδοξεν· αὕτη γὰρ μετὰ Ἑλίκην ἐπικλυσθεῖσαν πόλεων ἐν Ἀχαΐᾳ τῶν ἄλλων δόξῃ προεῖχεν ἐκ παλαιοῦ καὶ ἴσχυεν ἐν τῷ τότε. Ἑλλήνων δὲ τῶν λοιπῶν Σικυώνιοι συνεδρίου πρῶτοι τοῦ Ἀχαιῶν μετέσχον, μετὰ δὲ Σικυωνίους ἐσῄεσαν ἤδη καὶ τῶν ἄλλων Πελοποννησίων οἱ μὲν αὐτίκα, οἱ δὲ χρόνον τινὰ ἐπισχόντες· τοὺς δὲ καὶ ἐκτὸς οἰκοῦντας τοῦ ἰσθμοῦ συντελεῖν ἐς Ἀχαιοὺς ἔπειθεν, ὅτι ἐς πλέον ἰσχύος προϊὸν ἑώρων ἀεὶ τὸ Ἀχαϊκόν.", "st": "7.7"}, {"sp": "N", "t": "Λακεδαιμόνιοι δὲ Ἑλλήνων μόνοι διάφοροί τε Ἀχαιοῖς τὰ μάλιστα ἦσαν καὶ ἐκ τοῦ φανεροῦ πόλεμόν σφισιν ἐπῆγον. Πελλήνην μέν γε Ἀχαιῶν πόλιν Ἆγις εἷλεν ὁ Εὐδαμίδου βασιλεύων ἐν [τῇ] Σπάρτῃ, καὶ ἐξέπεσεν αὐτίκα ἐκ Πελλήνης ὑπὸ Ἀράτου καὶ Σικυωνίων· Κλεομένης δὲ ὁ Λεωνίδου τοῦ Κλεωνύμου, βασιλεὺς οἰκίας τῆς ἑτέρας, ἀντικαθημένους Ἄρατον καὶ Ἀχαιοὺς πρὸς Δύμῃ παρὰ πολύ τε ἐκράτησεν ἐλθόντας ἐς χεῖρας καὶ ὕστερον Ἀχαιοῖς καὶ Ἀντιγόνῳ συνέθετο εἰρήνην.", "st": "7.7"}, {"sp": "N", "t": "Ἀντίγονος δὲ οὗτος τηνικαῦτα ἀρχὴν τὴν Μακεδόνων εἶχεν, ἐπιτροπεύων Φίλιππον τὸν Δημητρίου παῖδα ἔτι ἡλικίαν ὄντα· ἦν δὲ καὶ ἀνεψιὸς τῷ Φιλίππῳ καὶ μητρὶ αὐτοῦ συνῴκει. πρὸς τοῦτον οὖν τὸν Ἀντίγονον καὶ Ἀχαιοὺς ποιησάμενος ὁ Κλεομένης σπονδὰς καὶ αὐτίκα παραβὰς ὅσα ὤμοσεν ἠνδραποδίσατο Ἀρκάδων Μεγάλην πόλιν· Λακεδαιμονίοις τε τὸ ἐν Σελλασίᾳ πταῖσμα πρὸς Ἀχαιοὺς καὶ Ἀντίγονον Κλεομένους ἕνεκα καὶ ἐπιορκίας τῆς ἐκείνου συνέβη. Κλεομένους μὲν δὴ καὶ αὖθις ἐν λόγοις τοῖς Ἀρκαδικοῖς ἀφιξόμεθα ἐς μνήμην·", "st": "7.7"}, {"sp": "N", "t": "Φίλιππος δὲ ὁ Δημητρίου τὴν Μακεδόνων ἀρχήν, ὡς ἀφίκετο ἐς ἄνδρας, παρὰ ἑκόντος Ἀντιγόνου λαβὼν φόβον τοῖς πᾶσιν Ἕλλησιν ἐνεποίησε, τὰ Φιλίππου τοῦ Ἀμύντου, προγόνου μὲν οὐκ ὄντος αὐτῷ, τῷ δὲ ἀληθεῖ λόγῳ δεσπότου, τά τε ἄλλα αὐτοῦ μιμούμενος καὶ τὰ ἐς θεραπείαν ὅσοις πατρίδας ἀρεστὰ ἦν ἐπ’ οἰκείοις προδιδόναι κέρδεσι. προπίνειν δὲ παρὰ τὰ συμπόσια ἐπὶ δεξιότητι καὶ φιλίᾳ κύλικας οὐκ οἴνου, φαρμάκων δὲ ἐς ὄλεθρον ἀνθρώποις, ἃ δὴ ὁ μὲν τοῦ Ἀμύντου Φίλιππος οὐδ’ ἐπενόησεν ἐμοὶ δοκεῖν ἀρχήν, Φιλίππῳ δὲ τῷ Δημητρίου τὰ φάρμακα τόλμημα ἦν ἐλαφρότατον.", "st": "7.7"}, {"sp": "N", "t": "κατεῖχε ⟨δὲ⟩ καὶ τρεῖς πόλεις φρουραῖς ὁρμητήρια εἶναί οἱ κατὰ τῆς Ἑλλάδος, καὶ ὠνόμαζε δὲ ὑπὸ τῆς ὕβρεως καὶ τῆς ἐς τὸ Ἑλληνικὸν ὑπεροψίας κλεῖς τῆς Ἑλλάδος τὰς πόλεις ταύτας· ἐπὶ μέν γε Πελοποννήσῳ Κόρινθος καὶ ἡ Κορινθίων ἀκρόπολις ἐτετείχιστο, ἐπὶ δὲ Εὐβοίᾳ καὶ Βοιωτοῖς τε καὶ Φωκεῦσι Χαλκὶς ἡ πρὸς τῷ Εὐρίπῳ, κατὰ δὲ Θεσσαλῶν τε αὐτῶν καὶ τοῦ Αἰτωλῶν ἔθνους Μαγνησίαν τὴν ὑπὸ τὸ Πήλιον κατεῖχεν ὁ Φίλιππος. μάλιστα δὲ Ἀθηναίους καὶ τὸ Αἰτωλικὸν ἐπιστρατείαις τε συνεχέσιν ἐπίεζε καὶ λῃστῶν καταδρομαῖς·", "st": "7.7"}, {"sp": "N", "t": "ἐμνημόνευσε δέ μοι καὶ πρότερον ὁ λόγος ἐν τῇ Ἀτθίδι συγγραφῇ, ὅσοι τε Ἑλλήνων ἢ βαρβάρων ἐναντία Φιλίππου συνήραντο Ἀθηναίοις καὶ ὡς ὑπὸ ἀσθενείας τῶν συμμάχων ἐπὶ Ῥωμαίους καὶ ἐπικουρίαν τὴν ἐκεῖθεν κατέφευγον οἱ Ἀθηναῖοι. Ῥωμαῖοι δὲ ἐπεπόμφεσαν καὶ οὐ πολλῷ τινι ἔμπροσθεν λόγῳ μὲν ἐπικουρήσοντας Αἰτωλοῖς ἐναντία Φιλίππου, τῷ δὲ ἔργῳ μᾶλλόν τι ἐπὶ κατασκοπῇ τῶν ἐν Μακεδονίᾳ πραγμάτων·", "st": "7.7"}, {"sp": "N", "t": "τότε δὲ ἀποστέλλουσιν Ἀθηναίοις στρατιάν τε καὶ ἡγεμόνα Ὀτίλιον· τοῦτο γάρ οἱ τῶν ὀνομάτων ἦν τὸ ἐκδηλότατον, ἐπεὶ καλοῦνταί γε οὐ πατρόθεν οἱ Ῥωμαῖοι κατὰ ταὐτὰ Ἕλλησιν, ἀλλὰ καὶ τρία ὁπότε ὀλίγιστα καὶ ἔτι πλέονα ὀνόματα ἑκάστῳ τίθενται. τῷ δὲ Ὀτιλίῳ προσετέτακτο ὑπὸ Ῥωμαίων ἀπείργειν ἀπὸ Ἀθηναίων καὶ τοῦ Αἰτωλικοῦ τὸν Φιλίππου πόλεμον.", "st": "7.7"}, {"sp": "N", "t": "Ὀτίλιος δὲ τὰ μὲν ἄλλα τοῖς πράγμασι κατὰ τὰ ἐπιτεταγμένα ἐχρῆτο, τάδε δὲ οὐ κατὰ γνώμην οἱ τὴν Ῥωμαίων ἐστὶν εἰργασμένα· Εὐβοέων γὰρ Ἑστίαιαν πόλιν καὶ Ἀντίκυραν τὴν ἐν τῇ Φωκίδι ἑλών, ὑπηκόους κατ’ ἀνάγκην οὔσας Φιλίππου, ἐποίησεν ἀναστάτους. καὶ τοῦδε ἕνεκα ἐμοὶ δοκεῖν, ἐπεὶ ἐπύθετο ἡ βουλή, ἀποστέλλουσιν Ὀτιλίῳ διάδοχον τῆς ἀρχῆς Φλαμίνιον.", "st": "7.7"}, {"sp": "N", "t": "τότε δὲ ἥκων ὁ Φλαμίνιος Ἐρέτριάν τε διήρπασε, τοὺς φρουροῦντας Μακεδόνων μάχῃ νικήσας, καὶ αὖθις ἐλάσας ἐπὶ Κόρινθον κατεχομένην ὑπὸ Φιλίππου φρουρᾷ αὐτός τε προσεκάθητο πολιορκῶν καὶ παρὰ Ἀχαιοὺς ἅμα ἀποστέλλων ἐπήγγελλέ σφισιν ἀφικνεῖσθαι πρὸς Κόρινθον στρατιᾷ, συμμάχους τε ἀξιωθησομένους καλεῖσθαι Ῥωμαίων καὶ ἅμα εὐνοίᾳ τῇ ἐς τὸ Ἑλληνικόν.", "st": "7.8"}, {"sp": "N", "t": "Ἀχαιοὶ δὲ ἐποιοῦντο μὲν μεγάλως καὶ αὐτὸν ἐν αἰτίᾳ Φλαμίνιον καὶ ἔτι πρότερον Ὀτίλιον, οἳ μετεχειρίσαντο ὠμῶς οὕτω πόλεις Ἑλληνίδας καὶ ἀρχαίας, ἀναμαρτήτους τε οὔσας πρὸς Ῥωμαίους καὶ οὐ κατὰ γνώμην ὑπὸ Μακεδόνων ἀρχομένας· προεωρῶντο δὲ καὶ ὡς ἀντὶ Φιλίππου καὶ Μακεδόνων Ῥωμαῖοι σφίσι τε ἥκοιεν καὶ τῷ Ἑλληνικῷ δεσπόται προστάττειν. ῥηθέντων δὲ ἐν τῷ συνεδρίῳ πολλῶν καὶ ἐναντίων ἀλλήλοις, τέλος οἱ εὖνοι Ῥωμαίοις ἐνίκησαν καὶ Ἀχαιοὶ Φλαμινίῳ Κόρινθον συνεπολιόρκησαν.", "st": "7.8"}, {"sp": "N", "t": "Κορίνθιοι δὲ ἀπὸ Μακεδόνων ἐλευθερωθέντες μετέσχον αὐτίκα συνεδρίου τοῦ Ἀχαιῶν, μετασχόντες καὶ πρότερον, ὅτε Ἄρατος καὶ Σικυώνιοι φρουρὰν ἐκ τοῦ Ἀκροκορίνθου τὴν πᾶσαν ἐξήλασαν καὶ ἀπέκτειναν Περσαῖον ὑπὸ Ἀντιγόνου ταχθέντα ἐπὶ τῇ φρουρᾷ. Ἀχαιοὶ δὲ τὸ ἀπὸ τούτου σύμμαχοί τε ὠνομάζοντο Ῥωμαίων καὶ ἐς τὰ πάντα ἦσαν πρόθυμοι· καί σφισιν εἵποντο μὲν ἐς Μακεδονίαν καὶ ἐπὶ Φίλιππον, μετέσχον δὲ καὶ στρατείας ἐς Αἰτωλούς, τρίτα δὲ ὁμοῦ Ῥωμαίοις ἐμαχέσαντο ἐναντία Ἀντιόχου καὶ Σύρων.", "st": "7.8"}, {"sp": "N", "t": "ὅσα μὲν δὴ Ἀχαιοὶ Μακεδόσιν ἢ στρατιᾷ τῇ Σύρων ἐναντία ἐτάξαντο, φιλίᾳ τῇ πρὸς Ῥωμαίους ἔπραξαν· ἐς δὲ Αἰτωλοὺς ἐκ παλαιοῦ σφισιν ἦν οἰκεῖα ἐγκλήματα. ἐπεὶ δὲ ἡ Νάβιδος ἐν Σπάρτῃ τυραννὶς κατελέλυτο, ἐς πλείστην ὠμότητα ἀνδρὸς ἀφικομένου, τὰ ἐς τοὺς Λακεδαιμονίους αὐτίκα ἐνεπεπτώκει·", "st": "7.8"}, {"sp": "N", "t": "καὶ σφᾶς ὑπὸ τὸν χρόνον οἱ Ἀχαιοὶ τοῦτον ἐς σύλλογον ὑπάγονται τὸν Ἀχαϊκὸν καὶ δίκας τε ἐδίκαζόν σφισιν ἐς τὸ ἀκριβέστατον καὶ τὰ τείχη τῆς Σπάρτης καταβάλλουσιν ἐς ἔδαφος, οἰκοδομηθέντα μὲν καὶ πρότερον ἔτι αὐτοσχεδίως [καὶ] ἐπί τε τῆς Δημητρίου καὶ ὕστερον τῆς Πύρρου καὶ Ἠπειρωτῶν στρατείας, ἐπὶ δὲ τῆς τυραννίδος τῆς Νάβιδος καὶ ἐς τὸ ἀσφαλέστατον ὀχυρωθέντα. τά τε οὖν τείχη τῆς Σπάρτης οἱ Ἀχαιοὶ καθεῖλον καὶ τὰ ἐς μελέτην τοῖς ἐφήβοις ἐκ τῶν Λυκούργου νόμων καταλύσαντες ἐπέταξαν τοῖς Ἀχαιῶν ἐφήβοις τὰ αὐτὰ ἐπιτηδεύειν.", "st": "7.8"}, {"sp": "N", "t": "ταῦτα μὲν δὴ καὶ ἐς πλέον ἐπέξεισιν αὖθίς μοι τὰ ἐς Ἀρκάδας· Λακεδαιμόνιοι δὲ ἅτε μεγάλως τοῖς ἐπιτάγμασιν ἀχθόμενοι τοῖς Ἀχαιῶν καταφεύγουσιν ἐπὶ Μέτελλον καὶ ὅσοι σὺν Μετέλλῳ κατὰ πρεσβείαν ἧκον ἐκ Ῥώμης. ἀφίκοντο δὲ οὗτοι Φιλίππῳ καὶ Μακεδόσι πόλεμον μὲν οὐδένα ἐπάξοντες ἅτε εἰρήνης πρότερον ἔτι Φιλίππῳ καὶ Ῥωμαίοις ὀμωμοσμένης, ὁπόσα δὲ ἢ Θεσσαλοῖς ἢ τῶν ἐξ Ἠπείρου τισὶν ἐγκλήματα ἦν ἐς Φίλιππον, ταῦτα ἧκον οἱ ὁμοῦ Μετέλλῳ κρινοῦντες.", "st": "7.8"}, {"sp": "N", "t": "ἔργῳ μὲν δὴ Φίλιππός τε αὐτὸς καὶ ἡ Μακεδόνων ἀκμὴ καθῄρητο ὑπὸ Ῥωμαίων—μαχεσάμενος γὰρ Φλαμινίου καὶ Ῥωμαίων ἐναντία Φίλιππος ἐν Κυνὸς καλουμέναις κεφαλαῖς [ἐν λόγοις] τὸ ἧττον ἠνέγκατο, ἀλλ’ ἅτε δὴ κατὰ δύναμιν ἀγωνισάμενος αὐτὸς οὗτος ὁ Φίλιππος τοσοῦτον ἐκρατήθη τῇ συμβολῇ, ὡς στρατιᾶς τε ἣν ἦγεν ἀποβαλεῖν τὸ πολὺ καὶ ἐκ τῶν πόλεων, ὅσας εἷλεν ἐν τῇ Ἑλλάδι πολέμῳ παραστησάμενος, ἐξήγαγεν ἐξ ἁπασῶν τὰς φρουρὰς κατὰ ὁμολογίαν πρὸς Ῥωμαίους—", "st": "7.8"}, {"sp": "N", "t": "κατὰ μέντοι τοῦ λόγου τὸ εὐπρεπὲς παρὰ Ῥωμαίων εὕρητο εἰρήνην δεήσεσί τε παντοίαις καὶ δαπάναις χρημάτων μεγάλαις. τὰ δὲ ἐς Μακεδόνας δύναμίν τε, ἣν ἐπὶ Φιλίππου περιεβάλοντο τοῦ Ἀμύντου, καὶ ὡς ἐπὶ Φιλίππου τοῦ ὑστέρου τὰ πράγματά σφισιν ἐφθάρη, Σίβυλλα οὐκ ἄνευ θεοῦ προεθέσπισεν· ἔχει δὲ οὕτω τὰ χρησθέντα·", "st": "7.8"}, {"sp": "N", "t": "αὐχοῦντες βασιλεῦσι Μακεδόνες Ἀργεάδῃσιν,<br>ὑμῖν κοιρανέων ἀγαθὸν καὶ πῆμα Φίλιππος.<br>ἤτοι ὁ μὲν πρότερος πόλεσιν λαοῖσί τ’ ἄνακτας<br>θήσει· ὁ δ’ ὁπλότερος τιμὴν ἀπὸ πᾶσαν ὀλέσσει,<br>δμηθεὶς ἑσπερίοισιν ὑπ’ ἀνδράσιν ἠῴοις τε.<br>Ῥωμαῖοί τε δὴ τὰ πρὸς ἑσπέραν νεμόμενοι τῆς Εὐρώπης καθεῖλον τὴν Μακεδόνων ἀρχὴν καὶ τῶν ἐς τὸ συμμαχικὸν ταχθέντων Ἄτταλος ⟨τῆς ἐκ Περγάμου συλλεχθείσης ἡγεμὼν⟩ καὶ ἔτι ἐκ Μυσίας στρατιᾶς· πρὸς δὲ ἀνίσχοντα ἥλιον μᾶλλόν τι ἡ Μυσία τέτραπται.", "st": "7.8"}, {"sp": "N", "t": "τότε δὲ τῷ Μετέλλῳ καὶ τῇ ἄλλῃ πρεσβείᾳ μὴ ὑπεριδεῖν Λακεδαιμονίων ἤρεσε καὶ Ἀχαιῶν, τοὺς δὲ τὰς ἀρχὰς ἔχοντας ἐς τὸ συνέδριον ἠξίουν συγκαλέσαι τοὺς Ἀχαιούς, ἵνα ἐν κοινῷ διδάξωσιν αὐτοὺς ἠπιώτερον μεταχειρίζεσθαι τὰ ἐν Λακεδαίμονι. οἱ δέ σφισιν ἀπεκρίναντο μήτε ἐκείνοις Ἀχαιοὺς ἐς σύλλογον μήτε ἄλλῳ συνάξειν, ὅστις μὴ ἐπὶ τῷ πράγματι ἐφ’ ὅτῳ ποιεῖται τὴν πρόσοδον παρὰ τῆς Ῥωμαίων βουλῆς ἔχει δόγμα. Μέτελλος δὲ καὶ οἱ σὺν αὐτῷ ὑπὸ τῶν Ἀχαιῶν περιυβρίσθαι νομίζοντες, ἐπειδὴ ἀφίκοντο ἐς Ῥώμην, πολλὰ ἐπὶ τῆς βουλῆς καὶ οὐ τὰ πάντα ἀληθῆ κατηγόρουν τῶν Ἀχαιῶν.", "st": "7.9"}, {"sp": "N", "t": "τούτων δὲ πλείονα ἐνεκάλουν Ἀχαιοῖς Ἀρεὺς καὶ Ἀλκιβιάδας, [ὡς] Λακεδαιμόνιοι μὲν καὶ δόκιμοι τὰ μάλιστα ἐν τῇ Σπάρτῃ, τὰ δὲ ἐς Ἀχαιοὺς οὐ δίκαιοι· γενομένους γὰρ ὑπὸ Νάβιδος φυγάδας ὑπεδέξαντο αὐτοὺς οἱ Ἀχαιοὶ καὶ ἀποθανόντος Νάβιδος παρὰ γνώμην Λακεδαιμονίων τοῦ δήμου κατάγουσιν ἐς Σπάρτην. τότε οὖν ἀναβεβηκότες καὶ οὗτοι παρὰ τὴν βουλὴν προθυμότατα ἐνέκειντο Ἀχαιοῖς· Ἀχαιοὶ δέ σφισιν ἀπελθοῦσιν ἐπιβάλλουσιν ἐν τῷ συνεδρίῳ θάνατον ζημίαν.", "st": "7.9"}, {"sp": "N", "t": "Ῥωμαίων δὲ ἡ βουλὴ πέμπουσιν ἄλλους τε ἄνδρας καὶ Ἄππιον Λακεδαιμονίοις καὶ Ἀχαιοῖς τὰ δίκαια ὁρίσαι. Ἄππιος δὲ καὶ οἱ σὺν αὐτῷ ἔμελλον μὲν οὐδὲ ὀφθέντες Ἀχαιοῖς ἔσεσθαι καθ’ ἡδονήν, οἳ Ἀρέα καὶ Ἀλκιβιάδαν ἅμ’ αὐτοῖς ἐπήγοντο ἐν τῷ τότε Ἀχαιοῖς ἐχθίστους· ἐλύπησαν δὲ καὶ ἐς πλέον τοὺς Ἀχαιούς, ἐπειδὴ ἐς τὸν σύλλογον αὐτῶν ἐπελθόντες σὺν ὀργῇ μᾶλλον ἐποιοῦντο ἢ πειθοῖ τοὺς λόγους.", "st": "7.9"}, {"sp": "N", "t": "Λυκόρτας δὲ ὁ Μεγαλοπολίτης, οὔτε ἀξιώματι οὐδενὸς Ἀρκάδων ὕστερος καί τι καὶ φρόνημα κατὰ φιλίαν προσειληφὼς τὴν Φιλοποίμενος, λόγῳ τε ἀπέφαινε τὰ ὑπὲρ τῶν Ἀχαιῶν δίκαια καὶ ὁμοῦ τοῖς λόγοις καὶ μέμψιν τινὰ ὑπέτεινεν ἐς τοὺς Ῥωμαίους. Ἄππιος δὲ καὶ οἱ σὺν αὐτῷ Λυκόρταν λέγοντα ἐποιοῦντο ἐν χλευασμῷ καὶ Ἀρέως ἀποψηφίζονται καὶ Ἀλκιβιάδα μηδὲν ἀδίκημα ἐξ αὐτῶν ἐς Ἀχαιοὺς εἶναι, Λακεδαιμονίοις τε ἀποστεῖλαι πρέσβεις ἐφιᾶσιν ἐς Ῥώμην, ἐναντία ἐφιέντες ἢ Ῥωμαίοις συγκείμενα ἦν καὶ Ἀχαιοῖς· Ἀχαιῶν μὲν γὰρ εἴρητο ἀπὸ τοῦ κοινοῦ παρὰ τὴν Ῥωμαίων βουλὴν ἀπιέναι πρέσβεις, ἰδίᾳ δὲ ἀπείρητο μὴ πρεσβεύεσθαι τὰς πόλεις ὅσαι συνεδρίου τοῦ Ἀχαιῶν μετεῖχον.", "st": "7.9"}, {"sp": "N", "t": "ἀντιπρεσβευσαμένων δὲ καὶ Ἀχαιῶν Λακεδαιμονίοις καὶ λόγων ῥηθέντων ὑπὸ ἀμφοτέρων ἐπὶ τῆς βουλῆς, τοὺς αὐτοὺς ἀποστέλλουσιν αὖθις οἱ Ῥωμαῖοι Λακεδαιμονίοις γενέσθαι καὶ Ἀχαιοῖς δικαστάς, Ἄππιον καὶ ὅσοι σὺν ἐκείνῳ πρότερον ἐς τὴν Ἑλλάδα ἀφίκοντο. οἱ δὲ τούς τε ἐκβληθέντας ὑπὸ Ἀχαιῶν κατάγουσιν ἐς Σπάρτην καὶ ὅσων πρὸ κρίσεως ἀπελθόντων κατέγνωστο ὑπὸ τῶν Ἀχαιῶν ἀδικεῖν, καὶ τὰ ἐπὶ τούτοις τιμήματα ἔλυσαν· καὶ συντελείας μὲν Λακεδαιμονίους ⟨τῆς⟩ ἐς τὸ Ἀχαϊκὸν οὐκ ἀφιᾶσι, περὶ δὲ τῇ ἑκάστου ψυχῇ ξενικά σφισι διδόασιν εἶναι δικαστήρια, ὅσα δὲ ἄλλα ἐγκλήματα, λαμβάνειν τε αὐτοὺς καὶ ἐν τῷ Ἀχαϊκῷ ὑπέχειν τὰς κρίσεις. ἐτειχίσθη δὲ καὶ ἐξ ἀρχῆς αὖθις Σπαρτιάταις ὁ κύκλος τοῦ ἄστεως.", "st": "7.9"}, {"sp": "N", "t": "Λακεδαιμονίων δὲ οἱ κατελθόντες, βουλεύοντες παντοῖα ἐπὶ Ἀχαιοῖς, λυπήσειν σφᾶς ἐπὶ τοιῷδε μάλιστα ἤλπιζον. Μεσσηνίους τοὺς Φιλοποίμενι θανάτου συναιτίους γενέσθαι νομισθέντας καὶ κατὰ ⟨τὴν⟩ αἰτίαν ταύτην ὑπὸ Ἀχαιῶν ἐκπεπτωκότας, τούτους τε καὶ Ἀχαιῶν αὐτῶν τοὺς φεύγοντας ἀναβῆναι πείθουσιν ἐς Ῥώμην· σὺν δέ σφισιν ἀνεληλυθότες καὶ αὐτοὶ γενέσθαι τοῖς ἀνδράσιν ἔπρασσον κάθοδον. ἅτε δὲ τοῦ Ἀππίου Λακεδαιμονίοις συμπροθυμουμένου μεγάλως, Ἀχαιοῖς δὲ ἐπὶ παντὶ ἀντιβαίνοντος, ἔμελλεν οὐ χαλεπῶς Μεσσηνίων καὶ Ἀχαιῶν τοῖς φεύγουσι τὰ βουλεύματα ἐς δέον χωρήσειν· γράμματά τε αὐτίκα ὑπὸ τῆς βουλῆς ἔς τε Ἀθήνας κατεπέμπετο καὶ ἐς Αἰτωλίαν κατάγειν σφᾶς Μεσσηνίους καὶ Ἀχαιοὺς ἐπὶ τὰ οἰκεῖα.", "st": "7.9"}, {"sp": "N", "t": "τοῦτο Ἀχαιοὺς ἐς τὰ μάλιστα ἠνίασεν, ὡς οὔτε ἄλλως πάσχοντας δίκαια ὑπὸ Ῥωμαίων καὶ ἐς τὸ ἀνωφελὲς προϋπηργμένων σφίσιν ἐς αὐτούς, οἳ ἐπὶ τὰ Φιλίππου καὶ Αἰτωλῶν ἐναντία καὶ αὖθις Ἀντιόχου στρατεύσαντες χάριτι ⟨τῇ⟩ ἐς Ῥωμαίους ἐγίνοντο ὕστεροι φυγάδων ἀνθρώπων καὶ οὐ καθαρῶν χεῖρας· ὅμως δὲ εἴκειν σφίσιν ἐδόκει.", "st": "7.9"}, {"sp": "N", "t": "τότε μὲν δὴ ἐς τοσοῦτο ἐπράχθη· τολμημάτων δὲ τὸ ἀνοσιώτατον, τὴν πατρίδα καὶ ἄνδρας προδιδόναι πολίτας ἐπὶ οἰκείοις κέρδεσιν, ἔμελλε καὶ Ἀχαιοῖς κακῶν ἄρξειν, οὔποτε ἐκ τοῦ χρόνου παντὸς τὴν Ἑλλάδα ἐκλιπόν. ἐπὶ μέν γε Δαρείου τοῦ Ὑστάσπου βασιλεύοντος Περσῶν Ἴωσι τὰ πράγματα ἐφθάρη Σαμίων πλὴν ἑνός τε καὶ δέκα ἀνδρῶν τῶν ἄλλων τριηράρχων τὸ ναυτικὸν τὸ Ἰώνων προδόντων·", "st": "7.10"}, {"sp": "N", "t": "μετὰ δὲ Ἴωνας κεχειρωμένους ἠνδραποδίσαντο καὶ Ἐρέτριαν Μῆδοι, προδόται δὲ ἐγένοντο οἱ εὐδοκιμοῦντες μάλιστα ἐν Ἐρετρίᾳ Φίλαγρος Κυνέου καὶ Εὔφορβος Ἀλκιμάχου. Ξέρξῃ δὲ ἐπὶ τὴν Ἑλλάδα ἐλαύνοντι Θεσσαλία τε δι’ Ἀλευάδου προεδόθη, Θήβας δὲ Ἀτταγῖνος καὶ Τιμηγενίδας προδιδόασι φερόμενοι τὰ πρῶτα ἐν Θήβαις. Πελοποννησίων δὲ καὶ Ἀθηναίων πολεμησάντων Ξενίας Ἠλεῖος ἐπεχείρησεν Ἦλιν Λακεδαιμονίοις καὶ Ἄγιδι προδοῦναι, οἵ τε Λυσάνδρου καλούμενοι ξένοι χρόνον", "st": "7.10"}, {"sp": "N", "t": "οὐδένα ἀνίεσαν πατρίδας ἐγχειρίζοντες Λυσάνδρῳ τὰς ἑαυτῶν. κατὰ δὲ τὴν Φιλίππου βασιλείαν τοῦ Ἀμύντου Λακεδαίμονα πόλεων μόνην οὐ προδοθεῖσαν τῶν ἐν Ἕλλησιν εὕροι τις ἄν· αἱ δὲ ἄλλαι πόλεις αἱ ἐν τῇ Ἑλλάδι ὑπὸ προδοσίας μᾶλλον ἢ ὑπὸ νόσου πρότερον τῆς λοιμώδους ἐφθάρησαν. Ἀλεξάνδρῳ δὲ τῷ Φιλίππου παρέσχεν ἡ εὐτυχία μικρὰ ἀνδρῶν προδοτῶν καὶ οὐκ ἄξια λόγου προσδεηθῆναι.", "st": "7.10"}, {"sp": "N", "t": "ἐπεὶ δὲ τὸ ἐν Λαμίᾳ πταῖσμα ἐγένετο Ἕλλησιν, Ἀντίπατρος μέν, ἅτε διαβῆναι ποιούμενος σπουδὴν πρὸς τὸν ἐν τῇ Ἀσίᾳ πόλεμον, ἐβούλετο εἰρήνην ἐν τάχει συντίθεσθαι, καί οἱ διέφερεν οὐδὲν εἰ Ἀθήνας τε ἐλευθέραν καὶ τὴν πᾶσαν Ἑλλάδα ἀφήσει· Δημάδης δὲ καὶ ὅσον προδοτῶν Ἀθήνῃσιν ἄλλο ἦν, ἀναπείθουσιν Ἀντίπατρον μηδὲν ἐς Ἕλληνας φρονῆσαι φιλάνθρωπον, ἐκφοβήσαντες δὲ Ἀθηναίων τὸν δῆμον ἔς τε Ἀθήνας καὶ πόλεων τῶν ἄλλων τὰς πολλὰς ἐγένοντο αἴτιοι Μακεδόνων ἐσαχθῆναι φρουράς.", "st": "7.10"}, {"sp": "N", "t": "βεβαιοῖ δέ μοι καὶ τόδε τὸν λόγον· Ἀθηναῖοι γὰρ μετὰ τὸ ἀτύχημα τὸ ἐν Βοιωτοῖς οὐκ ἐγένοντο Φιλίππου κατήκοοι, ἁλόντων μέν σφισι δισχιλίων, ὡς ἐκρατήθησαν, παρὰ τὸ ἔργον, χιλίων δὲ φονευθέντων· ἐν Λαμίᾳ δὲ περὶ διακοσίους πεσόντων καὶ οὐ πλέον τι, Μακεδόσιν ἐδουλώθησαν. οὕτω μὲν οὔποτε τὴν Ἑλλάδα ἐπέλειπον οἱ ἐπὶ προδοσίᾳ νοσήσαντες· Ἀχαιοὺς δὲ ἀνὴρ Ἀχαιὸς Καλλικράτης τηνικαῦτα ἐς ἅπαν ἐποίει Ῥωμαίοις ὑποχειρίους. ἀρχὴ δέ σφισιν ἐγίνετο κακῶν Περσεὺς καὶ ἡ Μακεδόνων ἀρχὴ καταλυθεῖσα ὑπὸ Ῥωμαίων.", "st": "7.10"}, {"sp": "N", "t": "Περσεῖ τῷ Φιλίππου πρὸς Ῥωμαίους ἄγοντι εἰρήνην κατὰ συνθήκας, ἃς ὁ πατήρ οἱ Φίλιππος ἐποιήσατο, ἐπῆλθεν ὑπερβῆναι τοὺς ὅρκους καὶ ἐπί τε ⟨Σαπαίους καὶ⟩ Σαπαίων τὸν βασιλέα Ἀβρούπολιν στράτευμα ἀγαγὼν ἐποίησεν ἀναστάτους Ῥωμαίων συμμάχους ὄντας· Σαπαίων δὲ τούτων καὶ Ἀρχίλοχος ἐν ἰάμβῳ μνήμην ἔσχε.", "st": "7.10"}, {"sp": "N", "t": "Μακεδόνων δὲ καὶ Περσέως κεχειρωμένων πολέμῳ διὰ τὸ ἐς Σαπαίους ἀδίκημα, ἄνδρες τῆς Ῥωμαίων βουλῆς δέκα ἐπέμφθησαν καταστησόμενοι πρὸς τὸ ἐπιτηδειότατον Ῥωμαίοις τὰ ἐν Μακεδονίᾳ. ἥκοντας δὲ ἐς τὴν Ἑλλάδα ὑπήρχετο ὁ Καλλικράτης οὔτε ἔργον τῶν ἐς τὴν κολακείαν οὔτε λόγον οὐδένα ἐς αὐτοὺς παριείς· ἕνα δέ τινα ἐξ αὐτῶν ἄνδρα οὐδαμῶς ἐς δικαιοσύνην πρόθυμον, τοῦτον τὸν ἄνδρα προσεποιήσατο ὁ Καλλικράτης ἐς τοσοῦτον ὥστε αὐτὸν καὶ ἐς τὸ συνέδριον ἐσελθεῖν τὸ Ἀχαιῶν ἔπεισεν.", "st": "7.10"}, {"sp": "N", "t": "ὁ δὲ ὡς ἐς τὸν σύλλογον ἐσῆλθεν, ἔλεγεν ὡς πολεμοῦντι πρὸς Ῥωμαίους Περσεῖ χρήματα οἱ δυνατώτατοι τῶν Ἀχαιῶν παράσχοιεν, συνάραιντο δὲ καὶ ἐς τὰ ἄλλα· ἐκέλευσεν οὖν καταγνῶναι τοὺς Ἀχαιοὺς θάνατον· εἰ δὲ ἐκεῖνοι καταγνοῖεν, τότε καὶ αὐτὸς τὰ ὀνόματα ἐρεῖν ἔφασκε τῶν ἀνδρῶν. λέγειν τε δὴ ἐδόκει παντάπασιν ἄδικα καὶ αὐτὸν ἠξίουν οἱ ἐς τὸν σύλλογον ἐληλυθότες ἤδη, εἰ Περσεῖ τὰ αὐτὰ Ἀχαιῶν τινες ἔπραξαν, ὀνομαστὶ αὐτῶν ἑκάστου μνησθῆναι, πρότερον δὲ οὐ σφᾶς καταγινώσκειν εἰκὸς εἶναι.", "st": "7.10"}, {"sp": "N", "t": "ἔνθα δὴ ὡς ἠλέγχετο ὁ Ῥωμαῖος, ἀπετόλμησεν εἰπεῖν ὡς οἱ ἐστρατηγηκότες Ἀχαιῶν ἐνέχονται πάντες τῇ αἰτίᾳ· πάντας γὰρ φρονῆσαι τὰ Μακεδόνων τε καὶ Περσέως. ὁ μὲν δὴ ταῦτα ἔλεγεν ὑπὸ διδασκαλίᾳ Καλλικράτους· ἀναστὰς δὲ μετ’ αὐτὸν Ξένων—⟨ἦν δὲ ὁ Ξένων⟩ οὗτος οὐκ ἐλαχίστου λόγου παρὰ Ἀχαιοῖς— “οὕτως” ἔφη “κατὰ τὴν αἰτίαν ἔχει ταύτην· ἐστρατήγησα μὲν Ἀχαιῶν καὶ ἐγώ, ἀδικίας δὲ οὐδὲν ἐς Ῥωμαίους οὔτε εὐνοίας μοι μέτεστιν ἐς Περσέα· καὶ τοῦδε ἕνεκα ἐθέλω μὲν ἐν συνεδρίῳ τῷ Ἀχαιῶν, ἐθέλω δὲ καὶ ἐν αὐτοῖς Ῥωμαίοις ὑπέχειν κρίσιν.” ὁ μὲν δὴ ὑπὸ συνειδότος ἐπαρρησιάζετο ἀγαθοῦ·", "st": "7.10"}, {"sp": "N", "t": "ὁ δὲ ἐπελάβετο αὐτίκα ὁ Ῥωμαῖος τῆς προφάσεως, καὶ ὁπόσοις Καλλικράτης ἐπῆγεν αἰτίαν Περσεῖ σφᾶς φρονῆσαι τὰ αὐτά, ἀνέπεμπεν ἐν δικαστηρίῳ κρίσιν τῷ Ῥωμαίων ὑφέξοντας. ὃ μή πω κατειλήφει πρότερον Ἕλληνας· οὐδὲ γὰρ [παρὰ] Μακεδόνων οἱ ἰσχύσαντες μέγιστον, Φίλιππος Ἀμύντου καὶ Ἀλέξανδρος, τοὺς ἀνθεστηκότας σφίσιν Ἑλλήνων ἐς Μακεδονίαν ἐβιάσαντο ἀποσταλῆναι, διδόναι δὲ αὐτοὺς ἐν Ἀμφικτύοσιν εἴων λόγον.", "st": "7.10"}, {"sp": "N", "t": "τότε δὲ ἐκ τοῦ Ἀχαιῶν ἔθνους ὅντινα καὶ ἀναίτιον Καλλικράτης ἐθελήσειεν αἰτιάσασθαι, ἀνάγεσθαι πάντα τινὰ ἐκεκύρωτο ἐς Ῥώμην· καὶ ἐγένοντο ὑπὲρ χιλίους οἱ ἀναχθέντες. τούτους ὑπὸ Ἀχαιῶν οἱ Ῥωμαῖοι προκατεγνῶσθαι νομίζοντες ἔς τε Τυρσηνίαν καὶ ἐς τὰς ἐκεῖ διέπεμψαν πόλεις, καὶ Ἀχαιῶν ἄλλοτε ἄλλας ὑπὲρ τῶν ἀνδρῶν πρεσβείας τε καὶ ἱκεσίας ἐπιπεμπόντων λόγον ἐποιοῦντο οὐδένα.", "st": "7.10"}, {"sp": "N", "t": "ἑπτακαιδεκάτῳ δὲ ὕστερον ἔτει τριακοσίους ἢ καὶ ἐλάσσονας, οἳ μόνοι περὶ Ἰταλίαν Ἀχαιῶν ἔτι ἐλείποντο, ἀφιᾶσιν, ἀποχρώντως κολασθῆναι σφᾶς ἡγούμενοι. ὅσοι δὲ ἀποδράντες ᾤχοντο ἢ εὐθὺς ἡνίκα ἀνήγοντο ἐς Ῥώμην ἢ ὕστερον ἐκ τῶν πόλεων ἐς ἃς ὑπὸ Ῥωμαίων ἐπέμφθησαν, πρόφασις οὐδεμία ἦν τούτους ἁλόντας ⟨μὴ⟩ ὑποσχεῖν δίκην.", "st": "7.10"}, {"sp": "N", "t": "Ῥωμαῖοι δὲ αὖθις ἄνδρα ἐκ τῆς βουλῆς καταπέμπουσιν ἐς τὴν Ἑλλάδα· ὄνομα μὲν τῷ ἀνδρὶ ἦν Γάλλος, ἀπέσταλτο δὲ Λακεδαιμονίοις καὶ Ἀργείοις ὑπὲρ γῆς ἀμφισβητουμένης γενέσθαι δικαστής. οὗτος ὁ Γάλλος ἐς τὸ Ἑλληνικὸν πολλὰ μὲν εἶπε, πολλὰ δὲ καὶ ἔπραξεν ὑπερήφανα, Λακεδαιμονίους δὲ καὶ Ἀργείους τὸ παράπαν ἔθετο ἐν χλευασίᾳ·", "st": "7.11"}, {"sp": "N", "t": "πόλεσι γὰρ ἐς τοσοῦτο ἡκούσαις ἀξιώματος καὶ ὑπὲρ τῶν ὅρων τῆς χώρας τὰ μὲν παλαιότερα ἐς οὐκ ἀφανῆ πόλεμον καὶ ἔργα οὕτως ἀφειδῆ προαχθείσαις, κριθείσαις δὲ καὶ ὕστερον παρὰ δικαστῇ κοινῷ Φιλίππῳ τῷ Ἀμύντου, αὐτὸς μέν σφισιν ὁ Γάλλος ἀπηξίωσε δικαστὴς καταστῆναι, Καλλικράτει δὲ ἁπάσης τῆς Ἑλλάδος ἀνδρὶ ἀλάστορι ἐπιτρέπει τὴν κρίσιν.", "st": "7.11"}, {"sp": "N", "t": "ἀφίκοντο δὲ ὡς τὸν Γάλλον καὶ Αἰτωλῶν οἱ Πλευρῶνα οἰκοῦντες, συντελείας τῆς ἐς Ἀχαιοὺς ἐθέλοντες ἄφεσιν εὕρασθαι· καὶ αὐτοῖς ἐπετράπη μὲν ὑπὸ τοῦ Γάλλου πρεσβείαν ἐπὶ σφῶν αὐτῶν ἰδίᾳ παρὰ Ῥωμαίους ἀποστεῖλαι, ἐπετράπη δὲ ὑπὸ Ῥωμαίων συνεδρίου ⟨τοῦ⟩ Ἀχαιῶν ἀποστῆναι. προσεπεστάλη δὲ ὑπὸ τῆς βουλῆς τῷ Γάλλῳ πόλεις ὁπόσας ἐστὶν οἷός τε [ὡς] πλείστας ἀφεῖναι συλλόγου τοῦ Ἀχαιῶν.", "st": "7.11"}, {"sp": "N", "t": "ὁ μὲν δὴ τὰ ἐντεταλμένα ἐποίει, Ἀθηναίων δὲ ὁ δῆμος ἀνάγκῃ πλέον ἢ ἑκουσίως διαρπάζουσιν Ὠρωπὸν ὑπήκοόν σφισιν οὖσαν· πενίας γὰρ ἐς τὸ ἔσχατον Ἀθηναῖοι τηνικαῦτα ἧκον ἅτε ὑπὸ Μακεδόνων πολέμῳ πιεσθέντες μάλιστα Ἑλλήνων. καταφεύγουσιν οὖν ἐπὶ τὴν Ῥωμαίων βουλὴν οἱ Ὠρώπιοι· καὶ δόξαντες παθεῖν οὐ δίκαια, [καὶ] ἐπεστάλη Σικυωνίοις ὑπὸ τῆς βουλῆς ἐπιβάλλειν σφᾶς Ἀθηναίοις ἐς Ὠρωπίους ζημίαν κατὰ τῆς βλάβης ἧς ἦρξαν τὴν ἀξίαν.", "st": "7.11"}, {"sp": "N", "t": "Σικυώνιοι μὲν οὖν οὐκ ἀφικομένοις ἐς καιρὸν τῆς κρίσεως Ἀθηναίοις ζημίαν πεντακόσια τάλαντα ἐπιβάλλουσι, Ῥωμαίων δὲ ἡ βουλὴ δεηθεῖσιν Ἀθηναίοις ἀφίησι πλὴν ταλάντων ἑκατὸν τὴν ἄλλην ζημίαν· ἐξέτισαν δὲ οὐδὲ ταῦτα οἱ Ἀθηναῖοι, ἀλλὰ ὑποσχέσεσι καὶ δώροις ὑπελθόντες Ὠρωπίους ὑπάγονται σφᾶς ἐς ὁμολογίαν φρουράν τε Ἀθηναίων ἐσελθεῖν ἐς Ὠρωπὸν καὶ ὁμήρους λαβεῖν παρὰ Ὠρωπίων Ἀθηναίους· ἢν δὲ αὖθις ἐς Ἀθηναίους γένηται ἔγκλημα Ὠρωπίοις, τὴν φρουρὰν τότε ἀπάγειν παρ’ αὐτῶν Ἀθηναίους, ἀποδοῦναι δὲ καὶ ὀπίσω τοὺς ὁμήρους.", "st": "7.11"}, {"sp": "N", "t": "χρόνος τε δὴ οὐ πολὺς ὁ μεταξὺ ἤνυστο, καὶ τῶν φρουρῶν ἀδικοῦσιν ἄνδρες Ὠρωπίους. οἱ μὲν δὴ ἐς τὰς Ἀθήνας ἀπέστελλον ὁμήρους τε ἀπαιτήσοντας καὶ φρουράν σφισιν ἐξάγειν κατὰ τὰ συγκείμενα ἐροῦντας· Ἀθηναῖοι δὲ οὐδέτερα ἔφασαν ποιήσειν, ἀνθρώπων γὰρ ⟨τῶν⟩ ἐπὶ τῇ φρουρᾷ καὶ οὐ τοῦ Ἀθηναίων δήμου τὸ ἁμάρτημα εἶναι· τοὺς μέντοι αὐτὰ εἰργασμένους ἐπηγγέλλοντο ὑφέξειν δίκην.", "st": "7.11"}, {"sp": "N", "t": "οἱ δὲ Ὠρώπιοι καταφεύγοντες ἐπὶ Ἀχαιοὺς ⟨ἐδέοντο⟩ τιμωρῆσαί σφισιν· Ἀχαιοῖς δὲ ἤρεσκε μὴ τιμωρεῖν φιλίᾳ τε καὶ αἰδοῖ τῇ Ἀθηναίων. ἐνταῦθα οἱ Ὠρώπιοι Μεναλκίδᾳ, Λακεδαιμονίῳ μὲν γένος, στρατηγοῦντι δὲ ἐν τῷ τότε Ἀχαιῶν, ὑπισχνοῦνται δέκα ταλάντων δόσιν, ἤν σφισιν ἐπικουρεῖν Ἀχαιοὺς ἄγῃ· ὁ δὲ ἀπὸ τῶν χρημάτων μεταδώσειν Καλλικράτει τὸ ἥμισυ ὑπισχνεῖτο, ἰσχύοντι διὰ φιλίαν τὴν Ρωμαίων ἐν Ἀχαιοῖς μέγιστον.", "st": "7.11"}, {"sp": "N", "t": "προσγενομένου δὲ τοῦ Καλλικράτους πρὸς τὴν Μεναλκίδου γνώμην ἐκεκύρωτο κατὰ Ἀθηναίων ἀμύνειν Ὠρωπίοις. καί τις ἐξαγγέλλει ταῦτα ἐς τοὺς Ἀθηναίους· οἱ δὲ ὡς ἕκαστος τάχους εἶχεν ἐς τὸν Ὠρωπὸν ἐλθόντες καὶ αὖθις κατασύραντες εἴ τι ἐν ταῖς προτέραις παρεῖτό σφισιν ἁρπαγαῖς, ἀπάγουσι τὴν φρουράν. Ἀχαιοὺς δὲ ὑστερήσαντας τῆς βοηθείας Μεναλκίδας μὲν καὶ Καλλικράτης ἐσβάλλειν ἐς τὴν Ἀττικὴν ἔπειθον· ἀνθισταμένων δὲ ἄλλων τε αὐτοῖς καὶ οὐχ ἥκιστα τῶν ἐκ Λακεδαίμονος, ἀνεχώρησεν ὀπίσω τὸ στράτευμα.", "st": "7.11"}, {"sp": "N", "t": "Ὠρώπιοι δὲ καὶ ὠφελείας σφίσιν οὐ γενομένης τῆς παρὰ Ἀχαιῶν, ὅμως ὑπὸ Μεναλκίδα τὰ χρήματα ἐξεπράχθησαν· ὁ δὲ ὡς τὸ δωροδόκημα εἶχεν ἐν χειρί, ἐποιεῖτο συμφορὰν εἰ καὶ Καλλικράτει μεταδώσει τῶν λημμάτων. τὰ μὲν δὴ πρῶτα ἀναβολαῖς καὶ ἀπάταις ἐχρῆτο ἐς τὴν δόσιν, μετὰ δὲ οὐ πολὺ ἐτόλμησεν ἀποστερεῖν ἐκ τοῦ εὐθέος.", "st": "7.12"}, {"sp": "N", "t": "βεβαιοῖ δὴ τὸ λεγόμενον ὡς ἄρ’ ἦν καὶ πῦρ ἐς πλέον ἄλλου πυρὸς καῖον καὶ λύκος ἀγριώτερος λύκων ἄλλων καὶ ὠκύτερος ἱέραξ ἱέρακος πέτεσθαι, εἴγε καὶ Καλλικράτην ἀνοσιώτατον τῶν τότε Μεναλκίδας [μὲν] ὑπερῆρεν ἀπιστίᾳ, Καλλικράτην, ὃς ἐλάσσων παντοίου λήμματος καὶ ἐπὶ οὐδενὶ οἰκείῳ κέρδει πόλει τῇ Ἀθηναίων ἀπηχθημένος παυσάμενον [μὲν] τῆς ἀρχῆς Μεναλκίδαν ἐδίωκεν ἐν τοῖς Ἀχαιοῖς θανάτου δίκην· πρεσβεῦσαί τε γὰρ Ἀχαιῶν ἐναντία ἔφασκεν αὐτὸν ἐς Ῥώμην καὶ ἐς τὰ μάλιστα γενέσθαι πρόθυμον ἐξελέσθαι τὴν Σπάρτην συνεδρίου τοῦ Ἀχαιῶν.", "st": "7.12"}, {"sp": "N", "t": "ἐνταῦθα ὡς ἀφικνεῖτο ἐς πᾶν ὁ Μεναλκίδας κινδύνου, μεταδίδωσι τάλαντα τρία τῶν ἐξ Ὠρωποῦ Μεγαλοπολίτῃ Διαίῳ. ἐγεγόνει δὲ αὐτῷ καὶ ἀρχῆς διάδοχος τῆς Ἀχαιῶν ὁ Δίαιος· τότε δὲ ὑπὲρ τοῦ λήμματος προθυμούμενος ἔμελλε Μεναλκίδᾳ καὶ ἀκόντων Ἀχαιῶν σωτηρίαν παρέξειν. Ἀχαιοὶ δὲ ἐπὶ μὲν τῇ ἀφέσει τοῦ Μεναλκίδα ἰδίᾳ τε ἕκαστος καὶ ἐν κοινῷ Δίαιον ἐποιοῦντο ἐν αἰτίᾳ· Δίαιος δὲ σφᾶς ἀπὸ τῶν ἐς αὐτὸν ἐγκλημάτων μετῆγεν ἐς πραγμάτων ἐλπίδα μειζόνων, προφάσει χρώμενος τοιᾷδε ἐς τὴν ἀπάτην.", "st": "7.12"}, {"sp": "N", "t": "Λακεδαιμόνιοι περὶ ἀμφισβητησίμου χώρας καταφεύγουσιν ἐπὶ τὴν Ῥωμαίων βουλήν· καταφεύγουσι δὲ αὐτοῖς προεῖπεν ἡ βουλὴ δικάζεσθαι τὰ ἄλλα πλὴν ψυχῆς ἐν συνεδρίῳ τῷ Ἀχαιῶν. ἡ μὲν δὴ ταῦτα ἀπεκρίνατο· Δίαιος δὲ οὐ τὸν ὄντα ἔλεγεν Ἀχαιοῖς λόγον, ψυχαγωγῶν δὲ αὐτοὺς ἔφασκε παρὰ τῆς Ῥωμαίων σφίσιν ἐφεῖσθαι βουλῆς καὶ θάνατον ἀνδρὸς καταγνῶναι τῶν ἐκ Σπάρτης.", "st": "7.12"}, {"sp": "N", "t": "οἱ μὲν δὴ δικάζειν Λακεδαιμονίοις ἠξίουν καὶ ὑπὲρ τῆς ἑκάστου ψυχῆς, Λακεδαιμόνιοι δὲ οὔτε ἀληθῆ συνεχώρουν Δίαιον λέγειν καὶ ἀνάγειν ἤθελον ἐπὶ τὴν Ῥωμαίων βουλήν. Ἀχαιοὶ δὲ ἀντελαμβάνοντο αὖθις ἄλλου λόγου, πόλεις ὅσαι τελοῦσιν ἐς Ἀχαιοὺς μηδεμίαν ἐφ’ ἑαυτῆς καθεστηκέναι κυρίαν ἄνευ τοῦ κοινοῦ τοῦ Ἀχαιῶν παρὰ Ῥωμαίους ἰδίᾳ πρεσβείαν ἀποστέλλειν.", "st": "7.12"}, {"sp": "N", "t": "πόλεμός τε δὴ ἀπὸ τῶν ἀμφισβητημάτων τούτων Ἀχαιοῖς καὶ Λακεδαιμονίοις ἤρχετο καὶ Λακεδαιμόνιοι συνιέντες οὐκ ἀξιόμαχοι πρὸς Ἀχαιοὺς εἶναι πρεσβείαις ἐχρῶντο πρὸς τὰς πόλεις αὐτῶν καὶ ἰδίᾳ πρὸς τὸν Δίαιον λόγοις. αἱ μὲν δὴ κατὰ τὰ αὐτὰ αἱ πόλεις ἐποιοῦντο τὰς ἀποκρίσεις, οὔ σφισιν ἔξοδον ἐπαγγέλλοντος στρατηγοῦ παρακούειν εἶναι νόμον· Δίαιος γὰρ ἦρχε τῶν Ἀχαιῶν καὶ ἔφασκεν οὐ τῇ Σπάρτῃ, τοῖς δὲ ταράσσουσιν αὐτὴν πολεμήσων ἀφίξεσθαι.", "st": "7.12"}, {"sp": "N", "t": "ἐρομένων δὲ τῶν γερόντων ὁπόσους ἡγοῖτο ἀδικεῖν, ἐσπέμπει σφίσι τεσσάρων ὀνόματα ἀνδρῶν καὶ εἴκοσι πρωτευόντων τὰ πάντα ἐν Σπάρτῃ. ἐνταῦθα Ἀγασισθένους ἐνίκησε γνώμη δοκίμου καὶ τὰ πρότερα ὄντος, ἀπὸ δὲ τῆς παραινέσεως ταύτης προελθόντος καὶ ἐς πλέον δόξης· ὃς τοὺς ἄνδρας τούτους ἐκέλευσεν ἐκ Λακεδαίμονος ἐθελοντὰς φεύγειν μηδὲ αὐτοῦ μένοντας ἐργάσασθαι τῇ Σπάρτῃ πόλεμον, φυγόντας δὲ ἐς Ῥώμην καταχθήσεσθαι σφᾶς οὐ μετὰ πολὺ ἔφασκεν ὑπὸ Ῥωμαίων.", "st": "7.12"}, {"sp": "N", "t": "καὶ οἱ μὲν ἀπελθόντες ὑπήγοντο ὑπὸ Σπαρτιατῶν ἐς δικαστήριον τῷ λόγῳ καὶ ἀποθανεῖν ἦσαν κατεγνωσμένοι· ἀπεστάλησαν δὲ καὶ ὑπὸ Ἀχαιῶν Καλλικράτης ἐς Ῥώμην καὶ Δίαιος τοῖς φεύγουσιν ἐκ Σπάρτης ἀντιδικήσοντες ἐπὶ τῆς βουλῆς. καὶ αὐτῶν ὁ μὲν κατὰ τὴν ὁδὸν Καλλικράτης τελευτᾷ νόσῳ, οὐδὲ οἶδα εἰ ἀφικόμενος ἐς Ῥώμην ὠφέλησεν ἄν τι Ἀχαιοὺς ἢ κακῶν σφισιν ἐγένετο μειζόνων ἀρχή· Δίαιος δὲ ἐς ἀντιλογίαν Μεναλκίδᾳ καταστὰς ἐπὶ τῆς βουλῆς πολλὰ μὲν εἶπε, τὰ δὲ ἤκουσεν οὐ σὺν κόσμῳ.", "st": "7.12"}, {"sp": "N", "t": "καί σφισιν ἀπεκρίνατο ἡ βουλὴ ἀποστέλλειν πρέσβεις, οἳ κρινοῦσιν ὅσα Λακεδαιμονίοις καὶ Ἀχαιοῖς διάφορα ἦν ἐς ἀλλήλους. καὶ τοῖς ἐκ Ῥώμης πρέσβεσι σχολαιτέρα πως ἐγίνετο ἡ ὁδός, ὥστε ἐξαπατᾶν ὑπῆρχεν ἐξ ἀρχῆς Διαίῳ τε Ἀχαιοὺς καὶ Μεναλκίδᾳ Λακεδαιμονίους· τοὺς μὲν δὴ παρῆγεν ὁ Δίαιος ὡς τὰ πάντα ἕπεσθαι Λακεδαιμόνιοί σφισιν ὑπὸ τῆς Ῥωμαίων βουλῆς εἰσιν ἐγνωσμένοι, Λακεδαιμονίους δὲ ὁ Μεναλκίδας ἠπάτα παντελῶς τοῦ συνεδρεύειν ἐς τὸ Ἀχαϊκὸν ὑπὸ Ῥωμαίων αὐτοὺς ἀπηλλάχθαι.", "st": "7.12"}, {"sp": "N", "t": "αὖθις οὖν ἐκ τῶν ἀντιλογιῶν Λακεδαιμονίοις ὥρμηντο Ἀχαιοὶ πολεμεῖν, καὶ στρατὸς ἐπὶ τὴν Σπάρτην ἠθροίζετο ὑπὸ Δαμοκρίτου στρατηγεῖν τηνικαῦτα Ἀχαιῶν ᾑρημένου. περὶ δὲ τὸν αὐτὸν χρόνον τοῦτον ἀφίκετο ἐς Μακεδονίαν στρατιά τε Ῥωμαίων καὶ ἡγεμὼν ἐπ’ αὐτῇ Μέτελλος, Ἀνδρίσκῳ τῷ Περσέως τοῦ Φιλίππου πολεμήσοντες ἀφεστηκότι ἀπὸ Ῥωμαίων. καὶ ὁ μὲν ἐν Μακεδονίᾳ πόλεμος ἔμελλεν ὡς ῥᾷστα κατὰ τὸ ἐπιτηδειότατον Ῥωμαίοις κριθήσεσθαι·", "st": "7.13"}, {"sp": "N", "t": "Μέτελλος δὲ ἄνδρας ὑπὸ τῆς Ῥωμαίων ἀπεσταλμένους βουλῆς ἐπὶ τὰ ἐν τῇ Ἀσίᾳ πράγματα ἐκέλευε, πρὶν ἢ ἐς τὴν Ἀσίαν διαβῆναι, τοῖς ἡγεμόσιν αὐτοὺς τοῖς Ἀχαιῶν ἐς λόγους ἐλθεῖν, ὅπλα μὲν ἐπὶ τὴν Σπάρτην μὴ ἐπιφέρειν σφίσιν ἀπαγορεύσοντας, τὴν δὲ ἐκ Ῥώμης παρουσίαν τῶν ἀνδρῶν προεροῦντας μένειν, οἳ κατὰ τοῦτο ἦσαν ἀπεσταλμένοι Λακεδαιμονίοις δικασταὶ καὶ Ἀχαιοῖς γενέσθαι.", "st": "7.13"}, {"sp": "N", "t": "οἱ μὲν δὴ τὰ ἐντεταλμένα Δαμοκρίτῳ καὶ Ἀχαιοῖς ἐπήγγελλον ἐφθακόσιν ἔξοδον ἐπὶ Λακεδαίμονα πεποιῆσθαι καὶ—ἑώρων γὰρ [τὰ] πρὸς τὴν παραίνεσιν ἀνθεστηκότα ⟨τὰ⟩ Ἀχαιῶν—ἀπηλλάσσοντο ἐς τὴν Ἀσίαν· Λακεδαιμόνιοι δὲ ὑπὸ φρονήματος μᾶλλον ἢ ἰσχύος ἔλαβον μὲν τὰ ὅπλα καὶ ἐπεξῆλθον ἀμυνοῦντες τῇ οἰκείᾳ, βιασθέντες δὲ οὐ μετὰ πολύ, ὅσον μὲν ἐς χιλίους οἱ ἡλικίᾳ μάλιστα αὐτῶν καὶ τόλμαις ἀκμάζοντες πίπτουσιν ἐν τῇ μάχῃ, τὸ δὲ ἄλλο στρατιωτικόν, ὡς ἕκαστος τάχους εἶχεν, ἔφευγον πρὸς τὴν πόλιν.", "st": "7.13"}, {"sp": "N", "t": "εἰ δὲ ὁ Δαμόκριτος προθυμίαν ἐποιήσατο, τοῖς φεύγουσιν ἐκ τῆς παρατάξεως ὁμοῦ καὶ Ἀχαιοῖς ἐσδραμεῖν ⟨ὑπῆρξεν ἂν⟩ ἐς τὸ τεῖχος τῆς Σπάρτης [εἰς Σπάρτην]· νῦν δὲ αὐτίκα τε ἀνεκάλεσεν ἀπὸ τῆς διώξεως τοὺς Ἀχαιοὺς καὶ ἐχρῆτο καὶ ἐς τὸ ἔπειτα καταδρομαῖς μᾶλλον καὶ ἁρπαγαῖς ἐκ τῆς χώρας ἢ συντόνῳ πολιορκίᾳ.", "st": "7.13"}, {"sp": "N", "t": "Δαμοκρίτῳ μὲν οὖν ἀπαγαγόντι ὀπίσω τὴν στρατιὰν ἐπιβάλλουσιν οἱ Ἀχαιοὶ ζημίαν πεντήκοντα ἅτε ἀνδρὶ προδότῃ τάλαντα, καὶ—οὐ γὰρ εἶχεν ἐκτῖσαι— φεύγων ᾤχετο ἐκ Πελοποννήσου· Δίαιος δὲ Ἀχαιῶν μετὰ Δαμόκριτον στρατηγεῖν ᾑρημένος ἀποστείλαντι αὖθις Μετέλλῳ πρέσβεις ὡμολόγησε μηδένα ἐπάξειν Λακεδαιμονίοις πόλεμον, ἀλλὰ ἔστ’ ἂν ἥκωσιν ἐκ Ῥώμης, ἀναμενεῖν τοὺς διαλλακτάς.", "st": "7.13"}, {"sp": "N", "t": "στρατήγημα δὲ ἄλλο ἐς τοὺς Λακεδαιμονίους παρεῦρε τοιόνδε· τὰ ἐν κύκλῳ τῆς Σπάρτης πολίσματα ἐς τὴν Ἀχαιῶν ὑπηγάγετο εὔνοιαν, ἐσήγαγε δὲ ἐς αὐτὰ καὶ φρουράς, ὁρμητήρια ἐπὶ τὴν Σπάρτην Ἀχαιοῖς εἶναι.", "st": "7.13"}, {"sp": "N", "t": "Μεναλκίδας δὲ ᾕρητο μὲν ὑπὸ Λακεδαιμονίων ἐναντία Διαίῳ στρατηγεῖν· ἐχόντων δὲ αὐτῶν ἔς τε τὴν πᾶσαν πολέμου παρασκευὴν καὶ οὐχ ἥκιστα τοῖς χρήμασιν ἀσθενῶς, πρὸς δὲ καὶ τῆς γῆς σφισιν ἀσπόρου μεμενηκυίας, †διας ὅμως τὰς σπονδὰς ὑπερβῆναι καὶ πόλισμα Ἴασον ἑλὼν ἐξ ἐπιδρομῆς ἐπόρθησεν, ἐν ὅροις μὲν χώρας τῆς Λακωνικῆς, Ἀχαιῶν δὲ ἐν τῷ τότε ὑπήκοον.", "st": "7.13"}, {"sp": "N", "t": "ἐξεγείρας δὲ αὖθις Λακεδαιμονίοις καὶ Ἀχαιοῖς πόλεμον ἐν ἐγκλήμασί τε ἦν ὑπὸ τῶν πολιτῶν καὶ— οὐ γάρ τινα ἐκ τοῦ προσδοκωμένου κινδύνου Λακεδαιμονίοις σωτηρίαν εὕρισκεν—ἀφίησιν ἑκουσίως τὴν ψυχὴν πιὼν φάρμακον. καὶ Μεκαλκίδᾳ μὲν τέλος τοιοῦτον ἐγένετο, ἄρξαντι ἐν τῷ [ἑαυτοῦ νῷ] τότε μὲν Λακεδαιμονίων ὡς ἂν ὁ ἀμαθέστατος στρατηγός, πρότερον δὲ ἔτι τοῦ Ἀχαιῶν ἔθνους ὡς ἀνθρώπων ὁ ἀδικώτατος.", "st": "7.13"}, {"sp": "N", "t": "ἀφίκοντο δὲ ἐς τὴν Ἑλλάδα καὶ οἱ ἀποσταλέντες ἐκ Ῥώμης Λακεδαιμονίοις δικασταὶ καὶ Ἀχαιοῖς γενέσθαι, ἄλλοι τε καὶ Ὀρέστης· ⟨ὁ δὲ⟩ τούς τε ἐν ἑκάστῃ πόλει τῶν Ἀχαιῶν ἔχοντας τὰς ἀρχὰς καὶ Δίαιον ἐκάλει παρ’ αὑτόν. ἀφικομένοις δὲ ἔνθα ἔτυχεν αὐτὸς ἐσῳκισμένος, ἀπεγύμνου τὸν πάντα σφίσιν ἤδη λόγον, ὡς δίκαια ἡγοῖτο ἡ Ῥωμαίων βουλὴ μήτε Λακεδαιμονίους τελεῖν ἐς τὸ Ἀχαϊκὸν μήτε αὐτὴν Κόρινθον, ἀφεῖσθαι δὲ καὶ Ἄργος καὶ Ἡράκλειαν τὴν πρὸς Οἴτῃ καὶ Ὀρχομενίους Ἀρκάδας συνεδρίου τοῦ Ἀχαιῶν· γένους τε γὰρ αὐτοῖς οὐδὲν τοῦ Ἀχαιῶν μετεῖναι καὶ ὕστερον τὰς πόλεις προσχωρῆσαι ταύτας πρὸς τὸ Ἀχαϊκόν.", "st": "7.14"}, {"sp": "N", "t": "ταῦτα Ὀρέστου λέγοντος οἱ ἄρχοντες τῶν Ἀχαιῶν οὐδὲ τὸν πάντα ὑπομείναντες ἀκοῦσαι λόγον ἔθεον ἐς τὸ ἐκτὸς τῆς οἰκίας καὶ ἐκάλουν Ἀχαιοὺς ἐς ἐκκλησίαν· οἱ δὲ ὡς τὰ ἐγνωσμένα ἐπύθοντο ὑπὸ Ῥωμαίων, αὐτίκα ἐτρέποντο ἐπὶ τοὺς Σπαρτιάτας οἳ Κορίνθῳ τότε ἔτυχον ἐπιδημοῦντες, συνήρπαζον δὲ πάντα τινὰ καὶ ὃν Λακεδαιμόνιον σαφῶς ὄντα ἠπίσταντο καὶ ὅτῳ κουρᾶς ἢ ὑποδημάτων ἕνεκα ἢ ἐπὶ τῇ ἐσθῆτι ἢ κατ’ ὄνομα προσγένοιτο ὑπόνοια· τοὺς δὲ αὐτῶν καὶ καταφυγεῖν ἔνθα Ὀρέστης ᾤκει φθάνοντας ὅμως καὶ ἐντεῦθεν ἐβιάζοντο ἕλκειν.", "st": "7.14"}, {"sp": "N", "t": "Ὀρέστης δὲ καὶ οἱ σὺν αὐτῷ τῆς τε τόλμης ἐπέχειν τοὺς Ἀχαιοὺς ἐπειρῶντο καὶ ἐκέλευον μεμνῆσθαι σφᾶς ὡς ἀδικημάτων καὶ ὕβρεως ἄρχουσιν ἐς Ῥωμαίους. ἡμέραις δὲ ὕστερον οὐ πολλαῖς οἱ Ἀχαιοὶ Λακεδαιμονίων μὲν αὐτῶν ὅσους εἶχον συνειληφότες, κατατίθενται σφᾶς ἐς δεσμωτήριον, τοὺς ξένους δὲ ἀπ’ αὐτῶν διακρίνοντες ἠφίεσαν. ἀποστέλλουσι δὲ καὶ ἐς Ῥώμην ἄλλους τε Ἀχαιῶν τῶν ἐν τέλει καὶ Θεαρίδαν· ὡς δὲ ἀπῆλθον, ἐντυχόντες κατὰ τὴν ἄνοδον Ῥωμαίων πρέσβεσιν ἐπὶ τὰ Λακεδαιμονίων καὶ Ἀχαιῶν ὕστερον ἢ Ὀρέστης ἀπεσταλμένοις, ὀπίσω καὶ αὐτοὶ τρέπονται.", "st": "7.14"}, {"sp": "N", "t": "Διαίῳ δὲ ἐξήκοντος τοῦ χρόνου τῆς ἀρχῆς στρατηγεῖν ὑπὸ Ἀχαιῶν ᾑρέθη Κριτόλαος. τοῦτον δριμὺς καὶ σὺν οὐδενὶ λογισμῷ τὸν Κριτόλαον πολεμεῖν πρὸς Ῥωμαίους ἔρως ἔσχε· καὶ—ἔτυχον γὰρ τότε ἤδη οἱ παρὰ Ῥωμαίων ἥκοντες τὰ Λακεδαιμονίων καὶ Ἀχαιῶν δικάσαι—ἀφίκετο μὲν ἐν Τεγέᾳ τῇ Ἀρκάδων τοῖς ἀνδράσιν ἐς λόγους ὁ Κριτόλαος, ἀθροῖσαι δὲ Ἀχαιούς σφισιν ἐς κοινὸν σύλλογον οὐδαμῶς ἤθελεν, ἀλλὰ ἐς μὲν ἐπήκοον τῶν Ῥωμαίων ἔπεμπεν ἀγγέλους κελεύων τοὺς συνέδρους καλεῖν ἐς τὸ Ἀχαϊκόν, ἰδίᾳ δὲ τοῖς συνέδροις ἐπέστελλεν ἐς τὰς πόλεις ἀπολείπεσθαι σφᾶς τοῦ συλλόγου.", "st": "7.14"}, {"sp": "N", "t": "ὡς δὲ οὐκ ἀφίκοντο οἱ συνεδρεύσοντες, ἐνταῦθα ὁ Κριτόλαος μάλιστα ἐπεδείκνυτο ἀπάτῃ πρὸς Ῥωμαίους χρώμενος, ὃς ἄλλην ἐκέλευεν ἀναμένειν αὐτοὺς Ἀχαιῶν σύνοδον, ἐς μῆνα ἐσομένην ἕκτον· αὐτὸς δὲ οὐδὲν ἰδίᾳ διαλέξεσθαί σφισιν ἄνευ τοῦ κοινοῦ τοῦ Ἀχαιῶν ἔφασκε. καὶ οἱ μὲν ἐπεὶ ἀπατώμενοι συνῆκαν, ἀπηλλάσσοντο ἐς Ῥώμην· Κριτόλαος δὲ ἐς Κόρινθον Ἀχαιοὺς ἀθροίσας ἀνέπεισε μὲν ἐπιφέρειν ὅπλα ἐπὶ τὴν Σπάρτην, ἀνέπεισε δὲ καὶ Ῥωμαίοις ἐκ τοῦ εὐθέος πόλεμον ἄρασθαι.", "st": "7.14"}, {"sp": "N", "t": "τὸ μὲν δὴ ἄνδρα βασιλέα καὶ πόλιν ἀνελέσθαι πόλεμον καὶ μὴ εὐτυχῆσαι συνέβη φθόνῳ μᾶλλον ἔκ του δαιμόνων ἢ τοῖς πολεμήσασι ποιεῖ τὸ ἔγκλημα· θρασύτης δὲ ἡ μετὰ ἀσθενείας μανία ⟨ἂν⟩ μᾶλλον ἢ ἀτυχία καλοῖτο. ὃ δὴ καὶ Κριτόλαον καὶ Ἀχαιοὺς ἔβλαψε. παρώξυνε δὲ καὶ Ἀχαιοὺς Πυθέας βοιωταρχῶν τηνικαῦτα ἐν Θήβαις, καὶ οἱ Θηβαῖοι συνεπιλήψεσθαι προθύμως ἐπηγγέλλοντο τοῦ πολέμου·", "st": "7.14"}, {"sp": "N", "t": "ἑαλώκεσαν δὲ οἱ Θηβαῖοι πρώτην δίκην Μετέλλου δικάζοντος Φωκεῦσιν ἐκτῖσαι ζημίαν, ὅτι ἐσέβαλον σὺν ὅπλοις ἐς γῆν τὴν Φωκίδα, δευτέραν Εὐβοεῦσιν, ἐδῄωσαν γὰρ καὶ Εὐβοέων τὴν χώραν, τρίτην δὲ Ἀμφισσεῦσι, τεμόντες καὶ τὴν Ἀμφισσέων περὶ ἀκμὴν σίτου.", "st": "7.14"}, {"sp": "N", "t": "Ῥωμαῖοι δὲ παρά τε τῶν ἀνδρῶν διδαχθέντες οὓς ἐς τὴν Ἑλλάδα ἀπέστειλαν καὶ ἐκ τῶν γραμμάτων ἃ Μέτελλος ἐπέστελλεν, ἀδικεῖν Ἀχαιῶν κατέγνωσαν· καὶ ἦν γὰρ Μόμμιός σφισιν ὕπατος τότε ᾑρημένος, τοῦτον ναῦς τε καὶ στρατιὰν πεζὴν ἐκέλευον ἐπ’ Ἀχαιοὺς ἄγειν. Μέτελλος δὲ παραυτίκα ἐπέπυστο ὡς Μόμμιος καὶ ὁ σὺν αὐτῷ στρατὸς ἐπὶ Ἀχαιοὺς ἀφίκοιτο· καὶ ἐποιεῖτο σπουδήν, εἰ ἐπιθεὶς αὐτὸς πέρας τῷ πολέμῳ φανῇ πρὶν ἢ Μόμμιον ἐς τὴν Ἑλλάδα ἀφῖχθαι.", "st": "7.15"}, {"sp": "N", "t": "ἀγγέλους οὖν παρὰ τοὺς Ἀχαιοὺς ἀπέστελλεν, ἀφιέναι κελεύων σφᾶς συντελείας Λακεδαιμονίους καὶ πόλεις ἄλλας ὁπόσας εἴρητο ὑπὸ Ῥωμαίων, τῆς τε ἐκ τοῦ χρόνου τοῦ προτέρου σφίσιν ἀπειθείας οὐδεμίαν παρὰ Ῥωμαίων ὑπισχνεῖτο ὀργὴν γενήσεσθαι. ἅμα τε δὴ ταῦτα ἐπεκηρυκεύετο καὶ ἤλαυνεν ἐκ Μακεδονίας τὸν στρατόν, διὰ Θεσσαλίας τὴν πορείαν καὶ παρὰ τὸν Λαμιακὸν ποιούμενος κόλπον. Κριτόλαος δὲ καὶ Ἀχαιοὶ λόγον μὲν φέροντα ἐς σύμβασιν προσίεντο οὐδένα, Ἡράκλειαν δὲ προσεκάθηντο πολιορκοῦντες οὐ βουλομένους ἐς τὸ Ἀχαϊκὸν συντελεῖν.", "st": "7.15"}, {"sp": "N", "t": "τότε δὲ ὡς παρὰ τῶν κατασκόπων ἐπυνθάνετο ὁ Κριτόλαος Μέτελλον καὶ Ῥωμαίους διαβεβηκέναι τὸν Σπερχειόν, ἀπέφευγεν ἐς Σκάρφειαν τὴν Λοκρῶν, οὐδὲ κατὰ τὸ στενὸν τὸ Ἡρακλείας τε μεταξὺ καὶ Θερμοπυλῶν τοὺς Ἀχαιοὺς τάξας ἐτόλμησεν ὑπομεῖναι Μέτελλον· ἀλλὰ ἐς τοσοῦτο ἀφίκετο δείματος ὡς μηδὲ αὐτὸ ποιήσασθαι τὸ χωρίον πρὸς ἀμείνονος ἐλπίδος, ἔνθα ἦν μὲν Λακεδαιμονίοις ὑπὲρ τῶν Ἑλλήνων τὰ ἐς Μήδους, ἦν δὲ καὶ Ἀθηναίοις τὰ ἐς Γαλάτας οὐδὲν ἀφανέστερα ἐκείνων τολμήματα.", "st": "7.15"}, {"sp": "N", "t": "ὑποφεύγοντας δὲ Κριτόλαον καὶ Ἀχαιοὺς αἱροῦσιν ὀλίγον πρὸ τῆς Σκαρφείας οἱ ὁμοῦ τῷ Μετέλλῳ, καὶ ἀπέκτεινάν τε πλήθει πολλοὺς καὶ ἔλαβον ζῶντας ὅσον χιλίους. Κριτόλαος δὲ οὔτε ὤφθη ζῶν μετὰ τὴν μάχην οὔτε ἐν τοῖς νεκροῖς εὑρέθη· εἰ δὲ ἐτόλμησε τῆς πρὸς τῇ Οἴτῃ θαλάσσης ἐς ταύτης καταδῦναι τὸ τέλμα, παντάπασιν ἔμελλεν ἄγνωστός τε καὶ ἄπυστος οἰχήσεσθαι κατὰ τοῦ βυθοῦ.", "st": "7.15"}, {"sp": "N", "t": "ἐς μὲν οὖν τὴν Κριτολάου τελευτὴν καὶ ἄλλα πάρεστιν εἰκάζειν· Ἀρκάδων δὲ ἐξεστρατευμένοι λογάδες χίλιοι, οἳ Κριτολάῳ τοῦ ἔργου μετέσχον, προῆλθον μὲν ἄχρι Ἐλατείας τῆς Φωκέων καὶ ἐς τὴν πόλιν ὑπ’ αὐτῶν κατὰ συγγένειαν δή τινα παλαιὰν ἐδέχθησαν· ὡς δὲ τοῖς Φωκεῦσιν ἡ Κριτολάου συμφορὰ καὶ Ἀχαιῶν ἀπηγγέλλετο, ἀπελθεῖν ἐκ τῆς Ἐλατείας κελεύουσι τοὺς Ἀρκάδας.", "st": "7.15"}, {"sp": "N", "t": "ἀπιοῦσι δὲ ὀπίσω σφίσιν ἐς τὴν Πελοπόννησον Μέτελλος καὶ Ῥωμαῖοι περὶ Χαιρώνειαν ἐπιφαίνονται· ἔνθα δὴ ἐπελάμβανε τοὺς Ἀρκάδας ἐκ θεῶν δίκη τῶν Ἑλληνικῶν, οἳ ἐν Χαιρωνείᾳ Φιλίππου καὶ Μακεδόνων ἐναντία ἀγωνιζομένους ἐγκαταλιπόντες Ἕλληνας τότε ἐν χωρίῳ τῷ αὐτῷ ἐκτείνοντο ὑπὸ Ῥωμαίων.", "st": "7.15"}, {"sp": "N", "t": "Ἀχαιοῖς δὲ αὖθις ἐπὶ τὴν ἡγεμονίαν τοῦ στρατεύματος παρῄει Δίαιος· καὶ δούλους τε ἐς ἐλευθερίαν ἠφίει, τὸ Μιλτιάδου καὶ Ἀθηναίων βούλευμα ⟨τὸ⟩ πρὸ τοῦ ἔργου τοῦ ἐν Μαραθῶνι μιμούμενος, καὶ Ἀχαιῶν συνέλεγε καὶ Ἀρκάδων ἀπὸ τῶν πόλεων τοὺς ἐν ἡλικίᾳ· ἐγένετο δέ, ἀναμεμιγμένων ὁμοῦ καὶ οἰκετῶν, τὸ ἀθροισθὲν ἐς ἑξακοσίους μὲν μάλιστα ἀριθμὸν ἱππεῖς, τὸ δὲ ὁπλιτεῦον τετρακισχίλιοί τε καὶ μύριοι.", "st": "7.15"}, {"sp": "N", "t": "ἐνταῦθα ὁ Δίαιος ἐς ἅπαν ἀφίκετο ἀνοίας, ὃς Κριτόλαον καὶ πᾶσαν τὴν Ἀχαιῶν ἐπιστάμενος παρασκευὴν κακῶς οὕτως ἀγωνισαμένην πρὸς Μέτελλον ἀπέλεξεν αὐτὸς ὅσον τετρακισχιλίους· καὶ ἄρχοντα ἐπ’ αὐτοῖς ἔταξεν Ἀλκαμένην. ἀπεστέλλοντο δὲ ἐς Μέγαρα φρουρά τε εἶναι Μεγαρεῦσι τοῦ ἄστεως καί, ἢν Μέτελλος ἐπίῃ καὶ οἱ Ῥωμαῖοι, τοῦ πρόσω σφᾶς κωλύειν.", "st": "7.15"}, {"sp": "N", "t": "Μέτελλος δὲ ὡς οἱ περὶ Χαιρώνειαν λογάδες κατέστρωντο οἱ Ἀρκάδων, ἀναστήσας τὸ στράτευμα ἤλαυνεν ἐπὶ τὰς Θήβας· Ἡράκλειάν τε γὰρ ἐπολιόρκησαν οἱ Θηβαῖοι μετὰ Ἀχαιῶν καὶ ἀγῶνος τοῦ πρὸς Σκάρφειαν μετεσχήκεσαν. τότε δὲ αὐτοί τε καὶ γυναῖκες ἐκλελοιπότες πᾶσα ἡλικία τὴν πόλιν ἐπλανῶντο ἀνὰ τὴν Βοιωτίαν καὶ ἐς τῶν ὀρῶν τὰ ἄκρα ἀνέφευγον.", "st": "7.15"}, {"sp": "N", "t": "Μέτελλος δὲ οὔτε ἱερὰ ἐμπιπράναι θεῶν οὔτε οἰκοδομήματα καθαιρεῖν εἴα, Θηβαίων τε τῶν ἄλλων μήτε ἀποκτεῖναι μηδένα μήτε αἱρεῖν φεύγοντα ἀπηγόρευε· Πυθέαν δὲ ἢν ἕλωσιν, ἀνάγειν ἐκέλευσεν ὡς αὐτόν· ἐξεύρητό τε δὴ αὐτίκα ὁ Πυθέας καὶ ἀναχθεὶς δίκην εἶχεν. ὡς δὲ πλησίον Μεγάρων ἐγίνετο ὁ στρατός, οὔτε ὑπέμειναν οἱ περὶ τὸν Ἀλκαμένην καὶ αὐτίκα ἐς Κόρινθον παρὰ τὸ στρατόπεδον τὸ Ἀχαιῶν ᾤχοντο φεύγοντες.", "st": "7.15"}, {"sp": "N", "t": "καὶ Μεγαρεῖς μὲν παραδιδόασιν ἀμαχεὶ Ῥωμαίοις τὴν πόλιν, Μέτελλος δὲ ὡς ἀφίκετο παρὰ τὸν ἰσθμόν, ἐπεκηρυκεύετο καὶ τότε Ἀχαιοῖς ⟨ἐς⟩ εἰρήνην καὶ ὁμολογίας προκαλούμενος· ἰσχυρὸς γάρ τις ἐνέκειτο αὐτῷ πόθος τὰ ἐν Μακεδονίᾳ τε ὁμοῦ καὶ τὰ Ἀχαιῶν κατεργασθῆναι δι’ αὐτοῦ. τούτῳ μὲν ταῦτα ἐσπευκότι Δίαιος ἠναντιοῦτο ὑπὸ ἀγνωμοσύνης·", "st": "7.15"}, {"sp": "N", "t": "Μόμμιος δὲ Ὀρέστην ἅμα ἀγόμενος, τὸν πρότερον ἐπὶ τῇ Λακεδαιμονίων διαφορᾷ καὶ Ἀχαιῶν ἐλθόντα, ἀφίκετο μὲν περὶ ὄρθρον ἐς τὸ τῶν Ῥωμαίων στράτευμα, ἀποπέμψας δὲ ἐς Μακεδονίαν Μέτελλον καὶ ὅσον εἵπετο ἐκείνῳ, ἀνέμενεν αὐτὸς ἐν τῷ ἰσθμῷ τὴν πᾶσαν ἀθροισθῆναι παρασκευήν. ἀφίκετο δὲ ἱππικὸν μὲν πεντακόσιοί τε καὶ τρισχίλιοι, τοῦ πεζοῦ δὲ ἀριθμὸς ἐγένετο ἐς μυριάδας δύο προσόντων καὶ τούτοις τρισχιλίων· ἐπῆλθον δὲ καὶ τοξόται Κρῆτες καὶ ἐκ Περγάμου τῆς ὑπὲρ Καΐκου Φιλοποίμην στρατιώτας ἄγων παρὰ Ἀττάλου.", "st": "7.16"}, {"sp": "N", "t": "Μόμμιος μὲν δὴ τῶν τε ἐξ Ἰταλίας τινὰς καὶ τὰ ἐπικουρικὰ ἀπωτέρω δύο τε καὶ δέκα ἔταξε σταδίοις, πρὸ τοῦ παντὸς εἶναι στρατεύματος φυλακήν· Ἀχαιοὶ δέ, ἐχόντων ἀφυλακτότερον ὑπὸ φρονήματος τῶν Ῥωμαίων, ἐπιτίθενται [τοῖς] ἐπὶ φυλακῆς αὐτοῖς τῆς πρώτης, καὶ τοὺς μὲν φονεύουσι, πλείονας δὲ ἔτι ἐς τὸ στρατόπεδον κατεῖρξαν, καὶ ἀσπίδας ὅσον τε πεντακοσίας εἷλον. ἀπὸ τούτου δὲ τοῦ ἔργου καὶ ἐπήρθησαν οἱ Ἀχαιοὶ ποιήσασθαι τὴν ἔξοδον πρότερον πρὶν ἢ Ῥωμαίους ἄρχειν μάχης·", "st": "7.16"}, {"sp": "N", "t": "ὡς δὲ ἀντεπῆγε καὶ ὁ Μόμμιος, οἱ μὲν ἐς τὸ ἱππικὸν τῶν Ἀχαιῶν ταχθέντες αὐτίκα ᾤχοντο φεύγοντες, τῆς Ῥωμαίων ἵππου μηδὲ τὴν πρώτην ἔφοδον ὑπομείναντες· ὁ δὲ πεζὸς στρατὸς ἀθύμως μὲν εἶχεν ἐπὶ τῶν ἱππέων τῇ τροπῇ, δεξάμενοι δὲ τὴν ἐμβολὴν τοῦ ὁπλιτικοῦ τοῦ Ῥωμαίων βιαζόμενοί τε τῷ πλήθει καὶ ἀπαγορεύοντες τοῖς τραύμασιν ὅμως ἀντεῖχον ὑπὸ τοῦ θυμοῦ, πρίν γε δὴ Ῥωμαίων λογάδες χίλιοι προσπεσόντες κατὰ τὰ πλάγια ἐς τελέαν τοὺς Ἀχαιοὺς φυγὴν κατέστησαν.", "st": "7.16"}, {"sp": "N", "t": "εἰ δὲ ἐτόλμησεν ἐσδραμεῖν μετὰ τὴν μάχην Δίαιος ἐς Κόρινθον καὶ ὑποδέξασθαι τῷ τείχει τοὺς διαπίπτοντας ἐκ τῆς φυγῆς, κἂν εὕρασθαί τι παρὰ Μομμίου οἱ Ἀχαιοὶ φιλάνθρωπον ἐδυνήθησαν, ἐς πολιορκίαν καὶ τριβὴν πολέμου καταστάντες· νῦν δὲ ἀρχομένων ἔτι ἐνδιδόναι τῶν Ἀχαιῶν εὐθὺ Μεγάλης πόλεως ἔφευγεν ὁ Δίαιος, οὐδέν τι γενόμενος ἐς Ἀχαιοὺς ὅμοιος ἢ καὶ Καλλίστρατος ὁ Ἐμπέδου πρὸς Ἀθηναίους.", "st": "7.16"}, {"sp": "N", "t": "τούτῳ γὰρ τῷ ἀνδρὶ ἱππαρχήσαντι ἐν Σικελίᾳ, ὅτε Ἀθηναῖοι καὶ ὅσοι ἄλλοι τοῦ στόλου μετεσχήκεσαν ἀπώλλυντο πρὸς τῷ ποταμῷ [τότε] τῷ Ἀσινάρῳ, τούτῳ τότε τῷ Καλλιστράτῳ παρέστη τόλμα διεκπαῖσαι διὰ τῶν πολεμίων ἄγοντι τοὺς ἱππέας· ὡς δὲ τὸ πολὺ ἀπέσωσεν αὐτῶν ἐς Κατάνην, ἀνέστρεφεν ὀπίσω τὴν αὐτὴν αὖθις ὁδὸν ἐς Συρακούσας, διαρπάζοντας δὲ ἔτι εὑρὼν τὸ Ἀθηναίων στρατόπεδον καταβάλλει τε ὅσον πέντε ἐξ αὐτῶν, καὶ τραύματα ἐπίκαιρα αὐτὸς καὶ ὁ ἵππος λαβόντες ἀφιᾶσι τὴν ψυχήν.", "st": "7.16"}, {"sp": "N", "t": "οὗτος μὲν δὴ ἀγαθὴν δόξαν Ἀθηναίοις καὶ αὑτῷ κτώμενος περιεποίησέ τε ὧν ἦρχε καὶ ἐτελεύτησεν αὐτὸς ἑκουσίως· Δίαιος δὲ Ἀχαιοὺς ἀπολωλεκὼς Μεγαλοπολίταις κακῶν τῶν ἐφεστηκότων ἧκεν ἄγγελος, ἀποκτείνας δὲ αὐτοχειρὶ τὴν γυναῖκα, ἵνα δὴ μὴ γένοιτο αἰχμάλωτος, τελευτᾷ πιὼν φάρμακον, ἐοικυῖαν μὲν παρασχόμενος Μεναλκίδᾳ τὴν ἐς χρήματα πλεονεξίαν, ἐοικυῖαν δὲ καὶ ⟨τὴν⟩ ἐς τὸν θάνατον δειλίαν.", "st": "7.16"}, {"sp": "N", "t": "Ἀχαιῶν δὲ οἱ ἐς Κόρινθον ἀποσωθέντες μετὰ τὴν μάχην ἀπεδίδρασκον ὑπὸ νύκτα εὐθύς· ἀπεδίδρασκον δὲ καὶ αὐτῶν Κορινθίων οἱ πολλοί. Μόμμιος δὲ τὸ μὲν παραυτίκα, ἀναπεπταμένων ὅμως τῶν πυλῶν, ἐπεῖχεν ἐς τὴν Κόρινθον παρελθεῖν, ὑποκαθῆσθαί τινα ἐντὸς τοῦ τείχους ὑποπτεύων ἐνέδραν· τρίτῃ δὲ ἡμέρᾳ μετὰ τὴν μάχην ᾕρει τε κατὰ κράτος καὶ ἔκαιε Κόρινθον.", "st": "7.16"}, {"sp": "N", "t": "τῶν δὲ ἐγκαταληφθέντων τὸ μὲν πολὺ οἱ Ῥωμαῖοι φονεύουσι, γυναῖκας δὲ καὶ παῖδας ἀπέδοτο Μόμμιος· ἀπέδοτο δὲ καὶ οἰκέτας, ὅσοι τῶν ἐς ἐλευθερίαν ἀφεθέντων καὶ μαχεσαμένων μετὰ Ἀχαιῶν μὴ εὐθὺς ὑπὸ τοῦ πολέμου τὸ ἔργον ἐτεθνήκεσαν. ἀναθημάτων δὲ καὶ τοῦ ἄλλου κόσμου τὰ μὲν μάλιστα ἀνήκοντα ἐς θαῦμα ἀνήγετο, τὰ δὲ ἐκείνοις οὐχ ὁμοίου λόγου Φιλοποίμενι ὁ Μόμμιος τῷ παρ’ Ἀττάλου στρατηγῷ δίδωσι· καὶ ἦν Περγαμηνοῖς καὶ ἐς ἐμὲ ἔτι λάφυρα Κορίνθια.", "st": "7.16"}, {"sp": "N", "t": "πόλεων δέ, ὅσαι Ῥωμαίων ἐναντία ἐπολέμησαν, τείχη μὲν ὁ Μόμμιος κατέλυε καὶ ὅπλα ἀφῃρεῖτο πρὶν ἢ καὶ συμβούλους ἀποσταλῆναι παρὰ Ῥωμαίων· ὡς δὲ ἀφίκοντο οἱ σὺν αὐτῷ βουλευσόμενοι, ἐνταῦθα δημοκρατίας μὲν κατέπαυε, καθίστα δὲ ἀπὸ τιμημάτων τὰς ἀρχάς· καὶ φόρος τε ἐτάχθη τῇ Ἑλλάδι καὶ οἱ τὰ χρήματα ἔχοντες ἐκωλύοντο ἐν τῇ ὑπερορίᾳ κτᾶσθαι· συνέδριά τε κατὰ ἔθνος τὰ ἑκάστων, Ἀχαιῶν καὶ τὸ ἐν Φωκεῦσιν ἢ Βοιωτοῖς ἢ ἑτέρωθί που τῆς Ἑλλάδος, κατελέλυτο ὁμοίως πάντα.", "st": "7.16"}, {"sp": "N", "t": "ἔτεσι δὲ οὐ πολλοῖς ὕστερον ἐτράποντο ἐς ἔλεον Ῥωμαῖοι τῆς Ἑλλάδος, καὶ συνέδριά τε κατὰ ἔθνος ἀποδιδόασιν ἑκάστοις τὰ ἀρχαῖα καὶ τὸ ἐν τῇ ὑπερορίᾳ κτᾶσθαι, ἀφῆκαν δὲ καὶ ὅσοις ἐπιβεβλήκει Μόμμιος ζημίαν· Βοιωτούς τε γὰρ Ἡρακλεώταις καὶ Εὐβοεῦσι τάλαντα ἑκατὸν καὶ Ἀχαιοὺς Λακεδαιμονίοις διακόσια ἐκέλευσεν ἐκτῖσαι. τούτων μὲν δὴ ἄφεσιν παρὰ Ῥωμαίων εὕροντο Ἕλληνες, ἡγεμὼν δὲ ἔτι καὶ ἐς ἐμὲ ἀπεστέλλετο· καλοῦσι δὲ οὐχ Ἑλλάδος, ἀλλὰ Ἀχαΐας ἡγεμόνα οἱ Ῥωμαῖοι, διότι ἐχειρώσαντο Ἕλληνας δι’ Ἀχαιῶν τότε τοῦ Ἑλληνικοῦ προεστηκότων. ὁ δὲ πόλεμος ἔσχεν οὗτος τέλος Ἀντιθέου μὲν Ἀθήνῃσιν ἄρχοντος, Ὀλυμπιάδι δὲ ἑξηκοστῇ πρὸς ταῖς ἑκατόν, ἣν ἐνίκα Διόδωρος Σικυώνιος.", "st": "7.16"}, {"sp": "N", "t": "ἐς ἅπαν δὲ ἀσθενείας τότε μάλιστα κατῆλθεν ἡ Ἑλλάς, λυμανθεῖσα κατὰ μέρη καὶ διαπορθηθεῖσα ἐξ ἀρχῆς ὑπὸ τοῦ δαίμονος. Ἄργος μέν, ἐς πλεῖστον ἀφικομένην δυνάμεως πόλιν ἐπὶ τῶν καλουμένων ἡρώων, ὁμοῦ τῇ μεταβολῇ τῇ ἐς Δωριέας ἐπέλιπε τὸ ἐκ τῆς τύχης εὐμενές·", "st": "7.17"}, {"sp": "N", "t": "τὸ δὲ ἔθνος τὸ Ἀττικόν, ἀπὸ τοῦ Πελοποννησίων πολέμου καὶ νόσου τῆς λοιμώδους ἀνενεγκόν τε καὶ αὖθις ἀνανηξάμενον, ἔτεσιν ἔμελλεν οὐ πολλοῖς ὕστερον ἡ Μακεδόνων ἀκμὴ καθαιρήσειν· κατέσκηψε δὲ ἐκ Μακεδονίας καὶ ἐς τὰς Βοιωτίας Θήβας τὸ Ἀλεξάνδρου μήνιμα. Λακεδαιμονίοις δὲ Ἐπαμινώνδας ὁ Θηβαῖος καὶ αὖθις ὁ Ἀχαιῶν πόλεμος ἐγένετο· ὅτε δὲ καὶ μόγις, ἅτε ἐκ δένδρου λελωβημένου καὶ αὔου τὰ πλείονα, ἀνεβλάστησεν ἐκ τῆς Ἑλλάδος τὸ Ἀχαϊκόν, καὶ αὐτὸ ἡ κακία τῶν στρατηγησάντων ἐκόλουσεν ἔτι αὐξανόμενον.", "st": "7.17"}, {"sp": "N", "t": "χρόνῳ δὲ ὕστερον ἐς Νέρωνα ἡ βασιλεία περιῆλθεν ἡ Ῥωμαίων, καὶ ἐλεύθερον ὁ Νέρων ἀφίησιν ἁπάντων, ἀλλαγὴν πρὸς δῆμον ποιησάμενος τὸν Ῥωμαίων· Σαρδὼ γὰρ τὴν νῆσον ἐς τὰ μάλιστα εὐδαίμονα ἀντὶ Ἑλλάδος σφίσιν ἀντέδωκεν. ἀπιδόντι οὖν ἐς τοῦτό μοι τοῦ Νέρωνος τὸ ἔργον ὀρθότατα εἰρηκέναι Πλάτων ἐφαίνετο ὁ Ἀρίστωνος, ὁπόσα ἀδικήματα μεγέθει καὶ τολμήματί ἐστιν ὑπερηρκότα, οὐ τῶν ἐπιτυχόντων εἶναι ταῦτα ἀνθρώπων, ψυχῆς δὲ γενναίας ὑπὸ ἀτόπου παιδείας διεφθαρμένης.", "st": "7.17"}, {"sp": "N", "t": "οὐ μὴν Ἕλλησί γε ἐξεγένετο ὄνασθαι τοῦ δώρου· Οὐεσπασιανοῦ γὰρ μετὰ Νέρωνα ἄρξαντος ἐς ἐμφύλιον στάσιν προήχθησαν, καὶ σφᾶς ὑποτελεῖς τε αὖθις ὁ Οὐεσπασιανὸς εἶναι φόρων καὶ ἀκούειν ἐκέλευσεν ἡγεμόνος, ἀπομεμαθηκέναι φήσας τὴν ἐλευθερίαν τὸ Ἑλληνικόν.", "st": "7.17"}, {"sp": "N", "t": "τάδε μὲν οὕτω συμβάντα εὕρισκον· Ἀχαιοῖς δὲ ὅροι καὶ Ἠλείοις τῆς χώρας ποταμός τε Λάρισος καὶ Ἀθηνᾶς ἐπὶ τῷ ποταμῷ ναός ἐστι Λαρισαίας, καὶ Ἀχαιῶν πόλις Δύμη σταδίους ὅσον τε τριάκοντα ἀπέχει τοῦ Λαρίσου. ταύτην Φίλιππος ὁ Δημητρίου πολεμῶν μόνην τῶν Ἀχαϊκῶν ἔσχεν ὑπήκοον, καὶ ἐπὶ τῇ αἰτίᾳ ταύτῃ Σουλπίκιος, ἡγεμὼν καὶ οὗτος Ῥωμαίων, ἐπέτρεψε τῇ στρατιᾷ διαρπάσαι τὴν Δύμην· Αὔγουστος δὲ ὕστερον καὶ προσένειμεν αὐτὴν Πατρεῦσιν.", "st": "7.17"}, {"sp": "N", "t": "ἐκαλεῖτο δὲ τὰ μὲν ἀρχαιότερα Πάλεια· ἐχόντων δὲ ἔτι Ἰώνων ὄνομά οἱ μετέθεντο ⟨τὸ⟩ ἐφ’ ἡμῶν, σαφῶς δὲ οὐκ οἶδα εἴτε ἀπὸ γυναικὸς ἐπιχωρίας Δύμης εἴτε ἀπὸ Δύμαντος τοῦ Αἰγιμίου. ὑπὸ δὲ τοῦ ἐλεγείου τοῦ Ὀλυμπίασιν ἐπὶ τῇ εἰκόνι τῇ Οἰβώτα οὐ προαχθείη ⟨ἄν⟩ τις ἐς ἀλογίαν. Οἰβώτᾳ γὰρ ἀνδρὶ Δυμαίῳ, σταδίου μὲν ἀνελομένῳ νίκην Ὀλυμπιάδι ἕκτῃ, εἰκόνος δὲ ἐν Ὀλυμπίᾳ περὶ τὴν ὀγδοηκοστὴν Ὀλυμπιάδα κατὰ μάντευμα ἐκ Δελφῶν ἀξιωθέντι, ἐπίγραμμά ἐστιν ἐπ’ αὐτῷ λέγον·", "st": "7.17"}, {"sp": "N", "t": "Οἰνία Οἰβώτας στάδιον νικῶν ὅδ’ Ἁχαιὸς<br>πατρίδα Πάλειαν θῆκ’ ὀνομαστοτέραν.<br>τοῦτο οὖν οὐκ ἄν τινι ἀλογίαν παραστήσειεν, εἰ Πάλειαν ἀλλὰ μὴ Δύμην τὸ ἐπίγραμμα καλεῖ τὴν πόλιν· τὰ γὰρ ἀρχαιότερα ὀνόματα ἐς ποίησιν ἐπάγεσθαι τῶν ὑστέρων καθεστηκός ἐστιν Ἕλλησι, καὶ Ἀμφιάραόν τε καὶ Ἄδραστον Φορωνείδας καὶ Ἐρεχθείδην ἐπονομάζουσι τὸν Θησέα.", "st": "7.17"}, {"sp": "N", "t": "ὀλίγον δὲ πρὸ τοῦ ἄστεώς ἐστι τοῦ Δυμαίων ἐν δεξιᾷ τῆς ὁδοῦ τάφος Σωστράτου· μειράκιον δὲ ἦν τῶν ἐπιχωρίων, γενέσθαι δὲ Ἡρακλέους ἐρώμενόν φασιν αὐτόν, καὶ—ἀποθανεῖν γὰρ τὸν Σώστρατον Ἡρακλέους ἔτι ὄντος μετὰ ἀνθρώπων—οὕτως οἱ τὸν Ἡρακλέα τό τε μνῆμα αὐτὸν εἶναι τὸν ποιήσαντα καὶ ἀπαρχὰς ἀπὸ τῶν ἐν τῇ κεφαλῇ τριχῶν δοῦναι. ἐπίθημα δὲ καὶ ἐς ἐμὲ ἔτι στήλη τε ἦν ἐπὶ τοῦ χώματος καὶ Ἡρακλῆς ἐπειργασμένος· ἐλέγετο δὲ ὡς οἱ ἐπιχώριοι καὶ ἐναγίζουσι τῷ Σωστράτῳ.", "st": "7.17"}, {"sp": "N", "t": "Δυμαίοις δὲ ἔστι μὲν Ἀθηνᾶς ναὸς καὶ ἄγαλμα ἐς τὰ μάλιστα ἀρχαῖον, ἔστι δὲ καὶ ἄλλο ἱερόν σφισι Δινδυμήνῃ μητρὶ καὶ Ἄττῃ πεποιημένον. Ἄττης δὲ ὅστις ἦν, οὐδὲν οἷός τε ἦν ἀπόρρητον ἐς αὐτὸν ἐξευρεῖν, ἀλλὰ Ἑρμησιάνακτι μὲν τῷ τὰ ἐλεγεῖα γράψαντι πεποιημένα ἐστὶν ὡς υἱός τε ἦν Καλαοῦ Φρυγὸς καὶ ὡς οὐ τεκνοποιὸς ὑπὸ τῆς μητρὸς τεχθείη· ἐπεὶ δὲ ηὔξητο, μετῴκησεν ἐς Λυδίαν τῷ Ἑρμησιάνακτος λόγῳ καὶ Λυδοῖς ὄργια ἐτέλει Μητρός, ἐς τοσοῦτο ἥκων παρ’ αὐτῇ τιμῆς ὡς Δία αὐτῇ νεμεσήσαντα ὗν ἐπὶ τὰ ἔργα ἐπιπέμψαι τῶν Λυδῶν.", "st": "7.17"}, {"sp": "N", "t": "ἐνταῦθα ἄλλοι τε τῶν Λυδῶν καὶ αὐτὸς Ἄττης ἀπέθανεν ὑπὸ τοῦ ὑός· καί τι ἑπόμενον τούτοις Γαλατῶν δρῶσιν οἱ Πεσσινοῦντα ἔχοντες, ὑῶν οὐχ ἁπτόμενοι. νομίζουσί γε μὴν οὐχ οὕτω τὰ ἐς τὸν Ἄττην, ἀλλὰ ἐπιχώριός ἐστιν ἄλλος σφίσιν ἐς αὐτὸν λόγος, Δία ὑπνωμένον ἀφεῖναι σπέρμα ἐς γῆν, τὴν δὲ ἀνὰ χρόνον ἀνεῖναι δαίμονα διπλᾶ ἔχοντα αἰδοῖα, τὰ μὲν ἀνδρός, τὰ δὲ αὐτῶν γυναικός· ὄνομα δὲ Ἄγδιστιν αὐτῷ τίθενται. θεοὶ δὲ Ἄγδιστιν δείσαντες τὰ αἰδοῖά οἱ τὰ ἀνδρὸς ἀποκόπτουσιν.", "st": "7.17"}, {"sp": "N", "t": "ὡς δὲ ἀπ’ αὐτῶν ἀναφῦσα ἀμυγδαλῆ εἶχεν ὡραῖον τὸν καρπόν, θυγατέρα τοῦ Σαγγαρίου ποταμοῦ λαβεῖν φασι τοῦ καρποῦ· ἐσθεμένης δὲ ἐς τὸν κόλπον καρπὸς μὲν ἐκεῖνος ἦν αὐτίκα ἀφανής, αὐτὴ δὲ ἐκύει· τεκούσης δὲ τράγος περιεῖπε τὸν παῖδα ἐκκείμενον. ὡς δὲ αὐξανομένῳ κάλλους οἱ μετῆν πλέον ἢ κατὰ εἶδος ἀνθρώπου, ἐνταῦθα τοῦ παιδὸς ἔρως ἔσχεν Ἄγδιστιν. αὐξηθέντα δὲ Ἄττην ἀποστέλλουσιν ἐς Πεσσινοῦντα οἱ προσήκοντες συνοικήσοντα τοῦ βασιλέως θυγατρί·", "st": "7.17"}, {"sp": "N", "t": "ὑμέναιος δὲ ᾔδετο καὶ Ἄγδιστις ἐφίσταται καὶ τὰ αἰδοῖα ἀπέκοψε μανεὶς ὁ Ἄττης, ἀπέκοψε δὲ καὶ ὁ τὴν θυγατέρα αὐτῷ διδούς· Ἄγδιστιν δὲ μετάνοια ἔσχεν οἷα Ἄττην ἔδρασε, καί οἱ παρὰ Διὸς εὕρετο μήτε σήπεσθαί τι Ἄττῃ τοῦ σώματος μήτε τήκεσθαι. τάδε μὲν ἐς Ἄττην τὰ γνωριμώτατα·", "st": "7.17"}, {"sp": "N", "t": "ἐν δὲ τῇ χώρᾳ τῇ Δυμαίᾳ καὶ τοῦ δρομέως Οἰβώτα ⟨τάφος ἐστί· τούτῳ τῷ Οἰβώτα⟩ νικήσαντι Ὀλύμπια Ἀχαιῶν πρώτῳ γέρας οὐδὲν ἐξαίρετον παρ’ αὐτῶν ἐγένετο εὕρασθαι· καὶ ἐπὶ τούτῳ κατάρας ὁ Οἰβώτας ἐποιήσατο μηδενὶ Ὀλυμπικὴν νίκην ἔτι Ἀχαιῶν γενέσθαι. καὶ—ἦν γάρ τις θεῶν ᾧ τοῦ Οἰβώτα τελεῖσθαι τὰς κατάρας οὐκ ἀμελὲς ἦν—διδάσκονταί ποτε οἱ Ἀχαιοὶ καθ’ ἥντινα αἰτίαν στεφάνου τοῦ Ὀλυμπίασιν ἡμάρτανον, διδάσκονται δὲ ἀποστείλαντες ἐς Δελφούς·", "st": "7.17"}, {"sp": "N", "t": "οὕτω καὶ ἄλλα ἐς τιμήν σφισι τοῦ Οἰβώτα ποιήσασι καὶ τὴν εἰκόνα ἀναθεῖσιν ἐς Ὀλυμπίαν Σώστρατος Πελληνεὺς σταδίου νίκην ἔσχεν ἐν παισί. διαμένει δὲ ἐς ἐμὲ ἔτι Ἀχαιῶν τοῖς ἀγωνίζεσθαι μέλλουσι τὰ Ὀλύμπια ἐναγίζειν τῷ Οἰβώτᾳ, καὶ ἢν κρατήσωσιν, ἐν Ὀλυμπίᾳ στεφανοῦν τοῦ Οἰβώτα τὴν εἰκόνα.", "st": "7.17"}, {"sp": "N", "t": "σταδίους δὲ ὅσον τεσσαράκοντα προελθόντι ἐκ Δύμης ποταμὸς Πεῖρος ἐς θάλατταν κάτεισι, καὶ Ἀχαιῶν πόλις ποτὲ Ὤλενος ᾠκεῖτο παρὰ τῷ Πείρῳ. ὁπόσοι δὲ ἐς Ἡρακλέα καὶ τὰ ἔργα αὐτοῦ πεποιήκασιν, ἔστιν οὐκ ἐλάχιστά σφισι δείγματα τοῦ λόγου Δεξαμενὸς ὁ ἐν Ὠλένῳ βασιλεὺς καὶ ὁποίων Ἡρακλῆς παρ’ αὐτῷ ξενίων ἔτυχε. καὶ ὅτι μὲν ἦν πόλισμα ἐξ ἀρχῆς μικρὸν ἡ Ὤλενος, μαρτυρεῖ τῷ λόγῳ μου καὶ ἐλεγεῖον ἐς Εὐρυτίωνα Κένταυρον ὑπὸ Ἑρμησιάνακτος πεποιημένον· ἀνὰ χρόνον δὲ τοὺς οἰκήτορας ἐκλιπεῖν ὑπὸ ἀσθενείας φασὶ τὴν Ὤλενον καὶ ἐς Πειράς τε καὶ ἐς Εὐρυτειὰς ἀποχωρῆσαι.", "st": "7.18"}, {"sp": "N", "t": "τοῦ δὲ Πείρου ποταμοῦ περὶ τοὺς ὀγδοήκοντα ἀφέστηκε σταδίους Πατρέων ἡ πόλις· οὐ πόρρω δὲ αὐτῆς ποταμὸς Γλαῦκος ἐκδίδωσιν ἐς θάλασσαν. Πατρέων δὲ οἱ τὰ ἀρχαιότατα μνημονεύοντές φασιν Εὔμηλον αὐτόχθονα οἰκῆσαι πρῶτον ἐν τῇ χώρᾳ, βασιλεύοντα αὐτὸν ἀνθρώπων οὐ πολλῶν. Τριπτολέμου δὲ ἐκ τῆς Ἀττικῆς ἀφικομένου τόν τε καρπὸν λαμβάνει τὸν ἥμερον καὶ οἰκίσαι διδαχθεὶς πόλιν Ἀρόην ὠνόμασεν ἐπὶ τῇ ἐργασίᾳ τῆς γῆς.", "st": "7.18"}, {"sp": "N", "t": "ὡς δὲ πρὸς ὕπνον ἐτράπετο ὁ Τριπτόλεμος, ἐνταῦθα Ἀνθείαν παῖδα Εὐμήλου τοὺς δράκοντάς φασιν ὑπὸ τοῦ Τριπτολέμου τὸ ἅρμα ζεύξαντα ἐθελῆσαι καὶ αὐτὸν σπεῖραι· καὶ τὸν μὲν ἐπιλαμβάνει τὸ χρεὼν ἐκπεσόντα τοῦ ἅρματος, Τριπτόλεμος δὲ καὶ Εὔμηλος Ἄνθειαν πόλιν οἰκίζουσιν ἐν κοινῷ, τοῦ Εὐμήλου παιδὸς ἐπώνυμον.", "st": "7.18"}, {"sp": "N", "t": "ᾠκίσθη δὲ καὶ τρίτη μεταξὺ Ἀνθείας καὶ Ἀρόης Μεσάτις πόλις. ὁπόσα δὲ οἱ Πατρεῖς περὶ Διονύσου λέγουσι, τραφῆναί τε αὐτὸν ἐν τῇ Μεσάτει καὶ ἐνταῦθα ἐπιβουλευθέντα ὑπὸ Τιτάνων ἐς παντοῖον ἀφικέσθαι κίνδυνον, οὐκ ἐναντιούμενος τοῖς Πατρεῦσιν [τῆς Μεσάτεως τὸ ὄνομα] αὐτοῖς σφισιν ἐξηγεῖσθαι παρίημι.", "st": "7.18"}, {"sp": "N", "t": "Ἀχαιῶν δὲ ὕστερον ἐκβαλόντων Ἴωνας, Πατρεὺς ὁ Πρευγένους τοῦ Ἀγήνορος ἐς μὲν Ἄνθειαν καὶ ἐς Μεσάτιν μὴ ἐνοικίζεσθαι τοῖς Ἀχαιοῖς ἀπεῖπε, περίβολον δὲ τείχους πρὸς τῇ Ἀρόῃ βαλόμενος μείζονα, ἵνα ἐντός οἱ τοῦ περιβόλου καὶ ἡ Ἀρόη γένηται, ὄνομα ἔθετο ἀφ’ ἑαυτοῦ Πάτρας τῇ πόλει. Ἀγήνωρ δὲ ὁ πατὴρ τοῦ Πρευγένους Ἀρέως παῖς ἦν τοῦ Ἄμπυκος, ὁ δὲ Ἄμπυξ Πελίου τοῦ Αἰγινήτου τοῦ Δηρείτου τοῦ Ἁρπάλου τοῦ Ἀμύκλα τοῦ Λακεδαίμονος.", "st": "7.18"}, {"sp": "N", "t": "Πατρεῖ μὲν τοιαῦτα ἐς τοὺς προγόνους ὑπάρχοντα ἦν· ἰδίᾳ δὲ ἀνὰ χρόνον Πατρεῖς διέβησαν ἐς Αἰτωλίαν Ἀχαιῶν μόνοι κατὰ φιλίαν τὴν Αἰτωλῶν, τὸν πόλεμόν σφισι τὸν πρὸς Γαλάτας συνδιοίσοντες. προσπταίσαντες δ’ ἐν ταῖς μάχαις λόγου μειζόνως καὶ ὑπὸ πενίας ἅμα οἱ πολλοὶ πιεζόμενοι Πάτρας μὲν πλὴν ὀλίγων τινῶν ἐκλείπουσιν· οἱ δὲ ἄλλοι κατὰ χώραν ὑπὸ φιλεργίας ἐσκεδάσθησαν καὶ πολίσματα παρὲξ αὐτὰς Πάτρας τοσάδε ἄλλα ᾤκησαν, Μεσάτιν καὶ Ἄνθειαν καὶ Βολίνην καὶ Ἀργυρᾶν τε καὶ Ἄρβαν.", "st": "7.18"}, {"sp": "N", "t": "Αὔγουστος δὲ ἢ τοῦ παράπλου νομίζων κεῖσθαι καλῶς τὰς Πάτρας ἢ κατ’ ἄλλην τινὰ αἰτίαν ἐπανήγαγεν αὖθις ἐκ τῶν πολισμάτων τῶν ἄλλων τοὺς ἄνδρας ἐς τὰς Πάτρας, προσσυνῴκισε δέ σφισι καὶ Ἀχαιοὺς τοὺς ἐκ Ῥυπῶν, καταβαλὼν ἐς ἔδαφος Ῥύπας· καὶ ἔδωκε μὲν ἐλευθέροις Ἀχαιῶν μόνοις τοῖς Πατρεῦσιν εἶναι, ἔδωκε δὲ καὶ ἐς τὰ ἄλλα γέρα σφίσιν, ὁπόσα τοῖς ἀποίκοις νέμειν οἱ Ῥωμαῖοι νομίζουσι.", "st": "7.18"}, {"sp": "N", "t": "Πατρεῦσι δὲ ἐν ἄκρᾳ τῇ πόλει Λαφρίας ἱερόν ἐστιν Ἀρτέμιδος· ξενικὸν μὲν τῇ θεῷ τὸ ὄνομα, ἐσηγμένον δὲ ἑτέρωθεν καὶ τὸ ἄγαλμα. Καλυδῶνος γὰρ καὶ Αἰτωλίας τῆς ἄλλης ὑπὸ Αὐγούστου βασιλέως ἐρημωθείσης διὰ τὸ [τὴν] ἐς ⟨τὴν⟩ Νικόπολιν τὴν ὑπὲρ τοῦ Ἀκτίου συνοικίζεσθαι καὶ τὸ Αἰτωλικόν, οὕτω τὸ ἄγαλμα τῆς Λαφρίας οἱ Πατρεῖς ἔσχον.", "st": "7.18"}, {"sp": "N", "t": "ὡσαύτως δὲ καὶ ὅσα ἄλλα ἀγάλματα ἔκ τε Αἰτωλίας καὶ παρὰ Ἀκαρνάνων, τὰ μὲν πολλὰ ἐς τὴν Νικόπολιν κομισθῆναι, Πατρεῦσι δὲ ὁ Αὔγουστος ἄλλα τε τῶν ἐκ Καλυδῶνος λαφύρων καὶ δὴ καὶ τῆς Λαφρίας ἔδωκε τὸ ἄγαλμα, ὃ δὴ καὶ ἐς ἐμὲ ἔτι ἐν τῇ ἀκροπόλει τῇ Πατρέων εἶχε τιμάς. γενέσθαι δὲ ἐπίκλησιν τῇ θεῷ Λαφρίαν ἀπὸ ἀνδρὸς Φωκέως φασί· Λάφριον γὰρ τὸν Κασταλίου τοῦ Δελφοῦ Καλυδωνίοις ἱδρύσασθαι τὸ ἄγαλμα τῆς Ἀρτέμιδος τὸ ἀρχαῖον, οἱ δὲ τῆς Ἀρτέμιδος τὸ μήνιμα τὸ", "st": "7.18"}, {"sp": "N", "t": "ἐς Οἰνέα ἀνὰ χρόνον τοῖς Καλυδωνίοις ἐλαφρότερον γενέσθαι λέγουσι καὶ αἰτίαν τῇ θεῷ τῆς ἐπικλήσεως ἐθέλουσιν εἶναι ταύτην. τὸ μὲν σχῆμα τοῦ ἀγάλματος θηρεύουσά ἐστιν, ἐλέφαντος δὲ καὶ χρυσοῦ πεποίηται, Ναυπάκτιοι δὲ Μέναιχμος καὶ Σοΐδας εἰργάσαντο· τεκμαίρονται σφᾶς Κανάχου τοῦ Σικυωνίου καὶ τοῦ Αἰγινήτου Κάλλωνος οὐ πολλῷ γενέσθαι τινὶ ἡλικίαν ὑστέρους.", "st": "7.18"}, {"sp": "N", "t": "ἄγουσι δὲ καὶ Λάφρια ἑορτὴν τῇ Ἀρτέμιδι οἱ Πατρεῖς ἀνὰ πᾶν ἔτος, ἐν ᾗ τρόπος ἐπιχώριος θυσίας ἐστὶν αὐτοῖς. περὶ μὲν τὸν βωμὸν ἐν κύκλῳ ξύλα ἱστᾶσιν ἔτι χλωρὰ καὶ ἐς ἑκκαίδεκα ἕκαστον πήχεις· ἐντὸς δὲ ἐπὶ τοῦ βωμοῦ τὰ αὐότατά σφισι τῶν ξύλων κεῖται. μηχανῶνται δὲ ὑπὸ τὸν καιρὸν τῆς ἑορτῆς καὶ ἄνοδον ἐπὶ τὸν βωμὸν λειοτέραν, ἐπιφέροντες γῆν ἐπὶ τοῦ βωμοῦ τοὺς ἀναβασμούς.", "st": "7.18"}, {"sp": "N", "t": "πρῶτα μὲν δὴ πομπὴν μεγαλοπρεπεστάτην τῇ Ἀρτέμιδι πομπεύουσι, καὶ ἡ ἱερωμένη παρθένος ὀχεῖται τελευταία τῆς πομπῆς ἐπὶ ἐλάφων ὑπὸ τὸ ἅρμα ἐζευγμένων· ἐς δὲ τὴν ἐπιοῦσαν τηνικαῦτα ἤδη δρᾶν τὰ ἐς τὴν θυσίαν νομίζουσι, δημοσίᾳ τε ἡ πόλις καὶ οὐχ ἧσσον ἐς τὴν ἑορτὴν οἱ ἰδιῶται φιλοτίμως ἔχουσιν. ἐσβάλλουσι γὰρ ζῶντας ἐς τὸν βωμὸν ὄρνιθάς τε τοὺς ἐδωδίμους καὶ ἱερεῖα ὁμοίως ἅπαντα, ἔτι δὲ ὗς ἀγρίους καὶ ἐλάφους τε καὶ δορκάδας, οἱ δὲ καὶ λύκων καὶ ἄρκτων σκύμνους, οἱ δὲ καὶ τὰ τέλεια τῶν θηρίων· κατατιθέασι δὲ ἐπὶ τὸν βωμὸν καὶ δένδρων καρπὸν τῶν ἡμέρων.", "st": "7.18"}, {"sp": "N", "t": "τὸ δὲ ἀπὸ τούτου πῦρ ἐνιᾶσιν ἐς τὰ ξύλα. ἐνταῦθά που καὶ ἄρκτον καὶ ἄλλο τι ἐθεασάμην τῶν ζῴων, τὰ μὲν ὑπὸ τὴν πρώτην ὁρμὴν τοῦ πυρὸς βιαζόμενα ἐς τὸ ἐκτός, τὰ δὲ καὶ ἐκφεύγοντα ὑπὸ ἰσχύος· ταῦτα οἱ ἐμβαλόντες ἐπανάγουσιν αὖθις ἐς τὴν πυράν. τρωθῆναι δὲ οὐδένα ὑπὸ ⟨τῶν⟩ θηρίων μνημονεύουσιν.", "st": "7.18"}, {"sp": "N", "t": "ἔστι δὲ ἐν τῷ μεταξὺ τοῦ ναοῦ τε τῆς Λαφρίας καὶ τοῦ βωμοῦ πεποιημένον μνῆμα Εὐρυπύλου. τὰ δὲ ὅστις τε ὢν καὶ καθ’ ἥντινα αἰτίαν ἀφίκετο ἐς τὴν γῆν ταύτην, δηλώσει μοι καὶ ταῦτα ὁ λόγος προδιηγησαμένῳ πρότερον ὁποῖα ὑπὸ τοῦ Εὐρυπύλου τὴν ἐπιδημίαν τοῖς ἐνταῦθα ἦν τὰ παρόντα [τοῖς] ἀνθρώποις. Ἰώνων τοῖς Ἀρόην καὶ Ἄνθειαν καὶ Μεσάτιν οἰκοῦσιν ἦν ἐν κοινῷ τέμενος καὶ ναὸς Ἀρτέμιδος Τρικλαρίας ἐπίκλησιν, καὶ ἑορτὴν οἱ Ἴωνες αὐτῇ καὶ παννυχίδα ἦγον ἀνὰ πᾶν ἔτος. ἱερωσύνην δὲ εἶχε τῆς θεοῦ παρθένος, ἐς ὃ ἀποστέλλεσθαι παρὰ ἄνδρα ἔμελλε.", "st": "7.19"}, {"sp": "N", "t": "λέγουσιν οὖν συμβῆναί ποτε ὡς ἱερᾶσθαι μὲν τῆς θεοῦ Κομαιθὼ τὸ εἶδος καλλίστην παρθένον, τυγχάνειν δὲ αὐτῆς ἐρῶντα Μελάνιππον, τά τε ἄλλα τοὺς ἡλικιώτας καὶ ὄψεως εὐπρεπείᾳ μάλιστα ὑπερηρκότα. ὡς δὲ ὁ Μελάνιππος ἐς τὸ ἴσον τοῦ ἔρωτος ὑπηγάγετο τὴν παρθένον, ἐμνᾶτο αὐτὴν παρὰ τοῦ πατρός. ἕπεται δέ πως τῷ γήρᾳ τά τε ἄλλα ὡς τὸ πολὺ ἐναντιοῦσθαι νέοις καὶ οὐχ ἥκιστα ἐς τοὺς ἐρῶντας τὸ ἀνάλγητον, ὅπου καὶ Μελανίππῳ τότε ἐθέλοντι ἐθέλουσαν ἄγεσθαι Κομαιθὼ οὔτε παρὰ τῶν ἑαυτοῦ γονέων οὔτε παρὰ τῶν Κομαιθοῦς ἥμερον ἀπήντησεν οὐδέν.", "st": "7.19"}, {"sp": "N", "t": "ἐπέδειξε δὲ ἐπὶ πολλῶν τε δὴ ἄλλων καὶ ἐν τοῖς Μελανίππου παθήμασιν, ὡς μέτεστιν ἔρωτι καὶ ἀνθρώπων συγχέαι νόμιμα καὶ ἀνατρέψαι θεῶν τιμάς, ὅπου καὶ τότε ἐν τῷ τῆς Ἀρτέμιδος ἱερῷ Κομαιθὼ καὶ Μελάνιππος [καὶ] ἐξέπλησαν τοῦ ἔρωτος τὴν ὁρμήν. καὶ οἱ μὲν ἔμελλον τῷ ἱερῷ καὶ ἐς τὸ ἔπειτα ἴσα καὶ θαλάμῳ χρήσεσθαι· τοὺς δὲ ἀνθρώπους αὐτίκα ἐξ Ἀρτέμιδος μήνιμα ἔφθειρε, τῆς τε γῆς καρπὸν οὐδένα ἀποδιδούσης καὶ νόσοι σφίσιν οὐ κατὰ τὰ εἰωθότα καὶ ἀπ’ αὐτῶν θάνατοι πλείονες ἢ τὰ πρότερα ἐγίνοντο.", "st": "7.19"}, {"sp": "N", "t": "καταφυγόντων δὲ αὐτῶν ἐπὶ χρηστήριον τὸ ἐν Δελφοῖς, ἤλεγχεν ἡ Πυθία Μελάνιππον καὶ Κομαιθώ· καὶ ἐκείνους τε αὐτοὺς μάντευμα ἀφίκετο θῦσαι τῇ Ἀρτέμιδι καὶ ἀνὰ πᾶν ἔτος παρθένον καὶ παῖδα οἳ τὸ εἶδος εἶεν κάλλιστοι τῇ θεῷ θύειν. ταύτης μὲν δὴ τῆς θυσίας ἕνεκα ὁ ποταμὸς ὁ πρὸς τῷ ἱερῷ τῆς Τρικλαρίας Ἀμείλιχος ἐκλήθη·", "st": "7.19"}, {"sp": "N", "t": "τέως δὲ ὄνομα εἶχεν οὐδέν. παίδων δὲ καὶ παρθένων ὁπόσοι μὲν ἐς τὴν θεὸν οὐδὲν εἰργασμένοι Μελανίππου καὶ Κομαιθοῦς ἕνεκα ἀπώλλυντο, αὐτοί τε οἰκτρότατα καὶ οἱ προσήκοντές σφισιν ἔπασχον, Μελάνιππον δὲ καὶ Κομαιθὼ συμφορᾶς ἐκτὸς γενέσθαι τίθεμαι· μόνον γὰρ δὴ ἀνθρώπῳ ψυχῆς ἐστιν ἀντάξιον κατορθῶσαί τινα ἐρασθέντα.", "st": "7.19"}, {"sp": "N", "t": "παύσασθαι δὲ οὕτω λέγονται θύοντες τῇ Ἀρτέμιδι ἀνθρώπους. ἐκέχρητο [δὲ] αὐτοῖς πρότερον ἔτι ἐκ Δελφῶν ὡς βασιλεὺς ξένος παραγενόμενός σφισιν ἐπὶ τὴν γῆν, ξενικὸν ἅμα ἀγόμενος δαίμονα, τὰ ἐς τὴν θυσίαν τῆς Τρικλαρίας παύσει. Ἰλίου δὲ ἁλούσης καὶ νεμομένων τὰ λάφυρα τῶν Ἑλλήνων, Εὐρύπυλος ὁ Εὐαίμονος λαμβάνει λάρνακα· Διονύσου δὲ ἄγαλμα ἦν ἐν τῇ λάρνακι, ἔργον μὲν ὥς φασιν Ἡφαίστου, δῶρον δὲ ὑπὸ Διὸς ἐδόθη Δαρδάνῳ.", "st": "7.19"}, {"sp": "N", "t": "λέγονται δὲ καὶ ἄλλοι λόγοι δύο ἐς αὐτήν, ὡς ὅτε ἔφυγεν Αἰνείας, ἀπολίποι ταύτην τὴν λάρνακα· οἱ δὲ ῥιφῆναί φασιν αὐτὴν ὑπὸ Κασσάνδρας συμφορὰν τῷ εὑρόντι Ἑλλήνων. ἤνοιξε δ’ οὖν ὁ Εὐρύπυλος τὴν λάρνακα καὶ εἶδε τὸ ἄγαλμα καὶ αὐτίκα ἦν ἔκφρων μετὰ τὴν θέαν· τὰ μὲν δὴ πλείονα ἐμαίνετο, ὀλιγάκις δὲ ἐγίνετο ἐν ἑαυτῷ. ἅτε δὲ οὕτω διακείμενος οὐκ ἐς τὴν Θεσσαλίαν τὸν πλοῦν ἐποιεῖτο, ἀλλ’ ἐπί τε Κίρραν καὶ ἐς τὸν ταύτῃ κόλπον· ἀναβὰς δὲ ἐς Δελφοὺς ἐχρᾶτο ὑπὲρ τῆς νόσου.", "st": "7.19"}, {"sp": "N", "t": "καὶ αὐτῷ γενέσθαι λέγουσι μάντευμα, ἔνθα ἂν ἐπιτύχῃ θύουσιν ἀνθρώποις θυσίαν ξένην, ἐνταῦθα ἱδρύσασθαί τε τὴν λάρνακα καὶ αὐτὸν οἰκῆσαι. ὁ μὲν δὴ ἄνεμος τὰς ναῦς τοῦ Εὐρυπύλου κατήνεγκεν ἐπὶ τὴν πρὸς τῇ Ἀρόῃ θάλασσαν· ἐκβὰς δὲ ἐς τὴν γῆν καταλαμβάνει παῖδα καὶ παρθένον ἐπὶ τὸν βωμὸν τῆς Τρικλαρίας ἠγμένους. καὶ ὁ μὲν ἔμελλεν οὐ χαλεπῶς συνήσειν τὰ ἐς τὴν θυσίαν· ἀφίκοντο δὲ ἐς μνήμην καὶ οἱ ἐπιχώριοι τοῦ χρησμοῦ, βασιλέα τε ἰδόντες ὃν οὔπω πρότερον ἑωράκεσαν καὶ ἐς τὴν λάρνακα ὑπενόησαν ὡς εἴη τις ἐν αὐτῇ θεός.", "st": "7.19"}, {"sp": "N", "t": "καὶ οὕτω τῷ Εὐρυπύλῳ τε ἡ νόσος καὶ τοῖς ἐνταῦθα ἀνθρώποις τὰ ἐς τὴν θυσίαν ἐπαύσθη, τό τε ὄνομα ἐτέθη τὸ νῦν τῷ ποταμῷ Μείλιχος. ἔγραψαν δὲ ἤδη τινὲς οὐ τῷ Θεσσαλῷ συμβάντα Εὐρυπύλῳ τὰ εἰρημένα, ἀλλὰ Εὐρύπυλον Δεξαμενοῦ παῖδα τοῦ ἐν Ὠλένῳ βασιλεύσαντος ἐθέλουσιν ἅμα Ἡρακλεῖ στρατεύσαντα ἐς Ἴλιον λαβεῖν παρὰ τοῦ Ἡρακλέους τὴν λάρνακα· τὰ δὲ ἄλλα κατὰ τὰ αὐτὰ εἰρήκασι καὶ οὗτοι.", "st": "7.19"}, {"sp": "N", "t": "ἐγὼ δὲ οὔτε Ἡρακλέα ἀγνοῆσαι τὰ ἐς τὴν λάρνακα εἰ δὴ τοιαῦτα ἦν πείθομαι οὔτε τὰ ἐς αὐτὴν ἐπιστάμενος δοκεῖ μοί ποτε ἂν δοῦναι δῶρον συμμαχήσαντι ἀνδρί· οὔτε μὴν οἱ Πατρεῖς ἄλλον τινὰ ἢ τὸν Εὐαίμονος ἔχουσιν Εὐρύπυλον ἐν μνήμῃ, καί οἱ καὶ ἐναγίζουσιν ἀνὰ πᾶν ἔτος, ἐπειδὰν τῷ Διονύσῳ τὴν ἑορτὴν ἄγωσι.", "st": "7.19"}, {"sp": "N", "t": "τῷ θεῷ δὲ τῷ ἐντὸς τῆς λάρνακος ἐπίκλησις μέν ἐστιν Αἰσυμνήτης, οἱ δὲ αὐτὸν ἐς τὰ μάλιστα θεραπεύοντες ἐννέα τέ εἰσιν ἄνδρες, οὓς ἂν ἐκ πάντων ὁ δῆμος προέληται κατ’ ἀξίωμα, καὶ ἴσαι γυναῖκες τοῖς ἀνδράσι. μιᾷ δὲ ἐν τῇ ἑορτῇ νυκτὶ ἐς τὸ ἐκτὸς φέρει τὴν λάρνακα ὁ ἱερεύς. αὕτη μὲν δὴ ἡ νὺξ γέρας τοῦτο εἴληφε, καταβαίνουσι δὲ καὶ ὁπόσοι δὴ τῶν ἐπιχωρίων παῖδες ἐπὶ τὸν Μείλιχον ἀστάχυσιν ἐστεφανωμένοι τὰς κεφαλάς· ἐκόσμουν δὲ οὕτω καὶ τὸ ἀρχαῖον οὓς ἄγοιεν τῇ Ἀρτέμιδι θύσοντες.", "st": "7.20"}, {"sp": "N", "t": "τὰ δὲ ἐφ’ ἡμῶν στεφάνους μὲν τῶν ἀσταχύων ἀποτίθενται παρὰ τῇ θεῷ, λουσάμενοι δὲ τῷ ποταμῷ καὶ αὖθις στεφάνους ἐπιθέμενοι κισσοῦ πρὸς τὸ ἱερὸν ἴασι τοῦ Αἰσυμνήτου. ταῦτα μέν σφισιν οὕτω δρᾶν καθέστηκε, τοῦ περιβόλου δέ ἐστιν ἐντὸς τῆς Λαφρίας καὶ Ἀθηνᾶς ναὸς ἐπίκλησιν Παναχαΐδος· ἐλέφαντος τὸ ἄγαλμα καὶ χρυσοῦ.", "st": "7.20"}, {"sp": "N", "t": "ἐρχομένῳ δὲ ἐς τὴν κάτω πόλιν Μητρὸς Δινδυμήνης ἐστὶν ἱερόν, ἐν δὲ αὐτῷ καὶ Ἄττης ἔχει τιμάς. τούτου μὲν δὴ [τὸ] ἄγαλμα οὐδὲν ἀποφαίνουσι· τὸ δὲ τῆς Μητρὸς λίθου πεποίηται. ἔστι δὲ ἐν τῇ ἀγορᾷ Διὸς ναὸς Ὀλυμπίου, αὐτός τε ἐπὶ θρόνου καὶ ἑστῶσα Ἀθηνᾶ παρὰ τὸν θρόνον, τῆς τε Ἥρας ἄγαλμα τοῦ Ὀλυμπίου πέραν ἱερόν τε Ἀπόλλωνος πεποίηται καὶ Ἀπόλλων χαλκοῦς, γυμνὸς ἐσθῆτος· ὑποδήματα δὲ ὑπὸ τοῖς ποσίν ἐστιν αὐτῷ, καὶ τῷ ἑτέρῳ ποδὶ ἐπὶ κρανίου βέβηκε βοός.", "st": "7.20"}, {"sp": "N", "t": "βουσὶ γὰρ χαίρειν μάλιστα Ἀπόλλωνα Ἀλκαῖός τε ἐδήλωσεν ἐν ὕμνῳ τῷ ἐς Ἑρμῆν, γράψας ὡς ὁ Ἑρμῆς βοῦς ὑφέλοιτο τοῦ Ἀπόλλωνος, καὶ ἔτι πρότερον ἢ Ἀλκαῖον γενέσθαι πεποιημένα ἦν Ὁμήρῳ βοῦς Ἀπόλλωνα Λαομέδοντος ἐπὶ μισθῷ νέμειν· Ποσειδῶνι περιέθηκεν ἐν Ἰλιάδι τὰ ἔπη,", "st": "7.20"}, {"sp": "N", "t": "ἤτοι ἐγὼ Τρώεσσι πόλιν πέρι τεῖχος ἔδειμα,<br>εὐρύ τε καὶ μάλα καλόν, ἵν’ ἄρρηκτος πόλις εἴη·<br>Φοῖβε, σὺ δ’ εἰλίποδας ἕλικας βοῦς βουκολέεσκες.<br>τὰ μὲν δὴ ἐς τὸ κρανίον τοῦ βοὸς ἐπὶ τοιῷδε ἄν τις εἰκάσειε πεποιῆσθαι· ἔστι δὲ ἐν ὑπαίθρῳ τῆς ἀγορᾶς ἄγαλμά τε Ἀθηνᾶς καὶ πρὸ αὐτοῦ Πατρέως τάφος.", "st": "7.20"}, {"sp": "N", "t": "ἔχεται δὲ τῆς ἀγορᾶς τὸ Ὠιδεῖον, καὶ Ἀπόλλων ἐνταῦθα ἀνάκειται θέας ἄξιος· ἐποιήθη δὲ ἀπὸ λαφύρων, ἡνίκα ἐπὶ τὸν στρατὸν τῶν Γαλατῶν οἱ Πατρεῖς ἤμυναν Αἰτωλοῖς Ἀχαιῶν μόνοι. κεκόσμηται δὲ καὶ ἐς ἄλλα τὸ Ὠιδεῖον ἀξιολογώτατα τῶν ἐν Ἕλλησι, πλήν γε δὴ τοῦ Ἀθήνῃσι· τοῦτο γὰρ μεγέθει τε καὶ ἐς τὴν πᾶσαν ὑπερῆρκε κατασκευήν, ἀνὴρ δὲ Ἀθηναῖος ἐποίησεν Ἡρώδης ἐς μνήμην ἀποθανούσης γυναικός. ἐμοὶ δὲ ἐν τῇ Ἀτθίδι συγγραφῇ τὸ ἐς τοῦτο παρείθη τὸ Ὠιδεῖον, ὅτι πρότερον ἔτι ἐξείργαστό μοι τὰ ἐς Ἀθηναίους ἢ ὑπῆρκτο Ἡρώδης τοῦ οἰκοδομήματος.", "st": "7.20"}, {"sp": "N", "t": "ἐν Πάτραις δὲ ἰόντι ἐκ τῆς ἀγορᾶς, ᾗ τὸ ἱερὸν τοῦ Ἀπόλλωνος, πύλη κατὰ τὴν ἔξοδόν ἐστι ταύτην, καὶ ἐπιθήματα ἐπὶ τῆς πύλης ἀνδριάντες εἰσὶν ἐπίχρυσοι, Πατρεύς τε καὶ Πρευγένης καὶ Ἀθερίων, οἳ Πατρέως ἡλικίαν παιδὸς ἔχοντος καὶ αὐτοὶ παῖδές εἰσι. τῆς δὲ ἀγορᾶς ἄντικρυς κατὰ ταύτην τὴν διέξοδον τέμενός ἐστιν Ἀρτέμιδος καὶ ναὸς Λιμνάτιδος.", "st": "7.20"}, {"sp": "N", "t": "ἐχόντων δὲ ἤδη Λακεδαίμονα καὶ Ἄργος Δωριέων, ὑφελέσθαι Πρευγένην τῆς Λιμνάτιδος τὸ ἄγαλμα κατὰ ὄψιν ὀνείρατος λέγουσιν ἐκ Σπάρτης, κοινωνῆσαι δὲ αὐτῷ τοῦ ἐγχειρήματος τῶν δούλων τὸν εὐνούστατον. τὸ δὲ ἄγαλμα τὸ ἐκ τῆς Λακεδαίμονος τὸν μὲν ἄλλον χρόνον ἔχουσιν ἐν Μεσόᾳ, ὅτι καὶ ἐξ ἀρχῆς ὑπὸ τοῦ Πρευγένους ἐς τοῦτο ἐκομίσθη τὸ χωρίον· ἐπειδὰν δὲ τῇ Λιμνάτιδι τὴν ἑορτὴν ἄγωσι, τῆς θεοῦ τις τῶν οἰκετῶν ἐκ Μεσόας ἔρχεται τὸ ξόανον κομίζων τὸ ἀρχαῖον ἐς τὸ τέμενος τὸ ἐν τῇ πόλει.", "st": "7.20"}, {"sp": "N", "t": "τούτου δὲ τοῦ τεμένους ἐστὶ καὶ ἄλλα τοῖς Πατρεῦσιν ἱερά· πεποίηται δὲ ταῦτα οὐκ ἐν ὑπαίθρῳ, ἀλλὰ ἔσοδος ἐς αὐτὰ διὰ τῶν στοῶν ἐστι. τὸ μὲν δὴ ἄγαλμα τοῦ Ἀσκληπιοῦ, πλὴν ἐσθῆτος, λίθου τὰ ἄλλα· Ἀθηνᾶ δὲ ἐλέφαντος εἴργασται καὶ χρυσοῦ. πρὸ δὲ τῆς Ἀθηνᾶς τοῦ ἱεροῦ Πρευγένους μνῆμά ἐστιν· ἐναγίζουσι δὲ καὶ τῷ Πρευγένει κατὰ ἔτος, ὡσαύτω; δὲ καὶ Πατρεῖ, τὴν ἑορτὴν τῇ Λιμνάτιδι ἄγοντες. τοῦ θεάτρου δὲ οὐ πόρρω Νεμέσεως ναὸς καὶ ἕτερός ἐστιν Ἀφροδίτης· μεγέθει μεγάλα λίθου λευκοῦ τὰ ἀγάλματα.", "st": "7.20"}, {"sp": "N", "t": "καὶ Διονύσου κατὰ τοῦτο τῆς πόλεώς ἐστιν ἱερὸν ἐπίκλησιν Καλυδωνίου· μετεκομίσθη γὰρ καὶ τοῦ Διονύσου τὸ ἄγαλμα ἐκ Καλυδῶνος. ὅτε δὲ ᾠκεῖτο ἔτι Καλυδών, ἄλλοι τε Καλυδωνίων ἐγένοντο ἱερεῖς τῷ θεῷ καὶ δὴ καὶ Κόρεσος, ὃν ἀνθρώπων μάλιστα ἐπέλαβεν ἄδικα ἐξ ἔρωτος παθεῖν. ἤρα μὲν Καλλιρόης παρθένου· ὁπόσον δὲ ἐς Καλλιρόην ἔρωτος Κορέσῳ μετῆν, τοσοῦτο εἶχεν ἀπεχθείας ἐς αὐτὸν ἡ παρθένος.", "st": "7.21"}, {"sp": "N", "t": "ὡς δὲ τοῦ Κορέσου δεήσεις τε ποιουμένου πάσας καὶ δώρων ὑποσχέσεις παντοίας οὐκ ἐνετρέπετο ἡ γνώμη τῆς παρθένου, ἐκομίζετο ἱκέτης ἤδη παρὰ τοῦ Διονύσου τὸ ἄγαλμα. ὁ δὲ ἤκουσέ τε εὐχομένου τοῦ ἱερέως καὶ οἱ Καλυδώνιοι τὸ παραυτίκα ὥσπερ ὑπὸ μέθης ἐγίνοντο ἔκφρονες καὶ ἡ τελευτὴ σφᾶς παραπλῆγας ἐπελάμβανε. καταφεύγουσιν οὖν ἐπὶ τὸ χρηστήριον τὸ ἐν Δωδώνῃ· τοῖς γὰρ τὴν ἤπειρον ταύτην οἰκοῦσι, τοῖς τε Αἰτωλοῖς καὶ τοῖς προσχώροις αὐτῶν Ἀκαρνᾶσι καὶ Ἠπειρώταις, αἱ πέλειαι καὶ τὰ ἐκ τῆς δρυὸς μαντεύματα μετέχειν μάλιστα ἐφαίνετο ἀληθείας.", "st": "7.21"}, {"sp": "N", "t": "τότε δὲ τὰ χρησθέντα ἐκ Δωδώνης Διονύσου μὲν ἔλεγεν εἶναι τὸ μήνιμα, ἔσεσθαι δὲ οὐ πρότερον λύσιν πρὶν ἢ θύσῃ τῷ Διονύσῳ Κόρεσος ἢ αὐτὴν Καλλιρόην ἢ τὸν ἀποθανεῖν ἀντ’ ἐκείνης τολμήσαντα. ὡς δὲ οὐδὲν ἐς σωτηρίαν εὑρίσκετο ἡ παρθένος, δεύτερα ἐπὶ τοὺς θρεψαμένους καταφεύγει· ἁμαρτάνουσα δὲ καὶ τούτων, ἐλείπετο οὐδὲν ἔτι ἢ αὐτὴν φονεύεσθαι.", "st": "7.21"}, {"sp": "N", "t": "προεξεργασθέντων δὲ ὁπόσα ἐς τὴν θυσίαν ἄλλα ἐκ Δωδώνης μεμαντευμένα ἦν, ἡ μὲν ἱερείου τρόπον ἦκτο ἐπὶ τὸν βωμόν, Κόρεσος δὲ ἐφειστήκει μὲν τῇ θυσίᾳ, τῷ δὲ ἔρωτι εἴξας καὶ οὐ τῷ θυμῷ ἑαυτὸν ἀντὶ Καλλιρόης διεργάζεται. ὁ μὲν δὴ ἀπέδειξεν ἔργον ἀνθρώπων ὧν ἴσμεν διατεθεὶς ἐς ἔρωτα ἀπλαστότατα·", "st": "7.21"}, {"sp": "N", "t": "Καλλιρόη τε ὡς Κόρεσον τεθνεῶτα εἶδεν, μετέπεσε τῇ παιδὶ ἡ γνώμη, καὶ—ἐσῄει γὰρ αὐτὴν Κορέσου τε ἔλεος καὶ ὅσα ἐς αὐτὸν εἴργασται αἰδώς—ἀπέσφαξέ ⟨τε⟩ αὑτὴν ἐς τὴν πηγήν, [τοῦ λιμένος] ἣ ἐν Καλυδῶνί ἐστιν οὐ πόρρω ⟨τοῦ λιμένος⟩, καὶ ἀπ’ ἐκείνης οἱ ἔπειτα ἄνθρωποι Καλλιρόην τὴν πηγὴν καλοῦσι.", "st": "7.21"}, {"sp": "N", "t": "τοῦ θεάτρου δὲ ἐγγὺς πεποίηται Πατρεῦσι γυναικὸς ἐπιχωρίας τέμενος. Διονύσου δέ ἐστιν ἐνταῦθα ἀγάλματα, ἴσοι τε τοῖς ἀρχαίοις πολίσμασι καὶ ὁμώνυμοι· Μεσατεὺς γὰρ καὶ Ἀνθεύς τε καὶ Ἀροεύς ἐστιν αὐτοῖς τὰ ὀνόματα. ταῦτα τὰ ἀγάλματα ἐν τῇ Διονύσου [τῇ] ἑορτῇ κομίζουσιν ἐς τὸ ἱερὸν τοῦ Αἰσυμνήτου· τὸ δὲ ἱερὸν τοῦτο ἐς τὰ ἐπὶ θαλάσσῃ τῆς πόλεως ἐρχομένοις ἔστιν ἐκ τῆς ἀγορᾶς ἐν δεξιᾷ τῆς ὁδοῦ.", "st": "7.21"}, {"sp": "N", "t": "ἀπὸ δὲ τοῦ Αἰσυμνήτου κατωτέρω ἰόντι ἄλλο ἱερὸν καὶ ἄγαλμα λίθου· καλεῖται μὲν Σωτηρίας, ἱδρύσασθαι δὲ αὐτὸ ἐξ ἀρχῆς ἀποφυγόντα φασὶ τὴν μανίαν Εὐρύπυλον. πρὸς δὲ τῷ λιμένι Ποσειδῶνός τε ναὸς καὶ ἄγαλμά ἐστιν ὀρθὸν λίθου. Ποσειδῶνι δὲ παρὲξ ἢ ὁπόσα ὀνόματα ποιηταῖς πεποιημένα ἐστὶν ἐς ἐπῶν κόσμον καὶ ἰδίᾳ σφίσιν ἐπιχώρια ὄντα ἕκαστοι τίθενται, τοσαίδε ἐς ἅπαντας γεγόνασιν ἐπικλήσεις αὐτῷ, Πελαγαῖος καὶ Ἀσφάλιός τε καὶ Ἵππιος.", "st": "7.21"}, {"sp": "N", "t": "ὠνομάσθαι δὲ Ἵππιον τὸν θεὸν πείθοιτο μὲν ἄν τις καὶ ἐπ’ αἰτίαις ἄλλαις· ἐγὼ δὲ εὑρετὴν ἱππικῆς ὄντα ἀπὸ τούτου σχεῖν καὶ τὸ ὄνομα εἰκάζω. Ὅμηρος μέν γε ἐν ἵππων ἄθλοις Μενελάῳ κατὰ τοῦ θεοῦ τούτου πρόκλησιν περιέθηκεν ὅρκου·<br>ἵππων ἁψάμενος, γαιήοχον ἐννοσίγαιον<br>ὄμνυθι μηδὲν ἑκὼν τὸ ἐμὸν δόλῳ ἅρμα πεδῆσαι.", "st": "7.21"}, {"sp": "N", "t": "Πάμφως δέ, ὃς Ἀθηναίοις τοὺς ἀρχαιοτάτους ⟨τῶν⟩ ὕμνων ἐποίησεν, εἶναί φησι τὸν Ποσειδῶνα<br>ἵππων τε δωτῆρα νεῶν τ’ ἰθυκρηδέμνων.<br>οὕτω διὰ τὴν ἱππικὴν καὶ οὐκ ἀπὸ ἑτέρας προφάσεως τὸ ὄνομα ἔσχηκεν.", "st": "7.21"}, {"sp": "N", "t": "ἐν Πάτραις δὲ οὐ πολὺ ἀπωτέρω τοῦ Ποσειδῶνος ἱερά ἐστιν Ἀφροδίτης· τὸ δὲ ἕτερον τῶν ἀγαλμάτων γενεᾷ πρότερον ἢ κατ’ ἐμὲ ἁλιεῖς ἄνδρες ἀνείλκυσαν ἐν δικτύῳ. ἔστι δὲ καὶ ἀγάλματα τοῦ λιμένος ἐγγυτάτω χαλκοῦ πεποιημένα Ἄρεως, τὸ δὲ Ἀπόλλωνος· καὶ Ἀφροδίτης, ⟨ἧς⟩ καὶ πρὸς τῷ λιμένι [δὲ] ἐστὶ τέμενος, λίθου μὲν πρόσωπον καὶ ἄκραι χεῖρες καὶ πόδες, ξύλου δὲ τὰ λοιπὰ εἴργασται.", "st": "7.21"}, {"sp": "N", "t": "ἔστι δέ σφισι καὶ ἄλσος ἐπὶ θαλάσσῃ, δρόμους τε ἐπιτηδειοτάτους καὶ ἐς τἄλλα δίαιταν ἡδεῖαν ὥρᾳ παρεχόμενον θερινῇ. ἐν τούτῳ τῷ ἄλσει καὶ ναοὶ θεῶν, Ἀπόλλωνος, ὁ δὲ Ἀφροδίτης· πεποίηται λίθου καὶ τούτοις τὰ ἀγάλματα. τοῦ δὲ ἄλσους ἱερὸν ἔχεται Δήμητρος· αὕτη μὲν καὶ ἡ παῖς ἑστᾶσι, τὸ δὲ ἄγαλμα τῆς Γῆς ἐστι καθήμενον.", "st": "7.21"}, {"sp": "N", "t": "πρὸ δὲ τοῦ ἱεροῦ τῆς Δήμητρός ἐστι πηγή· ταύτης τὰ μὲν πρὸς τοῦ ναοῦ λίθων ἀνέστηκεν αἱμασιά, κατὰ δὲ τὸ ἐκτὸς κάθοδος ἐς αὐτὴν πεποίηται. μαντεῖον δὲ ἐνταῦθά ἐστιν ἀψευδές, οὐ μὲν ἐπὶ παντί γε πράγματι, ἀλλὰ ἐπὶ τῶν καμνόντων. κάτοπτρον καλῳδίῳ τῶν λεπτῶν δήσαντες καθιᾶσι, σταθμώμενοι μὴ πρόσω καθικέσθαι τῆς πηγῆς, ἀλλ’ ὅσον ἐπιψαῦσαι τοῦ ὕδατος τῷ κύκλῳ τοῦ κατόπτρου. τὸ δὲ ἐντεῦθεν εὐξάμενοι τῇ θεῷ καὶ θυμιάσαντες ἐς τὸ κάτοπτρον βλέπουσι· τὸ δέ σφισι τὸν νοσοῦντα ἤτοι ζῶντα ἢ καὶ τεθνεῶτα ἐπιδείκνυσι.", "st": "7.21"}, {"sp": "N", "t": "τούτῳ μὲν τῷ ὕδατι ἐς τοσοῦτο μέτεστιν ἀληθείας, Κυανεῶν δὲ τῶν πρὸς Λυκίᾳ πλησιαίτατα χρηστήριον Ἀπόλλωνός ἐστι Θυρξέως· παρέχεται δὲ ὕδωρ τὸ πρὸς ταῖς Κυανέαις ἔσω ἐνιδόντα τινὰ ἐς τὴν πηγὴν ὁμοίως πάντα ὁπόσα θέλει θεάσασθαι. ἐν Πάτραις δὲ πρὸς τῷ ἄλσει καὶ ἱερὰ δύο ἐστὶ Σαράπιδος· ἐν δὲ τῷ ἑτέρῳ πεποίηται μνῆμα Αἰγύπτου τοῦ Βήλου. φυγεῖν δὲ ἐς τὴν Ἀρόην οἱ Πατρεῖς φασιν αὐτὸν τοῖς τε ἐς τοὺς παῖδας παθήμασι καὶ τὸ ὄνομα αὐτὸ πεφρικότα τοῦ Ἄργους καὶ ἐς πλέον τοῦ Δαναοῦ δείματι.", "st": "7.21"}, {"sp": "N", "t": "ἔστι δὲ καὶ ἱερὸν Πατρεῦσιν Ἀσκληπιοῦ· τοῦτο τὸ ἱερὸν ὑπὲρ τὴν ἀκρόπολιν τῶν πυλῶν ἐστιν ἐγγὺς αἳ ἐπὶ Μεσάτιν ἄγουσιν. αἱ δὲ γυναῖκές εἰσιν ἐν ταῖς Πάτραις ἀριθμὸν μὲν καὶ ἐς δὶς τῶν ἀνδρῶν· Ἀφροδίτης δέ, εἴπερ ἄλλαις γυναιξί, μέτεστι καὶ ταύταις. βίος δὲ αὐτῶν ταῖς πολλαῖς ἐστιν ἀπὸ τῆς βύσσου τῆς ἐν τῇ Ἤλιδι φυομένης· κεκρυφάλους τε γὰρ ἀπ’ αὐτῆς καὶ ἐσθῆτα ὑφαίνουσι τὴν ἄλλην.", "st": "7.21"}, {"sp": "N", "t": "Φαραὶ δέ, Ἀχαιῶν πόλις, τελοῦσι μὲν ἐς Πάτρας δόντος Αὐγούστου, ὁδὸς δὲ ἐς Φαρὰς Πατρέων μὲν ἐκ τοῦ ἄστεως στάδιοι πεντήκοντά εἰσι καὶ ἑκατόν, ἀπὸ θαλάσσης δὲ ἄνω πρὸς ἤπειρον περὶ ἑβδομήκοντα. ποταμὸς δὲ ῥεῖ πλησίον Φαρῶν Πίερος, ὁ αὐτὸς ἐμοὶ δοκεῖν ὃς καὶ τὰ Ὠλένου παρέξεισιν ἐρείπια, ὑπὸ ἀνθρώπων τῶν πρὸς θαλάσσῃ καλούμενος Πεῖρος. πρὸς δὲ τῷ ποταμῷ πλατάνων ἐστὶν ἄλσος, κοῖλαί τε ὑπὸ παλαιότητος αἱ πολλαὶ καὶ ἥκουσαι μεγέθους ἐς τοσοῦτο ὥστε καὶ ἑστιῶνται τῶν χηραμῶν ἐντός, καὶ ὁπόσοις ἂν κατὰ γνώμην ᾖ, καὶ ἐγκαθεύδουσι.", "st": "7.22"}, {"sp": "N", "t": "περίβολος δὲ ἀγορᾶς μέγας κατὰ τρόπον τὸν ἀρχαιότερόν ἐστιν ἐν Φαραῖς, Ἑρμοῦ δὲ ἐν μέσῃ τῇ ἀγορᾷ λίθου πεποιημένον ἄγαλμα ἔχον καὶ γένεια· ἑστηκὼς δὲ πρὸς αὐτῇ τῇ γῇ παρέχεται μὲν τὸ τετράγωνον σχῆμα, μεγέθει δέ ἐστιν οὐ μέγας. καὶ αὐτῷ καὶ ἐπίγραμμα ἔπεστιν, ἀναθεῖναι αὐτὸ Μεσσήνιον Σιμύλον· καλεῖται μὲν δὴ Ἀγοραῖος, παρὰ δὲ αὐτῷ καὶ χρηστήριον καθέστηκε. κεῖται δὲ πρὸ τοῦ ἀγάλματος ἑστία, λίθου καὶ αὐτή, μολίβδῳ δὲ πρὸς τὴν ἑστίαν προσέχονται λύχνοι χαλκοῖ.", "st": "7.22"}, {"sp": "N", "t": "ἀφικόμενος οὖν περὶ ἑσπέραν ⟨ὁ⟩ τῷ θεῷ χρώμενος λιβανωτόν τε ἐπὶ τῆς ἑστίας θυμιᾷ καὶ ἐμπλήσας τοὺς λύχνους ἐλαίου καὶ ἐξάψας τίθησιν ἐπὶ τὸν βωμὸν τοῦ ἀγάλματος ἐν δεξιᾷ νόμισμα ἐπιχώριον— καλεῖται δὲ χαλκοῦς τὸ νόμισμα—καὶ ἐρωτᾷ πρὸς τὸ οὖς τὸν θεὸν ὁποῖόν τι καὶ ἑκάστῳ τὸ ἐρώτημά ἐστι. τὸ ἀπὸ τούτου δὲ ἄπεισιν ἐκ τῆς ἀγορᾶς ἐπιφραξάμενος τὰ ὦτα· προελθὼν δὲ ἐς τὸ ἐκτὸς τὰς χεῖρας ἀπέσχεν ἀπὸ τῶν ὤτων, καὶ ἧστινος ἂν ἐπακούσῃ φωνῆς, μάντευμα ἡγεῖται.", "st": "7.22"}, {"sp": "N", "t": "τοιαύτη καὶ Αἰγυπτίοις ἑτέρα περὶ τοῦ Ἄπιδος τὸ ἱερὸν μαντεία καθέστηκεν· ἐν Φαραῖς δὲ καὶ ὕδωρ ἱερόν ἐστι τοῦ Ἑρμοῦ· ⟨Ἑρμοῦ⟩ νᾶμα μὲν τῇ πηγῇ τὸ ὄνομα, τοὺς δὲ ἰχθῦς οὐχ αἱροῦσιν ἐξ αὐτῆς, ἀνάθημα εἶναι τοῦ θεοῦ νομίζοντες. ἑστήκασι δὲ ἐγγύτατα τοῦ ἀγάλματος τετράγωνοι λίθοι τριάκοντα μάλιστα ἀριθμόν· τούτους σέβουσιν οἱ Φαρεῖς, ἑκάστῳ θεοῦ τινὸς ὄνομα ἐπιλέγοντες. τὰ δὲ ἔτι παλαιότερα καὶ τοῖς πᾶσιν Ἕλλησι τιμὰς θεῶν ἀντὶ ἀγαλμάτων εἶχον ἀργοὶ λίθοι.", "st": "7.22"}, {"sp": "N", "t": "Φαρεῦσι δὲ ὅσον πέντε σταδίους καὶ δέκα ἀπωτέρω τῆς πόλεώς ἐστιν ἄλσος Διοσκούρων. δάφναι μάλιστα ἐν αὐτῷ πεφύκασι, ναὸς δὲ οὐκ ἦν ἐν αὐτῷ οὐδὲ ἀγάλματα· κομισθῆναι δὲ οἱ ἐπιχώριοί φασιν ἐς Ῥώμην τὰ ἀγάλματα. ἐν Φαραῖς δὲ ἐν τῷ ἄλσει βωμὸς λίθων λογάδων ἐστί. πυθέσθαι δὲ οὐκ εἶχον εἰ [ὁ] Φάρης ὁ Φυλοδαμείας τῆς Δαναοῦ σφισιν ἢ ὁμώνυμος ἐκείνῳ τις ἐγένετο οἰκιστής.", "st": "7.22"}, {"sp": "N", "t": "Τρίτεια δέ, Ἀχαιῶν ⟨καὶ⟩ αὕτη πόλις, ἐν μεσογαίῳ μὲν ᾤκισται, τελοῦσι δὲ ἐς Πάτρας καὶ αὐτοὶ βασιλέως δόντος· στάδιοι δὲ ἐς Τρίτειαν εἴκοσί τε καὶ ἑκατόν εἰσιν ἐκ Φαρῶν. πρὶν δὲ ἢ ἐς τὴν πόλιν ἐσελθεῖν, μνῆμά ἐστι λευκοῦ λίθου, θέας καὶ ἐς τὰ ἄλλα ἄξιον καὶ οὐχ ἥκιστα ἐπὶ ταῖς γραφαῖς αἵ εἰσιν ἐπὶ τοῦ τάφου, τέχνη Νικίου· θρόνος τε ἐλέφαντος καὶ γυνὴ νέα καὶ εἴδους εὖ ἔχουσα ἐπὶ τῷ θρόνῳ, θεράπαινα δὲ αὐτῇ προσέστηκε σκιάδιον φέρουσα·", "st": "7.22"}, {"sp": "N", "t": "καὶ νεανίσκος ὀρθὸς οὐκ ἔχων πω γένειά ἐστι χιτῶνα ἐνδεδυκὼς καὶ χλαμύδα ἐπὶ τῷ χιτῶνι φοινικῆν· παρὰ δὲ αὐτὸν οἰκέτης ἀκόντια ἔχων ἐστὶ καὶ ἄγει κύνας ἐπιτηδείας θηρεύουσιν ἀνθρώποις. πυθέσθαι μὲν δὴ τὰ ὀνόματα αὐτῶν οὐκ εἴχομεν· ταφῆναι δὲ ἄνδρα καὶ γυναῖκα ἐν κοινῷ παρίστατο ἅπασιν εἰκάζειν.", "st": "7.22"}, {"sp": "N", "t": "Τριτείας δὲ οἰκιστὴν οἱ μὲν Κελβίδαν γενέσθαι λέγουσιν, ἀφικόμενον [δὲ] ἐκ Κύμης τῆς ἐν Ὀπικοῖς· οἱ δὲ ὡς Ἄρης συγγένοιτο Τριτείᾳ θυγατρὶ Τρίτωνος, ἱερᾶσθαι δὲ τῆς Ἀθηνᾶς τὴν παρθένον, Μελάνιππον δὲ παῖδα Ἄρεως καὶ Τριτείας οἰκίσαι τε ὡς ηὐξήθη τὴν πόλιν καὶ θέσθαι τὸ ὄνομα ἀπὸ τῆς μητρός.", "st": "7.22"}, {"sp": "N", "t": "ἐν Τριτείᾳ δὲ ἔστι μὲν ἱερὸν καλουμένων Μεγίστων θεῶν, ἀγάλματα δέ σφισι πηλοῦ πεποιημένα· τούτοις κατὰ ἔτος ἑορτὴν ἄγουσιν, οὐδέν τι ἀλλοίως ἢ καὶ τῷ Διονύσῳ δρῶσιν Ἕλληνες. ἔστι δὲ καὶ Ἀθηνᾶς ναός, τὸ δὲ ἄγαλμα λίθου τὸ ἐφ’ ἡμῶν· τὸ δὲ ἀρχαῖον ἐς Ῥώμην, καθὰ οἱ Τριταιεῖς λέγουσιν, ἐκομίσθη. θύειν δὲ οἱ ἐνταῦθα καὶ Ἄρει καὶ τῇ Τριτείᾳ νομίζουσιν.", "st": "7.22"}, {"sp": "N", "t": "αἵδε μὲν οὖν θαλάσσης τέ εἰσιν ἀπωτέρω πόλεις καὶ ἠπειρώτιδες βεβαίως· πλέοντι δὲ ἐς Αἴγιον ἐκ Πατρῶν ἄκρα πρῶτόν ἐστιν ὀνομαζομένη Ῥίον, σταδίους [δὲ] Πατρῶν πεντήκοντα ἀπέχουσα, λιμὴν δὲ ὁ Πάνορμος σταδίοις πέντε καὶ δέκα ἀπωτέρω τῆς ἄκρας. τοσούτους δὲ ἀφέστηκεν ἑτέρους ἀπὸ Πανόρμου τὸ Ἀθηνᾶς καλούμενον τεῖχος. ἐς δὲ λιμένα Ἐρινεὸν ἐξ Ἀθηνᾶς τείχους παράπλους ἐνενήκοντά εἰσι στάδιοι, ἑξήκοντα δὲ ἐς Αἴγιον ἀπὸ τοῦ Ἐρινεοῦ· ὁδὸς δὲ ἡ πεζὴ σταδίους τεσσαράκοντα μάλιστα ἐς τὸν ἀριθμὸν ἀποδεῖ τὸν εἰρημένον.", "st": "7.22"}, {"sp": "N", "t": "οὐ πόρρω δὲ τοῦ Πατρέων ἄστεως ποταμός τε ὁ Μείλιχος καὶ τὸ ἱερὸν τῆς Τρικλαρίας [ἐν ὧ] ἐστίν, ἄγαλμα οὐδὲν ἔτι ἔχον. τοῦτο μὲν δή ἐστιν ἐν δεξιᾷ, προελθόντι δὲ ἀπὸ τοῦ Μειλίχου ποταμός ἐστιν ἄλλος· ὄνομα μὲν τῷ ποταμῷ Χάραδρος, ὥρᾳ δὲ ἦρος πίνοντα ἐξ αὐτοῦ τὰ βοσκήματα ὀφείλει τίκτειν ἄρρενα ὡς τὰ πλείω συμβαίνει, καὶ τοῦδε ἕνεκα οἱ νομεῖς ἑτέρωσε αὐτὰ τῆς χώρας μεθιστᾶσι πλήν γε δὴ τὰς βοῦς· ταύτας δὲ αὐτοῦ καταλείπουσιν ἐπὶ τῷ ποταμῷ, διότι καὶ πρὸς θυσίας οἱ ταῦροί σφισι καὶ ἐς τὰ ἔργα ἐπιτηδειότεροι θηλειῶν βοῶν εἰσιν, ἐπὶ δὲ τοῖς ἄλλοις κτήνεσι τὸ θῆλυ ἐπὶ πλέον τετίμηται.", "st": "7.22"}, {"sp": "N", "t": "μετὰ δὲ τὸν Χάραδρον ἐρείπια οὐκ ἐπιφανῆ πόλεώς ἐστιν Ἀργυρᾶς, καὶ πηγή τε Ἀργυρᾶ ἐν δεξιᾷ τῆς λεωφόρου καὶ Σέλεμνος ποταμὸς κατιὼν ἐς θάλασσαν. λόγος δὲ τῶν ἐπιχωρίων ἐς αὐτόν ἐστι, Σέλεμνον μειράκιον ὡραῖον ποιμαίνειν ἐνταῦθα, Ἀργυρᾶν δὲ εἶναι μὲν τῶν ἐν θαλάσσῃ νυμφῶν, ἐρασθεῖσαν δὲ αὐτὴν Σελέμνου φοιτᾶν τε ὡς αὐτόν φασιν ἐκ θαλάσσης ἀνιοῦσαν, καὶ καθεύδειν παρ’ αὐτῷ·", "st": "7.23"}, {"sp": "N", "t": "μετὰ δὲ οὐ πολὺν χρόνον οὔτε ὡραῖος ἔτι ἐφαίνετο Σέλεμνος οὔτε ὡς αὐτὸν φοιτήσειν ἔμελλεν ἡ νύμφη, Σέλεμνον δὲ μονωθέντα Ἀργυρᾶς καὶ τελευτήσαντα ὑπὸ τοῦ ἔρωτος ἐποίησεν Ἀφροδίτη ποταμόν. λέγω δὲ τὰ ὑπὸ Πατρέων λεγόμενα. καὶ—ἤρα γὰρ καὶ ὕδωρ γενόμενος Ἀργυρᾶς, καθότι ἔχει καὶ ἐπὶ τῷ Ἀλφειῷ λόγος Ἀρεθούσης ἔτι ἐρᾶν αὐτόν—δωρεῖται καὶ τῷδε Ἀφροδίτη Σέλεμνον·", "st": "7.23"}, {"sp": "N", "t": "ἐς λήθην ἄγει τὸν ποταμὸν Ἀργυρᾶς. ἤκουσα δὲ καὶ ἄλλον ἐπ’ αὐτῷ λόγον, τὸ ὕδωρ τοῦ Σελέμνου σύμφορον καὶ ἀνδράσιν εἶναι καὶ γυναιξὶν ἐς ἔρωτος ἴαμα, λουομένοις ἐν τῷ ποταμῷ λήθην ἔρωτος γίνεσθαι. εἰ δὲ μέτεστιν ἀληθείας τῷ λόγῳ, τιμιώτερον χρημάτων πολλῶν ἐστιν ἀνθρώποις τὸ ὕδωρ τοῦ Σελέμνου.", "st": "7.23"}, {"sp": "N", "t": "ἀπωτέρω δὲ Ἀργυρᾶς ποταμός ἐστιν ὀνομαζόμενος Βολιναῖος, καὶ πόλις ποτὲ ᾠκεῖτο πρὸς αὐτῷ Βολίνα. παρθένου δὲ ἐρασθῆναι Βολίνης Ἀπόλλωνα, τὴν δὲ φεύγουσαν ἐς τὴν ταύτῃ φασὶν ἀφεῖναι θάλασσαν αὑτήν, καὶ ἀθάνατον γενέσθαι χάριτι τοῦ Ἀπόλλωνος. ἐφεξῆς δὲ ἄκρα τε ἐς τὴν θάλασσαν ἔχει, καὶ ἐπ’ αὐτῇ λέγεται λόγος ὡς Κρόνος τῆς θαλάσσης ἐνταῦθα ἔρριψε τὸ δρέπανον, ᾧ τὸν πατέρα Οὐρανὸν ἐλυμήνατο· ἐπὶ τούτῳ δὲ καὶ τὴν ἄκραν Δρέπανον ὀνομάζουσιν. ὀλίγον δὲ ὑπὲρ τὴν λεωφόρον Ῥυπῶν ἐστι τὰ ἐρείπια· σταδίους δὲ Αἴγιον περὶ τοὺς τριάκοντα ἀπέχει Ῥυπῶν.", "st": "7.23"}, {"sp": "N", "t": "Αἰγίου δὲ τὴν χώραν διέξεισι μὲν ποταμὸς Φοῖνιξ, διέξεισι δὲ καὶ ἕτερος Μειγανίτας, ἐς θάλασσαν ῥέοντες. στοὰ δὲ τῆς πόλεως πλησίον ἐποιήθη Στράτωνι ἀθλητῇ, Ὀλυμπίασιν ἐπὶ ἡμέρας τῆς αὐτῆς παγκρατίου καὶ πάλης ἀνελομένῳ νίκας. αὕτη μὲν ἐγγυμνάζεσθαι τούτῳ τῷ ἀνδρὶ ἐποιήθη· Αἰγιεῦσι δὲ Εἰλειθυίας ἱερόν ἐστιν ἀρχαῖον, καὶ ἡ Εἰλείθυια ἐς ἄκρους ἐκ κεφαλῆς τοὺς πόδας ὑφάσματι κεκάλυπται λεπτῷ, ξόανον πλὴν προσώπου τε καὶ χειρῶν ἄκρων καὶ ποδῶν, ταῦτα δὲ τοῦ", "st": "7.23"}, {"sp": "N", "t": "Πεντελησίου λίθου πεποίηται· καὶ ταῖς χερσὶ τῇ μὲν ἐς εὐθὺ ἐκτέταται, τῇ δὲ ἀνέχει δᾷδα. Εἰλειθυίᾳ δὲ εἰκάσαι τις ἂν εἶναι δᾷδας, ὅτι γυναιξὶν ἐν ἴσῳ καὶ πῦρ εἰσιν αἱ ὠδῖνες· ἔχοιεν δ’ ἂν λόγον καὶ ἐπὶ τοιῷδε αἱ δᾷδες, ὅτι Εἰλείθυιά ἐστιν ἡ ἐς φῶς ἄγουσα τοὺς παῖδας. ἔργον δὲ τοῦ Μεσσηνίου Δαμοφῶντός ἐστι τὸ ἄγαλμα.", "st": "7.23"}, {"sp": "N", "t": "τῆς δὲ Εἰλειθυίας οὐ μακρὰν Ἀσκληπιοῦ τέ ἐστι τέμενος καὶ ἀγάλματα Ὑγείας καὶ Ἀσκληπιοῦ· ἰαμβεῖον δὲ ἐπὶ τῷ βάθρῳ τὸν Μεσσήνιον Δαμοφῶντα εἶναι τὸν εἰργασμένον φησίν. ἐν τούτῳ τοῦ Ἀσκληπιοῦ τῷ ἱερῷ ἐς ἀντιλογίαν ἀφίκετο ἀνήρ μοι Σιδόνιος, ὃς ἐγνωκέναι τὰ ἐς τὸ θεῖον ἔφασκε Φοίνικας [καὶ] τά τε ἄλλα Ἑλλήνων βέλτιον καὶ δὴ καὶ Ἀσκληπιῷ πατέρα μὲν σφᾶς Ἀπόλλωνα ἐπιφημίζειν, θνητὴν δὲ γυναῖκα οὐδεμίαν μητέρα·", "st": "7.23"}, {"sp": "N", "t": "Ἀσκληπιὸν μὲν γὰρ ἀέρα γένει τε ἀνθρώπων εἶναι καὶ πᾶσιν ὁμοίως ζῴοις ἐπιτήδειον πρὸς ὑγίειαν, Ἀπόλλωνα δὲ ἥλιον, καὶ αὐτὸν ὀρθότατα Ἀσκληπιῷ πατέρα ἐπονομάζεσθαι, ὅτι ἐς τὸ ἁρμόζον ταῖς ὥραις ποιούμενος ὁ ἥλιος τὸν δρόμον μεταδίδωσι καὶ τῷ ἀέρι ὑγιείας. ἐγὼ δὲ ἀποδέχεσθαι μὲν τὰ εἰρημένα, οὐδὲν δέ τι Φοινίκων μᾶλλον ἢ καὶ Ἑλλήνων ἔφην τὸν λόγον, ἐπεὶ καὶ ἐν Τιτάνῃ τῆς Σικυωνίων τὸ αὐτὸ ἄγαλμα Ὑγείαν τε ὀνομάζεσθαι καὶ †παιδὶ ἦν δῆλα ὡς τὸν ἡλιακὸν δρόμον ἐπὶ γῆς ὑγίειαν ποιοῦντα ἀνθρώποις.", "st": "7.23"}, {"sp": "N", "t": "Αἰγιεῦσι δὲ Ἀθηνᾶς τε ναὸς καὶ Ἥρας ἐστὶν ἄλσος. Ἀθηνᾶς μὲν δὴ δύο ἀγάλματα λευκοῦ λίθου· τῆς δὲ Ἥρας τὸ ἄγαλμα ὅτι μὴ γυναιξίν, ἣ ἂν τὴν ἱερωσύνην ἔχῃ, ἄλλῳ γε δὴ οὐδενὶ ἔστι θεάσασθαι. Διονύσου δὲ πρὸς τῷ θεάτρῳ πεποίηταί σφισιν ἱερὸν καὶ ἄγαλμα, οὐκ ἔχων πω γένεια. ἔστι δὲ καὶ Διὸς ἐπίκλησιν Σωτῆρος ἐν τῇ ἀγορᾷ τέμενος καὶ ἀγάλματα ἐσελθόντων ἐν ἀριστερᾷ, χαλκοῦ μὲν ἀμφότερα, τὸ δὲ οὐκ ἔχον πω γένεια ἐφαίνετο ἀρχαιότερον εἶναί μοι.", "st": "7.23"}, {"sp": "N", "t": "ἐν δὲ οἰκήματι κατευθὺ τῆς ὁδοῦ, χαλκοῦ καὶ ταῦτα, ἔστι μὲν Ποσειδῶν καὶ Ἡρακλῆς, ἐστι δὲ Ζεύς τε καὶ Ἀθηνᾶ· θεοὺς δὲ σφᾶς καλοῦσιν ἐξ Ἄργους, ὡς μὲν ὁ Ἀργείων ἔχει λόγος, ὅτι ἐποιήθησαν ἐν τῇ πόλει τῇ Ἀργείων, ὡς δὲ αὐτοὶ λέγουσιν οἱ Αἰγιεῖς, παρακαταθήκη σφίσιν ὑπὸ Ἀργείων ἐδόθη ⟨τὰ⟩ ἀγάλματα.", "st": "7.23"}, {"sp": "N", "t": "καὶ αὐτοῖς καὶ τάδε ἔτι προσταχθῆναί φασιν, ἑκάστῃ τοῖς ἀγάλμασιν ἡμέρᾳ θύειν· αὐτοὶ δὲ σόφισμα εὑρόντες θύειν μὲν πλεῖστα ὅσα, κατευωχουμένοις δὲ τὰ ἱερεῖα ἐν κοινῷ ἀνάλωμα οὐδὲν ἐς αὐτὰ γίνεσθαι· τέλος δὲ ἀπαιτεῖσθαι ὑπὸ τῶν Ἀργείων καὶ αὐτοὺς τὰ ἐς τὰς θυσίας ἀναλούμενα ἀπαιτεῖν· τοὺς δὲ—οὐ γὰρ ἔχειν ἐκτῖσαι—καταλιπεῖν σφισιν αὐτοὺς τὰ ἀγάλματα.", "st": "7.23"}, {"sp": "N", "t": "Αἰγιεῦσι δὲ ἔστι μὲν πρὸς τῇ ἀγορᾷ ναὸς Ἀπόλλωνι καὶ Ἀρτέμιδι ἐν κοινῷ, ἔστι δὲ ἐν τῇ ἀγορᾷ ἱερὸν Ἀρτέμιδος, τοξευούσῃ δὲ εἴκασται, καὶ Ταλθυβίου τοῦ κήρυκος τάφος· κέχωσται δὲ τῷ Ταλθυβίῳ καὶ ἄλλο μνῆμα ἐν Σπάρτῃ, καὶ αὐτῷ αἱ πόλεις ἐναγίζουσιν ἀμφότεραι.", "st": "7.24"}, {"sp": "N", "t": "πρὸς θαλάσσῃ δὲ Ἀφροδίτης ἱερὸν ἐν Αἰγίῳ καὶ μετ’ αὐτὸ Ποσειδῶνος, Κόρης τε πεποίηται τῆς Δήμητρος καὶ τέταρτον Ὁμαγυρίῳ Διί. ἐνταῦθα Διὸς καὶ Ἀφροδίτης ἐστὶ καὶ Ἀθηνᾶς ἀγάλματα· Ὁμαγύριος δὲ ἐγένετο τῷ Διὶ ἐπίκλησις, ὅτι Ἀγαμέμνων ἤθροισεν ἐς τοῦτο τὸ χωρίον τοὺς λόγου μάλιστα ἐν τῇ Ἑλλάδι ἀξίους, μεθέξοντας ἐν κοινῷ βουλῆς καθ’ ὅντινα χρὴ τρόπον ἐπὶ ἀρχὴν τὴν Πριάμου στρατεύεσθαι. Ἀγαμέμνονι δὲ καὶ ἄλλα ἐστὶν ἐς ἔπαινον καὶ ὅτι τοῖς ἐξ ἀρχῆς ἀκολουθήσασι καὶ οὐδεμιᾶς ἐπελθούσης ὕστερον στρατιᾶς τήν τε Ἴλιον ἐπόρθησε καὶ ὅσαι περίοικοι πόλεις ἦσαν.", "st": "7.24"}, {"sp": "N", "t": "ἐφεξῆς δὲ τῷ Ὁμαγυρίῳ Διὶ Παναχαιᾶς ἐστι Δήμητρος. παρέχεται δὲ ὁ αἰγιαλός, ἐν ᾧ καὶ τὰ ἱερὰ Αἰγιεῦσίν ἐστι τὰ εἰρημένα, ὕδωρ ἄφθονον θεάσασθαί τε καὶ πιεῖν ἐκ πηγῆς ἡδύ. ἔστι δέ σφισι καὶ Σωτηρίας ἱερόν. ἰδεῖν μὲν δὴ τὸ ἄγαλμα οὐδενὶ πλὴν τῶν ἱερωμένων ἔστι, δρῶσι δὲ ἄλλα τοιαῦτα· λαμβάνοντες παρὰ τῆς θεοῦ πέμματα ἐπιχώρια ἀφιᾶσιν ἐς θάλασσαν, πέμπειν δὲ τῇ ἐν Συρακούσαις Ἀρεθούσῃ φασὶν αὐτά.", "st": "7.24"}, {"sp": "N", "t": "ἔστι δὲ καὶ ἄλλα Αἰγιεῦσιν ἀγάλματα χαλκοῦ πεποιημένα, Ζεύς τε ἡλικίαν παῖς καὶ Ἡρακλῆς, οὐδὲ οὗτος ἔχων πω γένεια, Ἀγελάδα τέχνη τοῦ Ἀργείου. τούτοις κατὰ ἔτος ἱερεῖς αἱρετοὶ γίνονται, καὶ ἑκάτερα τῶν ἀγαλμάτων ἐπὶ ταῖς οἰκίαις μένει τοῦ ἱερωμένου. τὰ δὲ ἔτι παλαιότερα προεκέκριτο ἐκ τῶν παίδων ἱερᾶσθαι τῷ Διὶ ὁ νικῶν κάλλει· ἀρχομένων δὲ αὐτῷ γενείων ἐς ἄλλον παῖδα ἡ ἐπὶ τῷ κάλλει μετῄει τιμή. ταῦτα μὲν οὕτως ἐνομίζετο· ἐς δὲ Αἴγιον καὶ ἐφ’ ἡμῶν ἔτι συνέδριον τὸ Ἀχαιῶν ἀθροίζεται, καθότι ἐς Θερμοπύλας τε καὶ ἐς Δελφοὺς οἱ Ἀμφικτύονες.", "st": "7.24"}, {"sp": "N", "t": "ἰόντι δὲ ἐς τὸ πρόσω Σελινοῦς τε ποταμὸς καὶ ἀπωτέρω τεσσαράκοντα Αἰγίου σταδίοις ἐπὶ θαλάσσῃ χωρίον ἐστὶν Ἑλίκη. ἐνταῦθα ᾤκητο Ἑλίκη πόλις καὶ Ἴωσιν ἱερὸν ἁγιώτατον Ποσειδῶνος ἦν Ἑλικωνίου. διαμεμένηκε δέ σφισι, καὶ ὡς ὑπὸ Ἀχαιῶν ἐκπεσόντες ἐς Ἀθήνας καὶ ὕστερον ἐξ Ἀθηνῶν ἐς τὰ παραθαλάσσια ἀφίκοντο τῆς Ἀσίας, σέβεσθαι Ποσειδῶνα Ἑλικώνιον· καὶ Μιλησίοις τε ἰόντι ἐπὶ τὴν πηγὴν τὴν Βιβλίδα Ποσειδῶνος πρὸ τῆς πόλεώς ἐστιν Ἑλικωνίου βωμὸς καὶ ὡσαύτως ἐν Τέῳ περίβολός τε καὶ βωμός ἐστι τῷ Ἑλικωνίῳ θέας ἄξιος.", "st": "7.24"}, {"sp": "N", "t": "ἔστι δὲ καὶ Ὁμήρῳ πεποιημένα ἐς Ἑλίκην καὶ τὸν Ἑλικώνιον Ποσειδῶνα. χρόνῳ δὲ ὕστερον Ἀχαιοῖς τοῖς ἐνταῦθα, ἱκέτας ἄνδρας ἀποστήσασιν ἐκ τοῦ ἱεροῦ καὶ ἀποκτείνασιν, οὐκ ἐμέλλησε τὸ μήνιμα ἐκ τοῦ Ποσειδῶνος, ἀλλὰ σεισμὸς ἐς τὴν χώραν σφίσιν αὐτίκα κατασκήψας τῶν τε οἰκοδομημάτων τὴν κατασκευὴν καὶ ὁμοῦ τῇ κατασκευῇ καὶ αὐτὸ τῆς πόλεως τὸ ἔδαφος ἀφανὲς ἐς τοὺς ἔπειτα ἐποίησε.", "st": "7.24"}, {"sp": "N", "t": "τὰ μὲν οὖν ἄλλα ἐπὶ τοῖς σεισμοῖς, ὅσοι μεγέθει τε ὑπερήρκασι καὶ ἐπὶ μήκιστον διικνοῦνται τῆς γῆς, προσημαίνειν ὁ θεὸς κατὰ τὰ αὐτὰ ὡς τὸ ἐπίπαν εἴωθεν—ἢ γὰρ ἐπομβρίαι συνεχεῖς ἢ αὐχμοὶ πρὸ τῶν σεισμῶν συμβαίνουσιν ἐπὶ χρόνον πλείονα, καὶ ὁ ἀὴρ παρὰ τὴν ἑκάστοτε τοῦ ἔτους ὥραν χειμῶνός τε γίνεται καυματωδέστερος καὶ ἐν θέρει μετὰ ἀχλύος μᾶλλον ὁ κύκλος παρέχεται τοῦ ἡλίου τὴν χρόαν παρὰ τὸ εἰωθὸς ἤτοι ἐς τὸ ἐρυθρότερον ἢ καὶ ἡσυχῇ ῥέπουσαν ἐς τὸ μελάντερον·", "st": "7.24"}, {"sp": "N", "t": "τῶν τε ὑδάτων ὡς τὸ πολὺ ἐπιλείπουσιν αἱ πηγαί, καὶ ἀνέμων ἔστιν οἷς ἐνέπεσον ἐς τὴν χώραν ἐμβολαὶ περιτρέπουσαι τὰ δένδρα, καί που καὶ ἐν τῷ οὐρανῷ διαδρομαὶ σὺν πολλῇ τῇ φλογί, τὰ δὲ καὶ ἀστέρων ὤφθη σχήματα οὔτε ἐγνωσμένα ὑπὸ τῶν πρότερον καὶ μεγάλην τοῖς ὁρῶσιν ἐμποιοῦντα ἔκπληξιν, ἔτι δὲ καὶ τῆς γῆς κάτω πνευμάτων ὑπήχησις ἰσχυρά, ἄλλα τε πολλὰ ὁ θεὸς ἐπὶ τοῖς βιαίοις τῶν σεισμῶν ἐθέλει προενδείκνυσθαι·", "st": "7.24"}, {"sp": "N", "t": "—τῆς δὲ κινήσεως αὐτῆς καθέστηκεν οὐχ εἷς τρόπος, ἀλλ’ οἱ φροντίσαντες τὰ τοιαῦτα ἐξ ἀρχῆς καὶ οἱ παρ’ ἐκείνων διδαχθέντες ἰδέας καταμαθεῖν ἐδυνήθησαν τοσάσδε ἐπὶ τοῖς σεισμοῖς. ἠπιώτατος μέν ἐστιν αὐτῶν, ἢν δὴ ἐν κακῷ γε τοσούτῳ ῥᾳστώνην ἐνεῖναί τινα ἡγησώμεθα, ἐπειδὰν ὁμοῦ τῇ κινήσει τῇ ἀρξαμένῃ τὸ πρῶτον καὶ τῇ ἐς τὸ ἔδαφος τροπῇ τῶν οἰκοδομημάτων ἀντιστᾶσα ἐναντία κίνησις ἐξεγείρῃ τὰ ἤδη τραπέντα, —καὶ ἐν τῇ τοιᾷδε ἰδέᾳ", "st": "7.24"}, {"sp": "N", "t": "τοῦ σεισμοῦ κίονας ὁρᾶν ἔστιν ἀνορθουμένους οἳ ὀλίγου ἐδέησαν ἐς ἅπαν ἐκριφῆναι, καὶ ὁπόσα διέστη τοίχων συνερχόμενα ἐς τὸ ἐξ ἀρχῆς· δοκοὶ δέ, ὅσας ἐκτὸς ὀλισθεῖν ἐποίησεν ἡ κίνησις, ἐπανίασιν αὖθις ἐς τὰς ἕδρας· ὡσαύτως δὲ καὶ ὀχετῶν κατασκευῆς καὶ εἰ δή τι ἄλλο ἐπὶ ὕδατος ῥοαῖς προάγει, καὶ τούτων συνδεῖ τὰ διεσπασμένα μᾶλλον ἢ ἀνθρώπων τεκτόνων· —ὁ δὲ δὴ δεύτερος τῶν σεισμῶν ἀπώλειάν τε τῶν ἑτοιμοτέρων φέρει καί, ἐφ’ ὅ τι ἂν βάλῃ τὴν ὁρμήν, ἀνέκλινεν αὐτίκα τοῖς ἐς πολιορκίαν μηχανήμασιν ὁμοίως.", "st": "7.24"}, {"sp": "N", "t": "τὸν δὲ αὐτῶν ὀλεθριώτατον τοιῷδέ τινι ἐθέλουσιν εἰκάζειν, τὸ ἐντὸς τοῦ ἀνθρώπου πνεῦμα εἰ συνεχεῖ πυρετῷ πυκνότερόν τε καὶ ὑπὸ πολλῆς ἄνω τῆς βίας ⟨ὠθοῖτο⟩· τοῦτο δὲ ἀλλαχοῦ τε τοῦ σώματος ἐπισημαίνει καὶ ἐν ταῖς χερσὶν ὑπὸ ἑκάτερον μάλιστα τὸν καρπόν. κατὰ ταὐτὰ οὖν καὶ τὸν σεισμὸν [εἴτ’] εὐθὺ ὑποδύεσθαι τῶν οἰκοδομημάτων καὶ θεμέλια ἀναπάλλειν φασὶν αὐτόν, καθότι καὶ τὰ ἔργα τῶν σφαλάκων ἐκ μυχοῦ τῆς γῆς ἀναπέμπεται· μόνη τε ἡ τοιαύτη κίνησις οὐδὲ τοῦ οἰκισθῆναί ποτε ὑπολείπει σημεῖα ἐν τῇ γῇ.", "st": "7.24"}, {"sp": "N", "t": "τότε δὲ ἰδέαν μὲν ταύτην ἐπὶ τῇ Ἑλίκῃ τοῦ σεισμοῦ τὴν ἐς τὸ ἔδαφος ἀνακινοῦσαν, σὺν δὲ αὐτῇ καὶ ἄλλο πῆμα τοιόνδε οἱ ἐπιγενέσθαι φασὶν ὥρᾳ χειμῶνος. ἐπῆλθε γάρ σφισιν ἐπὶ πολὺ τῆς χώρας ἡ θάλασσα καὶ τὴν Ἑλίκην περιέλαβεν ἐν κύκλῳ πᾶσαν· καὶ δὴ καὶ τὸ ἄλσος τοῦ Ποσειδῶνος ἐπὶ τοσοῦτον ἐπέσχεν ὁ κλύδων ὡς τὰ ἄκρα τῶν δένδρων σύνοπτα εἶναι μόνον. σείσαντος δὲ ἐξαίφνης τοῦ θεοῦ καὶ ὁμοῦ τῷ σεισμῷ τῆς θαλάσσης ἀναδραμούσης, καθείλκυσεν αὔτανδρον τὸ κῦμα τὴν Ἑλίκην.", "st": "7.24"}, {"sp": "N", "t": "τοιοῦτό γε δὴ κατέλαβεν, [καὶ] ἕτερον τὴν ἰδέαν, ἐν Σιπύλῳ πόλιν ἐς χάσμα ἀφανισθῆναι· ἐξ ὅτου δὲ [ἡ ἰδέα] κατεάγη τοῦ ὄρους, ὕδωρ αὐτόθεν ἐρρύη, καὶ λίμνη τε ὀνομαζομένη Σαλόη τὸ χάσμα ἐγένετο καὶ ἐρείπια πόλεως δῆλα ἦν ἐν τῇ λίμνῃ, πρὶν ἢ τὸ ὕδωρ ἀπέκρυψεν αὐτὰ τοῦ χειμάρρου. σύνοπτα δὲ καὶ Ἑλίκης ἐστὶ τὰ ἐρείπια, οὐ μὴν ἔτι γε ὁμοίως, ἅτε ὑπὸ τῆς ἅλμης λελυμασμένα.", "st": "7.24"}, {"sp": "N", "t": "τὸ δὲ τοῦ Ἱκεσίου μήνιμα πάρεστι μὲν τοῖς ἐς τὴν Ἑλίκην, πάρεστι δὲ καὶ ἄλλοις διδαχθῆναι πολλοῖς ὡς ἔστιν ἀπαραίτητον· φαίνεται δὲ καὶ ὁ θεὸς παραινῶν ὁ ἐν Δωδώνῃ νέμειν ἐς ἱκέτας αἰδῶ. Ἀθηναίοις γὰρ ἐπὶ ἡλικίας μάλιστα τῆς Ἀφείδαντος ἀφίκετο παρὰ τοῦ ἐν Δωδώνῃ Διὸς τὰ ἔπη τάδε·<br>φράζεο δ’ Ἄρειόν τε πάγον βωμούς τε θυώδεις<br>Εὐμενίδων, ὅθι χρὴ Λακεδαιμονίους ⟨σ’⟩ ἱκετεῦσαι<br>δουρὶ πιεζομένους. τοὺς μὴ σὺ κτεῖνε σιδήρῳ,<br>μηδ’ ἱκέτας ἀδικεῖν· ἱκέται δ’ ἱεροί τε καὶ ἁγνοί.", "st": "7.25"}, {"sp": "N", "t": "ταῦτα Ἕλλησιν ἦλθεν ἐς μνήμην, ὅτε ἀφίκοντο ἐπὶ Ἀθήνας Πελοποννήσιοι, τότε Κόδρου τοῖς Ἀθηναίοις τοῦ Μελάνθου βασιλεύοντος. ὁ μὲν δὴ ἄλλος στρατὸς τῶν Πελοποννησίων ἀπεχώρησεν ἐκ τῆς Ἀττικῆς, ἐπειδὴ ἐπύθοντο τοῦ Κόδρου τὴν τελευτὴν καὶ ὅντινα ἐγένετο αὐτῷ τρόπον· οὐ γὰρ εἶναι νίκην ἔτι σφίσι κατὰ τὸ ἐκ Δελφῶν μάντευμα ἤλπιζον· Λακεδαιμονίων δὲ ἄνδρες γενόμενοι μὲν ἐντὸς τείχους λανθάνουσιν ἐν τῇ νυκτί, ἅμα δὲ ἡμέρᾳ τούς τε ἑαυτῶν ἀπεληλυθότας αἰσθάνονται καὶ ἀθροιζομένων ἐπ’ αὐτοὺς τῶν Ἀθηναίων καταφεύγουσιν ἐς τὸν Ἄρειον πάγον καὶ ἐπὶ τῶν θεῶν αἳ Σεμναὶ καλοῦνται τοὺς βωμούς.", "st": "7.25"}, {"sp": "N", "t": "Ἀθηναῖοι δὲ τότε μὲν διδόασι τοῖς ἱκέταις ἀπελθεῖν ἀζημίοις, χρόνῳ δὲ ὕστερον αὐτοὶ οἱ ἔχοντες τὰς ἀρχὰς διέφθειραν τῆς Ἀθηνᾶς ἱκέτας τῶν Κύλωνι ὁμοῦ τὴν ἀκρόπολιν κατειληφότων· καὶ αὐτοί τε ⟨οἱ⟩ ἀποκτείναντες ἐνομίσθησαν καὶ οἱ ἐξ ἐκείνων ἐναγεῖς τῆς θεοῦ. Λακεδαιμονίοις δέ, ἀποκτείνασι καὶ τούτοις ἄνδρας ἐς τὸ ἱερὸν καταπεφευγότας τὸ ἐπὶ Ταινάρῳ τοῦ Ποσειδῶνος, οὐ μετὰ πολὺ ἐσείσθη σφίσιν ἡ πόλις συνεχεῖ τε ὁμοῦ καὶ ἰσχυρῷ τῷ σεισμῷ, ὥστε οἰκίαν μηδεμίαν τῶν ἐν Λακεδαίμονι ἀντισχεῖν.", "st": "7.25"}, {"sp": "N", "t": "ἐγένετο δὲ τῆς Ἑλίκης ἀπώλεια Ἀστείου μὲν Ἀθήνῃσιν ἔτι ἄρχοντος, τετάρτῳ δὲ ἔτει τῆς πρώτης Ὀλυμπιάδος ἐπὶ ταῖς ἑκατόν, ἣν Δάμων Θούριος ἐνίκα τὸ πρῶτον. Ἑλικαέων δὲ οὐκέτι ὄντων νέμονται τὴν χώραν οἱ Αἰγιεῖς.", "st": "7.25"}, {"sp": "N", "t": "μετὰ δὲ Ἑλίκην ἀποτραπήσῃ τε ἀπὸ θαλάσσης ἐς δεξιὰν καὶ ἥξεις ἐς πόλισμα Κερύνειαν· ᾤκισται δὲ ὑπὲρ τὴν λεωφόρον ἐν ὄρει, καί οἱ τὸ ὄνομα ἢ δυνάστης ἐπιχώριος ἢ ὁ Κερυνίτης ποταμὸς πεποίηκεν, ὃς ἐξ Ἀρκαδίας καὶ ὄρους Κερυνείας ῥέων Ἀχαιοὺς τοὺς ταύτῃ παρέξεισι. παρὰ τούτους σύνοικοι Μυκηναῖοι κατὰ συμφορὰν ἀφίκοντο ἐκ τῆς Ἀργολίδος. Μυκηναίοις [μὲν] γὰρ τὸ μὲν τεῖχος ἁλῶναι κατὰ τὸ ἰσχυρὸν οὐκ ἐδύνατο ὑπὸ Ἀργείων, ἐτετείχιστο γὰρ κατὰ ταὐτὰ", "st": "7.25"}, {"sp": "N", "t": "τῷ ἐν Τίρυνθι ὑπὸ τῶν Κυκλώπων καλουμένων, κατὰ ἀνάγκην δὲ ἐκλείπουσι Μυκηναῖοι τὴν πόλιν ἐπιλειπόντων σφᾶς τῶν σιτίων, καὶ ἄλλοι μέν τινες ἐς Κλεωνὰς ἀποχωροῦσιν ἐξ αὐτῶν, τοῦ δήμου δὲ πλέον μὲν ἥμισυ ἐς Μακεδονίαν καταφεύγουσι παρὰ Ἀλέξανδρον, ᾧ Μαρδόνιος ὁ Γωβρύου τὴν ἀγγελίαν ἐπίστευσεν ἐς Ἀθηναίους ἀπαγγεῖλαι· ὁ δὲ ἄλλος δῆμος ἀφίκοντο ἐς τὴν Κερύνειαν, καὶ δυνατωτέρα τε ἡ Κερύνεια οἰκητόρων πλήθει καὶ ἐς τὸ ἔπειτα ἐγένετο ἐπιφανεστέρα διὰ τὴν συνοίκησιν τῶν Μυκηναίων.", "st": "7.25"}, {"sp": "N", "t": "ἐν Κερυνείᾳ δὲ ἱερόν ἐστιν Εὐμενίδων· ἱδρύσασθαι δὲ αὐτὸ Ὀρέστην λέγουσιν. ὃς δ’ ἂν ἐνταῦθα ἢ αἵματι ἢ ἄλλῳ τῳ μιάσματι ἔνοχος ἢ καὶ ἀσεβὴς ἐσέλθῃ θέλων θεάσασθαι, αὐτίκα λέγεται δείμασιν ἐκτὸς τῶν φρενῶν γίνεσθαι· καὶ τοῦδε ἕνεκα οὐ τοῖς πᾶσιν ἡ ἔσοδος οὐδὲ ἐξ ἐπιδρομῆς ἐστι. τοῖς μὲν δὴ ἀγάλμασι ξύλων εἰργασμένοις … μέγεθός εἰσιν οὐ μεγάλοι, κατὰ δὲ τὴν ἔσοδον ἐς τὸ ἱερὸν γυναικῶν εἰκόνες λίθου τέ εἰσιν εἰργασμέναι καὶ ἔχουσαι τέχνης εὖ· ἐλέγοντο δὲ ὑπὸ τῶν ἐπιχωρίων ἱέρειαι ταῖς Εὐμενίσιν αἱ γυναῖκες γενέσθαι.", "st": "7.25"}, {"sp": "N", "t": "ἐκ Κερυνείας δὲ ἐπανελθόντι ἐς τὴν λεωφόρον καὶ ὁδεύσαντι οὐκ ἐπὶ πολὺ δεύτερα ἔστιν ἐς Βοῦραν ἀποτραπέσθαι· θαλάσσης δὲ ἐν δεξιᾷ [καὶ] ἡ Βοῦρα ἐν ὄρει κεῖται. τεθῆναι δέ φασι τῇ πόλει τὸ ὄνομα ἀπὸ γυναικὸς Βούρας, θυγατέρα δ’ αὐτὴν Ἴωνος τοῦ Ξούθου καὶ Ἑλίκης εἶναι. ὅτε δὲ Ἑλίκην ἐποίησεν ἄδηλον ἐξ ἀνθρώπων ὁ θεός, τότε καὶ τὴν Βοῦραν σεισμὸς ἐπέλαβεν ἰσχυρός, ὡς μηδὲ τὰ ἀγάλματα ἐν τοῖς ἱεροῖς ὑπολειφθῆναι τὰ ἀρχαῖα.", "st": "7.25"}, {"sp": "N", "t": "ὁπόσοι δὲ τηνικαῦτα ἀποδημοῦντες ἢ στρατείας ἕνεκα ἔτυχον ἢ κατὰ πρόφασιν ἀλλοίαν, μόνοι τε οὗτοι Βουρέων ἐλείφθησαν καὶ αὐτοὶ τῆς Βούρας ἐγένοντο οἰκισταί. ναὸς ἐνταῦθα Δήμητρος, ὁ δὲ Ἀφροδίτης Διονύσου τέ ἐστι, καὶ ἄλλος Εἰλειθυίας· λίθου τοῦ Πεντελησίου τὰ ἀγάλματα, Ἀθηναίου δὲ ἔργα Εὐκλείδου· καὶ τῇ Δήμητρί ἐστιν ἐσθής. πεποίηται δὲ καὶ Ἴσιδι ἱερόν.", "st": "7.25"}, {"sp": "N", "t": "καταβάντων δὲ ἐκ Βούρας ὡς ἐπὶ θάλασσαν ποταμός τε Βουραϊκὸς ὀνομαζόμενος καὶ Ἡρακλῆς οὐ μέγας ἐστὶν ἐν σπηλαίῳ· ἐπίκλησις μὲν καὶ τούτου Βουραϊκός, μαντείας δὲ ἐπὶ πίνακί τε καὶ ἀστραγάλοις ἔστι ⟨λαβεῖν⟩. εὔχεται μὲν γὰρ πρὸ τοῦ ἀγάλματος ὁ τῷ θεῷ χρώμενος, ἐπὶ δὲ τῇ εὐχῇ λαβὼν ἀστραγάλους —οἱ δὲ ἄφθονοι παρὰ τῷ Ἡρακλεῖ κεῖνται—τέσσαρας ἀφίησιν ἐπὶ τῆς τραπέζης· ἐπὶ δὲ παντὶ ἀστραγάλου σχήματι γεγραμμένα ἐν πίνακι ἐπίτηδες ἐξήγησιν ἔχει τοῦ σχήματος.", "st": "7.25"}, {"sp": "N", "t": "σταδίων ἐπὶ τὸν Ἡρακλέα ὡς τριάκοντα ἐξ Ἑλίκης ὁδὸς ἡ εὐθεῖά ἐστι. προελθόντι δὲ ἀπὸ τοῦ Ἡρακλέους ποταμὸς ἐς θάλασσαν ἐκδίδωσιν ἀέναος ἐξ ὄρους Ἀρκαδικοῦ κατερχόμενος, ὄνομα δὲ αὐτῷ ⟨τε⟩ [καὶ] τῷ ποταμῷ Κρᾶθις καὶ ἔνθα αἱ πηγαὶ τοῦ ποταμοῦ τῷ ὄρει· ἀπὸ ταύτης τῆς Κράθιδος καὶ πρὸς Κρότωνι τῇ ἐν Ἰταλίᾳ ποταμὸς ὄνομα ἔσχηκε.", "st": "7.25"}, {"sp": "N", "t": "πρὸς δὲ τῇ Ἀχαϊκῇ Κράθιδι Ἀχαιῶν ποτε ᾠκεῖτο Αἰγαὶ πόλις· ἐκλειφθῆναι δὲ αὐτὴν ἀνὰ χρόνον ὑπὸ ἀσθενείας λέγουσι. τούτων δὲ καὶ Ὅμηρος τῶν Αἰγῶν ἐν Ἥρας λόγοις ἐποιήσατο μνήμην,<br>οἱ δέ τοι εἰς Ἑλίκην τε καὶ Αἰγὰς δῶρ’ ἀνάγουσι,<br>δῆλον ὡς γέρα τοῦ Ποσειδῶνος ἐπ’ ἴσης ἔν τε Ἑλίκῃ καὶ ἐν ταῖς Αἰγαῖς ἔχοντος.", "st": "7.25"}, {"sp": "N", "t": "οὐ πολὺ δὲ ἀπωτέρω Κράθιδος σῆμά τε ἐν δεξιᾷ τῆς ὁδοῦ καὶ ἄνδρα εὑρήσεις ἐπὶ τῷ μνήματι ἵππῳ παρεστῶτα, ἀμυδρὰν γραφήν. ὁδὸς δὲ ἀπὸ τοῦ τάφου σταδίων ὅσον τριάκοντα ἐπὶ τὸν καλούμενον Γαῖον· Γῆς δὲ ἱερόν ἐστιν ὁ Γαῖος ἐπίκλησιν Εὐρυστέρνου, ξόανον δὲ τοῖς μάλιστα ὁμοίως ἐστὶν ἀρχαῖον. γυνὴ δὲ ἡ ἀεὶ τὴν ἱερωσύνην λαμβάνουσα ἁγιστεύει μὲν τὸ ἀπὸ τούτου, οὐ μὴν οὐδὲ τὰ πρότερα ἔσται πλέον ἢ ἑνὸς ἀνδρὸς ἐς πεῖραν ἀφιγμένη. πίνουσαι δὲ αἷμα ταύρου δοκιμάζονται· ἣ δ’ ἂν αὐτῶν τύχῃ μὴ ἀληθεύουσα, αὐτίκα ἐκ τούτου τὴν δίκην ἔσχεν. ἢν δὲ ὑπὲρ τῆς ἱερωσύνης ἀφίκωνται γυναῖκες ⟨ἐς⟩ ἀμφισβήτησιν πλέονες, ἡ τῷ κλήρῳ λαχοῦσα προτετίμηται.", "st": "7.25"}, {"sp": "N", "t": "ἐς δὲ τὸ ἐπίνειον τὸ Αἰγειρατῶν—ὄνομα τὸ αὐτὸ ἥ τε πόλις καὶ τὸ ἐπίνειον ἔχει—, ἐς οὖν τὸ ἐπίνειον Αἰγειρατῶν δύο καὶ ἑβδομήκοντα ἀπὸ τοῦ κατὰ τὴν ὁδὸν τὴν Βουραϊκήν εἰσιν Ἡρακλέους στάδιοι. ἐπὶ θαλάσσῃ μὲν δὴ Αἰγειράταις οὐδέν ἐστιν ἐς μνήμην, ὁδὸς δὲ ἐκ τοῦ ἐπινείου δύο σταδίων καὶ δέκα ἐς τὴν ἄνω πόλιν.", "st": "7.26"}, {"sp": "N", "t": "Ὁμήρου δὲ ἐν τοῖς ἔπεσιν Ὑπερησία ὠνόμασται· τὸ δὲ ὄνομα τὸ νῦν ἐγένετο Ἰώνων ἐποικούντων, ἐγένετο δὲ ἐπ’ αἰτίᾳ τοιᾷδε. Σικυωνίων ἀφίξεσθαι στρατὸς ἔμελλεν αὐτοῖς πολέμιος ἐς τὴν γῆν· οἱ δὲ —οὐ γὰρ ἐδόκουν ἀξιόμαχοι τοῖς Σικυωνίοις εἶναι— ἀθροίζουσιν αἶγας, ὁπόσαι σφίσιν ἦσαν ἐν τῇ χώρᾳ, συλλέξαντες δὲ ἔδησαν πρὸς τοῖς κέρασιν αὐτῶν δᾷδας, καὶ ὡς πρόσω νυκτὸς ἦν, ἐξάπτουσι τὰς δᾷδας.", "st": "7.26"}, {"sp": "N", "t": "Σικυώνιοι δὲ—ἰέναι γὰρ συμμάχους τοῖς Ὑπερησιεῦσιν ἤλπιζον ⟨καὶ⟩ εἶναι τὴν φλόγα [καὶ] ἐκ τοῦ ἐπικουρικοῦ πυρός—οἱ μὲν οἴκαδε ἐπανήρχοντο, Ὑπερησιεῖς δὲ τῇ τε πόλει τὸ ὄνομα τὸ νῦν μετέθεντο ἀπὸ τῶν αἰγῶν, καὶ καθότι αὐτῶν ἡ καλλίστη καὶ ἡγουμένη τῶν ἄλλων ὤκλασεν, Ἀρτέμιδος Ἀγροτέρας ἐποιήσαντο ἱερόν, τὸ σόφισμα ἐς τοὺς Σικυωνίους οὐκ ἄνευ τῆς Ἀρτέμιδός σφισιν ἐπελθεῖν νομίζοντες.", "st": "7.26"}, {"sp": "N", "t": "οὐ μὴν καὶ αὐτίκα ⟨γε⟩ ἐξενίκησεν Αἴγειραν ἀντὶ Ὑπερησίας καλεῖσθαι, ἐπεὶ κατ’ ἐμὲ ἦσαν ἔτι οἳ Ὠρεὸν τὴν ἐν Εὐβοίᾳ τῷ ὀνόματι Ἑστίαιαν ἐκάλουν τῷ ἀρχαίῳ. παρείχετο δὲ ἡ Αἴγειρα ἐς συγγραφὴν ἱερὸν Διὸς καὶ ἄγαλμα καθήμενον λίθου τοῦ Πεντελησίου, Ἀθηναίου δὲ ἔργον Εὐκλείδου. ἐν τούτῳ τῷ ἱερῷ καὶ Ἀθηνᾶς ἄγαλμα ἕστηκε· πρόσωπόν τε καὶ ἄκραι χεῖρες ἐλέφαντος καὶ οἱ πόδες, τὸ δὲ ἄλλο ξόανον χρυσῷ τε ἐπιπολῆς διηνθισμένον ἐστὶ καὶ φαρμάκοις.", "st": "7.26"}, {"sp": "N", "t": "Ἀρτέμιδός τε ναὸς καὶ ἄγαλμα τέχνης τῆς ἐφ’ ἡμῶν· ἱερᾶται δὲ παρθένος, ἔστ’ ἂν ἐς ὥραν ἀφίκηται γάμου. ἕστηκε δὲ καὶ ἄγαλμα ἐνταῦθα ἀρχαῖον, Ἰφιγένεια ἡ Ἀγαμέμνονος, ὡς οἱ Αἰγειρᾶταί φασιν· εἰ δὲ ἀληθῆ λέγουσιν οὗτοι, δῆλός ἐστιν ἐξ ἀρχῆς Ἰφιγενείᾳ ποιηθεὶς ὁ ναός.", "st": "7.26"}, {"sp": "N", "t": "ἔστι καὶ Ἀπόλλωνος ἱερὸν ἐς τὰ μάλιστα ἀρχαῖον τό τε ἱερὸν αὐτὸ καὶ ὁπόσα ἐν τοῖς ἀετοῖς, ἀρχαῖον δὲ καὶ τοῦ θεοῦ τὸ ξόανον, γυμνός, μεγέθει μέγας· τὸν ποιήσαντα δὲ εἶχεν οὐδεὶς τῶν ἐπιχωρίων εἰπεῖν· ὅστις δὲ ἤδη τὸν Ἡρακλέα τὸν ἐν Σικυῶνι ἐθεάσατο, τεκμαίροιτο ἂν καὶ ἐν Αἰγείρᾳ τὸν Ἀπόλλωνα ἔργον εἶναι τοῦ αὐτοῦ Φλιασίου Λαφάους.", "st": "7.26"}, {"sp": "N", "t": "Ἀσκληπιοῦ δὲ ἀγάλματα ὀρθά ἐστιν ἐν ναῷ καὶ Σαράπιδος ἑτέρωθι καὶ Ἴσιδος, λίθου καὶ ταῦτα Πεντελησίου. τὴν δὲ Οὐρανίαν σέβουσι μὲν τὰ μάλιστα, ἐσελθεῖν δὲ ἐς τὸ ἱερὸν οὐκ ἔστιν ἀνθρώποις. θεοῦ δὲ ἣν Συρίαν ἐπονομάζουσιν, ἐς ταύτης τὸ ἱερὸν ἐσίασιν ἐν ἡμέραις ῥηταῖς, ἄλλα τε ὅσα νομίζουσι προκαθαριεύσαντες καὶ ἐς τὴν δίαιταν.", "st": "7.26"}, {"sp": "N", "t": "οἶδα καὶ οἴκημα ἐν Αἰγείρᾳ θεασάμενος· ἄγαλμα ἦν ἐν τῷ οἰκήματι Τύχης, τὸ κέρας φέρουσα τὸ Ἀμαλθείας· παρὰ δὲ αὐτὴν Ἔρως πτερὰ ἔχων ἐστίν, ἐθέλει δὲ σημαίνειν ὅτι ἀνθρώποις καὶ τὰ ἐς ἔρωτα τύχῃ μᾶλλον ἢ ὑπὸ κάλλους κατορθοῦται. ἐγὼ μὲν οὖν Πινδάρου τά τε ἄλλα πείθομαι τῇ ᾠδῇ καὶ Μοιρῶν τε εἶναι μίαν τὴν Τύχην καὶ ὑπὲρ τὰς ἀδελφάς τι ἰσχύειν·", "st": "7.26"}, {"sp": "N", "t": "ἐν Αἰγείρᾳ δὲ ἐν τούτῳ τῷ οἰκήματι ἀνήρ τε ἤδη γέρων ἴσα καὶ ὀδυρόμενος καὶ γυναῖκες [αἱ] τρεῖς ἀφαιρούμεναι ψέλιά εἰσι καὶ ἴσοι νεανίσκοι ταῖς γυναιξί, [καὶ ὁ] ἐνδεδυκὼς ⟨δὲ⟩ θώρακα εἷς. τοῦτόν φασιν Ἀχαιοῖς γενομένου πολέμου μαχεσάμενον ἀνδρειότατα Αἰγειρατῶν τελευτῆσαι, καὶ αὐτοῦ τὸν θάνατον οἱ λοιποὶ τῶν ἀδελφῶν οἴκαδε ἀπήγγειλαν· καὶ τοῦδε ἕνεκα αἵ τε ἀδελφαὶ διὰ τὸ ἐπ’ αὐτῷ πένθος ἀποκοσμοῦνται καὶ τὸν πατέρα ἐπονομάζουσιν οἱ ἐπιχώριοι Συμπαθῆ, ἅτε ἐλεεινὸν καὶ ἐν τῇ εἰκόνι.", "st": "7.26"}, {"sp": "N", "t": "ὁδὸς δὲ ἐξ Αἰγείρας εὐθεῖα ἀπὸ τοῦ ἱεροῦ τοῦ Διὸς διά τε ὀρῶν καὶ ἀνάντης ἐστί· μῆκος μὲν οὖν τῆς ὁδοῦ τεσσαράκοντά εἰσι στάδιοι, ἄγει δὲ ἐς Φελλόην, πόλισμα οὐκ ἐπιφανές, †οὐδὲ ὡς ἀεὶ ᾠκεῖτο καὶ Ἰώνων ἔτι ἐχόντων τὴν γῆν. τὰ δὲ περὶ τὴν Φελλόην ἐς φυτείαν ἀμπέλων ἐστὶν ἐπιτήδεια· καὶ ὅσα πετρώδη τῆς χώρας, δρῦς τέ εἰσι καὶ θηρία, ἔλαφοι καὶ ὗς ἄγριοι·", "st": "7.26"}, {"sp": "N", "t": "εἰ δέ τινα τῶν ἐν Ἕλλησι πολισματίων ἀφθόνῳ καταρρεῖται τῷ ὕδατι, ἀριθμεῖν καὶ τὴν Φελλόην ἔστιν ἐν τούτοις. θεῶν δὲ ἱερὰ Διονύσου καὶ Ἀρτέμιδός ἐστιν· ἡ μὲν χαλκοῦ πεποίηται, βέλος δὲ ἐκ φαρέτρας λαμβάνουσα· τῷ Διονύσῳ δὲ ὑπὸ κινναβάρεως τὸ ἄγαλμά ἐστιν ἐπηνθισμένον. ἐς δὲ τὸ ἐπίνειον καταβᾶσιν ἐξ Αἰγείρας καὶ αὖθις ἐς τὰ πρόσω βαδίζουσιν ἔστιν ἐν δεξιᾷ τῆς ὁδοῦ τὸ ἱερὸν τῆς Ἀγροτέρας, ἔνθα τὴν αἶγα ὀκλάσαι λέγουσιν.", "st": "7.26"}, {"sp": "N", "t": "τῆς δὲ Αἰγειρατῶν ἔχονται Πελληνεῖς· πρὸς Σικυῶνος δὲ οὗτοι καὶ μοίρας τῆς Ἀργολίδος Ἀχαιῶν οἰκοῦσιν ἔσχατοι. τὸ δὲ ὄνομα ἐγένετο τῇ πόλει λόγῳ μὲν τῷ Πελληνέων ἀπὸ Πάλλαντος, τῶν Τιτάνων δὲ καὶ Πάλλαντα εἶναι λέγουσι, δόξῃ δὲ τῇ Ἀργείων ἀπὸ ἀνδρὸς Ἀργείου Πέλληνος· Φόρβαντος δὲ εἶναι τοῦ Τριόπα παῖδα αὐτὸν λέγουσιν.", "st": "7.26"}, {"sp": "N", "t": "Αἰγείρας δὲ ἐν τῷ μεταξὺ καὶ Πελλήνης πόλισμα ὑπήκοον Σικυωνίων Δονοῦσσα καλουμένη ἐγένετο μὲν ὑπὸ τῶν Σικυωνίων ἀνάστατος, μνημονεύειν δὲ καὶ Ὅμηρον ἐν καταλόγῳ τῶν σὺν Ἀγαμέμνονί φασιν αὐτῆς ποιήσαντα ἔπος<br>οἵ θ’ Ὑπερησίην τε καὶ αἰπεινὴν Δονόεσσαν·<br>Πεισίστρατον δέ, ἡνίκα ἔπη τὰ Ὁμήρου διεσπασμένα τε καὶ ⟨ἄλλα⟩ ἀλλαχοῦ μνημονευόμενα ἤθροιζε, τότε αὐτὸν Πεισίστρατον ἢ τῶν τινα ἑταίρων μεταποιῆσαι τὸ ὄνομα ὑπὸ ἀγνοίας.", "st": "7.26"}, {"sp": "N", "t": "ἔστι δὲ Ἀριστοναῦται Πελληνεῦσιν ἐπίνειον. ἐς τοῦτο ἐξ Αἰγείρας τῆς ἐπὶ θαλάσσῃ σταδίων ἐστὶν εἴκοσιν ὁδὸς καὶ ἑκατόν· ταύτης δὲ ἡμίσεια ἐς Πελλήνην ἀπὸ τοῦ ἐπινείου. ὄνομα δὲ Ἀριστοναύτας γενέσθαι τῷ ἐπινείῳ λέγουσιν, ὅτι καὶ ἐς τοῦτον τὸν λιμένα ὡρμίσαντο οἱ πλεύσαντες ἐπὶ τῆς Ἀργοῦς.", "st": "7.26"}, {"sp": "N", "t": "Πελληνεῦσι δὲ ἡ πόλις ἐστὶν ἐπὶ λόφου κατὰ ἄκραν τὴν κορυφὴν ἐς ὀξὺ ἀνεστηκότος. τοῦτο μὲν δὴ ἀπότομον καὶ δι’ αὐτό ἐστιν ἀοίκητον· τῷ δὲ χθαμαλωτέρῳ πεπόλισταί σφισιν οὐ συνεχὴς ἡ πόλις, ἐς δὲ μοίρας νενεμημένη δύο ὑπὸ τῆς ἄκρας μεταξὺ ἀνεχούσης. ἰόντων δὲ ἐς Πελλήνην ἄγαλμά ἐστιν Ἑρμοῦ κατὰ τὴν ὁδόν, ἐπίκλησιν μὲν Δόλιος, εὐχὰς δὲ ἀνθρώπων ἕτοιμος τελέσαι· σχῆμα δὲ αὐτῷ τετράγωνον, γένειά τε ἔχει καὶ ἐπὶ τῇ κεφαλῇ πῖλον εἰργασμένον.", "st": "7.27"}, {"sp": "N", "t": "κατὰ δὲ τὴν ὁδὸν ἐς αὐτὴν τὴν πόλιν ἐστὶν Ἀθηνᾶς λίθου μὲν ἐπιχωρίου ναός, ἐλέφαντος δὲ τὸ ἄγαλμα καὶ χρυσοῦ· Φειδίαν δὲ εἶναι τὸν εἰργασμένον φασὶ πρότερον ἔτι ἢ ἐν τῇ ἀκροπόλει τε αὐτὸν τῇ Ἀθηναίων καὶ ἐν Πλαταιαῖς ποιῆσαι τῆς Ἀθηνᾶς τὰ ἀγάλματα. λέγουσι δὲ οἱ Πελληνεῖς καὶ ἄδυτον τῆς Ἀθηνᾶς καθήκειν ἐς βάθος τῆς γῆς, εἶναι δὲ τὸ ἄδυτον τοῦτο ὑπὸ τοῦ ἀγάλματος τῷ βάθρῳ, καὶ τὸν ἀέρα ἐκ τοῦ ἀδύτου νότιόν τε εἶναι καὶ δι’ αὐτὸ τῷ ἐλέφαντι ἐπιτήδειον.", "st": "7.27"}, {"sp": "N", "t": "ὑπὲρ δὲ τὸν ναὸν τῆς Ἀθηνᾶς ἐστιν ἄλσος περιῳκοδομημένον τείχει Σωτείρας ἐπίκλησιν Ἀρτέμιδος, καὶ ὀμνύουσιν ἐπὶ μεγίστοις αὐτήν· ἔσοδός τε πλὴν τοῖς ἱερεῦσιν ἄλλῳ γε οὐδενὶ ἔστιν ἀνθρώπων. ἱερεῖς δὲ ἄνδρες τῶν ἐπιχωρίων εἰσὶ κατὰ δόξαν γένους μάλιστα αἱρούμενοι. τοῦ δὲ ἄλσους τῆς Σωτείρας ἱερὸν ἀπαντικρὺ Διονύσου Λαμπτῆρός ἐστιν ἐπίκλησιν· τούτῳ καὶ Λαμπτήρια ἑορτὴν ἄγουσι, καὶ δᾷδάς τε ἐς τὸ ἱερὸν κομίζουσιν ἐν νυκτὶ καὶ οἴνου κρατῆρας ἱστᾶσιν ἀνὰ τὴν πόλιν πᾶσαν.", "st": "7.27"}, {"sp": "N", "t": "ἔστι καὶ Ἀπόλλωνος Θεοξενίου Πελληνεῦσιν ἱερόν, τὸ δὲ ἄγαλμα χαλκοῦ πεποίηται· καὶ ἀγῶνα ἐπιτελοῦσι Θεοξένια τῷ Ἀπόλλωνι, τιθέντες ἀργύριον ἆθλα τῆς νίκης, καὶ ἄνδρες ἀγωνίζονται τῶν ἐπιχωρίων. πλησίον δὲ τοῦ Ἀπόλλωνος ναός ἐστιν Ἀρτέμιδος· τοξευούσης δὲ ἡ θεὸς παρέχεται σχῆμα. ᾠκοδόμηται δὲ καὶ ἔλυτρον κρήνης ἐν τῇ ἀγορᾷ, καὶ λουτρά ἐστιν αὐτοῖς τὸ ὕδωρ τὸ ἐκ τοῦ θεοῦ, ἐπεί τοι πίνειν πηγαί σφισιν ὑπὸ τὴν πόλιν εἰσὶν οὐ πολλαί· τὸ δὲ χωρίον, ἔνθα αἱ πηγαί, Γλυκείας ὀνομάζουσι.", "st": "7.27"}, {"sp": "N", "t": "γυμνάσιον δὲ ἀρχαῖον ἐς ἐφήβων μάλιστα ἀνεῖται μελέτην· οὐδὲ ἐς τὴν πολιτείαν ἐγγραφῆναι πρότερον καθέστηκεν οὐδενὶ πρὶν ἂν ἐφηβεύσωσιν. ἐνταῦθα ἀνὴρ Πελληνεὺς ἕστηκε Πρόμαχος ὁ Δρύωνος, ἀνελόμενος παγκρατίου νίκας, τὴν μὲν Ὀλυμπίασι, τρεῖς δ’ Ἰσθμίων καὶ Νεμέᾳ δύο· καὶ αὐτοῦ καὶ εἰκόνας ποιήσαντες οἱ Πελληνεῖς τὴν μὲν ἐς Ὀλυμπίαν ἀνέθεσαν, τὴν δὲ ἐν τῷ γυμνασίῳ, λίθου ταύτην καὶ οὐ χαλκοῦ.", "st": "7.27"}, {"sp": "N", "t": "λέγεται δὲ καὶ ὡς Κορινθίου συνεστῶτος πολέμου Πελληνεῦσιν ἀποκτείνειεν ὁ Πρόμαχος πλείστους τῶν ἀντιτεταγμένων. λέγεται δὲ καὶ ὡς Πουλυδάμαντος τοῦ Σκοτουσσαίου κρατήσειεν ἐν Ὀλυμπίᾳ· τὸν δὲ Πουλυδάμαντα δεύτερα τότε ἐς τὸν ἀγῶνα ἀφῖχθαι τὸν Ὀλυμπικὸν παρὰ βασιλέως τοῦ Περσῶν ἀνασωθέντα οἴκαδε. Θεσσαλοὶ δὲ ἡσσηθῆναι Πουλυδάμαντα οὐχ ὁμολογοῦντες παρέχονται καὶ ἄλλα ἐς πίστιν καὶ ἐλεγεῖον ἐπὶ τῷ Πουλυδάμαντι·<br>ὦ τροφὲ Πουλυδάμαντος ἀνικάτου Σκοτόεσσα.", "st": "7.27"}, {"sp": "N", "t": "Πελληνεῖς δ’ οὖν Πρόμαχον τὰ μάλιστα ἄγουσιν ἐν τιμῇ. Χαίρωνα δὲ δύο ἀνελόμενον πάλης νίκας ⟨Ἰσθμικὰς⟩ καὶ ἐν Ὀλυμπίᾳ τέσσαρας οὐδὲ ἀρχὴν ἐθέλουσιν ὀνομάζειν, ὅτι κατέλυσε πολιτείαν ἐμοὶ δοκεῖν τὴν ἐν Πελλήνῃ, δῶρον τὸ ἐπιφθονώτατον παρὰ Ἀλεξάνδρου τοῦ Φιλίππου λαβών, τύραννος πατρίδος τῆς αὑτοῦ καταστῆναι.", "st": "7.27"}, {"sp": "N", "t": "ἔστι δὲ καὶ Εἰλειθυίας Πελληνεῦσιν ἱερόν· τοῦτο ἐν μοίρᾳ τῆς πόλεως τῇ ἐλάσσονί ἐστιν ἱδρυμένον. τὸ δὲ ὀνομαζόμενον Ποσείδιον τὰ μὲν ἀρχαιότερα ἦν δῆμος, ἔρημον δὲ ἐφ’ ἡμῶν. ἔστι μὲν δὴ τὸ Ποσείδιον τοῦτο ὑπὸ τὸ γυμνάσιον, διαμεμένηκε δὲ καὶ ἐς τόδε ἔτι αὐτῷ Ποσειδῶνος ἱερὸν νομίζεσθαι.", "st": "7.27"}, {"sp": "N", "t": "Πελλήνης δὲ ὅσον στάδια ἑξήκοντα ἀπέχει τὸ Μύσαιον, ἱερὸν Δήμητρος Μυσίας· ἱδρύσασθαι δὲ αὐτὸ Μύσιόν φασιν ἄνδρα Ἀργεῖον, ἐδέξατο δὲ οἴκῳ Δήμητρα καὶ ὁ Μύσιος λόγῳ τῷ Ἀργείων. ἔστι δὲ ἄλσος ἐν τῷ Μυσαίῳ, δένδρα ὁμοίως τὰ πάντα, καὶ ὕδωρ ἄφθονον ἄνεισιν ἐκ πηγῶν. ἄγουσι δὲ καὶ ἑορτὴν τῇ Δήμητρι ἐνταῦθα ἡμερῶν ἑπτά·", "st": "7.27"}, {"sp": "N", "t": "τρίτῃ δὲ ἡμέρᾳ τῆς ἑορτῆς ὑπεξίασιν οἱ ἄνδρες ἐκ τοῦ ἱεροῦ, καταλειπόμεναι δὲ αἱ γυναῖκες δρῶσιν ἐν τῇ νυκτὶ ὁπόσα νόμος ἐστὶν αὐταῖς· ἀπελαύνονται δὲ οὐχ οἱ ἄνδρες μόνον ἀλλὰ καὶ τῶν κυνῶν τὸ ἄρρεν. ἐς δὲ τὴν ἐπιοῦσαν ἀφικομένων ἐς τὸ ἱερὸν τῶν ἀνδρῶν, αἱ γυναῖκές τε ἐς αὐτοὺς καὶ ἀνὰ μέρος ἐς τὰς γυναῖκας οἱ ἄνδρες γέλωτί τε ἐς ἀλλήλους χρῶνται καὶ σκώμμασιν.", "st": "7.27"}, {"sp": "N", "t": "ἀπωτέρω δὲ οὐ πολὺ ἀπὸ τοῦ Μυσαίου ἱερόν ἐστιν Ἀσκληπιοῦ καλούμενον Κῦρος, καὶ ἰάματα ἀνθρώποις παρὰ τοῦ θεοῦ γίνεται. ὕδωρ δὲ καὶ ἐνταῦθα ἀνέδην ἐστί, καὶ ἐπὶ τῇ μεγίστῃ τῶν πηγῶν τοῦ Ἀσκληπιοῦ τὸ ἄγαλμα ἵδρυται. ποταμοὶ δὲ ἐκ τῶν ὀρῶν κατέρχονται ⟨τῶν⟩ ὑπὲρ τὴν Πελλήνην, πρὸς μὲν Αἰγείρας καλούμενος Κριός· ἔχειν δὲ αὐτὸν τὸ ὄνομα ἀπὸ Τιτᾶνος Κριοῦ·", "st": "7.27"}, {"sp": "N", "t": "⟨Κριὸς δὲ⟩ καὶ ἄλλος ὠνόμασται ποταμός, ὃς ἀρχόμενος ἐκ Σιπύλου τοῦ ὄρους ἐς τὸν Ἕρμον κάτεισι. καθότι δὲ Πελληνεῦσιν ὅροι τῆς χώρας πρὸς Σικυωνίους εἰσί, κατὰ τοῦτο ποταμός σφισι Σύθας, ἔσχατος ποταμῶν τῶν Ἀχαϊκῶν, ἐς τὴν Σικυωνίαν ἐκδίδωσι θάλασσαν.", "st": "7.27"}, {"sp": "HDR", "t": "Βιβλίον Ηʹ — Ἀρκαδικά", "st": "8"}, {"sp": "N", "t": "Ἀρκάδων δὲ τὰ πρὸς τῆς Ἀργείας Τεγεᾶταί τε ἔχουσι καὶ Μαντινεῖς, νέμονται δὲ οὗτοί τε καὶ τὸ ἄλλο Ἀρκαδικὸν ⟨τὸ⟩ μεσόγαιον τῆς Πελοποννήσου. Κορίνθιοι γὰρ οἰκοῦσιν ἐπὶ τῷ ἰσθμῷ πρῶτοι· Κορινθίοις δὲ τὰ πρὸς θαλάσσης εἰσὶν Ἐπιδαύριοι γείτονες· τὰ δὲ ἐς Ἐπίδαυρον καὶ Τροιζῆνά τε καὶ Ἑρμιόνα ὁ κόλπος ἐστὶν ὁ Ἀργολικὸς καὶ ὅσα ἐπιθαλάσσια τῆς Ἀργείας· ταύτης δὲ ἔχονται τῆς χώρας Λακεδαιμονίων περίοικοι, τούτοις δὲ ὅμορος ἡ Μεσσηνία· καταβαίνει γὰρ μέχρι θαλάσσης ἐς Μοθώνην καὶ Πύλον καὶ ἐπὶ Κυπαρισσιάς.", "st": "8.1"}, {"sp": "N", "t": "τὰ δὲ πρὸς Λεχαίου Κορινθίοις Σικυώνιοι προσοικοῦσιν ἔσχατοι ταύτῃ μοίρας τῆς Ἀργολίδος· μετὰ δὲ Σικυῶνα Ἀχαιοὶ τὸ ἐντεῦθέν εἰσιν οἱ παρὰ τὸν αἰγιαλὸν οἰκοῦντες· τὸ δὲ ἕτερον Πελοποννήσου πέρας τὸ ἀπαντικρὺ τῶν Ἐχινάδων οἰκοῦσιν Ἠλεῖοι· τῆς δὲ γῆς τῆς Ἠλείας κατὰ μὲν Ὀλυμπίαν καὶ τοῦ Ἀλφειοῦ τὰς ἐκβολὰς πρὸς τὴν Μεσσηνίαν εἰσὶν ὅροι, τὰ δὲ πρὸς Ἀχαΐαν Δυμαίων εἰσὶν ὅμοροι.", "st": "8.1"}, {"sp": "N", "t": "τούτων τῶν κατειλεγμένων καθηκόντων ἐπὶ θάλασσαν Ἀρκάδες τὸ ἐντὸς οἰκοῦσιν ἀποκλειόμενοι θαλάσσης πανταχόθεν· ὅθεν σφᾶς καὶ Ὅμηρος ἀφικέσθαι φησὶν ἐς Τροίαν παρ’ Ἀγαμέμνονος πλοῖα εἰληφότας καὶ οὐχὶ ναυσὶν οἰκείαις.", "st": "8.1"}, {"sp": "N", "t": "φασὶ δὲ Ἀρκάδες ὡς Πελασγὸς γένοιτο ἐν τῇ γῇ ταύτῃ πρῶτος. εἰκὸς δὲ ἔχει τοῦ λόγου καὶ ἄλλους ὁμοῦ τῷ Πελασγῷ μηδὲ αὐτὸν Πελασγὸν γενέσθαι μόνον· ποίων γὰρ ἂν καὶ ἦρχεν ὁ Πελασγὸς ἀνθρώπων; μεγέθει μέντοι καὶ κατὰ ἀλκὴν καὶ κάλλος προεἶχεν ὁ Πελασγὸς καὶ γνώμην ὑπὲρ τοὺς ἄλλους ἦν, καὶ τούτων ἕνεκα αἱρεθῆναί μοι δοκεῖ βασιλεύειν ὑπ’ αὐτῶν. πεποίηται δὲ καὶ Ἀσίῳ τοιάδε ἐς αὐτόν·<br>Ἀντίθεον δὲ Πελασγὸν ἐν ὑψικόμοισιν ὄρεσσι<br>γαῖα μέλαιν’ ἀνέδωκεν, ἵνα θνητῶν γένος εἴη.", "st": "8.1"}, {"sp": "N", "t": "Πελασγὸς δὲ βασιλεύσας τοῦτο μὲν ποιήσασθαι καλύβας ἐπενόησεν, ὡς μὴ ῥιγοῦν τε καὶ ὕεσθαι τοὺς ἀνθρώπους μηδὲ ὑπὸ τοῦ καύματος ταλαιπωρεῖν· τοῦτο δὲ τοὺς χιτῶνας τοὺς ἐκ τῶν δερμάτων τῶν οἰῶν, οἷς καὶ νῦν περί τε Εὔβοιαν ἔτι χρῶνται καὶ ἐν τῇ Φωκίδι ὁπόσοι βίου σπανίζουσιν, οὗτός ἐστιν ὁ ἐξευρών. καὶ δὴ καὶ τῶν φύλλων τὰ ἔτι χλωρὰ καὶ πόας τε καὶ ῥίζας οὐδὲ ἐδωδίμους, ἀλλὰ καὶ ὀλεθρίους ἐνίας σιτουμένους τοὺς ἀνθρώπους τούτων μὲν ἔπαυσεν ὁ Πελασγός·", "st": "8.1"}, {"sp": "N", "t": "ὁ δὲ τὸν καρπὸν τῶν δρυῶν οὔτι που πασῶν, ἀλλὰ τὰς βαλάνους τῆς φηγοῦ τροφὴν ἐξεῦρεν εἶναι. παρέμεινέ τε ἐνίοις ἐς τοσοῦτο ἀπὸ Πελασγοῦ τούτου ἡ δίαιτα, ὡς καὶ τὴν Πυθίαν, ἡνίκα Λακεδαιμονίοις γῆς τῆς Ἀρκάδων ἀπηγόρευεν ἅπτεσθαι, καὶ τάδε εἰπεῖν τὰ ἔπη·<br>πολλοὶ ἐν Ἀρκαδίῃ βαλανηφάγοι ἄνδρες ἔασιν,<br>οἵ σ’ ἀποκωλύσουσιν· ἐγὼ δέ τοι οὔ τι μεγαίρω.<br>Πελασγοῦ δὲ βασιλεύοντος γενέσθαι καὶ τῇ χώρᾳ Πελασγίαν φασὶν ὄνομα.", "st": "8.1"}, {"sp": "N", "t": "Λυκάων δὲ ὁ Πελασγοῦ τοσάδε εὗρεν ἢ ὁ πατήρ οἱ σοφώτερα· Λυκόσουράν τε γὰρ πόλιν ᾤκισεν ἐν τῷ ὄρει τῷ Λυκαίῳ καὶ Δία ὠνόμασε Λυκαῖον καὶ ἀγῶνα ἔθηκε Λύκαια. οὐκέτι δὲ τὰ παρ’ Ἀθηναίοις Παναθήναια τεθῆναι πρότερα ἀποφαίνομαι· τούτῳ γὰρ τῷ ἀγῶνι Ἀθήναια ὄνομα ἦν, Παναθήναια δὲ κληθῆναί φασιν ἐπὶ Θησέως, ὅτι ὑπὸ Ἀθηναίων ἐτέθη συνειλεγμένων ἐς μίαν ἁπάντων πόλιν.", "st": "8.2"}, {"sp": "N", "t": "ὁ δὲ ἀγὼν ὁ Ὀλυμπικὸς—ἐπανάγουσι γὰρ δὴ αὐτὸν ἐς τὰ ἀνωτέρω τοῦ ἀνθρώπων γένους, Κρόνον καὶ Δία αὐτόθι παλαῖσαι λέγοντες καὶ ὡς Κούρητες δράμοιεν πρῶτοι—τούτων ἕνεκα ἐκτὸς ἔστω μοι τοῦ παρόντος λόγου. δοκῶ δὲ ἔγωγε Κέκροπι ἡλικίαν τῷ βασιλεύσαντι Ἀθηναίων καὶ Λυκάονι εἶναι τὴν αὐτήν, σοφίᾳ δὲ οὐχ ὁμοίᾳ σφᾶς ἐς τὸ θεῖον χρήσασθαι.", "st": "8.2"}, {"sp": "N", "t": "ὁ μὲν γὰρ Δία τε ὠνόμασεν Ὕπατον πρῶτος, καὶ ὁπόσα ἔχει ψυχήν, τούτων μὲν ἠξίωσεν οὐδὲν θῦσαι, πέμματα δὲ ἐπιχώρια ἐπὶ τοῦ βωμοῦ καθήγισεν, ἃ πελάνους καλοῦσιν ἔτι καὶ ἐς ἡμᾶς Ἀθηναῖοι· Λυκάων δὲ ἐπὶ τὸν βωμὸν τοῦ Λυκαίου Διὸς βρέφος ἤνεγκεν ἀνθρώπου καὶ ἔθυσε τὸ βρέφος καὶ ἔσπεισεν ἐπὶ τοῦ βωμοῦ τὸ αἷμα, καὶ αὐτὸν αὐτίκα ἐπὶ τῇ θυσίᾳ γενέσθαι λύκον φασὶν ἀντὶ ἀνθρώπου.", "st": "8.2"}, {"sp": "N", "t": "καὶ ἐμέ γε ὁ λόγος οὗτος πείθει, λέγεται δὲ ὑπὸ Ἀρκάδων ἐκ παλαιοῦ, καὶ τὸ εἰκὸς αὐτῷ πρόσεστιν. οἱ γὰρ δὴ τότε ἄνθρωποι ξένοι καὶ ὁμοτράπεζοι θεοῖς ἦσαν ὑπὸ δικαιοσύνης καὶ εὐσεβείας, καί σφισιν ἐναργῶς ἀπήντα παρὰ τῶν θεῶν τιμή τε οὖσιν ἀγαθοῖς καὶ ἀδικήσασιν ὡσαύτως ἡ ὀργή, ἐπεί τοι καὶ θεοὶ τότε ἐγίνοντο ἐξ ἀνθρώπων, οἳ γέρα καὶ ἐς τόδε ἔτι ἔχουσιν ὡς Ἀρισταῖος καὶ Βριτόμαρτις ἡ Κρητικὴ καὶ Ἡρακλῆς ὁ Ἀλκμήνης καὶ Ἀμφιάραος ὁ Ὀικλέους, ἐπὶ δὲ αὐτοῖς Πολυδεύκης τε καὶ Κάστωρ.", "st": "8.2"}, {"sp": "N", "t": "οὕτω πείθοιτο ἄν τις καὶ Λυκάονα θηρίον καὶ τὴν Ταντάλου Νιόβην γενέσθαι λίθον. ἐπ’ ἐμοῦ δὲ—κακία γὰρ δὴ ἐπὶ πλεῖστον ηὔξετο καὶ γῆν τε ἐπενέμετο πᾶσαν καὶ πόλεις πάσας—οὔτε θεὸς ἐγίνετο οὐδεὶς ἔτι ἐξ ἀνθρώπου, πλὴν ὅσον λόγῳ καὶ κολακείᾳ πρὸς τὸ ὑπερέχον, καὶ ἀδίκοις τὸ μήνιμα τὸ ἐκ τῶν θεῶν ὀψέ τε καὶ ἀπελθοῦσιν ἐνθένδε ἀπόκειται.", "st": "8.2"}, {"sp": "N", "t": "ἐν δὲ τῷ παντὶ αἰῶνι πολλὰ μὲν πάλαι συμβάντα, ⟨τὰ⟩ δὲ καὶ ἔτι γινόμενα ἄπιστα εἶναι πεποιήκασιν ἐς τοὺς πολλοὺς οἱ τοῖς ἀληθέσιν ἐποικοδομοῦντες ἐψευσμένα. λέγουσι γὰρ δὴ ὡς Λυκάονος ὕστερον ἀεί τις ἐξ ἀνθρώπου λύκος γίνοιτο ἐπὶ τῇ θυσίᾳ τοῦ Λυκαίου Διός, γίνοιτο δὲ οὐκ ἐς ἅπαντα τὸν βίον· ὁπότε δὲ εἴη λύκος, εἰ μὲν κρεῶν ἀπόσχοιτο ἀνθρωπίνων, ὕστερον ἔτει δεκάτῳ φασὶν αὐτὸν αὖθις ἄνθρωπον ἐκ λύκου γίνεσθαι, γευσάμενον δὲ ἐς ἀεὶ μένειν θηρίον.", "st": "8.2"}, {"sp": "N", "t": "ὡσαύτως δὲ καὶ Νιόβην λέγουσιν ἐν Σιπύλῳ τῷ ὄρει θέρους ὥρᾳ κλαίειν. ἤδη δὲ καὶ ἄλλα ἤκουσα, τοῖς γρυψὶ στίγματα ὁποῖα καὶ ταῖς παρδάλεσιν εἶναι, καὶ ὡς οἱ Τρίτωνες ἀνθρώπου φωνῇ φθέγγοιντο· οἱ δὲ καὶ φυσᾶν διὰ κόχλου τετρυπημένης φασὶν αὐτούς. ὁπόσοι δὲ μυθολογήμασιν ἀκούοντες ἥδονται, πεφύκασι καὶ αὐτοί τι ἐπιτερατεύεσθαι· καὶ οὕτω τοῖς ἀληθέσιν ἐλυμήναντο, συγκεραννύντες αὐτὰ ἐψευσμένοις.", "st": "8.2"}, {"sp": "N", "t": "τρίτῃ δὲ ὕστερον γενεᾷ μετὰ Πελασγὸν ἔς τε πόλεων καὶ ἐς ἀνθρώπων πλῆθος ἐπέδωκεν ἡ χώρα. Νύκτιμος μὲν γὰρ πρεσβύτατός τε ἦν καὶ εἶχε τὸ πᾶν κράτος· οἱ δὲ ἄλλοι παῖδες τοῦ Λυκάονος πόλεις ἐνταῦθα ἔκτιζον ἔνθα ἑκάστῳ μάλιστα ἦν κατὰ γνώμην. Πάλλας μὲν καὶ Ὀρεσθεὺς καὶ Φίγαλος Παλλάντιον, Ὀρεσθεὺς δὲ Ὀρεσθάσιον, Φιγαλίαν δὲ οἰκίζει Φίγαλος.", "st": "8.3"}, {"sp": "N", "t": "Παλλαντίου μὲν δὴ καὶ Στησίχορος ὁ Ἱμεραῖος ἐν Γηρυονηίδι ἐποιήσατο μνήμην· Φιγαλία δὲ καὶ Ὀρεσθάσιον [ἐν] χρόνῳ μεταβάλλουσι τὰ ὀνόματα, Ὀρέστειόν τε ἀπὸ Ὀρέστου κληθεῖσα τοῦ Ἀγαμέμνονος καὶ Φιαλία ἀπὸ τοῦ Βουκολίωνος παιδὸς Φιάλου. Τραπεζεὺς δὲ καὶ Δασεάτας καὶ Μακαρεὺς καὶ Ἑλισσὼν καὶ Ἄκακός τε καὶ Θῶκνος Θωκνίαν πόλιν, ὁ δὲ Ἀκακήσιον ἔκτισεν· ἀπὸ τούτου δὲ τοῦ Ἀκάκου καὶ Ὅμηρος λόγῳ τῷ Ἀρκάδων ἐς Ἑρμῆν ἐποίησεν ἐπίκλησιν·", "st": "8.3"}, {"sp": "N", "t": "ἀπὸ δὲ Ἑλισσόντος ἥ τε πόλις καὶ ὁ ποταμὸς Ἑλισσὼν τὰ ὀνόματα ἐσχήκασιν, ὡσαύτως δὲ καὶ Μακαρία τε καὶ Δασέα καὶ Τραπεζοῦς ἀπὸ τῶν Λυκάονος ἐκλήθησαν καὶ αὗται παίδων. Ὀρχομενὸς δὲ ἐγένετο οἰκιστὴς Μεθυδρίου τε καλουμένης καὶ Ὀρχομενίων, οὓς ἐν τοῖς ἔπεσι πολυμήλους ὠνόμασεν Ὅμηρος. ὑπὸ δὲ Ὑψοῦντος καὶ … Μελαινεαί τε ἐκτίσθησαν καὶ Ὑψοῦς, ἔτι δὲ Θυραῖόν τε καὶ Αἱμονιαί· δόξῃ δὲ τῇ Ἀρκάδων καὶ ἡ Θυρέα ⟨ἡ⟩ ἐν τῇ Ἀργολίδι γῇ καὶ ὁ Θυρεάτης καλούμενος κόλπος ἀπὸ τοῦ Θυραίου τούτου τὰ ὀνόματα ἐσχήκασι.", "st": "8.3"}, {"sp": "N", "t": "Μαντινεὺς δὲ καὶ Τεγεάτης καὶ Μαίναλος, ὁ μὲν τῶν ἐν Ἀρκαδίᾳ πόλεων ὀνομαστοτάτην τὸ ἀρχαῖον Μαίναλον, Τεγεάτης δὲ καὶ Μαντινεὺς Τεγέαν κτίζουσι καὶ Μαντίνειαν. ὠνομάσθησαν δὲ καὶ ἀπὸ Κρώμου Κρῶμοι, καὶ Χαρισία Χαρίσιον ἔχουσα οἰκιστήν, Τρικόλωνοι δὲ ἀπὸ Τρικολώνου, καὶ ἀπὸ μὲν Περαίθου Περαιθεῖς, Ἀσέα δὲ ἀπὸ Ἀσεάτα καὶ ⟨ἀπὸ Λυκέως⟩ Λυκόα καὶ Σουματία ἀπὸ Σουματέως· Ἀλίφηρος δὲ καὶ Ἡραιεὺς ἐπώνυμοι καὶ οὗτοι πόλεσίν εἰσιν ἀμφότεροι.", "st": "8.3"}, {"sp": "N", "t": "Οἴνωτρος δὲ ὁ τῶν παίδων νεώτατος Λυκάονι ἀρσένων Νύκτιμον τὸν ἀδελφὸν χρήματα καὶ ἄνδρας αἰτήσας ἐπεραιώθη ναυσὶν ἐς Ἰταλίαν, καὶ ἡ Οἰνωτρία χώρα τὸ ὄνομα ἔσχεν ἀπὸ Οἰνώτρου βασιλεύοντος. οὗτος ἐκ τῆς Ἑλλάδος ἐς ἀποικίαν στόλος πρῶτος ἐστάλη· ἀναριθμουμένῳ δὲ ἐς τὸ ἀκριβέστατον οὐδὲ ἐκ τῶν βαρβάρων οὐδένες πρότερον ἢ Οἴνωτρος ἀφίκοντο ἐς τὴν ἀλλοδαπήν.", "st": "8.3"}, {"sp": "N", "t": "ἐπὶ δὲ τῷ γένει παντὶ τῷ ἄρσενι θυγάτηρ Λυκάονι ἐγένετο Καλλιστώ. ταύτῃ τῇ Καλλιστοῖ—λέγω δὲ τὰ λεγόμενα ὑπὸ Ἑλλήνων—συνεγένετο ἐρασθεὶς Ζεύς· Ἥρα δὲ ὡς ἐφώρασεν, ἐποίησεν ἄρκτον τὴν Καλλιστώ, Ἄρτεμις δὲ ἐς χάριν τῆς Ἥρας κατετόξευσεν αὐτήν. καὶ ὁ Ζεὺς Ἑρμῆν πέμπει σῶσαι τὸν παῖδά οἱ προστάξας, ὃν ἐν τῇ γαστρὶ εἶχεν ἡ Καλλιστώ·", "st": "8.3"}, {"sp": "N", "t": "Καλλιστὼ δὲ αὐτὴν ἐποίησεν ἀστέρας καλουμένην ἄρκτον μεγάλην, ἧς καὶ Ὅμηρος ἐν Ὀδυσσέως ἀνάπλῳ παρὰ Καλυψοῦς μνήμην ἔσχε·<br>Πληιάδας τ’ ἐσορῶντα καὶ ὀψὲ δύοντα Βοώτην<br>ἄρκτον θ’, ἣν καὶ ἅμαξαν ἐπίκλησιν καλέουσιν.<br>ἔχοιεν δ’ ἂν καὶ ἄλλως τὸ ὄνομα οἱ ἀστέρες ἐπὶ τιμῇ τῇ Καλλιστοῦς, ἐπεὶ τάφον γε αὐτῆς ἀποφαίνουσιν οἱ Ἀρκάδες.", "st": "8.3"}, {"sp": "N", "t": "μετὰ δὲ Νύκτιμον ἀποθανόντα Ἀρκὰς ἐξεδέξατο ὁ Καλλιστοῦς τὴν ἀρχήν· καὶ τόν τε ἥμερον καρπὸν ἐσηγάγετο οὗτος παρὰ Τριπτολέμου καὶ τὴν ποίησιν ἐδίδαξε τοῦ ἄρτου καὶ ἐσθῆτα ὑφαίνεσθαι καὶ ἄλλα, τὰ ἐς ταλασίαν μαθὼν παρὰ Δρίστα. ἀπὸ τούτου δὲ βασιλεύσαντος Ἀρκαδία τε ἀντὶ Πελασγίας ἡ χώρα καὶ ἀντὶ Πελασγῶν Ἀρκάδες ἐκλήθησαν οἱ ἄνθρωποι.", "st": "8.4"}, {"sp": "N", "t": "συνοικῆσαι δὲ οὐ θνητῇ γυναικὶ αὐτόν, ἀλλὰ νύμφῃ Δρυάδι ἔλεγον· Δρυάδας γὰρ δὴ καὶ Ἐπιμηλιάδας, τὰς δὲ αὐτῶν ἐκάλουν Ναΐδας, καὶ Ὁμήρῳ γε ἐν τοῖς ἔπεσι Ναΐδων νυμφῶν μάλιστά ἐστι μνήμη. τὴν δὲ νύμφην ταύτην καλοῦσιν Ἐρατώ, καὶ ἐκ ταύτης φασὶν Ἀρκάδι Ἀζᾶνα καὶ Ἀφείδαντα γενέσθαι καὶ Ἔλατον·", "st": "8.4"}, {"sp": "N", "t": "ἐγεγόνει δὲ αὐτῷ πρότερον ἔτι Αὐτόλαος νόθος. τοῖς δὲ παισίν, ὡς ηὐξήθησαν, διένειμεν Ἀρκὰς τριχῇ τὴν χώραν, καὶ ἀπὸ μὲν Ἀζᾶνος ἡ Ἀζανία μοῖρα ὠνομάσθη· παρὰ τούτων δὲ ἀποικισθῆναι λέγουσιν, ὅσοι περὶ τὸ ἄντρον ἐν Φρυγίᾳ τὸ καλούμενον Στεῦνος καὶ Πέγκαλαν ποταμὸν οἰκοῦσιν. Ἀφείδας δὲ Τεγέαν καὶ τὴν προσεχῆ ταύτης ἔλαχεν· ἐπὶ τούτῳ δὲ καὶ ποιηταὶ καλοῦσιν Ἀφειδάντειον κλῆρον τὴν Τεγέαν.", "st": "8.4"}, {"sp": "N", "t": "Ἔλατος δὲ ἔσχε τὸ ὄρος τὴν Κυλλήνην, ἔτι τότε οὖσαν ἀνώνυμον· χρόνῳ δὲ ὕστερον μετῴκησεν ὁ Ἔλατος ἐς τὴν νῦν καλουμένην Φωκίδα, καὶ τοῖς τε Φωκεῦσιν ἤμυνεν ὑπὸ Φλεγυῶν πολέμῳ πιεζομένοις καὶ Ἐλατείας πόλεως ἐγένετο οἰκιστής. παῖδα δὲ Ἀζᾶνι μὲν Κλείτορα, Ἀφείδαντι δὲ Ἄλεον, Ἐλάτῳ δέ φασιν εἶναι πέντε, Αἴπυτον Περέα Κυλλῆνα Ἴσχυν Στύμφηλον.", "st": "8.4"}, {"sp": "N", "t": "ἐπὶ δὲ Ἀζᾶνι τῷ Ἀρκάδος τελευτήσαντι ἆθλα ἐτέθη πρῶτον· εἰ μὲν καὶ ἄλλα, οὐκ οἶδα, ἱπποδρομίας δὲ ἐτέθη. Κλείτωρ μὲν δὴ ὁ Ἀζᾶνος ἐν Λυκοσώρᾳ τε ᾤκει καὶ ἦν τῶν βασιλέων δυνατώτατος καὶ Κλείτορα ᾤκισεν ἀφ’ αὑτοῦ πόλιν, Ἄλεος δὲ εἶχε τὴν πατρῴαν λῆξιν·", "st": "8.4"}, {"sp": "N", "t": "ἀπὸ δὲ Ἐλάτου τῶν παίδων Κυλλήνην τὸ ὄρος καλοῦσιν ἀπὸ Κυλλῆνος, καὶ ἀπὸ Στυμφήλου πηγή τε ὀνομάζεται καὶ πόλις Στύμφηλος ἐπὶ τῇ πηγῇ. τὰ δὲ ἐς τὸν θάνατον Ἴσχυος τοῦ Ἐλάτου πρότερον ἔτι ἐν τῇ συγγραφῇ τῇ Ἀργολίδι ἐδήλωσα. παῖδα δὲ Περεῖ ἄρρενα μέν φασιν οὐδένα, Νέαιραν δὲ γενέσθαι θυγατέρα· ταύτην γυναῖκα ἔσχεν Αὐτόλυκος, οἰκῶν μὲν ἐν τῷ ὄρει τῷ Παρνασσῷ, λεγόμενος δὲ Ἑρμοῦ παῖς εἶναι, Δαιδαλίωνος δὲ ὢν τῷ ἀληθεῖ λόγῳ.", "st": "8.4"}, {"sp": "N", "t": "Κλείτορι δὲ τῷ Ἀζᾶνος οὐ γενομένων παίδων, ἐς Αἴπυτον Ἐλάτου περιεχώρησεν ἡ Ἀρκάδων βασιλεία· τὸν δὲ Αἴπυτον ἐξελθόντα ἐς ἄγραν θηρίων μὲν τῶν ἀλκιμωτέρων οὐδέν, σὴψ δὲ οὐ προϊδόμενον ἀποκτίννυσι. τὸν δὲ ὄφιν τοῦτον καὶ αὐτός ποτε εἶδον· κατὰ ἔχιν ἐστὶ τὸν μικρότατον, τέφρᾳ ἐμφερής, στίγμασιν οὐ συνεχέσι πεποικιλμένος· κεφαλὴ δέ ἐστιν αὐτῷ πλατεῖα καὶ τράχηλος στενός, γαστέρα δὲ ἔχει μείζονα καὶ οὐρὰν βραχεῖαν· βαδίζει δὲ οὗτός τε καὶ ὄφις ἕτερος ὁ κεράστης καλούμενος ἐνδιδόντες ἐς τὰ πλάγια, ὥσπερ οἱ καρκίνοι.", "st": "8.4"}, {"sp": "N", "t": "μετὰ δὲ Αἴπυτον ἔσχεν Ἄλεος τὴν ἀρχήν· Ἀγαμήδης μὲν γὰρ καὶ Γόρτυς οἱ Στυμφήλου τέταρτον γένος ἦσαν ἀπὸ Ἀρκάδος, Ἄλεος δὲ τρίτον ὁ Ἀφείδαντος. Ἄλεος δὲ τῇ τε Ἀθηνᾷ τῇ Ἀλέᾳ τὸ ἱερὸν ᾠκοδόμησεν ἐν Τεγέᾳ τὸ ἀρχαῖον καὶ αὐτῷ κατεσκεύαστο αὐτόθι ἡ βασιλεία· Γόρτυς δὲ ὁ Στυμφήλου πόλιν Γόρτυνα ᾤκισεν ἐπὶ ποταμῷ· καλεῖται δὲ Γορτύνιος καὶ ὁ ποταμός. Ἀλέῳ δὲ ἄρσενες μὲν παῖδες Λυκοῦργός τε καὶ Ἀμφιδάμας καὶ Κηφεύς, θυγάτηρ δὲ ἐγένετο Αὔγη.", "st": "8.4"}, {"sp": "N", "t": "ταύτῃ τῇ Αὔγῃ τῷ Ἑκαταίου λόγῳ συνεγίνετο Ἡρακλῆς, ὁπότε ἀφίκοιτο ἐς Τεγέαν· τέλος δὲ καὶ ἐφωράθη τετοκυῖα ἐκ τοῦ Ἡρακλέους, καὶ αὐτὴν ὁ Ἄλεος ἐσθέμενος ὁμοῦ τῷ παιδὶ ἐς λάρνακα ἀφίησεν ἐς θάλασσαν, καὶ ἡ μὲν ἀφίκετο ἐς Τεύθραντα δυνάστην ἄνδρα ἐν Καΐκου πεδίῳ καὶ συνῴκησεν ἐρασθέντι τῷ Τεύθραντι· καὶ νῦν ἔστι μὲν Αὔγης μνῆμα ἐν Περγάμῳ τῇ ὑπὲρ τοῦ Καΐκου, γῆς χῶμα λίθου περιεχόμενον κρηπῖδι, ἔστι δὲ ἐν τῷ μνήματι ἐπίθημα χαλκοῦ πεποιημένον, γυνὴ γυμνή.", "st": "8.4"}, {"sp": "N", "t": "μετὰ δὲ Ἄλιον τελευτήσαντα Λυκοῦργος ὁ Ἀλέου τὴν βασιλείαν πρεσβεῖα ἔσχε· παρέσχετο δὲ ἐς μνήμην Ἀρηίθοον ἄνδρα πολεμικὸν δόλῳ καὶ οὐ σὺν τῷ δικαίῳ κτείνας. γενομένων δὲ αὐτῷ παίδων Ἀγκαίου τε καὶ Ἐπόχου, τὸν μὲν νοσήσαντα ἐπιλαμβάνει τὸ χρεών, Ἀγκαῖος δὲ Ἰάσονί τε τοῦ πλοῦ μετέσχεν ἐς Κόλχους καὶ ὕστερον ὁμοῦ Μελεάγρῳ τὸ ἐν Καλυδῶνι κατεργαζόμενος θηρίον ἀπέθανεν ὑπὸ τοῦ ὑός. Λυκοῦργος μὲν δὴ πορρωτάτω γήρως ἀφίκετο ἐπιδὼν τοὺς παῖδας ἀμφοτέρους τελευτήσαντας·", "st": "8.4"}, {"sp": "N", "t": "Λυκούργου δὲ ἀποθανόντος Ἔχεμος ὁ Ἀερόπου τοῦ Κηφέως τοῦ Ἀλέου τὴν Ἀρκάδων ἔσχεν ἀρχήν. ἐπὶ τούτου Δωριεῖς κατιόντας ἐς Πελοπόννησον ὑπὸ ἡγεμόνι Ὕλλῳ τῷ Ἡρακλέους Ἀχαιοὶ περὶ ἰσθμὸν τὸν Κορινθίων κρατοῦσι μάχῃ, καὶ Ἔχεμος ἀποκτίννυσιν Ὕλλον μονομαχήσαντά οἱ κατὰ πρόκλησιν. τάδε γὰρ ἐφαίνετο εἰκότα εἶναί μοι μᾶλλον ἢ ὁ πρότερος λόγος, ἐν ᾧ βασιλεύειν τε Ἀχαιῶν τηνικαῦτα Ὀρέστην ἔγραψα καὶ Ὕλλον [καὶ] Ὀρέστου βασιλεύοντος ἀποπειρᾶσαι καθόδου τῆς ἐς Πελοπόννησον. φαίνοιτο δ’ ἂν τῷ ὑστέρῳ τῶν λόγων καὶ Τιμάνδρα συνοικήσασα ἡ Τυνδάρεω τῷ ἀποκτείναντι Ὕλλον Ἐχέμῳ.", "st": "8.5"}, {"sp": "N", "t": "Ἀγαπήνωρ δὲ ὁ Ἀγκαίου τοῦ Λυκούργου μετὰ Ἔχεμον βασιλεύσας ἐς Τροίαν ἡγήσατο Ἀρκάσιν. Ἰλίου δὲ ἁλούσης ὁ τοῖς Ἕλλησι κατὰ τὸν πλοῦν τὸν οἴκαδε ἐπιγενόμενος χειμὼν Ἀγαπήνορα καὶ τὸ Ἀρκάδων ναυτικὸν κατήνεγκεν ἐς Κύπρον, καὶ Πάφου τε Ἀγαπήνωρ ἐγένετο οἰκιστὴς καὶ τῆς Ἀφροδίτης κατεσκευάσατο ἐν Παλαιπάφῳ τὸ ἱερόν· τέως δὲ ἡ θεὸς παρὰ Κυπρίων τιμὰς εἶχεν ἐν Γολγοῖς καλουμένῳ χωρίῳ.", "st": "8.5"}, {"sp": "N", "t": "χρόνῳ δὲ ὕστερον Λαοδίκη γεγονυῖα ἀπὸ Ἀγαπήνορος ἔπεμψεν ἐς Τεγέαν τῇ Ἀθηνᾷ τῇ Ἀλέᾳ πέπλον· τὸ δὲ ἐπὶ τῷ ἀναθήματι ἐπίγραμμα καὶ αὐτῆς Λαοδίκης ἅμα ἐδήλου τὸ γένος·<br>Λαοδίκης ὅδε πέπλος· ἑᾷ δ’ ἀνέθηκεν Ἀθηνᾷ<br>πατρίδ’ ἐς εὐρύχορον Κύπρου ἀπὸ ζαθέας.<br>Ἀγαπήνορος δὲ οὐκ ἀνασωθέντος οἴκαδε ἐξ Ἰλίου,", "st": "8.5"}, {"sp": "N", "t": "παρέλαβε τὴν ἀρχὴν Ἱππόθους Κερκυόνος τοῦ Ἀγαμήδους τοῦ Στυμφήλου. καὶ τῷ μὲν ἐπιφανὲς συμβῆναι παρὰ τὸν βίον φασὶν οὐδέν, πλὴν ὅσον οὐκ ἐν Τεγέᾳ τὴν βασιλείαν κατεστήσατο ἀλλὰ ἐν Τραπεζοῦντι· Αἴπυτος δὲ ὁ Ἱππόθου μετὰ τὸν πατέρα ἔσχε τὴν ἀρχήν, καὶ Ὀρέστης ὁ Ἀγαμέμνονος κατὰ μαντείαν τοῦ ἐν Δελφοῖς Ἀπόλλωνος μετῴκησεν ἐς Ἀρκαδίαν ἐκ Μυκηνῶν.", "st": "8.5"}, {"sp": "N", "t": "Αἰπύτῳ δὲ τῷ Ἱππόθου παρελθεῖν ἐς τὸ ἱερὸν τοῦ Ποσειδῶνος τὸ ἐν Μαντινείᾳ τολμήσαντι— ἔσοδος δὲ ἀνθρώποις οὔτε τότε ἐς αὐτὸ ἦν οὔτε ἄχρι ἡμῶν ἔστιν—, ἐς τοῦτο ἐσελθόντι τυφλωθῆναι καὶ οὐ μετὰ πολὺ τῆς συμφορᾶς τελευτῆσαί οἱ τὸν βίον ἐγένετο.", "st": "8.5"}, {"sp": "N", "t": "Κυψέλου δὲ τοῦ Αἰπύτου βασιλεύοντος μετὰ Αἴπυτον, ὁ Δωριέων στόλος οὐ διὰ τοῦ Κορινθίων ἰσθμοῦ, καθὰ ἐπὶ τρεῖς τὰς πρότερον γενεάς, ναυσὶ δὲ κατὰ τὸ ὀνομαζόμενον Ῥίον κάτεισιν ἐς Πελοπόννησον· πυνθανόμενός τε ⟨τὰ⟩ ἐς αὐτοὺς ὁ Κύψελος, ὃν τῶν Ἀριστομάχου παίδων οὐκ ἔχοντά πω γυναῖκα εὕρισκε, τούτῳ τὴν θυγατέρα ἐκδοὺς καὶ οἰκειωσάμενος τὸν Κρεσφόντην αὐτός τε καὶ οἱ Ἀρκάδες ἐκτὸς ἑστήκεσαν δείματος.", "st": "8.5"}, {"sp": "N", "t": "Ὁλαίας δὲ ἦν Κυψέλου παῖς, ὃς καὶ τῆς ἀδελφῆς τὸν παῖδα Αἴπυτον, σὺν δὲ αὐτῷ καὶ οἱ ἐκ Λακεδαίμονος καὶ Ἄργους Ἡρακλεῖδαι κατάγουσιν ἐς Μεσσήνην. τοῦ δὲ ἦν Βουκολίων, τοῦ δὲ Φίαλος, ὃς τὸν Λυκάονος Φίγαλον οἰκιστὴν ὄντα ἀφελόμενος τὴν τιμὴν Φιαλίαν τὸ ὄνομα τῇ πόλει μετέθετο ἀφ’ ἑαυτοῦ· οὐ μὴν καὶ ἐς ἅπαν γε ἐξενίκησεν.", "st": "8.5"}, {"sp": "N", "t": "ἐπὶ δὲ Σίμου τοῦ Φιάλου βασιλεύοντος ἠφανίσθη Φιγαλεῦσιν ὑπὸ πυρὸς τῆς Μελαίνης Δήμητρος τὸ ἀρχαῖον ξόανον· ἐσήμαινε δὲ ἄρα οὐ μετὰ πολὺ ἔσεσθαι καὶ αὐτῷ Σίμῳ τοῦ βίου τὴν τελευτήν. Πόμπου δὲ ἐκδεξαμένου τοῦ Σίμου τὴν ἀρχήν, Αἰγινῆται κατὰ ἐμπορίαν ἐσέπλεον ναυσὶν ἐς Κυλλήνην, ἐκεῖθεν δὲ ὑποζυγίοις τὰ φορτία ἀνῆγον παρὰ τοὺς Ἀρκάδας. ἀντὶ τούτου ἐτίμησεν ὁ Πόμπος μεγάλως, καὶ δὴ καὶ ὄνομα Αἰγινήτην τῷ παιδὶ ἔθετο ἐπὶ τῶν Αἰγινητῶν τῇ φιλίᾳ.", "st": "8.5"}, {"sp": "N", "t": "μετὰ δὲ Αἰγινήτην Πολυμήστωρ ἐγένετο ⟨ὁ⟩ Αἰγινήτου βασιλεὺς Ἀρκάδων, καὶ Λακεδαιμόνιοι καὶ Χάριλλος πρῶτον τότε ἐς τὴν Τεγεατῶν ἐσβάλλουσι στρατιᾷ· καὶ σφᾶς αὐτοί τε οἱ Τεγεᾶται καὶ γυναῖκες ὅπλα ἐνδῦσαι μάχῃ νικῶσι, καὶ τόν τε ἄλλον στρατὸν καὶ αὐτὸν Χάριλλον ζῶντα αἱροῦσι. Χαρίλλου μὲν δὴ καὶ τῆς σὺν αὐτῷ στρατιᾶς ἐς πλέον μνήμην ποιησόμεθα ἐν τοῖς Τεγεατικοῖς·", "st": "8.5"}, {"sp": "N", "t": "Πολυμήστορι δὲ οὐ γενομένων παίδων παρέλαβεν Αἶχμις τὴν ἀρχήν, Βριάκα μὲν παῖς, Πολυμήστορος δὲ ἀδελφιδοῦς· Αἰγινήτου γὰρ ἦν καὶ Βριάκας, νεώτερος δὲ ἦν Πολυμήστορος. Αἴχμιδος δὲ βασιλεύσαντος Λακεδαιμονίοις ἐγένετο ὁ πρὸς Μεσσηνίους πόλεμος· τοῖς δὲ Ἀρκάσιν ὑπῆρχε μὲν ἐς τοὺς Μεσσηνίους εὔνοια ἐξ ἀρχῆς, τότε δὲ καὶ ἐκ τοῦ φανεροῦ πρὸς Λακεδαιμονίους ἐμαχέσαντο μετὰ Ἀριστοδήμου βασιλεύοντος ἐν Μεσσήνῃ.", "st": "8.5"}, {"sp": "N", "t": "Ἀριστοκράτης δὲ ὁ Αἴχμιδος τάχα μέν που καὶ ἄλλα ἐς τοὺς Ἀρκάδας ὕβρισεν· ἃ δὲ ἀνοσιώτατα ἔργων ἐς θεοὺς ἐργασάμενον οἶδα αὐτόν, ἐπέξεισί μοι ταῦτα ὁ λόγος. ἔστιν Ἀρτέμιδος ἱερὸν Ὑμνίας ἐπίκλησιν. τοῦτο ἐν ὅροις μέν ἐστιν Ὀρχομενίων, πρὸς δὲ τῇ Μαντινικῇ· σέβουσιν ἐκ παλαιοτάτου καὶ οἱ πάντες Ἀρκάδες Ὑμνίαν Ἄρτεμιν. ἐλάμβανε δὲ τὴν ἱερωσύνην τῆς θεοῦ τότε ἔτι κόρη παρθένος.", "st": "8.5"}, {"sp": "N", "t": "Ἀριστοκράτης δέ, ὥς οἱ πειρῶντι τὴν παρθένον ἀντέβαινεν ἀεὶ τὰ παρ’ αὐτῆς, τέλος καταφυγοῦσαν ἐς τὸ ἱερὸν παρὰ τῇ Ἀρτέμιδι ᾔσχυνεν. ὡς δὲ ἐς ἅπαντας ἐξηγγέλθη τὸ τόλμημα, τὸν μὲν καταλιθοῦσιν οἱ Ἀρκάδες, μετεβλήθη δὲ ἐξ ἐκείνου καὶ ὁ νόμος· ἀντὶ γὰρ παρθένου διδόασι τῇ Ἀρτέμιδι ἱέρειαν γυναῖκα ὁμιλίας ἀνδρῶν ἀποχρώντως ἔχουσαν.", "st": "8.5"}, {"sp": "N", "t": "τούτου δὲ υἱὸς ἐγένετο Ἱκέτας, Ἱκέτα δὲ Ἀριστοκράτης ἄλλος ὁμώνυμός τε τῷ προγόνῳ καὶ δὴ καὶ τοῦ βίου τὴν αὐτὴν ἔσχεν ἐκείνῳ τελευτήν· κατελίθωσαν γὰρ καὶ τοῦτον οἱ Ἀρκάδες, φωράσαντες δῶρα ἐκ Λακεδαίμονος εἰληφότα καὶ Μεσσηνίοις τὸ ἐπὶ τῇ Μεγάλῃ τάφρῳ πταῖσμα προδοσίαν τοῦ Ἀριστοκράτους οὖσαν. αὕτη δὲ ἡ ἀδικία καὶ τῷ γένει τῷ ἀπὸ Κυψέλου παντὶ παρέσχεν αἰτίαν παυσθῆναι τῆς ἀρχῆς.", "st": "8.5"}, {"sp": "N", "t": "τὰ μὲν δὴ ἐς τοὺς βασιλεῖς πολυπραγμονήσαντί μοι κατὰ ταῦτα ἐγενεαλόγησαν οἱ Ἀρκάδες· κοινῇ δὲ Ἀρκάσιν ὑπῆρχεν ἐς μνήμην τὰ μὲν ἀρχαιότατα ὁ πρὸς Ἰλίῳ πόλεμος, δεύτερα δὲ ὁπόσα ἀμύνοντες Μεσσηνίοις Λακεδαιμονίων ἐναντία ἐμαχέσαντο· μέτεστι δὲ καὶ πρὸς Μήδους σφίσιν ἔργου τοῦ ἐν Πλαταιαῖς.", "st": "8.6"}, {"sp": "N", "t": "Λακεδαιμονίοις δὲ ἀνάγκῃ πλέον καὶ οὐ μετ’ εὐνοίας ἐπί τε Ἀθηναίους συνεστρατεύσαντο καὶ ἐς τὴν Ἀσίαν μετὰ Ἀγησιλάου διέβησαν, καὶ δὴ καὶ ἐς Λεῦκτρα αὐτοῖς τὰ Βοιωτικὰ ἠκολούθησαν. τὸ δὲ ὕποπτον τὸ ἐς τοὺς Λακεδαιμονίους ἀλλαχοῦ τε ἐπεδείξαντο καὶ μετὰ τὸ ἀτύχημα Λακεδαιμονίων τὸ ἐν Λεύκτροις παρὰ Θηβαίους αὐτίκα ἀπ’ αὐτῶν μετέστησαν. Φιλίππῳ δὲ καὶ Μακεδόσιν ἐν Χαιρωνείᾳ καὶ ὕστερον ἐν Θεσσαλίᾳ πρὸς Ἀντίπατρον οὐκ ἐμαχέσαντο μετὰ Ἑλλήνων, οὐ μὴν οὐδὲ τοῖς Ἕλλησιν ἐναντία ἐτάξαντο.", "st": "8.6"}, {"sp": "N", "t": "πρὸς Γαλάτας δὲ τοῦ ἐν Θερμοπύλαις κινδύνου φασὶ Λακεδαιμονίων ἕνεκα οὐ μετασχεῖν, ἵνα μή σφισιν οἱ Λακεδαιμόνιοι κακουργοῖεν τὴν γῆν ἀπόντων τῶν ἐν ἡλικίᾳ· συνεδρίου δὲ τῶν Ἀχαιῶν μετέσχον οἱ Ἀρκάδες προθυμότατα Ἑλλήνων. ὁπόσα δὲ αὐτοῖς οὐχὶ ἐν κοινῷ, κατὰ πόλεις δὲ ἰδίᾳ συμβεβηκότα εὕρισκον, ἀποθησόμεθα αὐτῶν ἕκαστον ἐς τὸ οἰκεῖον τοῦ λόγου.", "st": "8.6"}, {"sp": "N", "t": "εἰσὶν οὖν ἐς Ἀρκαδίαν ἐσβολαὶ κατὰ τὴν Ἀργείαν πρὸς μὲν Ὑσιῶν καὶ ὑπὲρ τὸ ὄρος τὸ Παρθένιον ἐς τὴν Τεγεατικήν, δύο δὲ ἄλλαι κατὰ Μαντίνειαν διά τε Πρίνου καλουμένης καὶ διὰ Κλίμακος. αὕτη δὲ εὐρυτέρα τέ ἐστι καὶ ἡ κάθοδος εἶχεν αὕτη βασμίδας ποτὲ ἐμπεποιημένας· ὑπερβαλόντων δὲ τὴν Κλίμακα χωρίον ἐστὶν ὀνομαζόμενον Μελαγγεῖα, καὶ τὸ ὕδωρ αὐτόθεν τὸ πότιμον Μαντινεῦσι κάτεισιν ἐς τὴν πόλιν.", "st": "8.6"}, {"sp": "N", "t": "προελθόντι δὲ ἐκ τῶν Μελαγγείων, ἀπέχοντι τῆς πόλεως στάδια ὡς ἑπτὰ ἔστι κρήνη καλουμένη Μελιαστῶν· οἱ Μελιασταὶ δὲ οὗτοι δρῶσι τὰ ὄργια τοῦ Διονύσου, καὶ Διονύσου τε μέγαρον πρὸς τῇ κρήνῃ καὶ Ἀφροδίτης ἐστὶν ἱερὸν Μελαινίδος. ἐπίκλησιν δὲ ἡ θεὸς ταύτην κατ’ ἄλλο μὲν ἔσχεν οὐδέν, ὅτι δὲ ἀνθρώπων μὴ τὰ πάντα αἱ μίξεις ὥσπερ τοῖς κτήνεσι μεθ’ ἡμέραν, τὰ πλείω δέ εἰσιν ἐν νυκτί.", "st": "8.6"}, {"sp": "N", "t": "ἡ δὲ ὑπολειπομένη τῶν ὁδῶν στενωτέρα ἐστὶ τῆς προτέρας καὶ ἄγει διὰ τοῦ Ἀρτεμισίου. τούτου δὲ ἐπεμνήσθην καὶ ἔτι πρότερον τοῦ ὄρους, ὡς ἔχοι μὲν ναὸν καὶ ἄγαλμα Ἀρτέμιδος, ἔχοι δὲ καὶ τοῦ Ἰνάχου τὰς πηγάς. ὁ δὲ Ἴναχος ἐφ’ ὅσον μὲν πρόεισι κατὰ τὴν ὁδὸν τὴν διὰ τοῦ ὄρους, τοῦτό ἐστιν Ἀργείοις καὶ Μαντινεῦσιν ὅρος τῆς χώρας· ἀποστρέψας δὲ ἐκ τῆς ὁδοῦ τὸ ὕδωρ διὰ τῆς Ἀργείας ἤδη τὸ ἀπὸ τούτου κάτεισι, καὶ ἐπὶ τούτῳ τὸν Ἴναχον ἄλλοι τε καὶ Αἰσχύλος ποταμὸν καλοῦσιν Ἀργεῖον.", "st": "8.6"}, {"sp": "N", "t": "ὑπερβαλόντα δὲ ἐς τὴν Μαντινικὴν διὰ τοῦ Ἀρτεμισίου πεδίον ἐκδέξεταί σε Ἀργὸν καλούμενον, καθάπερ γε καὶ ἔστι· τὸ γὰρ ὕδωρ τὸ ἐκ τοῦ θεοῦ κατερχόμενον ἐς αὐτὸ ἐκ τῶν ὀρῶν ἀργὸν εἶναι τὸ πεδίον ποιεῖ, ἐκώλυέ τε οὐδὲν ἂν τὸ πεδίον τοῦτο εἶναι λίμνην, εἰ μὴ τὸ ὕδωρ ἠφανίζετο ἐς χάσμα γῆς.", "st": "8.7"}, {"sp": "N", "t": "ἀφανισθὲν δὲ ἐνταῦθα ἄνεισι κατὰ τὴν Δίνην· ἔστι δὲ ἡ Δίνη κατὰ τὸ Γενέθλιον καλούμενον τῆς Ἀργολίδος, ὕδωρ γλυκὺ ἐκ θαλάσσης ἀνερχόμενον. τὸ δὲ ἀρχαῖον καὶ καθίεσαν ἐς τὴν Δίνην τῷ Ποσειδῶνι ἵππους οἱ Ἀργεῖοι κεκοσμημένους χαλινοῖς. γλυκὺ δὲ ὕδωρ ἐν θαλάσσῃ δῆλόν ἐστιν ἐνταῦθά τε ἀνιὸν ⟨ἐν⟩ τῇ Ἀργολίδι καὶ ἐν τῇ Θεσπρωτίδι κατὰ τὸ Χειμέριον καλούμενον.", "st": "8.7"}, {"sp": "N", "t": "θαύματος δὲ ἔτι πλέονός ἐστιν ἐν Μαιάνδρῳ ζέον ὕδωρ, τὸ μὲν ἐκ πέτρας, περιέχοντος τοῦ ῥεύματος τὴν πέτραν, τὸ δὲ καὶ ἐκ τῆς ἰλύος ἄνεισι τοῦ ποταμοῦ. πρὸ Δικαιαρχίας δὲ τῆς Τυρσηνῶν ὕδωρ τε ἐν θαλάσσῃ ζέον καὶ νῆσος δι’ αὐτό ἐστι χειροποίητος, ὡς μηδὲ τοῦτο τὸ ὕδωρ ἀργὸν ⟨εἶναι⟩ ἀλλά σφισι λουτρὰ θερμά.", "st": "8.7"}, {"sp": "N", "t": "τοῦ δὲ Ἀργοῦ καλουμένου πεδίου Μαντινεῦσιν ὄρος ἐστὶν ἐν ἀριστερᾷ, σκηνῆς τε Φιλίππου τοῦ Ἀμύντου καὶ κώμης ἐρείπια ἔχον Νεστάνης· πρὸς ταύτῃ γὰρ στρατοπεδεύσασθαι τῇ Νεστάνῃ Φίλιππον λέγουσι καὶ τὴν πηγὴν αὐτόθι ὀνομάζουσιν ἔτι ἀπὸ ἐκείνου Φιλίππιον. ἀφίκετο δὲ ἐς Ἀρκαδίαν Φίλιππος οἰκειωσόμενός τε Ἀρκάδας καὶ ἀπὸ τοῦ Ἑλληνικοῦ σφᾶς τοῦ ἄλλου διαστήσων.", "st": "8.7"}, {"sp": "N", "t": "Φίλιππον δὲ βασιλέων μὲν τῶν πρὸ αὐτοῦ καὶ ὅσοι Μακεδόσι γεγόνασιν ὕστερον, τούτων μὲν πείθοιτο ἄν τις μέγιστα αὐτὸν ἔργα ἐπιδείξασθαι· στρατηγὸν δὲ ἀγαθὸν οὐκ ἄν τις φρονῶν ὀρθὰ καλέσειεν αὐτόν, ὅς γε καὶ ὅρκους θεῶν κατεπάτησεν ἀεὶ καὶ σπονδὰς ἐπὶ παντὶ ἐψεύσατο πίστιν τε ἠτίμασε μάλιστα ἀνθρώπων.", "st": "8.7"}, {"sp": "N", "t": "καί οἱ τὸ ἐκ τοῦ θεοῦ μήνιμα ἀπήντησεν οὐκ ὀψέ, πρῶτα δὲ ὧν ἴσμεν. Φίλιππος μὲν οὐ πρόσω βιώσας ἕξ τε καὶ τεσσαράκοντα ἐτῶν τὸ μάντευμα ἐξετέλεσε τὸ ἐκ Δελφῶν, ὃ δὴ χρωμένῳ οἱ περὶ τοῦ Πέρσου γενέσθαι λέγουσιν,<br>ἔστεπται μὲν ὁ ταῦρος, ἔχει τέλος, ἔστιν ὁ θύσων·<br>τοῦτο μὲν δὴ οὐ μετὰ πολὺ ἐδήλωσεν οὐκ ἐς τὸν Μῆδον, ἀλλὰ ἐς αὐτὸν ἔχον Φίλιππον·", "st": "8.7"}, {"sp": "N", "t": "ἐπὶ δὲ Φιλίππῳ τελευτήσαντι Φιλίππου παῖδα νήπιον, γεγονότα δὲ ἐκ Κλεοπάτρας ἀδελφιδῆς Ἀττάλου, τοῦτον τὸν παῖδα ὁμοῦ τῇ μητρὶ Ὀλυμπιὰς ἐπὶ σκεύους χαλκοῦ πυρὸς ὑποβεβλημένου διέφθειρεν ἕλκουσα· χρόνῳ δὲ ὕστερον καὶ Ἀριδαῖον ἀπέκτεινεν. ἔμελλε δὲ ἄρα ὁ δαίμων καὶ τὸ γένος τὸ Κασσάνδρου κακῶς ἐξαμήσειν· Κασσάνδρῳ δὲ οἱ παῖδες ἐκ Θεσσαλονίκης γεγόνασι τῆς Φιλίππου, Θεσσαλονίκῃ δὲ ἦσαν καὶ Ἀριδαίῳ μητέρες Θεσσαλαί. τὰ δὲ ἐς Ἀλέξανδρον καὶ τοῖς πᾶσιν ὁμοίως δῆλά ἐστιν [Ἀλεξάνδρου θάνατος]·", "st": "8.7"}, {"sp": "N", "t": "εἰ δὲ τῶν ἐς Γλαῦκον τὸν Σπαρτιάτην ἐποιήσατο ὁ Φίλιππος λόγον καὶ τὸ ἔπος ἐφ’ ἑκάστου τῶν ἔργων ἀνεμίμνησκεν αὑτόν,<br>ἀνδρὸς δ’ εὐόρκου γενεὴ μετόπισθεν ἀρείων,<br>οὐκ ἂν οὕτω δίχα λόγου δοκεῖ μοι θεῶν τις Ἀλεξάνδρου τε ὁμοῦ τὸν βίον καὶ ἀκμὴν τὴν Μακεδόνων σβέσαι.", "st": "8.7"}, {"sp": "N", "t": "τόδε μὲν ἡμῖν ἐγένετο ἐπεισόδιον τῷ λόγῳ· μετὰ δὲ τὰ ἐρείπια τῆς Νεστάνης ἱερὸν Δήμητρός ἐστιν ἅγιον, καὶ αὐτῇ καὶ ἑορτὴν ἀνὰ πᾶν ἔτος ἄγουσιν οἱ Μαντινεῖς. καὶ κατὰ τὴν Νεστάνην ὑπόκειται μάλιστα …, μοῖρα μὲν καὶ αὐτὴ τοῦ πεδίου τοῦ Ἀργοῦ, χορὸς δὲ ὀνομάζεται Μαιρᾶς. τοῦ πεδίου δέ ἐστιν ἡ διέξοδος τοῦ Ἀργοῦ σταδίων δέκα. ὑπερβὰς δὲ οὐ πολὺ ἐς ἕτερον καταβήσῃ πεδίον· ἐν τούτῳ δὲ παρὰ τὴν λεωφόρον ἐστὶν Ἄρνη καλουμένη κρήνη.", "st": "8.8"}, {"sp": "N", "t": "λέγεται δὲ καὶ τοιάδε ὑπὸ Ἀρκάδων, Ῥέα ἡνίκα Ποσειδῶνα ἔτεκε, τὸν μὲν ἐς ποίμνην καταθέσθαι δίαιταν ἐνταῦθα ἕξοντα μετὰ τῶν ἀρνῶν, ἐπὶ τούτῳ δὲ ὀνομασθῆναι καὶ τὴν πηγήν, ὅτι περὶ αὐτὴν ἐποιμαίνοντο οἱ ἄρνες· φάναι δὲ αὐτὴν πρὸς τὸν Κρόνον τεκεῖν ἵππον καί οἱ πῶλον ἵππου καταπιεῖν ἀντὶ τοῦ παιδὸς δοῦναι, καθὰ καὶ ὕστερον ἀντὶ τοῦ Διὸς λίθον ἔδωκεν αὐτῷ κατειλημένον σπαργάνοις.", "st": "8.8"}, {"sp": "N", "t": "τούτοις Ἑλλήνων ἐγὼ τοῖς λόγοις ἀρχόμενος μὲν τῆς συγγραφῆς εὐηθίας ἔνεμον πλέον, ἐς δὲ τὰ Ἀρκάδων προεληλυθὼς πρόνοιαν περὶ αὐτῶν τοιάνδε ἐλάμβανον· Ἑλλήνων τοὺς νομιζομένους σοφοὺς δι’ αἰνιγμάτων πάλαι καὶ οὐκ ἐκ τοῦ εὐθέος λέγειν τοὺς λόγους, καὶ τὰ εἰρημένα οὖν ἐς τὸν Κρόνον σοφίαν εἶναί τινα εἴκαζον Ἑλλήνων. τῶν μὲν δὴ ἐς τὸ θεῖον ἡκόντων τοῖς εἰρημένοις χρησόμεθα·", "st": "8.8"}, {"sp": "N", "t": "Μαντινέων δὲ ἡ πόλις σταδίους μάλιστά που δώδεκά ἐστιν ἀπωτέρω τῆς πηγῆς ταύτης. Μαντινεὺς μὲν οὖν ὁ Λυκάονος ἑτέρωθι φαίνεται οἰκίσας τὴν πόλιν, ἣν ὀνομάζουσι καὶ ἐς ἡμᾶς ἔτι ⟨Πτόλιν⟩ οἱ Ἀρκάδες· ἐκεῖθεν δὲ Ἀντινόη Κηφέως τοῦ Ἀλέου θυγάτηρ κατὰ μάντευμα ἀναστήσασα τοὺς ἀνθρώπους ἤγαγεν ἐς τοῦτο τὸ χωρίον, ὄφιν—ὁποῖον, οὐ μνημονεύουσιν— ἡγεμόνα ποιησαμένη τῆς ὁδοῦ· καὶ διὰ τοῦτο ὁ παρὰ τὴν πόλιν ῥέων τὴν νῦν ποταμὸς Ὄφις ὄνομα ἔσχηκεν.", "st": "8.8"}, {"sp": "N", "t": "εἰ δὲ Ὁμήρου χρὴ τεκμαιρόμενον τοῖς ἔπεσι συμβαλέσθαι γνώμην, τὸν ὄφιν τοῦτον δράκοντα εἶναι πείθομαι. περὶ Φιλοκτήτου μὲν ἐν νεῶν καταλόγῳ ποιήσας ὡς ἀπολίποιεν αὐτὸν οἱ Ἕλληνες ἐν Λήμνῳ ταλαιπωροῦντα ὑπὸ τοῦ ἕλκους, ἐπίκλησιν [δὲ] οὐκ ἔθετο ὄφιν τῷ ὕδρῳ· τὸν δράκοντα δέ, ὃν ἐς τοὺς Τρῶας ἀφῆκεν ὁ ἀετός, ἐκάλεσεν ὄφιν. οὕτω τὸ εἰκὸς ἔχει καὶ τῇ Ἀντινόῃ τὸν ἡγεμόνα γενέσθαι δράκοντα.", "st": "8.8"}, {"sp": "N", "t": "Μαντινεῖς δὲ μάχην μὲν τὴν ἐν Διπαιεῦσιν οὐκ ἐμαχέσαντο πρὸς Λακεδαιμονίους μετὰ Ἀρκάδων τῶν ἄλλων, ἐν δὲ τῷ Πελοποννησίων καὶ Ἀθηναίων πολέμῳ συνέστησαν ἐπὶ Λακεδαιμονίους μετὰ Ἠλείων, καὶ παραγενομένου συμμαχικοῦ σφισιν ἐξ Ἀθηνῶν Λακεδαιμονίων ἐναντία ἐμαχέσαντο· μετέσχον δὲ καὶ τοῦ ἐς Σικελίαν στόλου κατὰ Ἀθηναίων φιλίαν.", "st": "8.8"}, {"sp": "N", "t": "χρόνῳ δὲ ὕστερον Λακεδαιμονίων στρατιὰ καὶ Ἀγησίπολις ὁ Παυσανίου βασιλεὺς ἐσέβαλον ἐς τὴν Μαντινικήν. ὡς δὲ ἐκράτησεν ὁ Ἀγησίπολις τῇ μάχῃ καὶ ἐς τὸ τεῖχος κατέκλεισε τοὺς Μαντινέας, εἷλεν οὐ μετὰ πολὺ τὴν πόλιν, οὐ πολιορκίᾳ κατὰ τὸ ἰσχυρόν, τὸν δὲ Ὄφιν ποταμὸν ἀποστρέψας σφίσιν ἐς τὸ τεῖχος ὠμῆς ᾠκοδομημένον τῆς πλίνθου.", "st": "8.8"}, {"sp": "N", "t": "ἐς μὲν δὴ μηχανημάτων ἐμβολὴν ἀσφάλειαν ἡ πλίνθος παρέχεται μᾶλλον ἢ ὁπόσα λίθου πεποιημένα ἐστίν· οἱ μὲν γὰρ κατάγνυνταί τε καὶ ἐκπηδῶσιν ἐκ τῶν ἁρμονιῶν, ἡ δὲ πλίνθος ἐκ μηχανημάτων μὲν οὐχ ὁμοίως πονεῖ, διαλύεται δὲ ὑπὸ τοῦ ὕδατος οὐχ ἧσσον ἢ ὑπὸ τοῦ ἡλίου κηρός.", "st": "8.8"}, {"sp": "N", "t": "τοῦτο οὐκ Ἀγησίπολις τὸ στρατήγημα ἐς τὸ τεῖχος τῶν Μαντινέων ἐστὶν ὁ συνείς, ἀλλὰ πρότερον ἔτι Κίμωνι ἐξευρέθη τῷ Μιλτιάδου Βόγην πολιορκοῦντι ἄνδρα Μῆδον καὶ ὅσοι Περσῶν Ἠιόνα τὴν ἐπὶ Στρυμόνι εἶχον· Ἀγησίπολις δὲ καθεστηκὸς καὶ ᾀδόμενον ὑπὸ Ἑλλήνων ἐμιμήσατο. ὡς δὲ εἷλε τὴν Μαντίνειαν, ὀλίγον μέν τι κατέλιπεν οἰκεῖσθαι, τὸ πλεῖστον δὲ ἐς ἔδαφος καταβαλὼν αὐτῆς κατὰ κώμας τοὺς ἀνθρώπους διῴκισε.", "st": "8.8"}, {"sp": "N", "t": "Μαντινέας δὲ ἐκ τῶν κωμῶν κατάξειν ἐς τὴν πατρίδα ἔμελλον Θηβαῖοι μετὰ τὸ ἔργον τὸ ἐν Λεύκτροις. κατελθόντες δὲ οὐ τὰ πάντα ἐγένοντο δίκαιοι· περιληφθέντες δὲ ἐπικηρυκευόμενοι Λακεδαιμονίοις καὶ εἰρήνην ἰδίᾳ πρὸς αὐτοὺς ἄνευ τοῦ Ἀρκάδων κοινοῦ πράσσοντες, οὕτω διὰ τὸ δέος τῶν Θηβαίων ἐς τὴν Λακεδαιμονίων συμμαχίαν μετεβάλοντο ἐκ τοῦ φανεροῦ, καὶ τῆς Μαντινικῆς πρὸς Ἐπαμινώνδαν καὶ Θηβαίους μάχης Λακεδαιμονίων γινομένης ὁμοῦ τοῖς Λακεδαιμονίοις ἐτάξαντο οἱ Μαντινεῖς.", "st": "8.8"}, {"sp": "N", "t": "τούτων δὲ ὕστερον διαφορὰ ἐγένετο Μαντινεῦσιν ἐς τοὺς Λακεδαιμονίους, καὶ ἀπ’ αὐτῶν μετέστησαν ἐς τὸ Ἀχαϊκόν· καὶ Ἆγιν τὸν Εὐδαμίδου βασιλεύοντα ἐν Σπάρτῃ νικῶσιν ἀμύνοντες τῇ σφετέρᾳ, νικῶσι δὲ προσλαβόντες Ἀχαιῶν στρατιὰν καὶ Ἄρατον ἡγεμόνα ἐπ’ αὐτῇ. μετέσχον δὲ καὶ πρὸς Κλεομένην τοῦ ἔργου τοῖς Ἀχαιοῖς καὶ συγκαθεῖλον Λακεδαιμονίων τὴν ἰσχύν. Ἀντιγόνου δὲ ἐν Μακεδονίᾳ Φίλιππον τὸν Περσέως πατέρα ἔτι παῖδα ἐπιτροπεύοντος καὶ Ἀχαιοῖς ἐς τὰ μάλιστα ὄντος ἐπιτηδείου, ἄλλα τε ἐς τιμὴν αὐτοῦ Μαντινεῦσιν ἐποιήθη καὶ ὄνομα τῇ πόλει μετέθεντο Ἀντιγόνειαν.", "st": "8.8"}, {"sp": "N", "t": "χρόνῳ δὲ ὕστερον Αὐγούστου πρὸς τῇ ἄκρᾳ τοῦ Ἀπόλλωνος τοῦ Ἀκτίου ναυμαχήσειν μέλλοντος Μαντινεῖς ἐμαχέσαντο ὁμοῦ Ῥωμαίοις, τὸ δὲ ἄλλο Ἀρκαδικὸν συνετάχθησαν Ἀντωνίῳ, κατ’ ἄλλο μὲν ἐμοὶ δοκεῖν οὐδέν, ὅτι δὲ ἐφρόνουν οἱ Λακεδαιμόνιοι τὰ Αὐγούστου. δέκα δὲ ὕστερον γενεαῖς ἐβασίλευσέ τε Ἀδριανὸς καὶ ἀφελὼν Μαντινεῦσι τὸ ὄνομα τὸ ἐκ Μακεδονίας ἐπακτὸν ἀπέδωκεν αὖθις Μαντίνειαν καλεῖσθαί σφισι τὴν πόλιν.", "st": "8.8"}, {"sp": "N", "t": "ἔστι δὲ Μαντινεῦσι ναὸς διπλοῦς μάλιστά που κατὰ μέσον τοίχῳ διειργόμενος· τοῦ ναοῦ δὲ τῇ μὲν ἄγαλμά ἐστιν Ἀσκληπιοῦ, τέχνη [δὲ] Ἀλκαμένους, τὸ δὲ ἕτερον Λητοῦς ἐστιν ἱερὸν καὶ τῶν παίδων· Πραξιτέλης δὲ τὰ ἀγάλματα εἰργάσατο τρίτῃ μετὰ Ἀλκαμένην ὕστερον γενεᾷ. τούτων πεποιημένα ἐστὶν ἐπὶ τῷ βάθρῳ Μοῦσαι καὶ Μαρσύας αὐλῶν. ἐνταῦθα ἀνὴρ ἐπείργασται στήλῃ Πολύβιος ὁ Λυκόρτα·", "st": "8.9"}, {"sp": "N", "t": "καὶ τοῦ μὲν ἐπιμνησθησόμεθα καὶ ἐν τοῖς ἔπειτα, Μαντινεῦσι δέ ἐστι καὶ ἄλλα ἱερά, τὸ μὲν Σωτῆρος Διός, τὸ δὲ Ἐπιδώτου καλουμένου· ἐπιδιδόναι γὰρ δὴ ἀγαθὰ αὐτὸν ἀνθρώποις. ἔστι δὲ καὶ Διοσκούρων καὶ ἑτέρωθι Δήμητρος καὶ Κόρης ἱερόν· πῦρ δὲ ἐνταῦθα καίουσι, ποιούμενοι φροντίδα μὴ λάθῃ σφίσιν ἀποσβεσθέν. καὶ Ἥρας πρὸς τῷ θεάτρῳ ναὸν ἐθεασάμην·", "st": "8.9"}, {"sp": "N", "t": "Πραξιτέλης δὲ τὰ ἀγάλματα αὐτήν τε καθημένην ἐν θρόνῳ καὶ παρεστώσας ἐποίησεν Ἀθηνᾶν καὶ Ἥβην παῖδα Ἥρας. πρὸς δὲ τῆς Ἥρας τῷ βωμῷ καὶ Ἀρκάδος τάφος τοῦ Καλλιστοῦς ἐστι· τὰ δὲ ὀστᾶ τοῦ Ἀρκάδος ἐπηγάγοντο ἐκ Μαινάλου, χρησμοῦ σφισιν ἐλθόντος ἐκ Δελφῶν·", "st": "8.9"}, {"sp": "N", "t": "ἔστι δὲ Μαιναλίη δυσχείμερος, ἔνθα τε κεῖται<br>Ἀρκάς, ἀφ’ οὗ δὴ πάντες ἐπίκλησιν καλέονται,<br>οὗ τρίοδος καὶ τετράοδος καὶ πεντακέλευθος.<br>ἔνθα σ’ ἐγὼ κέλομαι στείχειν καὶ ἐύφρονι θυμῷ<br>Ἀρκάδ’ ἀειραμένους κατάγειν εἰς ἄστυ ἐραννόν·<br>ἔνθα τε δὴ τέμενός τε θυηλάς τ’ Ἀρκάδι τεύχειν.<br>τὸ δὲ χωρίον τοῦτο, ἔνθα ὁ τάφος ἐστὶ τοῦ Ἀρκάδος, καλοῦσιν Ἡλίου βωμούς.", "st": "8.9"}, {"sp": "N", "t": "τοῦ θεάτρου δὲ οὐ πόρρω μνήματα προήκοντά ἐστιν ἐς δόξαν, τὸ μὲν Ἑστία καλουμένη κοινή, περιφερὲς σχῆμα ἔχουσα· Ἀντινόην δὲ αὐτόθι ἐλέγετο κεῖσθαι τὴν Κηφέως· τῷ δὲ στήλη τε ἐφέστηκε καὶ ἀνὴρ ἱππεὺς ἐπειργασμένος ἐστὶν ἐπὶ τῇ στήλῃ, Γρύλος ὁ Ξενοφῶντος.", "st": "8.9"}, {"sp": "N", "t": "τοῦ θεάτρου δὲ ὄπισθεν ναοῦ τε Ἀφροδίτης ἐπίκλησιν Συμμαχίας ἐρείπια καὶ ἄγαλμα ἐλείπετο· τὸ δὲ ἐπίγραμμα ⟨τὸ⟩ ἐπὶ τῷ βάθρῳ τὴν ἀναθεῖσαν τὸ ἄγαλμα ἐδήλου θυγατέρα εἶναι Πασέου Νικίππην. τὸ δὲ ἱερὸν κατεσκευάσαντο τοῦτο οἱ Μαντινεῖς ὑπόμνημα ἐς τοὺς ἔπειτα τῆς ὁμοῦ Ῥωμαίοις ἐπ’ Ἀκτίῳ ναυμαχίας. σέβουσι δὲ καὶ Ἀθηνᾶν Ἀλέαν, καὶ ἱερόν τε καὶ ἄγαλμα Ἀθηνᾶς ἐστιν Ἀλέας αὐτοῖς.", "st": "8.9"}, {"sp": "N", "t": "ἐνομίσθη δὲ καὶ Ἀντίνους σφίσιν εἶναι θεός· τῶν δὲ ἐν Μαντινείᾳ νεώτατός ἐστιν ὁ τοῦ Ἀντίνου ναός. οὗτος ἐσπουδάσθη περισσῶς δή τι ὑπὸ βασιλέως Ἀδριανοῦ· ἐγὼ δὲ μετ’ ἀνθρώπων μὲν ἔτι αὐτὸν ὄντα οὐκ εἶδον, ἐν δὲ ἀγάλμασιν εἶδον καὶ ἐν γραφαῖς. ἔχει μὲν δὴ γέρα καὶ ἑτέρωθι, καὶ ἐπὶ τῷ Νείλῳ πόλις Αἰγυπτίων ἐστὶν ἐπώνυμος Ἀντίνου· τιμὰς δὲ ἐν Μαντινείᾳ κατὰ τοιόνδε ἔσχηκε. γένος ἦν ὁ Ἀντίνους ἐκ Βιθυνίου τῆς ὑπὲρ Σαγγαρίου ποταμοῦ· οἱ δὲ Βιθυνιεῖς Ἀρκάδες τέ εἰσι καὶ Μαντινεῖς τὰ ἄνωθεν.", "st": "8.9"}, {"sp": "N", "t": "τούτων ἕνεκα ὁ βασιλεὺς κατεστήσατο αὐτῷ καὶ ἐν Μαντινείᾳ τιμάς, καὶ τελετή τε κατὰ ἔτος ἕκαστον καὶ ἀγών ἐστιν αὐτῷ διὰ ἔτους πέμπτου. οἶκος δέ ἐστιν ἐν τῷ γυμνασίῳ Μαντινεῦσιν ἀγάλματα ἔχων Ἀντίνου καὶ ἐς τἄλλα θέας ἄξιος λίθων ἕνεκα οἷς κεκόσμηται καὶ ἀπιδόντι ἐς τὰς γραφάς· αἱ δὲ Ἀντίνου εἰσὶν αἱ πολλαί, Διονύσῳ μάλιστα εἰκασμέναι. καὶ δὴ καὶ τῆς ἐν Κεραμεικῷ γραφῆς, ἣ τὸ ἔργον εἶχε τὸ Ἀθηναίων ἐν Μαντινείᾳ, καὶ ταύτης αὐτόθι ἐστὶ μίμημα.", "st": "8.9"}, {"sp": "N", "t": "Μαντινεῦσι δὲ ἐν τῇ ἀγορᾷ γυναικός τε εἰκὼν χαλκῆ—[καὶ] Μαντινεῖς καλοῦσι Διομένειαν Ἀρκάδος —καὶ ἡρῷόν ἐστι Ποδάρου· φασὶ δὲ ἀποθανεῖν αὐτὸν ἐν τῇ πρὸς Ἐπαμινώνδαν καὶ Θηβαίους μάχῃ. γενεαῖς δὲ τρισὶν ἐμοῦ πρότερον μετέθεσαν τοῦ τάφου τὸ ἐπίγραμμα ἐς ἄνδρα ἀπόγονον μὲν ἐκείνου Ποδάρου καὶ ὁμώνυμον, γεγονότα δὲ καθ’ ἡλικίαν ὡς πολιτείας ἤδη Ῥωμαίων μετειληφέναι.", "st": "8.9"}, {"sp": "N", "t": "Ποδάρην δὲ ἐπ’ ἐμοῦ τὸν ἀρχαῖον ἐτίμων οἱ Μαντινεῖς, λέγοντες ὡς ἄριστος μὲν καὶ αὐτῶν καὶ τῶν συμμάχων γένοιτο ἐν τῇ μάχῃ Γρύλος ὁ Ξενοφῶντος, ἐπὶ δὲ τῷ Γρύλῳ Κηφισόδωρος Μαραθώνιος, οὗτος δὲ τηνικαῦτα Ἀθηναίοις ἐτύγχανεν ἱππαρχῶν· τρίτα δὲ ἀνδραγαθίας Ποδάρῃ νέμουσιν.", "st": "8.9"}, {"sp": "N", "t": "ἐς Ἀρκαδίαν δὲ τὴν ἄλλην εἰσὶν ἐκ Μαντινείας ὁδοί· ὁπόσα δὲ ἐφ’ ἑκάστης αὐτῶν μάλιστα ἦν θέας ἄξια, ἐπέξειμι καὶ ταῦτα. ἰόντι ἐς Τεγέαν ἐστὶν ἐν ἀριστερᾷ τῆς λεωφόρου παρὰ τοῖς Μαντινέων τείχεσι χωρίον ἐς τῶν ἵππων τὸν δρόμον καὶ οὐ πόρρω τούτου στάδιον, ἔνθα ἐπὶ τῷ Ἀντίνῳ τὸν ἀγῶνα τιθέασιν. ὑπὲρ δὲ τοῦ σταδίου τὸ ὄρος ἐστὶ τὸ Ἀλήσιον, διὰ τὴν ἄλην ὥς φασι καλούμενον τὴν Ῥέας, καὶ Δήμητρος ἄλσος ἐν τῷ ὄρει.", "st": "8.10"}, {"sp": "N", "t": "παρὰ δὲ τοῦ ὄρους τὰ ἔσχατα τοῦ Ποσειδῶνός ἐστι τοῦ Ἱππίου τὸ ἱερόν, οὐ πρόσω σταδίου Μαντινείας. τὰ δὲ ἐς τὸ ἱερὸν τοῦτο ἐγώ τε ἀκοὴν γράφω καὶ ὅσοι μνήμην ἄλλοι περὶ αὐτοῦ πεποίηνται. τὸ μὲν δὴ ἱερὸν τὸ ἐφ’ ἡμῶν ᾠκοδομήσατο Ἀδριανὸς βασιλεύς, ἐπιστήσας τοῖς ἐργαζομένοις ἐπόπτας ἄνδρας, ὡς μήτε ἐνίδοι τις ἐς τὸ ἱερὸν τὸ ἀρχαῖον μήτε τῶν ἐρειπίων τι αὐτοῦ μετακινοῖτο· πέριξ δὲ ἐκέλευε τὸν ναὸν σφᾶς οἰκοδομεῖσθαι τὸν καινόν. τὰ δὲ ἐξ ἀρχῆς τῷ Ποσειδῶνι τὸ ἱερὸν τοῦτο Ἀγαμήδης λέγονται καὶ Τροφώνιος ποιῆσαι, δρυῶν ξύλα ἐργασάμενοι καὶ ἁρμόσαντες πρὸς ἄλληλα·", "st": "8.10"}, {"sp": "N", "t": "ἐσόδου δὲ ἐς αὐτὸ εἴργοντες ἀνθρώπους ἔρυμα μὲν πρὸ τῆς ἐσόδου προεβάλοντο οὐδέν, μίτον δὲ διατείνουσιν ἐρεοῦν, τάχα μέν που τοῖς τότε ἄγουσι τὰ θεῖα ἐν τιμῇ δεῖμα καὶ τοῦτο ἔσεσθαι νομίζοντες, τάχα δ’ ἄν τι μετείη καὶ ἰσχύος τῷ μίτῳ. φαίνεται δὲ καὶ Αἴπυτος ὁ Ἱππόθου μήτε πηδήσας ὑπὲρ τὸν μίτον μήτε ὑποδύς, διακόψας δὲ αὐτὸν ἐσελθὼν ἐς τὸ ἱερόν· καὶ ποιήσας οὐχ ὅσια ἐτυφλώθη τε ἐμπεσόντος ἐς τοὺς ὀφθαλμοὺς αὐτῷ τοῦ κύματος καὶ αὐτίκα ἐπιλαμβάνει τὸ χρεὼν αὐτόν.", "st": "8.10"}, {"sp": "N", "t": "θαλάσσης δὲ ἀναφαίνεσθαι κῦμα ἐν τῷ ἱερῷ λόγος ἐστὶν ἀρχαῖος· ἐοικότα δὲ καὶ Ἀθηναῖοι λέγουσιν ἐς τὸ κῦμα τὸ ἐν ἀκροπόλει καὶ Καρῶν οἱ Μύλασα ἔχοντες ἐς τοῦ θεοῦ τὸ ἱερόν, ὃν φωνῇ τῇ ἐπιχωρίᾳ καλοῦσιν Ὀσογῶα. Ἀθηναίοις μὲν δὴ σταδίους μάλιστα εἴκοσιν ἀφέστηκε τῆς πόλεως ἡ πρὸς Φαληρῷ θάλασσα, ὡσαύτως δὲ καὶ Μυλασεῦσιν ἐπίνειον σταδίους ὀγδοήκοντα ἀπέχον ἐστὶν ἀπὸ τῆς πόλεως· Μαντινεῦσι δὲ ἐκ μακροτάτων τε ἡ θάλασσα ἄνεισι ⟨καὶ⟩ ἐκφανέστατα δὴ κατὰ τοῦ θεοῦ γνώμην.", "st": "8.10"}, {"sp": "N", "t": "πέραν δὲ τοῦ ἱεροῦ τοῦ Ποσειδῶνος τρόπαιόν ἐστι λίθου πεποιημένον ἀπὸ Λακεδαιμονίων καὶ Ἄγιδος· λέγεται δὲ καὶ ὁ τρόπος τῆς μάχης. τὸ μὲν δεξιὸν εἶχον οἱ Μαντινεῖς αὐτοί, στρατιάν τε ἀπὸ πάσης ἡλικίας καὶ στρατηγὸν παρεχόμενοι Ποδάρην ἀπόγονον τρίτον Ποδάρου τοῦ Θηβαίοις ἐναντία ἀγωνισαμένου, παρῆν δέ σφισι καὶ μάντις Ἠλεῖος Θρασύβουλος Αἰνέου τῶν Ἰαμιδῶν—οὗτος ὁ ἀνὴρ νίκην τε τοῖς Μαντινεῦσι προηγόρευσε καὶ αὐτός σφισι τοῦ ἔργου μετέσχεν—·", "st": "8.10"}, {"sp": "N", "t": "ἐπὶ δὲ τῷ εὐωνύμῳ πᾶν τὸ ἄλλο Ἀρκαδικὸν ἐτάσσοντο, ἄρχοντες δὲ κατὰ πόλεις τε ἦσαν καὶ Μεγαλοπολιτῶν Λυδιάδης καὶ Λεωκύδης· Ἀράτῳ δὲ ἐπετέτραπτο καὶ Σικυωνίοις τε καὶ Ἀχαιοῖς τὸ μέσον. Λακεδαιμόνιοι δὲ καὶ Ἆγις ἐπεξέτειναν τὴν φάλαγγα, ὡς τῶν ἐναντίων τῷ στρατεύματι ἀντιπαρήκοιεν· τὸ μέσον δὲ Ἆγις καὶ οἱ περὶ τὸν βασιλέα εἶχον.", "st": "8.10"}, {"sp": "N", "t": "Ἄρατος δὲ ἀπὸ συγκειμένου πρὸς τοὺς Ἀρκάδας ὑπέφευγεν αὐτός τε καὶ ὁ σὺν αὐτῷ στρατὸς οἷα δὴ τῶν Λακεδαιμονίων σφίσιν ἐγκειμένων· ὑποφεύγοντες δὲ ἅμα τὸ σύνταγμα σφῶν ἠρέμα ἐποίουν μηνοειδές. Λακεδαιμόνιοι δὲ καὶ Ἆγις νίκην τε ἤλπιζον καὶ τοῖς περὶ τὸν Ἄρατον ἐνέκειντο ἀθρόοι μᾶλλον· ἐπηκολούθουν δέ σφισι καὶ οἱ ἀπὸ τῶν κεράτων, Ἄρατον καὶ τὴν σὺν αὐτῷ στρατιὰν τρέψασθαι μέγα ἀγώνισμα ἡγούμενοι.", "st": "8.10"}, {"sp": "N", "t": "ἔλαθόν τε δὴ κατὰ νώτου γενόμενοί σφισιν οἱ Ἀρκάδες καὶ οἱ Λακεδαιμόνιοι κυκλωθέντες τῆς ⟨τε⟩ ἄλλης στρατιᾶς τὸ πολὺ ἀποβάλλουσι καὶ βασιλεὺς ἔπεσεν Ἆγις Εὐδαμίδου. φανῆναι δὲ καὶ τὸν Ποσειδῶνα ἀμύνοντά σφισιν ἔφασαν οἱ Μαντινεῖς, καὶ τοῦδε ἕνεκα τρόπαιον ἐποιήσαντο ἀνάθημα τῷ Ποσειδῶνι.", "st": "8.10"}, {"sp": "N", "t": "πολέμῳ δὲ καὶ ἀνθρώπων φόνοις παρεῖναι θεοὺς ἐποίησαν μὲν ὅσοις τὰ ἡρώων ἐμέλησεν ἐν Ἰλίῳ παθήματα, ᾄδεται δὲ ὑπὸ Ἀθηναίων ὡς θεοί σφισιν ἐν Μαραθῶνι καὶ ἐν Σαλαμῖνι τοῦ ἔργου μετάσχοιεν· ἐκδηλότατα δὲ ὁ Γαλατῶν στρατὸς ἀπώλετο ἐν Δελφοῖς ὑπὸ τοῦ θεοῦ καὶ ἐναργῶς ὑπὸ δαιμόνων. οὕτω καὶ Μαντινεῦσιν ἕπεται οὐκ ἄνευ τοῦ Ποσειδῶνος τὸ κράτος γενέσθαι σφίσι.", "st": "8.10"}, {"sp": "N", "t": "Λεωκύδους δὲ τοῦ Μεγαλοπολιτῶν ὁμοῦ Λυδιάδῃ στρατηγήσαντος πρόγονον ἔνατον Ἀρκεσίλαον οἰκοῦντα ἐν Λυκοσούρᾳ λέγουσιν οἱ Ἀρκάδες ὡς ἴδοι τὴν ἱερὰν τῆς καλουμένης Δεσποίνης ἔλαφον πεπονηκυῖαν ὑπὸ γήρως· τῇ δὲ ἐλάφῳ ταύτῃ ψάλιόν τε εἶναι περὶ τὸν τράχηλον καὶ γράμματα ἐπὶ τῷ ψαλίῳ,<br>νεβρὸς ἐὼν ἑάλων, ὅτ’ ἐς Ἴλιον ἦν Ἀγαπήνωρ.<br>οὗτος μὲν δὴ ἐπιδείκνυσιν ὁ λόγος ἔλαφον εἶναι πολλῷ καὶ ἐλέφαντος μακροβιώτερον θηρίον·", "st": "8.10"}, {"sp": "N", "t": "μετὰ δὲ τὸ ἱερὸν τοῦ Ποσειδῶνος χωρίον ὑποδέξεταί σε δρυῶν πλῆρες, καλούμενον Πέλαγος, καὶ ἐκ Μαντινείας ἡ ἐς Τεγέαν ὁδὸς φέρει διὰ τῶν δρυῶν. Μαντινεῦσι δὲ ὅροι πρὸς Τεγεάτας εἰσὶν ὁ περιφερὴς ἐν τῇ λεωφόρῳ βωμός. εἰ δὲ ἀπὸ τοῦ ἱεροῦ τοῦ Ποσειδῶνος ἐς ἀριστερὰν ἐκτραπῆναι θελήσειας, σταδίους τε ἥξεις μάλιστά που πέντε καὶ ἐπὶ τῶν Πελίου θυγατέρων ἀφίξῃ τοὺς τάφους· ταύτας φασὶν οἱ Μαντινεῖς μετοικῆσαι ⟨παρὰ⟩ σφᾶς, τὰ ἐπὶ τῷ θανάτῳ τοῦ πατρὸς ὀνείδη φευγούσας.", "st": "8.11"}, {"sp": "N", "t": "ὡς γὰρ δὴ ἀφίκετο ἡ Μήδεια ἐς Ἰωλκόν, αὐτίκα ἐπεβούλευε τῷ Πελίᾳ, τῷ ἔργῳ μὲν συμπράσσουσα τῷ Ἰάσονι, τῷ λόγῳ δὲ ἀπεχθανομένη. ἐπαγγέλλεται τοῦ Πελίου ταῖς θυγατράσιν ὡς τὸν πατέρα αὐταῖς, ἢν ἐθέλωσιν, ἀποφανοῖ νέον ἀντὶ γέροντος παλαιοῦ· κατασφάξασα δὲ ὅτῳ ⟨δὴ⟩ τρόπῳ κριὸν τὰ κρέα ὁμοῦ φαρμάκοις ἐν λέβητι ἥψησεν, οἷς ἐκ τοῦ λέβητος τὸν κριὸν τὸν ἑψόμενον ἄρνα ἐξήγαγε ζῶντα·", "st": "8.11"}, {"sp": "N", "t": "παραλαμβάνει τε δὴ τὸν Πελίαν κατακόψασα ἑψῆσαι, καὶ αὐτὸν ἐκομίσαντο αἱ θυγατέρες οὐδὲ ἐς ταφὴν ἔτι ἐπιτήδειον. τοῦτο ἠνάγκασε τὰς γυναῖκας ἐς Ἀρκαδίαν μετοικῆσαι, καὶ ἀποθανούσαις τὰ μνήματα ἐχώσθη σφίσιν αὐτοῦ· ὀνόματα δὲ αὐταῖς ποιητὴς μὲν ἔθετο οὐδείς, ὅσα γε ἐπελεξάμεθα ἡμεῖς, Μίκων δὲ ὁ ζωγράφος Ἀστερόπειάν τε εἶναι καὶ Ἀντινόην ἐπὶ ταῖς εἰκόσιν αὐτῶν ἐπέγραψεν.", "st": "8.11"}, {"sp": "N", "t": "χωρίον δὲ ὀνομαζόμενον Φοίζων περὶ εἴκοσί που σταδίους τῶν τάφων ἐστὶν ἀπωτέρω τούτων· ⟨ὁ⟩ δὲ Φοίζων μνῆμά ἐστι λίθου περιεχόμενον κρηπῖδι, ἀνέχον δὲ οὐ πολὺ ὑπὲρ τῆς γῆς. κατὰ τοῦτο ἥ τε ὁδὸς μάλιστα στενὴ γίνεται καὶ τὸ μνῆμα Ἀρηιθόου λέγουσιν εἶναι, Κορυνήτου διὰ τὸ ὅπλον ἐπονομασθέντος.", "st": "8.11"}, {"sp": "N", "t": "κατὰ δὲ τὴν ἐς Παλλάντιον ἐκ Μαντινείας ἄγουσαν προελθόντι ὡς τριάκοντά που σταδίους, παρήκει κατὰ τοῦτο ἐς τὴν λεωφόρον ὁ τοῦ Πελάγους καλουμένου δρυμός, καὶ τὰ ἱππικὰ τὸ Ἀθηναίων τε καὶ Μαντινέων ἐνταῦθα ἐμαχέσαντο ἐναντία τῆς Βοιωτίας ἵππου. Ἐπαμινώνδαν δὲ ἀποθανεῖν Μαντινεῖς μὲν ὑπὸ Μαχαιρίωνος Μαντινέως φασὶν ἀνδρός· ὡσαύτως δὲ καὶ Λακεδαιμόνιοι Σπαρτιάτην λέγουσιν εἶναι τὸν ἀποκτείναντα Ἐπαμινώνδαν, τίθενται δὲ Μαχαιρίωνα ὄνομα καὶ οὗτοι τῷ ἀνδρί.", "st": "8.11"}, {"sp": "N", "t": "ὁ δὲ Ἀθηναίων ἔχει λόγος— ὁμολογοῦσι δὲ αὐτῷ καὶ Θηβαῖοι—τρωθῆναι τὸν Ἐπαμινώνδαν ὑπὸ Γρύλου· παραπλήσια δέ σφισίν ἐστι καὶ τὰ ἐν τῇ γραφῇ ⟨τῇ⟩ τὸ ἔργον ἐχούσῃ τὸ ἐν Μαντινείᾳ. φαίνονται δὲ οἱ Μαντινεῖς Γρύλον μὲν δημοσίᾳ τε θάψαντες καὶ ἔνθα ἔπεσεν ἀναθέντες εἰκόνα ἐπὶ στήλης ὡς ἀνδρὸς ἀρίστου τῶν συμμάχων· Μαχαιρίωνα δὲ λόγῳ μὲν καὶ αὐτοὶ ⟨καὶ⟩ οἱ Λακεδαιμόνιοι λέγουσιν, ἔργῳ δὲ οὔτε ἐν Σπάρτῃ Μαχαιρίων ἐστὶν οὐδείς, οὐ μὴν οὐδὲ παρὰ Μαντινεῦσιν, ὅτῳ γεγόνασιν ὡς ἀνδρὶ ἀγαθῷ τιμαί.", "st": "8.11"}, {"sp": "N", "t": "ὡς δὲ ἐτέτρωτο ⟨ὁ⟩ Ἐπαμινώνδας, ἐκκομίζουσιν ἔτι ζῶντα ἐκ τῆς παρατάξεως αὐτόν· ὁ δὲ τέως μὲν τὴν χεῖρα ἔχων ἐπὶ τῷ τραύματι ἐταλαιπώρει καὶ ἐς τοὺς μαχομένους ἀφεώρα—ὁπόθεν δὲ ἀπέβλεπεν ἐς αὐτούς, ὠνόμαζον Σκοπὴν οἱ ἔπειτα—, λαβόντος δὲ ἴσον τοῦ ἀγῶνος πέρας, οὕτω τὴν χεῖρα ἀπέσχεν ἀπὸ τοῦ τραύματος· καὶ αὐτὸν ἀφέντα τὴν ψυχὴν ἔθαψαν ἔνθα σφίσιν ἐγένετο ἡ συμβολή.", "st": "8.11"}, {"sp": "N", "t": "τῷ τάφῳ δὲ κίων τε ἐφέστηκε καὶ ἀσπὶς ἐπ’ αὐτῷ δράκοντα ἔχουσα ἐπειργασμένον· ὁ μὲν δὴ δράκων ἐθέλει σημαίνειν γένους τῶν Σπαρτῶν καλουμένων εἶναι τὸν Ἐπαμινώνδαν, στῆλαι δέ εἰσιν ἐπὶ τῷ μνήματι, ἡ μὲν ἀρχαία καὶ ἐπίγραμμα ἔχουσα Βοιώτιον, τὴν δὲ αὐτήν τε ἀνέθηκεν Ἀδριανὸς βασιλεὺς καὶ ἐποίησε τὸ ἐπίγραμμα τὸ ἐπ’ αὐτῇ.", "st": "8.11"}, {"sp": "N", "t": "τὸν δὲ Ἐπαμινώνδαν τῶν παρ’ Ἕλλησι στρατηγίας ἕνεκα εὐδοκιμησάντων μάλιστα ἐπαινέσαι τις ἂν ἢ ὕστερόν γε οὐδενὸς ποιήσαιτο· Λακεδαιμονίων μὲν γὰρ καὶ Ἀθηναίων τοῖς ἡγεμόσι πόλεών τε ἀξίωμα ὑπῆρχεν ἐκ παλαιοῦ καὶ οἱ στρατιῶται φρονήματός τι ἦσαν ἔχοντες, Θηβαίους δὲ Ἐπαμινώνδας ἀθύμους τὰς γνώμας καὶ ἄλλων ἀκούειν εἰωθότας ἀπέφηνεν ⟨ἐν⟩ οὐ πολλῷ πρωτεύοντας.", "st": "8.11"}, {"sp": "N", "t": "ἐγεγόνει δὲ τῷ Ἐπαμινώνδᾳ μαντεία πρότερον ἔτι ἐκ Δελφῶν πέλαγος αὐτὸν φυλάσσεσθαι· καὶ ὁ μὲν τριήρους τε μὴ ἐπιβῆναι μηδὲ ἐπὶ νεὼς φορτίδος πλεῦσαι δεῖμα εἶχε, τῷ δὲ ἄρα Πέλαγος δρυμὸν καὶ οὐ θάλασσαν προέλεγεν ὁ δαίμων. χωρία δὲ τὰ ὁμώνυμα καὶ Ἀννίβαν ὕστερον τὸν Καρχηδόνιον καὶ πρότερον ἔτι Ἀθηναίους ἠπάτησεν.", "st": "8.11"}, {"sp": "N", "t": "Ἀννίβᾳ γὰρ χρησμὸς ἀφίκετο παρὰ Ἄμμωνος ὡς ἀποθανὼν γῇ καλυφθήσεται τῇ Λιβύσσῃ. ὁ μὲν δὴ ἤλπιζεν ἀρχήν τε τὴν Ῥωμαίων καθαιρήσειν καὶ οἴκαδε ἐς τὴν Λιβύην ἐπανελθὼν τελευτήσειν γήρᾳ τὸν βίον. Φλαμινίου δὲ τοῦ Ῥωμαίου ποιουμένου σπουδὴν ἑλεῖν ζῶντα αὐτόν, ἀφικόμενος παρὰ Προυσίαν ἱκέτης καὶ ἀπωσθεὶς ὑπ’ αὐτοῦ ἀνεπήδα τε ἐπὶ τὸν ἵππον καὶ γυμνωθέντος τοῦ ξίφους τιτρώσκεται τὸν δάκτυλον. προελθόντι δέ οἱ στάδια οὐ πολλὰ πυρετός τε ἀπὸ τοῦ τραύματος καὶ ἡ τελευτὴ τριταίῳ συνέβη· τὸ δὲ χωρίον ἔνθα ἀπέθανε καλοῦσιν οἱ Νικομηδεῖς Λίβυσσαν.", "st": "8.11"}, {"sp": "N", "t": "Ἀθηναίοις δὲ μάντευμα ἐκ Δωδώνης Σικελίαν ἦλθεν οἰκίζειν, ἡ δὲ οὐ πόρρω τῆς πόλεως ἡ Σικελία λόφος ἐστὶν οὐ μέγας· οἱ δὲ οὐ συμφρονήσαντες τὸ εἰρημένον ἔς τε ὑπερορίους στρατείας προήχθησαν καὶ ἐς τὸν Συρακοσίων πόλεμον. ἔχοι δ’ ἄν τις καὶ πλέονα τοῖς εἰρημένοις ἐοικότα ἄλλα ἐξευρεῖν.", "st": "8.11"}, {"sp": "N", "t": "τοῦ τάφου δὲ τοῦ Ἐπαμινώνδα μάλιστά που σταδίου μῆκος Διὸς ἀφέστηκεν ἱερὸν ἐπίκλησιν Χάρμωνος. Ἀρκάδων δὲ ἐν τοῖς δρυμοῖς εἰσιν αἱ δρῦς διάφοροι, καὶ τὰς μὲν πλατυφύλλους αὐτῶν, τὰς δὲ φηγοὺς καλοῦσιν· αἱ τρίται δὲ ἀραιὸν τὸν φλοιὸν καὶ οὕτω δή τι παρέχονται κοῦφον, ὥστε ἀπ’ αὐτοῦ καὶ ἐν θαλάσσῃ ποιοῦνται σημεῖα ἀγκύραις καὶ δικτύοις· ταύτης τῆς δρυὸς τὸν φλοιὸν ἄλλοι τε Ἰώνων καὶ Ἑρμησιάναξ ὁ τὰ ἐλεγεῖα ποιήσας φελλὸν ὀνομάζουσιν.", "st": "8.12"}, {"sp": "N", "t": "ἐς Μεθύδριον δὲ πόλιν μὲν οὐκέτι, κώμην δὲ ἐς τὸ Μεγαλοπολιτικὸν συντελοῦσαν, ἐς τοῦτό ἐστι τὸ Μεθύδριον ἐκ Μαντινείας ὁδός. προελθόντι δὲ σταδίους τριάκοντα πεδίον τε ὀνομαζόμενον Ἀλκιμέδων καὶ ὑπὲρ τοῦ πεδίου τὸ ὄρος ἐστὶν ἡ Ὀστρακίνα, ἐν δὲ αὐτῷ σπήλαιον, ἔνθα ᾤκησεν Ἀλκιμέδων, ἀνὴρ τῶν καλουμένων ἡρώων.", "st": "8.12"}, {"sp": "N", "t": "τούτου τοῦ Ἀλκιμέδοντος θυγατρὶ συγγενέσθαι Φιαλοῖ [ὡς] Φιγαλεῖς λέγουσιν Ἡρακλέα· ὡς δὲ ᾔσθετο αὐτὴν ὁ Ἀλκιμέδων τεκοῦσαν, ἐκτίθησιν ἀπολουμένην ἐς τὸ ὄρος, σὺν δὲ αὐτῇ καὶ τὸν παῖδα ὃν ἔτεκε· καλοῦσι δὲ Αἰχμαγόραν αὐτὸν οἱ Ἀρκάδες. ἀνακλαίοντος δὲ ὡς ἐξέκειτο τοῦ παιδός, κίσσα ἡ ὄρνις ἐπήκουέ τε ὀδυρομένου καὶ ἀπεμιμεῖτο τὰ κλαύματα·", "st": "8.12"}, {"sp": "N", "t": "καί πως ὁ Ἡρακλῆς ἐρχόμενος τὴν ὁδὸν ταύτην ἐπήκουσε τῆς κίσσης καὶ—ἐνόμισε γὰρ παιδὸς εἶναι καὶ οὐκ ὄρνιθος τὸν κλαυθμόν—ἐτράπετο εὐθὺ τῆς φωνῆς· γνωρίσας δὲ αὐτήν τε ἔλυσεν ἀπὸ τῶν δεσμῶν καὶ τὸν παῖδα ἀνεσώσατο. ἐξ ἐκείνου δὲ ἡ πλησίον πηγὴ Κίσσα ἀπὸ τῆς ὄρνιθος ὀνομάζεται. τεσσαράκοντα δὲ ἀπὸ τῆς πηγῆς στάδια ἀφέστηκε Πετροσάκα καλούμενον χωρίον· Μεγαλοπολιτῶν δὲ καὶ Μαντινέων ὅρος ἐστὶν ἡ Πετροσάκα.", "st": "8.12"}, {"sp": "N", "t": "ἐπὶ δὲ ὁδοῖς ταῖς κατειλεγμέναις δύο ἐς Ὀρχομενόν εἰσιν ἄλλαι, καὶ τῇ μέν ἐστι καλούμενον Λάδα στάδιον, ἐς ὃ ἐποιεῖτο Λάδας μελέτην δρόμου, καὶ παρ’ αὐτὸ ἱερὸν Ἀρτέμιδος καὶ ἐν δεξιᾷ τῆς ὁδοῦ γῆς χῶμα ὑψηλόν· Πηνελόπης δὲ εἶναι τάφον φασίν, οὐχ ὁμολογοῦντες τὰ ἐς αὐτὴν ποιήσει ⟨τῇ⟩ Θεσπρωτίδι ὀνομαζομένῃ.", "st": "8.12"}, {"sp": "N", "t": "ἐν ταύτῃ μέν γέ ἐστι τῇ ποιήσει ἐπανήκοντι ἐκ Τροίας Ὀδυσσεῖ τεκεῖν τὴν Πηνελόπην Πτολιπόρθην παῖδα· Μαντινέων δὲ ὁ ἐς αὐτὴν λόγος Πηνελόπην φησὶν ὑπ’ Ὀδυσσέως καταγνωσθεῖσαν ὡς ἐπισπαστοὺς ἐσαγάγοιτο ἐς τὸν οἶκον, καὶ ἀποπεμφθεῖσαν ὑπ’ αὐτοῦ, τὸ μὲν παραυτίκα ἐς Λακεδαίμονα ἀπελθεῖν, χρόνῳ δὲ ὕστερον ἐκ τῆς Σπάρτης ἐς Μαντίνειαν μετοικῆσαι, καί οἱ τοῦ βίου τὴν τελευτὴν ἐνταῦθα συμβῆναι.", "st": "8.12"}, {"sp": "N", "t": "τοῦ τάφου δὲ ἔχεται τούτου πεδίον οὐ μέγα, καὶ ὄρος ἐστὶν ἐν τῷ πεδίῳ τὰ ἐρείπια ἔτι Μαντινείας ἔχον τῆς ἀρχαίας· καλεῖται δὲ τὸ χωρίον τοῦτο ἐφ’ ἡμῶν Πτόλις. κατὰ δὲ τὸ πρὸς ἄρκτον αὐτῆς προελθόντι ὁδὸν οὐ μακρὰν Ἀλαλκομενείας ἐστὶ πηγή, τῆς Πτόλεως δὲ μετὰ σταδίους τριάκοντα κώμης τε ἐρείπια καλουμένης Μαιρᾶς ⟨καὶ τάφος Μαιρᾶς⟩, εἰ δὴ ἐνταῦθα καὶ μὴ ἐν τῇ Τεγεατῶν ἐτάφη· Τεγεάταις γὰρ τοῦ λόγου τὸ εἰκὸς καὶ οὐ Μαντινεῦσιν ἕπεται, Μαιρὰν τὴν Ἄτλαντος παρὰ σφίσι ταφῆναι. τάχα δ’ ἂν καὶ ἀπόγονος τῆς Ἄτλαντος Μαιρᾶς ἑτέρα Μαιρὰ ἀφίκοιτο ἐς τὴν Μαντινικήν.", "st": "8.12"}, {"sp": "N", "t": "λείπεται δὲ ἔτι τῶν ὁδῶν ἡ ἐς Ὀρχομενόν, καθ’ ἥντινα Ἀγχισία τε ὄρος καὶ Ἀγχίσου μνῆμά ἐστιν ὑπὸ τοῦ ὄρους τοῖς ποσίν. ὡς γὰρ δὴ ἐκομίζετο ἐς Σικελίαν ὁ Αἰνείας, ἔσχε ταῖς ναυσὶν ἐς τὴν Λακωνικήν, καὶ πόλεών τε Ἀφροδισιάδος καὶ Ἤτιδος ἐγένετο οἰκιστὴς καὶ τὸν πατέρα Ἀγχίσην κατὰ πρόφασιν δή τινα παραγενόμενον ἐς τοῦτο τὸ χωρίον καὶ αὐτόθι τοῦ βίου τῇ τελευτῇ χρησάμενον ἔθαψεν ἐνταῦθα· καὶ τὸ ὄρος τοῦτο ἀπὸ τοῦ Ἀγχίσου καλοῦσιν Ἀγχισίαν.", "st": "8.12"}, {"sp": "N", "t": "τούτου δὲ συντελοῦσιν ἐς πίστιν Αἰολέων οἱ Ἴλιον ἐφ’ ἡμῶν ἔχοντες, οὐδαμοῦ τῆς σφετέρας ἀποφαίνοντες μνῆμα Ἀγχίσου. πρὸς δὲ τοῦ Ἀγχίσου τῷ τάφῳ ἐρείπιά ἐστιν Ἀφροδίτης ἱεροῦ, καὶ Μαντινέων ὅροι πρὸς Ὀρχομενίους καὶ ἐν ταῖς Ἀγχισίαις εἰσίν.", "st": "8.12"}, {"sp": "N", "t": "ἐν δὲ τῇ χώρᾳ τῇ Ὀρχομενίων, ἐν ἀριστερᾷ τῆς ὁδοῦ τῆς ἀπὸ Ἀγχισιῶν, ἐν ὑπτίῳ τοῦ ὄρους τὸ ἱερόν ἐστι τῆς Ὑμνίας Ἀρτέμιδος· μέτεστι δὲ αὐτοῦ καὶ Μαντινεῦσι … καὶ ἱέρειαν καὶ ἄνδρα ἱερέα. τούτοις οὐ μόνον τὰ ἐς τὰς μίξεις ἀλλὰ καὶ ἐς τὰ ἄλλα ἁγιστεύειν καθέστηκε τὸν χρόνον τοῦ βίου πάντα, καὶ οὔτε λουτρὰ οὔτε δίαιτα λοιπὴ κατὰ τὰ αὐτά σφισι καθὰ καὶ τοῖς πολλοῖς ἐστιν, οὐδὲ ἐς οἰκίαν παρίασιν ἀνδρὸς ἰδιώτου. τοιαῦτα οἶδα ἕτερα ἐνιαυτὸν καὶ οὐ πρόσω Ἐφεσίων ἐπιτηδεύοντας τοὺς τῇ Ἀρτέμιδι ἱστιάτορας τῇ Ἐφεσίᾳ γινομένους, καλουμένους δὲ ὑπὸ τῶν πολιτῶν Ἐσσῆνας. τῇ δὲ Ἀρτέμιδι τῇ Ὑμνίᾳ καὶ ἑορτὴν ἄγουσιν ἐπέτειον.", "st": "8.13"}, {"sp": "N", "t": "Ὀρχομενίοις δὲ ἡ προτέρα πόλις ἐπὶ ὄρους ἦν ἄκρᾳ τῇ κορυφῇ, καὶ ἀγορᾶς τε καὶ τειχῶν ἐρείπια λείπεται· τὴν δὲ ἐφ’ ἡμῶν πόλιν ὑπὸ τὸν περίβολον οἰκοῦσι τοῦ ἀρχαίου τείχους. θέας δὲ αὐτόθι ἄξια πηγή τε, ἀφ’ ἧς ὑδρεύονται, καὶ Ποσειδῶνός ἐστι καὶ Ἀφροδίτης ἱερά, λίθου δὲ τὰ ἀγάλματα. πρὸς δὲ τῇ πόλει ξόανόν ἐστιν Ἀρτέμιδος· ἵδρυται δὲ ἐν κέδρῳ μεγάλῃ, καὶ τὴν θεὸν ὀνομάζουσιν ἀπὸ τῆς κέδρου Κεδρεᾶτιν.", "st": "8.13"}, {"sp": "N", "t": "σωροὶ δὲ ὑπὸ τὴν πόλιν λίθων εἰσὶ διεστηκότες ἀπὸ ἀλλήλων, ἐπενήθησαν δὲ ἐν πολέμῳ πεσοῦσιν ἀνδράσιν. οἷς τισι δὲ Πελοποννησίων ἐπολέμησαν ⟨ἢ⟩ τῶν ἄλλων ἢ Ἀρκάδων αὐτῶν, οὔτε ἐπιγράμματα ἐπὶ τοῖς τάφοις ἐσήμαινεν οὔτε οἱ Ὀρχομένιοι μνημονεύουσιν.", "st": "8.13"}, {"sp": "N", "t": "ἔστι δὲ ἀπαντικρὺ τῆς πόλεως ὄρος Τραχύ. τὸ δὲ ὕδωρ τὸ ἐκ τοῦ θεοῦ διὰ χαράδρας ῥέον κοίλης μεταξὺ τῆς τε πόλεως καὶ τοῦ Τραχέος ὄρους κάτεισιν ἐς ἄλλο Ὀρχομένιον πεδίον, τὸ δὲ πεδίον τοῦτο μεγέθει μὲν μέγα, τὰ πλείω δέ ἐστιν αὐτοῦ λίμνη. ἰόντι δὲ ἐξ Ὀρχομενοῦ καὶ σταδίους προελθόντι ὅσον τρεῖς, ἡ μὲν εὐθεῖα ἐπὶ πόλιν Καφυὰν ἄγει παρά τε αὐτὴν τὴν χαράδραν καὶ μετὰ ταύτην ἐν ἀριστερᾷ παρὰ τὸ ὕδωρ τὸ λιμνάζον· ἡ δὲ ἑτέρα τῶν ὁδῶν διαβάντι τὸ ὕδωρ τὸ διὰ τῆς χαράδρας ῥέον ὑπὸ ⟨τὸ⟩ Τραχύ ἐστιν ὄρος.", "st": "8.13"}, {"sp": "N", "t": "κατὰ δὲ τὴν ὁδὸν ταύτην πρῶτον μὲν μνῆμά ἐστιν Ἀριστοκράτους, ὃς βίᾳ ποτὲ ᾔσχυνε τὴν ἱερωμένην τῇ Ὑμνίᾳ θεῷ παρθένον, μετὰ δὲ τοῦ Ἀριστοκράτους τὸν τάφον πηγαί τέ εἰσι καλούμεναι Τενεῖαι καὶ ἀπέχει τῶν πηγῶν στάδια ὡς ἑπτὰ Ἄμιλος χωρίον· πόλιν δὲ τὴν Ἄμιλόν ποτε εἶναι λέγουσι. κατὰ τοῦτο αὖθις τὸ χωρίον δίχα ἡ ὁδὸς τέμνεται, καὶ ἡ μὲν ἐπὶ Στύμφηλον, ἡ δὲ ἐς Φενεὸν αὐτῶν ἄγει.", "st": "8.13"}, {"sp": "N", "t": "κατὰ δὲ τὴν ἐς Φενεὸν ἐκδέξεταί σε ὄρος· ἐν δὲ τῷ ὄρει τούτῳ συνάπτουσιν Ὀρχομενίων καὶ Φενεατῶν τε καὶ Καφυατῶν ὅροι τῆς γῆς. ἀνατείνει δὲ ὑπὲρ τοὺς ὅρους κρημνὸς ὑψηλός· πέτραν Καφυατικὴν ὀνομάζουσι τὸν κρημνόν. μετὰ δὲ τοὺς ὅρους ταῖς κατειλεγμέναις πόλεσι φάραγξ τε ὑπόκειται καὶ φέρει δι’ αὐτῆς ἡ ἐς Φενεὸν ὁδός· κατὰ μέσην δέ που μάλιστα τὴν φάραγγα ὕδωρ ἄνεισιν ἐκ πηγῆς, καὶ ἐπὶ τῷ πέρατι τῆς φάραγγος Καρυαί ⟨ἐστι⟩ χωρίον.", "st": "8.13"}, {"sp": "N", "t": "Φενεατῶν δὲ τὸ πεδίον κεῖται μὲν ὑπὸ ταῖς Καρυαῖς, πλεονάσαντος δέ ποτε αὐτῷ τοῦ ὕδατος κατακλυσθῆναί φασι τὴν ἀρχαίαν Φενεόν, ὥστε καὶ ἐφ’ ἡμῶν σημεῖα ἐλείπετο ἐπὶ τῶν ὀρῶν ἐς ἃ ἐπαναβῆναι τὸ ὕδωρ λέγουσι. Καρυῶν δὲ στάδια πέντε ἀφέστηκεν ἥ τε Ὄρυξις καλουμένη καὶ ἕτερον ὄρος Σκίαθις· ὑφ’ ἑκατέρῳ δέ ἐστι τῷ ὄρει βάραθρον τὸ ὕδωρ καταδεχόμενον τὸ ἐκ τοῦ πεδίου.", "st": "8.14"}, {"sp": "N", "t": "τὰ δὲ βάραθρα οἱ Φενεᾶται ταῦτά φασιν εἶναι χειροποίητα, ποιῆσαι δὲ αὐτὰ Ἡρακλέα τηνικαῦτα ἐν Φενεῷ παρὰ Λαονόμῃ τῇ Ἀμφιτρύωνος μητρὶ οἰκοῦντα· γενέσθαι γὰρ Ἀμφιτρύωνα ἐκ Λαονόμης Ἀλκαίῳ τῆς Γούνεω, γυναικὸς Φενεάτιδος, καὶ οὐκ ἐκ τῆς Πέλοπος Λυσιδίκης. εἰ δὲ Ἡρακλῆς ἀληθεῖ λόγῳ παρὰ τοὺς Φενεάτας μετῴκησε, πείθοιτο ἄν τις διωχθέντα ἐκ Τίρυνθος ὑπὸ Εὐρυσθέως αὐτὸν οὐκ αὐτίκα ἐς Θήβας, πρότερον δὲ ἐς Φενεὸν ἀφικέσθαι.", "st": "8.14"}, {"sp": "N", "t": "διὰ μέσου δὲ ὤρυξεν Ἡρακλῆς τοῦ Φενεατῶν πεδίου ⟨ἔλυτρον⟩, ῥεῦμα εἶναι τῷ ποταμῷ τῷ Ὀλβίῳ, ὅν τινα Ἀροάνιον Ἀρκάδων καλοῦσιν ἕτεροι καὶ οὐκ Ὄλβιον· μῆκος μὲν τοῦ ὀρύγματος στάδιοι πεντήκοντά εἰσι, βάθος δέ, ὅσον μὴ πεπτωκός ἐστιν αὐτοῦ, καὶ ἐς τριάκοντα καθήκει πόδας. οὐ μὴν ταύτῃ γε ἔτι κάτεισιν ὁ ποταμός, ἀλλὰ ἐς τὸ ῥεῦμα ἀπεχώρησεν αὖθις τὸ ἀρχαῖον, καταλιπὼν [ἔλυτρον] τοῦ Ἡρακλέους τὸ ἔργον.", "st": "8.14"}, {"sp": "N", "t": "τῶν βαράθρων δὲ ⟨τῶν⟩ ἐν τοῖς εἰρημένοις πεποιημένων ὄρεσιν ἀπωτέρω πεντήκοντά που σταδίοις ἐστὶν ἡ πόλις· οἰκιστὴν δὲ οἱ Φενεᾶται λέγουσιν ἄνδρα αὐτόχθονα εἶναι Φενεόν. ἔστι δέ σφισιν ἀκρόπολις ἀπότομος πανταχόθεν, τὰ μὲν πολλὰ ἔχουσα οὕτως, ὀλίγα δὲ αὐτῆς καὶ ὠχυρώσαντο ὑπὲρ ἀσφαλείας. ἐνταῦθα ἐν τῇ ἀκροπόλει ναός ἐστιν Ἀθηνᾶς ἐπίκλησιν Τριτωνίας, ἐρείπια δὲ ἐλείπετο αὐτοῦ μόνα·", "st": "8.14"}, {"sp": "N", "t": "καὶ Ποσειδῶν χαλκοῦς ἕστηκεν ἐπωνυμίαν Ἵππιος, ἀναθεῖναι δὲ τὸ ἄγαλμα τοῦ Ποσειδῶνος Ὀδυσσέα ἔφασαν· ἀπολέσθαι γὰρ ἵππους τῷ Ὀδυσσεῖ, καὶ αὐτὸν γῆν τὴν Ἑλλάδα κατὰ ζήτησιν ἐπιόντα τῶν ἵππων ἱδρύσασθαι μὲν ἱερὸν ἐνταῦθα Ἀρτέμιδος καὶ Εὑρίππαν ὀνομάσαι τὴν θεόν, ἔνθα τῆς Φενεατικῆς χώρας εὗρε τὰς ἵππους, ἀναθεῖναι δὲ καὶ τοῦ Ποσειδῶνος τὸ ἄγαλμα τοῦ Ἱππίου.", "st": "8.14"}, {"sp": "N", "t": "τῷ δὲ Ὀδυσσεῖ λέγουσιν εὑρόντι τὰς ἵππους γενέσθαι οἱ κατὰ γνώμην ἐν χώρᾳ τῇ Φενεατῶν ἔχειν ἵππους, καθάπερ γε καὶ τὰς βοῦς ἐν τῇ ἠπείρῳ τῆς Ἰθάκης ἀπαντικρὺ τρέφειν αὐτόν· καί μοι καὶ γράμματα οἱ Φενεᾶται παρείχοντο ἐπὶ τοῦ ἀγάλματος γεγραμμένα τῷ βάθρῳ, τοῦ Ὀδυσσέως δή τι πρόσταγμα τοῖς ποιμαίνουσι τὰς ἵππους.", "st": "8.14"}, {"sp": "N", "t": "τὰ μὲν δὴ ἄλλα ἑπομένοις ἡμῖν τῷ Φενεατῶν λόγῳ εἰκὸς προσέσται, τὸ δὲ ἄγαλμα Ὀδυσσέα ἀναθεῖναι τὸ χαλκοῦν οὐκ ἔχω πείθεσθαί σφισιν· οὐ γάρ πω τότε τοῦ χαλκοῦ τὰ ἀγάλματα διὰ παντὸς ἠπίσταντο ἐργάσασθαι καθάπερ ἐσθῆτα ἐξυφαίνοντες. τρόπον δὲ ὅστις ἦν αὐτοῖς ἐς τὰ χαλκᾶ ἐργασίας, ἔδειξεν ἤδη μοι τοῦ ἐς Σπαρτιάτας λόγου τὰ ἐπὶ τοῦ ἀγάλματος τοῦ Ὑπάτου Διός.", "st": "8.14"}, {"sp": "N", "t": "διέχεαν δὲ χαλκὸν πρῶτοι καὶ ἀγάλματα ἐχωνεύσαντο Ῥοῖκός τε Φιλαίου καὶ Θεόδωρος Τηλεκλέους Σάμιοι. Θεοδώρου δὲ ἔργον ἦν καὶ ἡ ἐπὶ τοῦ λίθου τῆς σμαράγδου σφραγίς, ἣν Πολυκράτης ὁ Σάμου τυραννήσας ἐφόρει τε τὰ μάλιστα καὶ ἐπ’ αὐτῇ περισσῶς δή τι ἠγάλλετο.", "st": "8.14"}, {"sp": "N", "t": "Φενεατῶν δὲ ἐκ τῆς ἀκροπόλεως καταβαίνοντι ἔστι μὲν στάδιον, ἔστι δὲ ἐπὶ λόφου μνῆμα Ἰφικλέους ἀδελφοῦ τε Ἡρακλέους καὶ Ἰολάου πατρός. Ἰόλαον μὲν δὴ τὰ πολλὰ Ἡρακλεῖ συγκάμνειν λέγουσιν Ἕλληνες· Ἰφικλῆς δὲ ὁ Ἰολάου πατήρ, ἡνίκα ἐμαχέσατο Ἡρακλῆς πρὸς Ἠλείους τε καὶ Αὐγέαν τὴν προτέραν μάχην, τότε ὑπὸ τῶν παίδων ἐτρώθη τῶν Ἄκτορος, καλουμένων δὲ ἀπὸ Μολίνης τῆς μητρός. καὶ ἤδη κάμνοντα κομίζουσιν οἱ προσήκοντες ἐς Φενεόν· ἐνταῦθα ἀνὴρ Φενεάτης αὐτὸν Βουφάγος καὶ ἡ τοῦ Βουφάγου γυνὴ Πρώμνη περιεῖπόν τε εὖ καὶ ἀποθανόντα ἐκ τοῦ τραύματος ἔθαψαν.", "st": "8.14"}, {"sp": "N", "t": "Ἰφικλεῖ μὲν δὴ καὶ ἐς τόδε ἔτι ἐναγίζουσιν ὡς ἥρωι, θεῶν δὲ τιμῶσιν Ἑρμῆν Φενεᾶται μάλιστα καὶ ἀγῶνα ἄγουσιν Ἕρμαια, καὶ ναός ἐστιν Ἑρμοῦ σφισι καὶ ἄγαλμα λίθου· τοῦτο ἐποίησεν ἀνὴρ Ἀθηναῖος Εὔχειρ Εὐβουλίδου. ὄπισθεν δέ ἐστι τοῦ ναοῦ τάφος Μυρτίλου. τοῦτον Ἑρμοῦ παῖδα εἶναι ⟨τὸν⟩ Μυρτίλον λέγουσιν Ἕλληνες, ἡνιοχεῖν δὲ αὐτὸν Οἰνομάῳ· καὶ ὁπότε ἀφίκοιτό τις μνώμενος τοῦ Οἰνομάου τὴν θυγατέρα, ὁ μὲν ἠπείγετο ὁ Μυρτίλος σὺν τέχνῃ τοῦ Οἰνομάου τὰς ἵππους, ὁ δὲ ἐν τῷ δρόμῳ τὸν μνηστῆρα, ὁπότε ἐγγὺς γένοιτο, κατηκόντιζεν.", "st": "8.14"}, {"sp": "N", "t": "Ἱπποδαμείας δὲ ἤρα μὲν καὶ αὐτὸς ὁ Μυρτίλος, ἐς δὲ τὸν ἀγῶνα ἀτόλμως ἔχων ὑπεῖκε καὶ ἡνιόχει τῷ Οἰνομάῳ. τέλος δὲ καὶ ἀναφανῆναι τοῦ Οἰνομάου προδότην φασὶν αὐτὸν ὑπαχθέντα ὅρκοις, ὥς οἱ νύκτα ὁ Πέλοψ μίαν Ἱπποδαμείᾳ συγγενέσθαι παρήσει. ἀναμιμνήσκοντα οὖν τῶν ὅρκων ὁ Πέλοψ ἐξέβαλεν ἐκ τῆς νεώς· Φενεᾶται δὲ τοῦ Μυρτίλου τὸν νεκρὸν ἐκβληθέντα ὑπὸ τοῦ κλύδωνος λέγουσιν ἀνελόμενοι θάψαι, καὶ νύκτωρ κατὰ ἔτος ἐναγίζουσιν αὐτῷ.", "st": "8.14"}, {"sp": "N", "t": "ἔστι δὲ ὁ Πέλοψ δῆλος οὐ πολλήν τινα παραπλεύσας θάλασσαν, ἀλλὰ ὅσον ἀπὸ τοῦ Ἀλφειοῦ τῶν ἐκβολῶν ἐς τὸ ἐπίνειον τὸ Ἠλείων. οὐκ ἂν οὖν τό γε πέλαγος τὸ Μυρτῷον ἀπὸ Μυρτίλου τοῦ Ἑρμοῦ φαίνοιτο κεκλημένον, ἀρχόμενόν τε ἀπὸ Εὐβοίας καὶ παρ’ Ἑλένην ἔρημον νῆσον καθῆκον ἐς τὸ Αἰγαῖον· ἀλλά μοι δοκοῦσιν Εὐβοέων οἱ τὰ ἀρχαῖα μνημονεύοντες εἰκότα εἰρηκέναι, λέγοντες ἀπὸ γυναικὸς Μυρτοῦς τῷ πελάγει γεγονέναι τὸ ὄνομα τῷ Μυρτῴῳ.", "st": "8.14"}, {"sp": "N", "t": "Φενεάταις δὲ καὶ Δήμητρός ἐστιν ἱερὸν ἐπίκλησιν Ἐλευσινίας, καὶ ἄγουσι τῇ θεῷ τελετήν, τὰ Ἐλευσῖνι δρώμενα καὶ παρὰ σφίσι τὰ αὐτὰ φάσκοντες καθεστηκέναι· ἀφικέσθαι γὰρ αὐτοῖς Ναὸν κατὰ μάντευμα ἐκ Δελφῶν, τρίτον δὲ ἀπόγονον Εὐμόλπου τοῦτον εἶναι τὸν Ναόν. παρὰ δὲ τῆς Ἐλευσινίας τὸ ἱερὸν πεποίηται Πέτρωμα καλούμενον, λίθοι δύο ἡρμοσμένοι πρὸς ἀλλήλους μεγάλοι.", "st": "8.15"}, {"sp": "N", "t": "ἄγοντες δὲ παρὰ ἔτος ἥντινα τελετὴν μείζονα ὀνομάζουσι, τοὺς λίθους τούτους τηνικαῦτα ἀνοίγουσι· λαβόντες ⟨δὲ⟩ γράμματα ἐξ αὐτῶν ἔχοντα ἐς τὴν τελετὴν καὶ ἀναγνόντες ⟨ἐς⟩ ἐπήκοον τῶν μυστῶν, κατέθεντο ἐν νυκτὶ αὖθις τῇ αὐτῇ. Φενεατῶν δὲ οἶδα τοὺς πολλοὺς καὶ ὀμνύντας ὑπὲρ μεγίστων τῷ Πετρώματι.", "st": "8.15"}, {"sp": "N", "t": "καὶ ἐπίθημα ἐπ’ αὐτῷ περιφερές ἐστιν, ἔχον ἐντὸς Δήμητρος πρόσωπον Κιδαρίας· τοῦτο ὁ ἱερεὺς περιθέμενος τὸ πρόσωπον ἐν τῇ μείζονι καλουμένῃ τελετῇ ῥάβδοις κατὰ λόγον δή τινα τοὺς ὑποχθονίους παίει. Φενεατῶν δέ ἐστι λόγος, καὶ πρὶν ἢ Ναὸν ἀφικέσθαι [γὰρ] καὶ ἐνταῦθα Δήμητρα πλανωμένην· ὅσοι δὲ Φενεατῶν οἴκῳ τε καὶ ξενίοις ἐδέξαντο αὐτήν, τούτοις τὰ ὄσπρια ἡ θεὸς τὰ ἄλλα, κύαμον δὲ οὐκ ἔδωκέ σφισι.", "st": "8.15"}, {"sp": "N", "t": "κύαμον μὲν οὖν ἐφ’ ὅτῳ μὴ καθαρὸν εἶναι νομίζουσιν ὄσπριον, ἔστιν ἱερὸς ἐπ’ αὐτῷ λόγος· οἱ δὲ τῷ Φενεατῶν λόγῳ δεξάμενοι τὴν θεόν, Τρισαύλης καὶ Δαμιθάλης, ἐποιήσαντο μὲν Δήμητρος ναὸν Θεσμίας ὑπὸ τῷ ὄρει τῇ Κυλλήνῃ, κατεστήσαντο δὲ αὐτῇ καὶ τελετήν, ἥντινα καὶ νῦν ἄγουσιν. ὁ δὲ ναὸς οὗτος τῆς Θεσμίας σταδίους πέντε μάλιστά που καὶ δέκα ἐστὶν ἀπωτέρω τῆς πόλεως.", "st": "8.15"}, {"sp": "N", "t": "ἐς δὲ Πελλήνην ἐκ Φενεοῦ καὶ ἐς Αἴγειραν ἰόντι Ἀχαιῶν πόλιν, πέντε που προεληλυθότι καὶ δέκα σταδίους, Ἀπόλλωνός ἐστι Πυθίου ναός· ἐρείπια δὲ ἐλείπετο αὐτοῦ μόνα καὶ βωμὸς μέγας λίθου λευκοῦ. ἐνταῦθα ἔτι καὶ νῦν Ἀπόλλωνι Φενεᾶται καὶ Ἀρτέμιδι θύουσιν, Ἡρακλέα ἑλόντα Ἦλιν τὸ ἱερὸν λέγοντες ποιῆσαι. ἔστι δὲ αὐτόθι καὶ ἡρώων μνήματα, ὅσοι [σὺν] Ἡρακλεῖ στρατείας ἐπὶ Ἠλείους μετασχόντες οὐκ ἀπεσώθησαν οἴκαδε ἐκ τῆς μάχης.", "st": "8.15"}, {"sp": "N", "t": "τέθαπται δὲ Τελαμὼν ἐγγύτατα τοῦ ποταμοῦ τοῦ Ἀροανίου, ἀπωτέρω μικρὸν ἢ ἔστι τὸ ἱερὸν τοῦ Ἀπόλλωνος, Χαλκώδων δὲ οὐ πόρρω κρήνης καλουμένης Οἰνόης. τὸν μὲν δὴ Ἐλεφήνορος τοῦ Εὐβοεῦσιν ἐς Ἴλιον ἡγησαμένου καὶ τὸν Αἴαντός τε καὶ Τεύκρου, τούτων μὲν τοὺς πατέρας οὐκ ἀποδέξαιτο ἄν τις ἐν τούτῳ πεσεῖν τῷ ἀγῶνι· πῶς μὲν γὰρ ⟨ἂν⟩ συνεπελάβετο Ἡρακλεῖ τοῦ ἔργου Χαλκώδων, ὃν πρότερον ἔτι ἀποκτεῖναι Ἀμφιτρύωνα καὶ μαρτυρεῖται καὶ πιστεύειν ἄξιά ἐστιν ἐν Θήβαις;", "st": "8.15"}, {"sp": "N", "t": "πῶς δὲ Τεῦκρος ᾤκισεν ἂν Σαλαμῖνα ἐν Κύπρῳ πόλιν, μηδενὸς ὡς ἀνέστρεψεν ἐκ Τροίας ἐκβαλόντος ἐκ τῆς οἰκείας; τίς δ’ ἂν ἐξήλασεν ἄλλος πλὴν ὁ Τελαμὼν αὐτόν; δῆλα οὖν ἐστι Χαλκώδοντα οὐ τὸν ἐξ Εὐβοίας καὶ Τελαμῶνα οὐ τὸν Αἰγινήτην ἐπὶ Ἠλείους Ἡρακλεῖ μετεσχηκέναι τῆς στρατείας· ὁμώνυμοι δὲ ἐπιφανέσιν ἄνδρες ἀφανέστεροι καὶ ἐφ’ ἡμῶν ἔτι καὶ τὸν ἅπαντα ἐγίνοντο ὁμοίως χρόνον.", "st": "8.15"}, {"sp": "N", "t": "Φενεάταις δὲ πρὸς τὸ Ἀχαϊκὸν τὸ ὅμορον οὐ καθ’ ἓν ὅροι τῆς γῆς εἰσιν, ἀλλὰ πρὸς μὲν Πελλήνην ὁ καλούμενος Πωρίνας, πρὸς δὲ τὴν Αἰγειρᾶτιν †τὸ ἐπ’ Ἄρτεμιν. ἐν δὲ αὐτῶν Φενεατῶν τῇ χώρᾳ μετὰ τὸ ἱερὸν τοῦ Ἀπόλλωνος τοῦ Πυθίου προήξεις τε οὐκ ἐπὶ πολὺ καὶ ἐντὸς ἔσῃ τῆς ὁδοῦ τῆς ἐπὶ τὸ ὄρος ἀγούσης τὴν Κρᾶθιν.", "st": "8.15"}, {"sp": "N", "t": "ἐν τούτῳ τῷ ὄρει τοῦ ποταμοῦ τοῦ Κράθιδός εἰσιν αἱ πηγαί· ῥεῖ δὲ ἐς θάλασσαν παρὰ Αἰγάς, ἔρημον τὰ ἐπ’ ἐμοῦ χωρίον, τὰ δὲ παλαιότερα Ἀχαιῶν πόλιν. ἀπὸ τούτου δὲ καλεῖται τοῦ Κράθιδος καὶ ἐν Ἰταλίᾳ ποταμὸς ἐν γῇ τῇ Βρεττίων· ἐν δὲ τῇ Κράθιδι τῷ ὄρει Πυρωνίας ἱερόν ἐστιν Ἀρτέμιδος, καὶ τὰ ἔτι ἀρχαιότερα παρὰ τῆς θεοῦ ταύτης ἐπήγοντο Ἀργεῖοι πῦρ ἐς τὰ Λερναῖα.", "st": "8.15"}, {"sp": "N", "t": "ἐκ δὲ Φενεοῦ πρὸς ἥλιον ἰόντι ἀνίσχοντα ὄρους ἐστὶν ἄκρα Γερόντειον καὶ κατὰ ταύτην ὁδός· Φενεάταις δὲ ὅροι πρὸς Στυμφαλίους τῆς γῆς τοῦτό ἐστι τὸ Γερόντειον. τοῦ Γεροντείου δὲ ἐν ἀριστερᾷ διὰ τῆς Φενεατικῆς ὁδεύοντι ὄρη Φενεατῶν ἐστι Τρίκρηνα καλούμενα, καὶ εἰσὶν αὐτόθι κρῆναι τρεῖς· ἐν ταύταις λοῦσαι τεχθέντα Ἑρμῆν αἱ περὶ τὸ ὄρος λέγονται νύμφαι, καὶ ἐπὶ τούτῳ τὰς πηγὰς ἱερὰς Ἑρμοῦ νομίζουσιν.", "st": "8.16"}, {"sp": "N", "t": "Τρικρήνων δὲ οὐ πόρρω ἄλλο ἐστὶν ὄρος Σηπία, καὶ Αἰπύτῳ τῷ Ἐλάτου λέγουσιν ἐνταῦθα γενέσθαι τὴν τελευτὴν ἐκ τοῦ ὄφεως, καί οἱ καὶ τὸν τάφον ἐποίησαν αὐτόθι· οὐ γὰρ οἷά τε ἦν σφισιν ἐς τὸ πρόσω φέρειν τὸν νεκρόν. τούτους οἱ Ἀρκάδες τοὺς ὄφεις γίνεσθαι καὶ ἐφ’ ἡμῶν ἔτι ἐν τῷ ὄρει φασίν, οὐ μέντοι πολλούς γε ἀλλὰ καὶ μάλιστα σπανίους· ἅτε γὰρ τοῦ ἔτους τὸ πολὺ νειφομένου τοῦ ὄρους, οἵ τε ἀποληφθέντες τῶν φωλεῶν ἐκτὸς ὑπὸ τῆς χιόνος διαφθείρονται, καὶ ἢν πρότερον καταφυγόντες τύχωσιν ἐς τὰ φωλεά, ὅμως ἡ χιὼν μέρος τι αὐτῶν ἀπόλλυσιν, ἅτε καὶ ἐς αὐτὰ τὰ φωλεὰ καθικνουμένου τοῦ κρυμοῦ.", "st": "8.16"}, {"sp": "N", "t": "τὸν δὲ τοῦ Αἰπύτου τάφον σπουδῇ μάλιστα ἐθεασάμην, ὅτι ἐν τοῖς ἐς τοὺς Ἀρκάδας ἔπεσιν ἔσχεν Ὅμηρος λόγον τοῦ· Αἰπύτου μνήματος. ἔστι μὲν οὖν γῆς χῶμα οὐ μέγα, λίθου κρηπῖδι ἐν κύκλῳ περιεχόμενον· Ὁμήρῳ δὲ— οὐ γὰρ εἶδεν ἀξιολογώτερον μνῆμα—εἰκότως παρέξειν ἔμελλε θαῦμα, ἐπεὶ καὶ Ἡφαίστου τὸν χορὸν ἐπὶ τῇ Ἀχιλλέως ἀσπίδι εἰργασμένον εἰκάζει χορῷ Δαιδάλου ποιηθέντι, σοφώτερα οὐ θεασάμενος.", "st": "8.16"}, {"sp": "N", "t": "τάφους δὲ ἀξίους θαύματος ἐπιστάμενος πολλοὺς δυοῖν ἐξ αὐτῶν ἐπιμνησθήσομαι, τοῦ τε ἐν Ἁλικαρνασσῷ καὶ ἐν τῇ Ἑβραίων. ὁ μὲν δὴ ἐν Ἁλικαρνασσῷ Μαυσώλῳ βασιλεύσαντι Ἁλικαρνασσέων πεποίηται, μέγεθος δὲ οὕτω δή τί ἐστι μέγας καὶ ἐς κατασκευὴν περίβλεπτος τὴν πᾶσαν, ὥστε καὶ Ῥωμαῖοι μεγάλως δή τι αὐτὸν θαυμάζοντες τὰ παρὰ σφίσιν ἐπιφανῆ μνήματα Μαυσώλεια ὀνομάζουσιν·", "st": "8.16"}, {"sp": "N", "t": "Ἑβραίοις δὲ Ἑλένης γυναικὸς ἐπιχωρίας τάφος ἐστὶν ἐν πόλει Σολύμοις, ἣν ἐς ἔδαφος κατέβαλεν ὁ Ῥωμαίων βασιλεύς. μεμηχάνηται δὲ ἐν τῷ τάφῳ τὴν θύραν, ὁμοίως παντὶ οὖσαν τῷ τάφῳ λιθίνην, μὴ πρότερον ἀνοίγεσθαι, πρὶν ἂν ἡμέραν τε ἀεὶ καὶ ὥραν τὸ ἔτος ἐπαγάγῃ τὴν αὐτήν· τότε δὲ ὑπὸ μόνου τοῦ μηχανήματος ἀνοιχθεῖσα καὶ οὐ πολὺ ἐπισχοῦσα συνεκλείσθη δι’ ἑαυτῆς. τοῦτον μὲν δὴ οὕτω, τὸν δὲ ἄλλον χρόνον ἀνοῖξαι πειρώμενος ἀνοίξαις μὲν οὐκ ἄν, κατάξεις δὲ αὐτὴν πρότερον βιαζόμενος.", "st": "8.16"}, {"sp": "N", "t": "μετὰ δὲ τοῦ Αἰπύτου τὸν τάφον ὄρος τε ὑψηλότατον ὀρῶν τῶν ἐν Ἀρκαδίᾳ Κυλλήνη καὶ Ἑρμοῦ Κυλληνίου κατερριμμένος ναός ἐστιν ἐπὶ κορυφῆς τοῦ ὄρους· δῆλα δέ ἐστιν ἀπὸ Κυλλῆνος τοῦ Ἐλάτου τῷ τε ὄρει τὸ ὄνομα καὶ ἡ ἐπίκλησις γεγενημένη τῷ θεῷ.", "st": "8.17"}, {"sp": "N", "t": "τοῖς δὲ ἀνθρώποις τὸ ἀρχαῖον, ὁπόσα καὶ ἡμεῖς καταμαθεῖν ἐδυνήθημεν, τοσάδε ἦν ἀφ’ ὧν τὰ ξόανα ἐποιοῦντο, ἔβενος, κυπάρισσος, αἱ κέδροι, τὰ δρύινα, ἡ μῖλαξ, ὁ λωτός· τῷ δὲ Ἑρμῇ τῷ Κυλληνίῳ τούτων μὲν ἀπὸ οὐδενός, θύου δὲ πεποιημένον τὸ ἄγαλμά ἐστιν, ὀκτὼ δὲ εἶναι ποδῶν μάλιστα αὐτὸ εἰκάζομεν.", "st": "8.17"}, {"sp": "N", "t": "παρέχεται δὲ καὶ θαῦμα τοιόνδε ἡ Κυλλήνη· κόσσυφοι γὰρ οἱ ὄρνιθες ⟨ὁλόλευκοί⟩ εἰσιν ἐν αὐτῇ· οἱ δὲ ὑπὸ Βοιωτῶν καλούμενοι γένος ἄλλο πού τί εἰσιν ὀρνίθων, οὐκ ᾠδικόν. ἀετοὺς μὲν οὖν ὀνομαζομένους κυκνίας μάλιστα ἐοικότας κύκνῳ λευκότητα οἶδα ἐν Σιπύλῳ θεασάμενος περὶ λίμνην καλουμένην Ταντάλου· ὗς δὲ ἀγρίους λευκοὺς καὶ ἄρκτους τῶν Θρᾳκίων λευκὰς ἤδη που καὶ ἄνδρες ἐκτήσαντο ἰδιῶται·", "st": "8.17"}, {"sp": "N", "t": "λαγῲ δὲ καὶ ἔλαφοι, τὸ μὲν Λιβυκὸν θρέμμα οἱ λαγῴ εἰσιν ⟨οἱ⟩ λευκοί, ἐλάφους δὲ ἐν Ῥώμῃ λευκὰς εἶδόν τε καὶ ἰδὼν θαῦμα ἐποιησάμην, ὁπόθεν δὲ ἢ τῶν ἠπείρων οὖσαι ἢ νησιώτιδες ἐκομίσθησαν, οὐκ ἐπῆλθεν ἐρέσθαι μοι. τάδε μὲν ἡμῖν λελέχθω τῶν ἐν Κυλλήνῃ κοσσύφων ἕνεκα, ὡς μὴ τοῖς ῥηθεῖσιν ἐς τὴν χρόαν αὐτῶν ἀπιστοίη μηδείς·", "st": "8.17"}, {"sp": "N", "t": "ἔχεται δὲ ἄλλο ὄρος Κυλλήνης Χελυδόρεα, ἔνθα εὑρὼν χελώνην Ἑρμῆς ἐκδεῖραι τὸ θηρίον καὶ ἀπ’ αὐτῆς λέγεται ποιήσασθαι λύραν. ἐνταῦθα Φενεάταις καὶ Πελληνεῦσιν ὅροι τῆς γῆς εἰσι, καὶ τοῦ ὄρους τῶν Χελυδορέων οἱ Ἀχαιοὶ τὸ πλέον νέμονται.", "st": "8.17"}, {"sp": "N", "t": "ἐκ Φενεοῦ δὲ ἰόντι ἐπὶ [τὴν] ἑσπέρας καὶ ἡλίου δυσμῶν ἡ μὲν ἀριστερὰ τῶν ὁδῶν ἐς πόλιν ἄγει Κλείτορα, ἐν δεξιᾷ δὲ ἐπὶ Νώνακριν καὶ τὸ ὕδωρ τῆς Στυγός. τὸ μὲν δὴ ἀρχαῖον ἡ Νώνακρις πόλισμα ἦν Ἀρκάδων καὶ ἀπὸ τῆς Λυκάονος γυναικὸς τὸ ὄνομα εἰλήφει· τὰ δὲ ἐφ’ ἡμῶν ἐρείπια ἦν, οὐδὲ τούτων τὰ πολλὰ ἔτι δῆλα. τῶν δὲ ἐρειπίων οὐ πόρρω κρημνός ἐστιν ὑψηλός, οὐχ ἕτερον δ’ ἐς τοσοῦτον ἀνήκοντα ὕψους οἶδα· καὶ ὕδωρ κατὰ τοῦ κρημνοῦ στάζει, καλοῦσι δὲ Ἕλληνες αὐτὸ ὕδωρ Στυγός.", "st": "8.17"}, {"sp": "N", "t": "εἶναι δὲ τὴν Στύγα Ἡσίοδος μὲν ἐν Θεογονίᾳ πεποίηκεν—Ἡσιόδου γὰρ δὴ ἔπη τὴν Θεογονίαν εἰσὶν οἳ νομίζουσι—, πεποιημένα οὖν ἐστιν ἐνταῦθα Ὠκεανοῦ θυγατέρα τὴν Στύγα, γυναῖκα δὲ αὐτὴν εἶναι Πάλλαντος. ἐοικότα δὲ πεποιηκέναι τούτοις καὶ Λίνον φασίν· ἐμοὶ δὲ ἐπιλεγομένῳ παντάπασιν ἐφαίνετο ταῦτά γε εἶναι κίβδηλα.", "st": "8.18"}, {"sp": "N", "t": "Ἐπιμενίδης δὲ ὁ Κρὴς εἶναι μὲν καὶ οὗτος θυγατέρα Ὠκεανοῦ τὴν Στύγα ἐποίησε, συνοικεῖν δὲ αὐτὴν οὐ Πάλλαντι, ἀλλὰ ἐκ Πείραντος Ἔχιδναν τεκεῖν, ὅστις δὴ ὁ Πείρας ἐστί. μάλιστα δὲ τῆς Στυγὸς τὸ ὄνομα ἐς τὴν ποίησιν ἐπεισηγάγετο Ὅμηρος. ἐν μέν γε Ἥρας ἐποίησεν ὅρκῳ<br>ἴστω νῦν τόδε γαῖα καὶ οὐρανὸς εὐρὺς ὕπερθεν<br>καὶ τὸ κατειβόμενον Στυγὸς ὕδωρ·<br>ταῦτα μὲν δὴ ἐποίησεν ὡς ἂν ἰδὼν ἐς τὸ ὕδωρ τῆς Στυγὸς στάζον· βούλεται δὲ καὶ ἐν καταλόγῳ τῶν μετὰ Γουνέως Τιταρησίῳ ποταμῷ ῥεῖν τὸ ὕδωρ ἀπὸ τῆς Στυγός.", "st": "8.18"}, {"sp": "N", "t": "ἐποίησε δὲ καὶ ἐν Ἅιδου ὕδωρ εἶναι, καὶ Ἀθηνᾶ τὸν Δία οὐ μεμνῆσθαί φησιν ὅτι δι’ αὐτῆς Ἡρακλέα ἔσωζεν ἐκ τῶν Εὐρυσθέως ἄθλων·<br>εἰ γὰρ ἐγὼ τόδε ᾔδη ἐνὶ φρεσὶ πευκαλίμῃσιν,<br>εὖτέ μιν εἰς Ἀίδαο πυλάρταο προὔπεμψεν<br>ἐξ Ἐρέβευς ἄξοντα κύνα στυγεροῦ Ἀίδαο,<br>οὐκ ἂν ὑπεξέφυγε Στυγὸς ὕδατος αἰπὰ ῥέεθρα.", "st": "8.18"}, {"sp": "N", "t": "τὸ δὲ ὕδωρ τὸ ἀπὸ τοῦ κρημνοῦ τοῦ παρὰ τὴν Νώνακριν στάζον ἐσπίπτει μὲν πρῶτον ἐς πέτραν ὑψηλήν, διεξελθὸν δὲ διὰ τῆς πέτρας ἐς τὸν Κρᾶθιν ποταμὸν κάτεισι· θάνατον δὲ τὸ ὕδωρ φέρει τοῦτο καὶ ἀνθρώπῳ καὶ ἄλλῳ ζῴῳ παντί. λέγεται δὲ ὅτι γένοιτό ποτε ὄλεθρος ἀπ’ αὐτοῦ καὶ αἰξίν, αἳ τοῦ ὕδατος ἔπιον πρῶτον· χρόνῳ δὲ ὕστερον ἐγνώσθη καὶ εἰ δή τι ἄλλο πρόσεστι τῷ ὕδατι τῶν ἐς θαῦμα ἡκόντων.", "st": "8.18"}, {"sp": "N", "t": "ὕαλος μέν γε καὶ κρύσταλλος καὶ μόρρια καὶ ὅσα ἐστὶν ἀνθρώποις ἄλλα λίθου ποιούμενα καὶ τῶν σκευῶν τὰ κεραμεᾶ, τὰ μὲν ὑπὸ τῆς Στυγὸς τοῦ ὕδατος ῥήγνυται· κεράτινα δὲ καὶ ὀστέινα σίδηρός τε καὶ χαλκός, ἔτι δὲ μόλιβδός τε καὶ κασσίτερος καὶ ἄργυρος καὶ τὸ ἤλεκτρον ὑπὸ τούτου σήπεται τοῦ ὕδατος. τὸ δὲ αὐτὸ [ἐν] μετάλλοις τοῖς πᾶσι καὶ ὁ χρυσὸς πέπονθε· καίτοι [γε] καθαρεύειν γε τὸν χρυσὸν ἀπὸ τοῦ ἰοῦ ἥ τε ποιήτρια μάρτυς ἐστὶν ἡ Λεσβία καὶ αὐτὸς ὁ χρυσὸς ἐπιδείκνυσιν.", "st": "8.18"}, {"sp": "N", "t": "ἔδωκε δὲ ἄρα ὁ θεὸς τοῖς μάλιστα ἀπερριμμένοις κρατεῖν τῶν ὑπερηρκότων τῇ δόξῃ. τοῦτο μὲν γὰρ τὰ μάργαρα ἀπόλλυσθαι πέφυκεν ὑπὸ τοῦ ὄξους, τοῦτο δὲ τὸν ἀδάμαντα λίθων ὄντα ἰσχυρότατον τοῦ τράγου κατατήκει τὸ αἷμα· καὶ δὴ καὶ τὸ ὕδωρ οὐ δύναται τῆς Στυγὸς ὁπλὴν ἵππου βιάσασθαι μόνην, ἀλλὰ ἐμβληθὲν κατέχεταί τε ὑπ’ αὐτῆς καὶ οὐ διεργάζεται τὴν ὁπλήν. εἰ δὲ καὶ Ἀλεξάνδρου τοῦ Φιλίππου συνέβη τὴν τελευτὴν διὰ τοῦ φαρμάκου γενέσθαι τούτου, σαφῶς μὲν οὐκ οἶδα, λεγόμενον δὲ οἶδα.", "st": "8.18"}, {"sp": "N", "t": "ὑπὲρ δὲ τὴν Νώνακριν ὄρη τε καλούμενα Ἀροάνια καὶ σπήλαιόν ἐστιν ἐν αὐτοῖς. ἐς τοῦτο ἀναφυγεῖν τὸ σπήλαιον τὰς θυγατέρας τὰς Προίτου μανείσας λέγουσιν, ἃς ὁ Μελάμπους θυσίαις τε ἀπορρήτοις καὶ καθαρμοῖς κατήγαγεν ἐς χωρίον καλούμενον Λουσούς. τοῦ μὲν δὴ ὄρους τῶν Ἀροανίων Φενεᾶται τὰ πολλὰ ἐνέμοντο· οἱ δὲ ἐν ὅροις ἤδη Κλειτορίων εἰσὶν οἱ Λουσοί.", "st": "8.18"}, {"sp": "N", "t": "πόλιν μὲν δή ποτε εἶναι λέγουσι τοὺς Λουσούς, καὶ Ἀγησίλας ἀνὴρ Λουσεὺς ἀνηγορεύθη κέλητι ἵππῳ νικῶν, ὅτε πρώτην ἐπὶ ταῖς δέκα ἐτίθεσαν πυθιάδα Ἀμφικτύονες· τὰ δὲ ἐφ’ ἡμῶν οὐδὲ ἐρείπια ἔτι λειπόμενα ἦν Λουσῶν. τὰς δ’ οὖν θυγατέρας τοῦ Προίτου κατήγαγεν ὁ Μελάμπους ἐς τοὺς Λουσοὺς καὶ ἠκέσατο τῆς μανίας ἐν Ἀρτέμιδος ἱερῷ· καὶ ἀπ’ ἐκείνου τὴν Ἄρτεμιν ταύτην Ἡμερασίαν καλοῦσιν οἱ Κλειτόριοι.", "st": "8.18"}, {"sp": "N", "t": "εἰσὶ δέ τινες γένους μὲν καὶ οὗτοι τῶν Ἀρκάδων, ὄνομα δέ σφισι Κυναιθαεῖς, οἳ καὶ ἐν Ὀλυμπίᾳ τὸ ἄγαλμα ἀνέθεσαν τοῦ Διός, κεραυνὸν ἐν ἑκατέρᾳ ἔχοντα τῇ χειρί· οὗτοι οἱ Κυναιθαεῖς τεσσαράκοντα ἀπωτέρω ⟨Λουσῶν⟩ σταδίοις μᾶλλον οἰκοῦσι, καί σφισιν ἐν ἀγορᾷ πεποίηνται μὲν θεῶν βωμοί, πεποίηται δὲ Ἀδριανοῦ βασιλέως εἰκών.", "st": "8.19"}, {"sp": "N", "t": "τὰ δὲ μάλιστα ἥκοντα ἐς μνήμην Διονύσου ἐστὶν ἐνταῦθα ἱερόν, καὶ ἑορτὴν ὥρᾳ ἄγουσι χειμῶνος, ἐν ᾗ λίπα ἀληλιμμένοι ἄνδρες ἐξ ἀγέλης βοῶν ταῦρον, ὃν ἄν σφισιν ἐπὶ νοῦν αὐτὸς ὁ θεὸς ποιήσῃ, ἀράμενοι κομίζουσι πρὸς τὸ ἱερόν. θυσία μὲν τοιαύτη σφίσι καθέστηκε· πηγὴ δέ ἐστιν αὐτόθι ὕδατος ψυχροῦ, δύο μάλιστα ἀπὸ τοῦ ἄστεως ἀπωτέρω σταδίοις, καὶ ὑπὲρ αὐτῆς πλάτανος πεφυκυῖα.", "st": "8.19"}, {"sp": "N", "t": "ὃς δ’ ἂν ὑπὸ κυνὸς κατασχέτου λύσσῃ ἤτοι ἕλκος ἢ καὶ ἄλλως κίνδυνον εὕρηται, τὸ ὕδωρ οἱ πίνοντι ἴαμα· καὶ Ἄλυσσον τοῦδε ἕνεκα ὀνομάζουσι τὴν πηγήν· καὶ οὕτω φαίνοιτο ἂν Ἀρκάσι τὸ μὲν πρὸς Φενεῷ ὕδωρ, ὃ Στύγα ὀνομάζουσιν, ἐπ’ ἀνθρώπου συμφορᾷ ἀνευρημένον, ἡ δὲ πηγὴ ⟨ἡ⟩ ἐν Κυναιθαεῦσιν ἀγαθὸν οὖσα ἀντίρροπον τῷ ἐκεῖ πήματι.", "st": "8.19"}, {"sp": "N", "t": "λείπεται δὲ ἐκ Φενεοῦ τῶν ὁδῶν, αἵ εἰσι πρὸς ἡλίου δυσμῶν, ἡ ἐν ἀριστερᾷ. αὕτη δὲ ἡ ὁδὸς ἄγει μὲν ἐς Κλείτορα, καθήκει δὲ παρὰ τοῦ Ἡρακλέους τὸ ἔργον, ὃ τῷ ποταμῷ ῥεῦμα ἐποίησεν εἶναι τῷ Ἀροανίῳ. παρὰ τοῦτο ἡ ὁδὸς κάτεισιν ἐπὶ χωρίον Λυκουρίαν, καὶ ἔστι Φενεάταις ἡ Λυκουρία πρὸς Κλειτορίους ὅροι τῆς γῆς.", "st": "8.19"}, {"sp": "N", "t": "προελθόντων δὲ σταδίους ὡς πεντήκοντα ἐκ Λυκουρίας, ἐπὶ τοῦ Λάδωνος ἀφίξῃ τὰς πηγάς· ἤκουσα δὲ ὡς τὸ ὕδωρ ⟨τὸ⟩ λιμνάζον ἐν τῇ Φενεατικῇ, κατερχόμενον ἐς τὰ βάραθρα τὰ ἐν τοῖς ὄρεσιν, ἄνεισιν ἐνταῦθα καὶ ποιεῖ τῷ Λάδωνι τὰς πηγάς. τοῦτο μὲν δὴ οὐκ ἔχω σαφῶς εἰπεῖν, εἴτε οὕτως εἴτε ἄλλως ἐστὶν ἔχον· ὁ δὲ Λάδων ποταμῶν τῶν ἐν Ἑλλάδι ὕδωρ παρέχεται κάλλιστον, ἔχει δὲ καὶ ἄλλως ἐς ἀνθρώπους φήμην Δάφνης τε εἵνεκα καὶ †τὰ ᾀδόμενα ἐς τὴν Δάφνην.", "st": "8.20"}, {"sp": "N", "t": "τοῦ λόγου δὲ τοῦ ἐς Δάφνην τὰ μὲν Σύροις τοῖς οἰκοῦσιν ἐπὶ Ὀρόντῃ ποταμῷ παρίημι, λέγεται δὲ καὶ ἄλλα τοιάδε ὑπὸ Ἀρκάδων καὶ Ἠλείων. Οἰνομάῳ τῷ δυναστεύσαντι ἐν Πίσῃ Λεύκιππος ἦν υἱός. οὗτος ἐρασθεὶς Δάφνης ὁ Λεύκιππος ἐκ μὲν τοῦ εὐθέος μνώμενος γυναῖκα ἕξειν ἀπεγίνωσκεν αὐτὴν ἅτε ἅπαν τὸ ἄρσεν γένος φεύγουσαν· παρέστη δέ οἱ τοιόνδε ἐς αὐτὴν σόφισμα.", "st": "8.20"}, {"sp": "N", "t": "ἔτρεφεν ὁ Λεύκιππος κόμην τῷ Ἀλφειῷ· ταύτην οἷα δὴ παρθένος πλεξάμενος τὴν κόμην καὶ ἐσθῆτα ἐνδὺς γυναικείαν ἀφίκετο ὡς τὴν Δάφνην, ἐλθὼν δὲ Οἰνομάου τε ἔλεγεν εἶναι θυγάτηρ καὶ ὡς συνθηρᾶν ἐθέλοι τῇ Δάφνῃ. ἅτε δὲ εἶναι παρθένος νομιζόμενος, καὶ τὰς ἄλλας ὑπερβεβλημένος παρθένους γένους τε ἀξιώματι καὶ σοφίᾳ τῇ ἐς τὰ κυνηγέσια, πρὸς δὲ καὶ τῇ θεραπείᾳ περισσῇ χρώμενος, ἐς φιλίαν ἰσχυρὰν ἐπάγεται τὴν Δάφνην.", "st": "8.20"}, {"sp": "N", "t": "οἱ δὲ τὸν Ἀπόλλωνος ἔρωτα ἐς αὐτὴν ᾄδοντες καὶ τάδε ἐπιλέγουσιν, Ἀπόλλωνα Λευκίππῳ νεμεσῆσαι τῆς ἐς τὸν ἔρωτα εὐδαιμονίας. αὐτίκα δὲ ἐπεθύμησεν ἐν τῷ Λάδωνι ἡ Δάφνη καὶ αἱ λοιπαὶ παρθένοι νήχεσθαι, καὶ τὸν Λεύκιππον ἀποδύουσιν ἄκοντα· ἰδοῦσαι δὲ οὐ παρθένον τοῖς τε ἀκοντίοις αὐτὸν καὶ ἐγχειριδίοις τύπτουσαι διέφθειραν.", "st": "8.20"}, {"sp": "N", "t": "ταῦτα μὲν δὴ οὕτω λέγουσι· τοῦ Λάδωνος δὲ τῶν πηγῶν ἀπέχει στάδια ἑξήκοντα ἡ Κλειτορίων πόλις, ἡ δὲ ὁδὸς ἡ ἀπὸ τῶν πηγῶν τοῦ Λάδωνός ἐστιν αὐλὼν στενὸς παρὰ τὸν Ἀροάνιον ποταμόν. πρὸς δὲ τῇ πόλει διαβήσῃ ποταμὸν καλούμενον Κλείτορα. ἐκδίδωσιν οὖν ὁ Κλείτωρ ἐς τὸν Ἀροάνιον, οὐ πλέον τῆς πόλεως σταδίους ἀπέχοντα ἑπτά.", "st": "8.21"}, {"sp": "N", "t": "εἰσὶ δὲ ἰχθῦς ἐν τῷ Ἀροανίῳ καὶ ἄλλοι καὶ οἱ ποικιλίαι καλούμενοι· τούτους λέγουσι τοὺς ποικιλίας φθέγγεσθαι κίχλῃ τῇ ὄρνιθι ἐοικός. ἐγὼ δὲ ἀγρευθέντας μὲν εἶδον, φθεγγομένων δὲ ἤκουσα οὐδὲν καταμείνας πρὸς τῷ ποταμῷ καὶ ἐς ἡλίου δυσμάς, ὅτε δὴ φθέγγεσθαι μάλιστα ἐλέγοντο οἱ ἰχθῦς.", "st": "8.21"}, {"sp": "N", "t": "τῇ δὲ Κλειτορίων πόλει τὸ μὲν ὄνομα ἀπὸ τοῦ παιδὸς ἐτέθη τοῦ Ἀζᾶνος, οἰκεῖται ⟨δ’⟩ ἐν ὁμαλῷ, κύκλῳ δὲ ὄρη περιέχοντά ἐστιν οὐ μεγάλα. Κλειτορίοις δὲ ἱερὰ τὰ ἐπιφανέστατα Δήμητρος τό τε Ἀσκληπιοῦ, τρίτον δέ ἐστιν Εἰλειθυίας … εἶναι, καὶ ἀριθμὸν ἐποίησεν οὐδένα ἐπ’ αὐτοῖς· Λύκιος δὲ Ὠλὴν ἀρχαιότερος τὴν ἡλικίαν, Δηλίοις ὕμνους καὶ ἄλλους ποιήσας καὶ ἐς Εἰλείθυιαν [τε], εὔλινόν τε αὐτὴν ἀνακαλεῖ— δῆλον ὡς τῇ πεπρωμένῃ τὴν αὐτήν—καὶ Κρόνου πρεσβυτέραν φησὶν εἶναι.", "st": "8.21"}, {"sp": "N", "t": "Κλειτορίοις δὲ καὶ Διοσκούρων, καλουμένων δὲ θεῶν Μεγάλων ἐστὶν ἱερὸν ὅσον τέσσαρα ἀπέχον στάδια ἀπὸ τῆς πόλεως· καὶ ἀγάλματά ἐστιν αὐτοῖς χαλκᾶ. πεποίηται δὲ καὶ ἐπὶ ὄρους κορυφῆς σταδίοις τριάκοντα ἀπωτέρω τῆς πόλεως ναὸς καὶ ἄγαλμα Ἀθηνᾶς Κορίας.", "st": "8.21"}, {"sp": "N", "t": "ἐπανάγει δὲ ὁ λόγος με ἐπὶ Στύμφαλον καὶ ἐπὶ τοὺς Φενεατῶν καὶ Στυμφαλίων ὅρους, τὸ ὀνομαζόμενον Γερόντειον. Στυμφάλιοι δὲ τεταγμένοι μὲν οὐ μετὰ Ἀρκάδων ἔτι εἰσὶν, ἀλλὰ ἐς τὸ Ἀργολικὸν συντελοῦσι μεταστάντες ἐς αὐτὸ ἐθελονταί· γένους δὲ εἶναι σφᾶς τοῦ Ἀρκάδων τὰ ἔπη μαρτυρεῖ τὰ Ὁμήρου, καὶ ὁ Στύμφαλος ὁ οἰκιστὴς ἀπόγονος ἦν τρίτος Ἀρκάδος τοῦ Καλλιστοῦς. λέγεται δὲ ἐξ ἀρχῆς ἑτέρωθι οἰκισθῆναι τῆς χώρας καὶ οὐκ ἐς τὴν ἐφ’ ἡμῶν πόλιν.", "st": "8.22"}, {"sp": "N", "t": "ἐν δὲ τῇ Στυμφάλῳ τῇ ἀρχαίᾳ Τήμενόν φασιν οἰκῆσαι τὸν Πελασγοῦ καὶ Ἥραν ὑπὸ τοῦ Τημένου τραφῆναι τούτου καὶ αὐτὸν ἱερὰ τῇ θεῷ τρία ἱδρύσασθαι καὶ ἐπικλήσεις τρεῖς ἐπ’ αὐτῇ θέσθαι· παρθένῳ μὲν ἔτι οὔσῃ Παιδί, γημαμένην δὲ [ἔτι] τῷ Διὶ ἐκάλεσεν αὐτὴν Τελείαν, διενεχθεῖσαν δὲ ἐφ’ ὅτῳ δὴ ἐς τὸν Δία καὶ ἐπανήκουσαν ἐς τὴν Στύμφαλον ὠνόμασεν ὁ Τήμενος Χήραν. τάδε μὲν ὑπὸ Στυμφαλίων λεγόμενα οἶδα ἐς τὴν θεόν·", "st": "8.22"}, {"sp": "N", "t": "ἡ δὲ ἐφ’ ἡμῶν πόλις τῶν μὲν εἰρημένων οὐδέν, ἄλλα δὲ εἶχε τοσάδε. ἔστιν ἐν τῇ Στυμφαλίων πηγή, καὶ ἀπὸ ταύτης ὕδωρ βασιλεὺς Ἀδριανὸς Κορινθίοις ἤγαγεν ἐς τὴν πόλιν. ἐν δὲ τῇ Στυμφάλῳ χειμῶνος μὲν ὥρᾳ λίμνην τε οὐ μεγάλην ἡ πηγὴ καὶ ἀπ’ αὐτῆς ποταμὸν ποιεῖ τὸν Στύμφαλον· ἐν θέρει δὲ προλιμνάζει μὲν οὐδὲν ἔτι, ποταμὸς δὲ αὐτίκα ἐστὶν ἀπὸ τῆς πηγῆς. οὗτος ἐς χάσμα γῆς κάτεισιν ὁ ποταμός, ἀναφαινόμενος δὲ αὖθις ἐν τῇ Ἀργολίδι μεταβάλλει τὸ ὄνομα, καὶ αὐτὸν ἀντὶ Στυμφάλου καλοῦσιν Ἐρασῖνον.", "st": "8.22"}, {"sp": "N", "t": "ἐπὶ δὲ τῷ ὕδατι τῷ ἐν Στυμφάλῳ κατέχει λόγος ὄρνιθάς ποτε ἀνδροφάγους ἐπ’ αὐτῷ τραφῆναι· ταύτας κατατοξεῦσαι τὰς ὄρνιθας Ἡρακλῆς λέγεται. Πείσανδρος δὲ αὐτὸν ὁ Καμιρεὺς ἀποκτεῖναι τὰς ὄρνιθας οὔ φησιν, ἀλλὰ ὡς ψόφῳ κροτάλων ἐκδιώξειεν αὐτάς. γῆς δὲ τῆς Ἀράβων ἡ ἔρημος παρέχεται καὶ ἄλλα θηρία καὶ ὄρνιθας καλουμένας Στυμφαλίδας, λεόντων καὶ παρδάλεων οὐδέν τι ἡμερωτέρας ἀνθρώποις·", "st": "8.22"}, {"sp": "N", "t": "αὗται τοῖς ἐπὶ ἄγραν αὐτῶν ἀφικνουμένοις ἐπιπέτανται, καὶ τιτρώσκουσί τε τοῖς ῥάμφεσι καὶ ἀποκτείνουσιν. ὅσα μὲν δὴ χαλκοῦ καὶ σιδήρου φοροῦσιν ἄνθρωποι, διατρυπῶσιν αἱ ὄρνιθες· ἢν δὲ ἐσθῆτα φλοΐνην παχεῖαν πλέξωνται, τὰ ῥάμφη τῶν Στυμφαλίδων ὑπὸ τῆς ἐσθῆτος ἔχεται τῆς φλοΐνης, καθὰ καὶ πτέρυγες ὀρνίθων τῶν μικρῶν προσέχονται τῷ ἰξῷ. αὗται μέγεθος μὲν κατὰ γέρανόν εἰσιν αἱ ὄρνιθες, ἐοίκασι δὲ ἴβεσι, ῥάμφη δὲ ἀλκιμώτερα φέρουσι καὶ οὐ σκολιὰ ὥσπερ αἱ ἴβεις.", "st": "8.22"}, {"sp": "N", "t": "εἰ μὲν δὴ καὶ αἱ κατ’ ἐμὲ ὄρνιθες αἱ Ἀράβιοι τῶν ἐν Ἀρκαδίᾳ ποτὲ ὀρνίθων τὸ ὄνομα, εἶδος δὲ ⟨οὐ⟩ τὸ αὐτὸ ἐκείναις ἔχουσιν, οὐκ οἶδα· εἰ δὲ τὸν πάντα αἰῶνα κατὰ τὰ αὐτὰ ἱέραξι καὶ ἀετοῖς καὶ Στυμφαλίδες εἰσὶν ὄρνιθες, Ἀράβιόν τε εἶναί μοι θρέμμα αἱ ὄρνιθες αὗται φαίνονται, καὶ δύναιτο ἂν πετομένη ποτὲ ἀπόμοιρα ἐξ αὐτῶν ἐς Ἀρκαδίαν ἀφικέσθαι ἐπὶ Στύμφαλον. ὑπὸ μὲν δὴ τῶν Ἀράβων ἄλλο ⟨τί⟩ που ἐξ ἀρχῆς καλοῖντο ἂν καὶ οὐ Στυμφαλίδες· τοῦ Ἡρακλέους δὲ ἡ δόξα καὶ τὸ Ἑλληνικὸν πρὸ τοῦ βαρβαρικοῦ τετιμημένον ἐξενίκησεν ὡς καὶ τὰς ἐν τῇ ἐρήμῳ τῇ Ἀράβων Στυμφαλίδας ⟨καὶ⟩ ἐπὶ ἡμῶν ὀνομάζεσθαι.", "st": "8.22"}, {"sp": "N", "t": "ἐν Στυμφάλῳ δὲ καὶ ἱερὸν Ἀρτέμιδός ἐστιν ἀρχαῖον Στυμφαλίας· τὸ δὲ ἄγαλμα ξόανόν ἐστι τὰ πολλὰ ἐπίχρυσον. πρὸς δὲ τοῦ ναοῦ τῷ ὀρόφῳ πεποιημέναι καὶ οἱ Στυμφαλίδες εἰσὶν ὄρνιθες· σαφῶς μὲν οὖν χαλεπὸν ἦν διαγνῶναι πότερον ξύλου ποίημα ἦν ἢ γύψου, τεκμαιρομένοις δὲ ἡμῖν ἐφαίνετο εἶναι ξύλου μᾶλλον ἢ γύψου. εἰσὶ δὲ αὐτόθι καὶ παρθένοι λίθου λευκοῦ, σκέλη δέ σφισίν ἐστιν ὀρνίθων, ἑστᾶσι δὲ ὄπισθε τοῦ ναοῦ.", "st": "8.22"}, {"sp": "N", "t": "λέγεται δὲ καὶ ἐφ’ ἡμῶν γενέσθαι θαῦμα τοιόνδε. ἐν Στυμφάλῳ τῆς Ἀρτέμιδος τῆς Στυμφαλίας τὴν ἑορτὴν [κα]τά τε ἄλλα ἦγον οὐ σπουδῇ καὶ τὰ ἐς αὐτὴν καθεστηκότα ὑπερέβαινον τὰ πολλά. ἐσπεσοῦσα οὖν ὕλη κατὰ τοῦ βαράθρου τὸ στόμα, ᾗ κάτεισιν ὁ ποταμός [ὅς ἐστιν ὁ Στύμφαλος], ἀνεῖργε μὴ καταδύεσθαι τὸ ὕδωρ, λίμνην τε ὅσον ἐπὶ τετρακοσίους σταδίους τὸ πεδίον σφίσι γενέσθαι λέγουσι.", "st": "8.22"}, {"sp": "N", "t": "φασὶ δὲ ἕπεσθαι θηρευτὴν ἄνδρα ἐλάφῳ φευγούσῃ, καὶ τὴν μὲν ἐς τὸ τέλμα ἵεσθαι, τὸν δὲ ἄνδρα τὸν θηρευτὴν ἐπακολουθοῦντα ὑπὸ τοῦ θυμοῦ κατόπιν τῆς ἐλάφου νήχεσθαι· καὶ οὕτω τὸ βάραθρον τήν τε ἔλαφον καὶ ἐπ’ αὐτῇ τὸν ἄνδρα ὑπεδέξατο. τούτοις δὲ τοῦ ποταμοῦ τὸ ὕδωρ ἐπακολουθῆσαί φασιν, ὥστε ἐς ἡμέραν Στυμφαλίοις ἐξήραντο ἅπαν τοῦ πεδίου τὸ λιμνάζον· καὶ ἀπὸ τούτου τῇ Ἀρτέμιδι τὴν ἑορτὴν φιλοτιμίᾳ πλέονι ἄγουσι.", "st": "8.22"}, {"sp": "N", "t": "μετὰ δὲ Στύμφαλόν ἐστιν Ἀλέα, συνεδρίου μὲν τοῦ Ἀργολικοῦ μετέχουσα καὶ αὕτη, Ἄλεον δὲ τὸν Ἀφείδαντος γενέσθαι σφίσιν ἀποφαίνουσιν οἰκιστήν. θεῶν δὲ ἱερὰ αὐτόθι Ἀρτέμιδός ἐστιν Ἐφεσίας καὶ Ἀθηνᾶς Ἀλέας, καὶ Διονύσου ναὸς καὶ ἄγαλμα. τούτῳ παρὰ ἔτος Σκιέρεια ἑορτὴν ἄγουσι, καὶ ἐν Διονύσου τῇ ἑορτῇ κατὰ μάντευμα ἐκ Δελφῶν μαστιγοῦνται γυναῖκες, καθὰ καὶ οἱ Σπαρτιατῶν ἔφηβοι παρὰ τῇ Ὀρθίᾳ.", "st": "8.23"}, {"sp": "N", "t": "ἐδήλωσα δὲ ἐν τῷ λόγῳ τῷ ἐς Ὀρχομενίους ὡς πρῶτα μὲν παρὰ τὴν χαράδραν ἐστὶν ⟨ἡ⟩ εὐθεῖα, τὸ ἀπὸ τούτου δὲ ἐν ἀριστερᾷ τοῦ ὕδατος τοῦ λιμνάζοντος. ἐν δὲ τῷ πεδίῳ τῷ Καφυῶν πεποίηται γῆς χῶμα, δι’ οὗ ἀπείργεται τὸ ὕδωρ τὸ ἐκ τῆς Ὀρχομενίας μὴ εἶναι Καφυεῦσιν βλάβος τῇ ἐνεργῷ. κατὰ δὲ τὸ ἐντὸς τοῦ χώματος παρέξεισιν ὕδωρ ἄλλο, πλήθει μὲν ὅσον τε εἶναι ποταμόν, κατερχόμενον δὲ ἐς χάσμα γῆς ἄνεισιν αὖθις παρὰ Νάσους καλουμένας· τὸ δὲ χωρίον ἔνθα ἄνεισιν ὀνομάζεται Ῥεῦνος· ἀνατείλαντος δὲ ἐνταῦθα, τὸ ὕδωρ τὸ ἀπὸ τούτου παρέχεται ποταμὸν ἀέναον Τράγον.", "st": "8.23"}, {"sp": "N", "t": "τὸ δὲ ὄνομά ἐστι μὲν δῆλον ἀπὸ Κηφέως τοῦ Ἀλέου τῇ πόλει γεγονός, ὀνομάζεσθαι δὲ αὐτὴν φωνῇ τῇ Ἀρκάδων Καφυὰς ἐκνενίκηκε. φασὶ δὲ οἱ Καφυεῖς τὰ ἄνωθεν ἐκ τῆς Ἀττικῆς εἶναι χώρας, ἐκβληθέντες δὲ ὑπὸ Αἰγέως ἐξ Ἀθηνῶν ἐς Ἀρκαδίαν φυγεῖν καὶ ἱκέται γενόμενοι Κηφέως οἰκῆσαι ἐνταῦθα. τὸ μὲν δὴ πόλισμα ἐπὶ τοῦ πεδίου τῷ πέρατι ὀρῶν οὐκ ἄγαν ὑψηλῶν παρὰ τοῖς ποσίν ἐστι· Καφυάταις δὲ ἱερὰ θεῶν Ποσειδῶνός ἐστι καὶ ἐπίκλησιν Κνακαλησίας Ἀρτέμιδος.", "st": "8.23"}, {"sp": "N", "t": "ἔστι δὲ αὐτοῖς καὶ ὄρος Κνάκαλος, ἔνθα ἐπέτειον τελετὴν ἄγουσι τῇ Ἀρτέμιδι. ὀλίγον δὲ ὑπὲρ τὴν πόλιν πηγή τέ ἐστι καὶ ἐπὶ τῇ πηγῇ πλάτανος μεγάλη καὶ εὐειδὴς πέφυκε· καλοῦσι δὲ αὐτὴν Μενελαΐδα, Μενέλαον [γὰρ] στρατὸν ἀθροίζοντα ἐς Τροίαν ἀφικέσθαι τε ἐνταῦθα καὶ ἐπὶ τῇ πηγῇ τὴν πλάτανον φυτεῦσαι λέγοντες· ἐφ’ ἡμῶν δὲ καὶ τὴν πηγὴν κατὰ ταὐτὰ τῇ πλατάνῳ καλοῦσι Μενελαΐδα.", "st": "8.23"}, {"sp": "N", "t": "εἰ δὲ Ἑλλήνων τοῖς λόγοις ἑπόμενον καταριθμήσασθαι δεῖ με ὁπόσα δένδρα σῶα ἔτι καὶ τεθηλότα λείπεται, πρεσβύτατον μὲν ἡ λύγος ἐστὶν αὐτῶν ἡ ἐν τῷ Σαμίων πεφυκυῖα ἱερῷ Ἥρας, μετὰ δὲ αὐτὴν ἡ ἐν Δωδώνῃ δρῦς καὶ ἐλαία τε ἡ ἐν ἀκροπόλει καὶ ἡ παρὰ Δηλίοις· τρίτα δὲ ἕνεκα ἀρχαιότητος νέμοιεν ἂν τῇ δάφνῃ τῇ παρὰ σφίσιν οἱ Σύροι· τῶν δὲ ἄλλων ἡ πλάτανός ἐστιν αὕτη παλαιότατον.", "st": "8.23"}, {"sp": "N", "t": "Καφυῶν δὲ ἀφέστηκεν ὅσον στάδιον Κονδυλέα χωρίον, καὶ Ἀρτέμιδος ἄλσος καὶ ναός ἐστιν ἐνταῦθα καλουμένης Κονδυλεάτιδος τὸ ἀρχαῖον· μετονομασθῆναι δὲ ἐπὶ αἰτίᾳ τὴν θεόν φασι τοιαύτῃ. παιδία περὶ τὸ ἱερὸν παίζοντα—ἀριθμὸν δὲ αὐτῶν οὐ μνημονεύουσιν—ἐπέτυχε καλῳδίῳ, δήσαντα δὲ τὸ καλῴδιον τοῦ ἀγάλματος περὶ τὸν τράχηλον ἐπέλεγεν ὡς ἀπάγχοιτο ἡ Ἄρτεμις.", "st": "8.23"}, {"sp": "N", "t": "φωράσαντες δὲ οἱ Καφυεῖς τὰ ποιηθέντα ὑπὸ τῶν παιδίων καταλεύουσιν αὐτά· καί σφισι ταῦτα ἐργασαμένοις ἐσέπεσεν ἐς τὰς γυναῖκας νόσος, τὰ ἐν τῇ γαστρὶ πρὸ τοκετοῦ τεθνεῶτα ἐκβάλλεσθαι, ἐς ὃ ἡ Πυθία θάψαι τε τὰ παιδία ἀνεῖπε καὶ ἐναγίζειν αὐτοῖς κατὰ ἔτος· ἀποθανεῖν γὰρ αὐτὰ οὐ σὺν δίκῃ. Καφυεῖς δὲ ποιοῦσι τά τε ἄλλα ἔτι καὶ νῦν κατ’ ἐκεῖνο τὸ μάντευμα καὶ τὴν ἐν ταῖς Κονδυλέαις θεὸν— προσεῖναι γὰρ καὶ τόδε ἔτι τῷ χρησμῷ φασι—καλοῦσιν Ἀπαγχομένην ἐξ ἐκείνου.", "st": "8.23"}, {"sp": "N", "t": "ἀνελθὼν δὲ ἐκ Καφυῶν ὅσον σταδίους ἑπτὰ ἐπὶ Νάσους καλουμένας καταβήσῃ· πεντήκοντα δὲ προελθόντι αὐτόθεν σταδίους ἐστὶν ὁ Λάδων. διαβήσῃ τε δὴ τὸν ποταμὸν καὶ ἐπὶ δρυμὸν ἀφίξῃ Σόρωνα διά τε Ἀργεαθῶν καὶ Λυκούντων καλουμένων καὶ Σκοτάνης.", "st": "8.23"}, {"sp": "N", "t": "ἄγει μὲν δὴ ὁ Σόρων τὴν ἐπὶ Ψωφῖδος· θηρία δὲ οὗτός τε καὶ ὅσοι δρυμοὶ τοῖς Ἀρκάσιν εἰσὶν ἄλλοι παρέχονται τοσάδε, ἀγρίους ὗς καὶ ἄρκτους καὶ χελώνας μεγίστας μεγέθει· λύρας ἂν ποιήσαιο ἐξ αὐτῶν χελώνης Ἰνδικῆς λύρᾳ παρισουμένας. τοῦ Σόρωνος δὲ πρὸς τοῖς πέρασιν ἔστι μὲν Πάου κώμης ἐρείπια, εἰσὶ δὲ οὐ πολὺ ἀπωτέρω ⟨αἱ⟩ καλούμεναι Σεῖραι· ὅροι δὲ Κλειτορίοις τῆς χώρας πρὸς Ψωφιδίους εἰσὶν αἱ Σεῖραι.", "st": "8.23"}, {"sp": "N", "t": "Ψωφῖδος δὲ οἱ μέν φασιν οἰκιστὴν γενέσθαι Ψώφιδα τὸν Ἄρρωνος τοῦ Ἐρυμάνθου τοῦ Ἀρίστα τοῦ Παρθάονος τοῦ Περιφήτου τοῦ Νυκτίμου· τοῖς δέ ἐστιν εἰρημένα θυγατέρα Ψωφῖδα εἶναι Ξάνθου τοῦ Ἐρυμάνθου τοῦ Ἀρκάδος. τάδε μὲν οὖν οὕτω κατὰ τὴν Ἀρκάδων ἐς τοὺς βασιλέας ἔχει μνήμην·", "st": "8.24"}, {"sp": "N", "t": "ὁ δὲ ἀληθέστατος τῶν λόγων ἐστὶν Ἔρυκος τοῦ ἐν Σικανίᾳ δυναστεύσαντος παῖδα εἶναι τὴν Ψωφῖδα, ᾗ ⟨συγγενόμενος Ἡρακλῆς ἀγαγέσθαι μὲν αὐτὴν⟩ ἐς τὸν οἶκον οὐκ ἠξίου, καταλείπει δὲ ἔχουσαν ἐν τῇ γαστρὶ παρὰ Λυκόρτᾳ, ξένῳ μὲν ὄντι αὐτοῦ, παροικοῦντι δὲ ἐν πόλει Φηγίᾳ, πρὸ δὲ τοῦ Φηγέως τῆς βασιλείας Ἐρυμάνθῳ καλουμένῃ· ἐπιτραφέντες δὲ αὐτόθι Ἐχέφρων καὶ Πρόμαχος Ἡρακλέους τε ὄντες καὶ τῆς γυναικὸς τῆς Σικανῆς μετέθεντο τῇ Φηγίᾳ τὸ ὄνομα Ψωφῖδα ἀπὸ τῆς μητρός.", "st": "8.24"}, {"sp": "N", "t": "ἔστι δὲ καὶ Ζακυνθίων τῇ ἀκροπόλει Ψωφὶς ὄνομα, ὅτι ναυσὶν ἐς τὴν νῆσον ἐπεραιώθη πρῶτος καὶ ἐγένετο οἰκιστὴς ἀνὴρ Ψωφίδιος, Ζάκυνθος [τε] ὁ Δαρδάνου. Σειρῶν μὲν δὴ σταδίοις ἐστὶν ἀπωτέρω τριάκοντα ἡ Ψωφίς· παρὰ δὲ αὐτὴν ὅ τε Ἀροάνιος ποταμὸς καὶ ὀλίγον ἀπωτέρω τῆς πόλεως Ἐρύμανθος ῥέουσιν.", "st": "8.24"}, {"sp": "N", "t": "ἔχει δὲ τὰς πηγὰς ὁ Ἐρύμανθος ἐν ὄρει Λαμπείᾳ, τὸ δὲ ὄρος τοῦτο ἱερὸν εἶναι Πανὸς λέγεται· εἴη δ’ ἂν τοῦ ὄρους τοῦ Ἐρυμάνθου μοῖρα ἡ Λάμπεια. ἐποίησε δὲ Ὅμηρος ὡς ἐν Ταϋγέτῳ τε καὶ Ἐρυμάνθῳ … θηρευτὴς … οὖν τῆς Λαμπείας ὁ Ἐρύμανθος, καὶ Ἀρκαδίαν διεξελθὼν ἐν δεξιᾷ μὲν τὸ ὄρος ἔχων τὴν Φολόην, ἐν ἀριστερᾷ δὲ πάλιν Θέλπουσαν χώραν, κάτεισιν ἐς τὸν Ἀλφειόν.", "st": "8.24"}, {"sp": "N", "t": "λέγεται δὲ ὡς Ἡρακλῆς κατὰ πρόσταγμα Εὐρυσθέως παρὰ τῷ Ἐρυμάνθῳ θηράσειεν ὗν μεγέθει καὶ ἀλκῇ τοὺς ἄλλους ὑπερηρκότα. Κυμαῖοι δὲ οἱ ἐν Ὀπικοῖς συὸς ὀδόντας ἀνακειμένους παρὰ σφίσιν ἐν Ἀπόλλωνος ἱερῷ λόγῳ μὲν λέγουσιν ὡς οἱ ὀδόντες ὑὸς εἶεν τοῦ Ἐρυμανθίου, τῷ λόγῳ δὲ αὐτῶν οὐδὲ ἐπ’ ὀλίγον μέτεστι τοῦ εἰκότος.", "st": "8.24"}, {"sp": "N", "t": "Ψωφιδίοις δὲ ἐν τῇ πόλει τοῦτο μὲν Ἀφροδίτης ἱερὸν Ἐρυκίνης ἐστὶν ἐπίκλησιν—[ἧς] ἐρείπια ἐφ’ ἡμῶν ἐλείπετο αὐτοῦ μόνα, ἐλέγοντο δὲ οἱ Ψωφῖδος αὐτὸ ἱδρύσασθαι παῖδες, καὶ [ἐν] τῷ λόγῳ τὸ εἰκὸς πρόσεστι· ἔστι γὰρ καὶ ἐν Σικελίᾳ τῆς Ἐρυκίνης ἱερὸν ἐν τῇ χώρᾳ τῇ Ἔρυκος, ἁγιώτατόν τε ἐκ παλαιοτάτου καὶ οὐκ ἀποδέον πλούτῳ τοῦ ἱεροῦ τοῦ ἐν Πάφῳ—", "st": "8.24"}, {"sp": "N", "t": "Προμάχου δὲ καὶ Ἐχέφρονος τῶν Ψωφῖδος οὐκ ἐπιφανῆ κατ’ ἐμὲ ἔτι ἦν τὰ ἡρῷα. τέθαπται δὲ καὶ Ἀλκμαίων ἐν Ψωφῖδι ὁ Ἀμφιαράου, καί οἱ τὸ μνῆμά ἐστιν οἴκημα οὔτε μεγέθει ⟨μέγα⟩ οὔτε ἄλλως κεκοσμημένον· περὶ δὲ αὐτὸ κυπάρισσοι πεφύκασιν ἐς τοσοῦτον ὕψος ἀνήκουσαι, ὥστε καὶ τὸ ὄρος τὸ πρὸς τῇ Ψωφῖδι κατεσκιάζετο ὑπ’ αὐτῶν. ταύτας οὐκ ἐθέλουσιν ἐκκόπτειν ἱερὰς τοῦ Ἀλκμαίωνος νομίζοντες· καλοῦνται δὲ ὑπὸ τῶν ἐπιχωρίων παρθένοι.", "st": "8.24"}, {"sp": "N", "t": "ὁ δὲ Ἀλκμαίων ἡνίκα τὴν μητέρα ἀποκτείνας ἔφυγεν ἐξ Ἄργους, τότε ἐς τὴν Ψωφῖδα ἐλθών, Φηγίαν ἔτι ἀπὸ τοῦ Φηγέως ὀνομαζομένην, συνῴκησεν Ἀλφεσιβοίᾳ τῇ Φηγέως θυγατρὶ καὶ αὐτῇ δῶρα ὡς τὸ εἰκὸς καὶ ἄλλα καὶ τὸν ὅρμον δίδωσιν. ὡς δὲ οἰκοῦντι αὐτῷ παρὰ τοῖς Ἀρκάσιν οὐδὲν ἐγίνετο ἡ νόσος ῥᾴων, κατέφυγεν ἐπὶ τὸ μαντεῖον τὸ ἐν Δελφοῖς, καὶ αὐτὸν ἡ Πυθία διδάσκει τὸν Ἐριφύλης ἀλάστορα ἐς ταύτην οἱ μόνην χώραν οὐ συνακολουθήσειν, ἥτις ἐστὶ νεωτάτη καὶ ἡ θάλασσα τοῦ μητρῴου μιάσματος ἀνέφηνεν ὕστερον αὐτήν.", "st": "8.24"}, {"sp": "N", "t": "καὶ ὁ μὲν ἐξευρὼν τοῦ Ἀχελῴου τὴν πρόσχωσιν ἐνταῦθα ᾤκησε, καὶ γυναῖκα ἔσχε Καλλιρόην τοῦ Ἀχελῴου θυγατέρα λόγῳ τῷ Ἀκαρνάνων, καί οἱ παῖδες Ἀκαρνάν τε καὶ Ἀμφότερος ἐγένοντο· ἀπὸ δὲ τοῦ Ἀκαρνᾶνος τοῖς ἐν τῇ ἠπείρῳ ταύτῃ τὸ ὄνομα τὸ νῦν γενέσθαι λέγουσι τὰ πρὸ τούτου Κούρησι καλουμένοις. ἐς ἐπιθυμίας δὲ ἀνοήτους πολλοὶ μὲν ἄνδρες, γυναῖκες δὲ ἔτι πλέον ἐξοκέλλουσιν.", "st": "8.24"}, {"sp": "N", "t": "ἐπεθύμησεν ἡ Καλλιρόη τῆς Ἐριφύλης οἱ γενέσθαι τὸν ὅρμον καὶ δι’ αὐτὸ ἐς τὴν Φηγίαν τὸν Ἀλκμαίωνα ἔστειλεν ἄκοντα, καὶ αὐτὸν ὑπὸ Φηγέως τῶν παίδων Τημένου καὶ Ἀξίονος δολοφονηθέντα ἐπέλαβεν ἡ τελευτή. τοῦ Φηγέως δὲ οἱ παῖδες τῷ Ἀπόλλωνι ἀναθεῖναι τῷ ἐν Δελφοῖς λέγονται τὸν ὅρμον. καὶ ἐπὶ τούτων βασιλευόντων ἐν Φηγίᾳ τότε ἔτι καλουμένῃ τῇ πόλει [Φηγίᾳ] στρατεῦσαί φασιν Ἕλληνας ἐς Τροίαν· σφᾶς δὲ οἱ Ψωφίδιοι τοῦ στόλου φασὶν οὐ μετασχεῖν, ὅτι αὐτῶν τοῖς βασιλεῦσιν οἱ Ἀργείων ἀπηχθάνοντο ἡγεμόνες, κατὰ γένος τε τῷ Ἀλκμαίωνι οἱ πολλοὶ προσήκοντες καὶ τῆς ἐπιστρατείας αὐτῷ κοινωνήσαντες ⟨τῆς⟩ ἐς Θήβας.", "st": "8.24"}, {"sp": "N", "t": "τὰς δὲ Ἐχινάδας νήσους ὑπὸ τοῦ Ἀχελῴου μὴ σφᾶς ἤπειρον ἄχρι ἡμῶν ἀπειργάσθαι γέγονε δὴ αἰτία τὸ Αἰτωλῶν ἔθνος, γεγόνασι δὲ αὐτοί τε ἀνάστατοι καὶ ἡ γῆ σφισι πᾶσα ἠρήμωται· ταῖς Ἐχινάσιν οὖν ἅτε ἀσπόρου μενούσης τῆς Αἰτωλίας οὐχ ὁμοίως ὁ Ἀχελῷος ἐπάγει τὴν ἰλύν. μαρτύριον δέ μοι τοῦ λόγου· ὁ γὰρ Μαίανδρος διὰ τῆς Φρυγῶν καὶ Καρῶν ἀρουμένης ὅσα ἔτη ῥέων τὴν μεταξὺ Πριήνης καὶ Μιλήτου θάλασσαν ἐν οὐ πολλῷ χρόνῳ πεποίηκεν ἤπειρον.", "st": "8.24"}, {"sp": "N", "t": "Ψωφιδίοις δὲ καὶ παρὰ τῷ Ἐρυμάνθῳ ναός ἐστιν Ἐρυμάνθου καὶ ἄγαλμα. ποιεῖται δὲ πλὴν τοῦ Αἰγυπτίου Νείλου ποταμοῖς τοῖς ἄλλοις λίθου λευκοῦ τὰ ἀγάλματα· τῷ Νείλῳ δέ, ἅτε διὰ τῆς Αἰθιόπων κατιόντι ἐς θάλασσαν, μέλανος λίθου τὰ ἀγάλματα ἐργάζεσθαι νομίζουσιν.", "st": "8.24"}, {"sp": "N", "t": "ὃν δὲ ἤκουσα ἐν Ψωφῖδι ἐπὶ Ἀγλαῷ λόγον ἀνδρὶ Ψωφιδίῳ κατὰ Κροῖσον τὸν Λυδὸν ὄντι ἡλικίαν, ὡς ὁ Ἀγλαὸς τὸν χρόνον τοῦ βίου πάντα γένοιτο εὐδαίμων, οὔ με ἔπειθεν ὁ λόγος. ἀλλὰ ἀνθρώπων μὲν τῶν ἐφ’ ἑαυτοῦ κακὰ ἄν τις ἐλάσσονα ἀναδέξαιτο, καθὰ καὶ ναῦς ἧσσον ἂν χειμασθείη νεὼς ἄλλης·", "st": "8.24"}, {"sp": "N", "t": "ἄνδρα δὲ συμφορῶν ἀεὶ στάντα ἐκτὸς ἢ τὰ πάντα οὐρίῳ ναῦν χρησαμένην πνεύματι οὐκ ἔστιν ὅπως δυνησόμεθα ἐξευρεῖν, ἐπεὶ καὶ Ὅμηρος κατακείμενον παρὰ τῷ Διὶ ἀγαθῶν πίθον, τὸν δὲ ἕτερον κακῶν ἐποίησεν, ὑπὸ τοῦ ἐν Δελφοῖς θεοῦ δεδιδαγμένος, ὃς αὐτόν ποτε Ὅμηρον κακοδαίμονά τε προσεῖπε καὶ ὄλβιον ὡς φύντα ἐπὶ ἀμφοτέροις ὁμοίως.", "st": "8.24"}, {"sp": "N", "t": "ἐς δὲ Θέλπουσαν ἰόντι ἐκ Ψωφῖδος πρῶτα μὲν χωρίον Τρόπαιά ἐστιν ὀνομαζόμενον ἐν ἀριστερᾷ τοῦ Λάδωνος, Τροπαίων δὲ ἔχεται δρυμὸς Ἀφροδίσιον· τρίτα δέ ἐστιν ἀρχαῖα ἐν στήλῃ γράμματα,<br>ὅροι Ψωφιδίοις πρὸς τὴν Θελπουσίαν χώραν.<br>ἐν δὲ τῇ γῇ τῇ Θελπουσίᾳ ποταμός ἐστιν Ἄρσην καλούμενος· τοῦτον οὖν διαβήσῃ καὶ ὅσον πέντε ἀπ’ αὐτοῦ σταδίοις ἀφίξῃ καὶ εἴκοσι ἐπὶ ἐρείπια Καοῦντος κώμης [ὃ] καὶ ἱερὸν Ἀσκληπιοῦ Καουσίου πεποιημένον ἐν τῇ ὁδῷ.", "st": "8.25"}, {"sp": "N", "t": "τοῦ δὲ ἱεροῦ τούτου σταδίους τεσσαράκοντα μάλιστα ἀφέστηκεν ἡ πόλις· τεθῆναι δὲ αὐτῇ ὄνομα ἀπὸ νύμφης λέγουσι Θελπούσης, ταύτην δὲ θυγατέρα εἶναι Λάδωνος. τῷ δὲ Λάδωνι ἄρχεται μὲν τὸ ὕδωρ ἐν πηγαῖς τῆς Κλειτορίας, καθὰ ὁ λόγος ἐδήλωσεν ἤδη μοι· ῥεῖ δὲ πρῶτον μὲν παρὰ Λευκάσιον χωρίον καὶ Μεσόβοα καὶ διὰ τῶν Νάσων ἐπί τε Ὄρυγα τὸν καὶ Ἁλοῦντα ὀνομαζόμενον, ἐξ Ἁλοῦντος δὲ ἐπὶ Θαλιάδας τε καὶ ἐπὶ Δήμητρος ἱερὸν κάτεισιν Ἐλευσινίας.", "st": "8.25"}, {"sp": "N", "t": "τὸ δὲ ἱερὸν τοῦτο ἔστι μὲν Θελπουσίων ἐν ὅροις· ἀγάλματα δὲ ἐν αὐτῷ, ποδῶν ἑπτὰ οὐκ ἀποδέον ἕκαστον, Δήμητρός ἐστι καὶ ἡ παῖς καὶ ὁ Διόνυσος, τὰ πάντα ὁμοίως λίθου. μετὰ δὲ τῆς Ἐλευσινίας τὸ ἱερὸν καὶ Θέλπουσαν τὴν πόλιν ὁ Λάδων παρέξεισιν ἐν ἀριστερᾷ, κειμένην μὲν ἐπὶ λόφου μεγάλου, τὰ πλείω δὲ ἐφ’ ἡμῶν ἔρημον, ὥστε καὶ τὴν ἀγορὰν ἐπὶ τῷ πέρατι οὖσάν φασιν ἐν τῷ μεσαιτάτῳ ποιηθῆναι τὸ ἐξ ἀρχῆς. ἔστι δὲ ἐν Θελπούσῃ ναὸς Ἀσκληπιοῦ καὶ θεῶν ἱερὸν τῶν δώδεκα·", "st": "8.25"}, {"sp": "N", "t": "τούτου τὰ πολλὰ ἐς ἔδαφος ἔκειτο ἤδη. μετὰ δὲ Θέλπουσαν ἐπὶ τὸ ἱερὸν τῆς Δήμητρος ὁ Λάδων κάτεισι τὸ ἐν Ὀγκείῳ· καλοῦσι δὲ Ἐρινὺν οἱ Θελπούσιοι τὴν θεόν, ὁμολογεῖ δέ σφισι καὶ Ἀντίμαχος ἐπιστρατείαν Ἀργείων ποιήσας ἐς Θήβας· καί οἱ τὸ ἔπος ἔχει,<br>Δήμητρος τόθι φασὶν Ἐρινύος εἶναι ἔδεθλον.<br>ὁ μὲν δὴ Ὄγκιος Ἀπόλλωνός ἐστι κατὰ τὴν φήμην καὶ ἐν τῇ Θελπουσίᾳ περὶ τὸ χωρίον ἐδυνάστευε τὸ Ὄγκιον, τῇ θεῷ δὲ Ἐρινὺς γέγονεν ἐπίκλησις·", "st": "8.25"}, {"sp": "N", "t": "πλανωμένῃ γὰρ τῇ Δήμητρι, ἡνίκα τὴν παῖδα ἐζήτει, λέγουσιν ἕπεσθαί οἱ τὸν Ποσειδῶνα ἐπιθυμοῦντα αὐτῇ μιχθῆναι, καὶ τὴν μὲν ἐς ἵππον μεταβαλοῦσαν ὁμοῦ ταῖς ἵπποις νέμεσθαι ταῖς Ὀγκίου, Ποσειδῶν δὲ συνίησεν ἀπατώμενος καὶ συγγίνεται τῇ Δήμητρι ἄρσενι ἵππῳ καὶ αὐτὸς εἰκασθείς.", "st": "8.25"}, {"sp": "N", "t": "τὸ μὲν δὴ παραυτίκα τὴν Δήμητρα ἐπὶ τῷ συμβάντι ἔχειν ὀργίλως, χρόνῳ δὲ ὕστερον τοῦ τε θυμοῦ παύσασθαι καὶ τῷ Λάδωνι ἐθελῆσαί φασιν αὐτὴν λούσασθαι· ἐπὶ τούτῳ καὶ ἐπικλήσεις τῇ θεῷ γεγόνασι, τοῦ μηνίματος μὲν ἕνεκα Ἐρινύς, ὅτι τὸ θυμῷ χρῆσθαι καλοῦσιν ἐρινύειν οἱ Ἀρκάδες, Λουσία δὲ ἐπὶ τῷ λούσασθαι τῷ Λάδωνι. τὰ δὲ ἀγάλματά ἐστι τὰ ⟨ἐν τῷ⟩ ναῷ ξύλου, πρόσωπα δέ σφισι καὶ χεῖρες ἄκραι καὶ πόδες εἰσὶ Παρίου λίθου·", "st": "8.25"}, {"sp": "N", "t": "τὸ μὲν δὴ τῆς Ἐρινύος τήν τε κίστην καλουμένην ἔχει καὶ ἐν τῇ δεξιᾷ δᾷδα, μέγεθος δὲ εἰκάζομεν ἐννέα εἶναι ποδῶν αὐτήν· ἡ Λουσία δὲ ποδῶν ἓξ ἐφαίνετο εἶναι. ὅσοι δὲ Θέμιδος καὶ οὐ Δήμητρος τῆς Λουσίας τὸ ἄγαλμα εἶναι νομίζουσι, μάταια ἴστωσαν ὑπειληφότες. τὴν δὲ Δήμητρα τεκεῖν φασιν ἐκ τοῦ Ποσειδῶνος θυγατέρα, ἧς τὸ ὄνομα ἐς ἀτελέστους λέγειν οὐ νομίζουσι, καὶ ἵππον τὸν Ἀρείονα· ἐπὶ τούτῳ δὲ παρὰ σφίσιν Ἀρκάδων πρώτοις Ἵππιον Ποσειδῶνα ὀνομασθῆναι.", "st": "8.25"}, {"sp": "N", "t": "ἐπάγονται δὲ ἐξ Ἰλιάδος ἔπη καὶ ἐκ Θηβαΐδος μαρτύριά σφισιν εἶναι τῷ λόγῳ, ἐν μὲν Ἰλιάδι ἐς αὐτὸν Ἀρείονα πεποιῆσθαι,<br>οὐδ’ εἴ κεν μετόπισθεν Ἀρείονα δῖον ἐλαύνοι,<br>Ἀδρήστου ταχὺν ἵππον, ὃς ἐκ θεόφιν γένος ἦεν·<br>ἐν δὲ τῇ Θηβαΐδι ὡς Ἄδραστος ἔφευγεν ἐκ Θηβῶν<br>εἵματα λυγρὰ φέρων σὺν Ἀρείονι κυανοχαίτῃ.<br>αἰνίσσεσθαι οὖν ἐθέλουσι τὰ ἔπη Ποσειδῶνα Ἀρείονι εἶναι πατέρα, Ἀντίμαχος δὲ παῖδα εἶναι Γῆς φησιν·", "st": "8.25"}, {"sp": "N", "t": "Ἄδρηστος Ταλαὼ υἱὸς Κρηθηιάδαο<br>πρώτιστος Δαναῶν ἑὼ αἰνέτω ἤλασεν ἵππω,<br>Καιρόν τε κραιπνὸν καὶ Ἀρείονα Θελπουσαῖον,<br>τόν ῥά τ’ Ἀπόλλωνος σχεδὸν ἄλσεος Ὀγκαίοιο<br>αὐτὴ Γαῖ’ ἀνέδωκε, σέβας θνητοῖσιν ἰδέσθαι.", "st": "8.25"}, {"sp": "N", "t": "δύναιτο δ’ ἂν καὶ ἀναφύντι ἐκ γῆς τῷ ἵππῳ ἐκ θεοῦ τε εἶναι τὸ γένος καὶ αἱ τρίχες οἱ τὴν χρόαν ἐοικέναι κυανῷ. λέγεται δὲ καὶ τοιάδε, Ἡρακλέα πολεμοῦντα Ἠλείοις αἰτῆσαι παρ’ Ὄγκου τὸν ἵππον καὶ ἑλεῖν τὴν Ἦλιν ἐπὶ τῷ Ἀρείονι ὀχούμενον ἐς τὰς μάχας, δοθῆναι δὲ ὑπὸ Ἡρακλέους ὕστερον Ἀδράστῳ τὸν ἵππον. ἐπὶ τούτῳ δὲ ἐς τὸν Ἀρείονα ἐποίησεν Ἀντίμαχος<br>ὅς ῥά ποτ’ Ἀδρήστῳ τριτάτῳ δέδμηθ’ ὑπ’ ἄνακτι.", "st": "8.25"}, {"sp": "N", "t": "ὁ δὲ Λάδων τῆς Ἐρινύος τὸ ἱερὸν ἀπολιπὼν ἐν ἀριστερᾷ, παρέξεισιν ἐν ἀριστερᾷ μὲν τοῦ Ἀπόλλωνος τοῦ Ὀγκαιάτου τὸν ναόν, τὰ δὲ ἐν δεξιᾷ παρὰ Ἀσκληπιοῦ Παιδὸς ἱερόν, ἔνθα Τρυγόνος μνῆμά ἐστι [τροφοῦ]· τροφὸν δὲ Ἀσκληπιοῦ τὴν Τρυγόνα εἶναι λέγουσιν· ἐν γὰρ τῇ Θελπούσῃ τῷ Ἀσκληπιῷ παιδὶ ἐκκειμένῳ φασὶν ἐπιτυχόντα Αὐτόλαον Ἀρκάδος υἱὸν νόθον ἀνελέσθαι τὸ παιδίον, καὶ ἐπὶ τούτῳ παῖδα Ἀσκληπιὸν … εἰκότα εἶναι μᾶλλον ἡγούμην, ὃ καὶ ἐδήλωσα ἐν τοῖς Ἐπιδαυρίων.", "st": "8.25"}, {"sp": "N", "t": "ἔστι δὲ Τουθόα ποταμός· ἐμβάλλει δὲ ἐς τὸν Λάδωνα καὶ ἡ Τουθόα κατὰ τὸν Θελπουσίων ὅρον πρὸς Ἡραιεῖς, καλούμενον δὲ ὑπὸ Ἀρκάδων Πεδίον. καθότι δὲ αὐτὸς ὁ Λάδων ἐκδίδωσιν ἐς τὸν Ἀλφειόν, Κοράκων ὠνόμασται νᾶσος. οἱ δὲ ἥγηνται τὴν Ἐνίσπην καὶ Στρατίην τε καὶ Ῥίπην τὰς ὑπὸ Ὁμήρου κατειλεγμένας γενέσθαι νήσους ποτὲ ἐν τῷ Λάδωνι ὑπὸ ἀνθρώπων οἰκουμένας, ἃ οἱ πεπιστευκότες μάταια ἴστωσαν·", "st": "8.25"}, {"sp": "N", "t": "οὐ γὰρ ἄν ποτε οὐδὲ νηὶ παρισουμένας πορθμίδι παράσχοιτο ὁ Λάδων νήσους. κάλλους μὲν γὰρ ἕνεκα οὐδενὸς ποταμῶν δεύτερος οὔτε τῶν βαρβαρικῶν ἐστιν οὔτε Ἕλληνος, μέγεθος δὲ οὐ τοσοῦτος ὡς ἐν αὐτῷ καὶ νήσους ἀναφαίνεσθαι καθάπερ ἐν Ἴστρῳ τε καὶ Ἠριδανῷ.", "st": "8.25"}, {"sp": "N", "t": "Ἡραιεῦσι δὲ οἰκιστὴς μὲν γέγονεν Ἡραιεὺς ὁ Λυκάονος, κεῖται δὲ ἡ πόλις ἐν δεξιᾷ τοῦ Ἀλφειοῦ, τὰ μὲν πολλὰ ἐν ἠρέμα προσάντει, τὰ δὲ καὶ ἐπ’ αὐτὸν καθήκει τὸν Ἀλφειόν. δρόμοι τε παρὰ τῷ ποταμῷ πεποίηνται μυρσίναις καὶ ἄλλοις ἡμέροις διακεκριμένοι δένδροις, καὶ τὰ λουτρὰ αὐτόθι, εἰσὶ δὲ καὶ Διονύσῳ ναοί· τὸν μὲν καλοῦσιν αὐτῶν Πολίτην, τὸν δὲ Αὐξίτην, καὶ οἴκημά ἐστί σφισιν ἔνθα τῷ Διονύσῳ τὰ", "st": "8.26"}, {"sp": "N", "t": "ὄργια ἄγουσιν. ἔστι καὶ ναὸς ἐν τῇ Ἡραίᾳ Πανὸς ἅτε τοῖς Ἀρκάσιν ἐπιχωρίου, τῆς δὲ Ἥρας τοῦ ναοῦ καὶ ἄλλα ἐρείπια καὶ οἱ κίονες ἔτι ἐλείποντο· ἀθλητὰς δὲ ὁπόσοι γεγόνασιν Ἀρκάσιν ὑπερῆρκε τῇ δόξῃ Δαμάρετος Ἡραιεύς, ὃς τὸν ὁπλίτην δρόμον ἐνίκησεν ⟨ἐν⟩ Ὀλυμπίᾳ πρῶτος.", "st": "8.26"}, {"sp": "N", "t": "ἐς δὲ τὴν Ἠλείαν κατιὼν ἐξ Ἡραίας στάδια μέν που πέντε καὶ δέκα ἀποσχὼν Ἡραίας διαβήσῃ τὸν Λάδωνα, ἀπὸ τούτου δὲ ⟨ἐς⟩ Ἐρύμανθον ὅσον εἴκοσιν ἀφίξῃ σταδίοις. τῇ δὲ Ἡραίᾳ ὅροι πρὸς τὴν Ἠλείαν λόγῳ μὲν τῷ Ἀρκάδων ἐστὶν ὁ Ἐρύμανθος, Ἠλεῖοι δὲ τὸν Κοροίβου τάφον φασὶ τὴν χώραν σφίσιν ὁρίζειν.", "st": "8.26"}, {"sp": "N", "t": "ἡνίκα δὲ τὸν ἀγῶνα τὸν Ὀλυμπικὸν ἐκλιπόντα ἐπὶ χρόνον πολὺν ἀνενεώσατο Ἴφιτος καὶ αὖθις ἐξ ἀρχῆς Ὀλύμπια ἤγαγον, τότε δρόμου σφίσιν ἆθλα ἐτέθη μόνον καὶ ὁ Κόροιβος ἐνίκησε· καὶ ἔστιν ἐπίγραμμα ἐπὶ τῷ μνήματι ὡς Ὀλυμπίασιν ὁ Κόροιβος ἐνίκησεν [καὶ] ἀνθρώπων πρῶτος καὶ ὅτι τῆς Ἠλείας ἐπὶ τῷ πέρατι ὁ τάφος αὐτῷ πεποίηται.", "st": "8.26"}, {"sp": "N", "t": "ἔστι δὲ Ἀλίφηρα πόλισμα οὐ μέγα· ἐξελείφθη γὰρ ὑπὸ οἰκητόρων πολλῶν ὑπὸ τὸν συνοικισμὸν τῶν Ἀρκάδων ἐς Μεγάλην πόλιν. ἐς τοῦτο οὖν τὸ πόλισμα ἐρχόμενος ἐξ Ἡραίας τόν τε Ἀλφειὸν διαβήσῃ καὶ σταδίων μάλιστά που δέκα διελθὼν πεδίον ἐπὶ ὄρος ἀφίξῃ καὶ αὖθις στάδια ὅσον τριάκοντα ἐς τὸ πόλισμα ἀναβήσῃ διὰ τοῦ ὄρους.", "st": "8.26"}, {"sp": "N", "t": "Ἀλιφηρεῦσι δὲ τὸ μὲν ὄνομα τῇ πόλει γέγονεν ἀπὸ Ἀλιφήρου Λυκάονος παιδός, ἱερὰ δὲ Ἀσκληπιοῦ τέ ἐστι καὶ Ἀθηνᾶς, ἣν θεῶν σέβονται μάλιστα, γενέσθαι καὶ τραφῆναι παρὰ σφίσιν αὐτὴν λέγοντες· καὶ Διός τε ἱδρύσαντο Λεχεάτου βωμόν, ἅτε ἐνταῦθα τὴν Ἀθηνᾶν τεκόντος, καὶ κρήνην καλοῦσι Τριτωνίδα, τὸν ἐπὶ τῷ ποταμῷ τῷ Τρίτωνι οἰκειούμενοι λόγον.", "st": "8.26"}, {"sp": "N", "t": "τῆς δὲ Ἀθηνᾶς τὸ ἄγαλμα πεποίηται χαλκοῦ, Ὑπατοδώρου [τε] ἔργον, θέας ἄξιον μεγέθους τε ἕνεκα καὶ ἐς τὴν τέχνην. ἄγουσι δὲ καὶ πανήγυριν ὅτῳ δὴ θεῶν, δοκῶ δὲ σφᾶς ἄγειν τῇ Ἀθηνᾷ· ἐν ταύτῃ τῇ πανηγύρει Μυάγρῳ προθύουσιν, ἐπευχόμενοί τε κατὰ τῶν ἱερείων τῷ ἥρωι καὶ ἐπικαλούμενοι τὸν Μύαγρον· καί σφισι ταῦτα δράσασιν οὐδὲν ἔτι ἀνιαρόν εἰσιν αἱ μυῖαι.", "st": "8.26"}, {"sp": "N", "t": "κατὰ δὲ τὴν ἐξ Ἡραίας ἄγουσαν ἐς Μεγάλην πόλιν εἰσὶ Μελαινεαί· ταύτας ᾤκισε μὲν Μελαινεὺς ὁ Λυκάονος, ἔρημος δὲ ἦν ἐφ’ ἡμῶν, ὕδατι δὲ καταρρεῖται. Μελαινεῶν δὲ τεσσαράκοντά ἐστιν ἀνωτέρω σταδίοις Βουφάγιον, καὶ ὁ ποταμὸς ἐνταῦθα ἔχει πηγὰς ὁ Βουφάγος κατιὼν ἐς τὸν Ἀλφειόν· τοῦ Βουφάγου δὲ περὶ τὰς πηγὰς ὅροι πρὸς Μεγαλοπολίτας Ἡραιεῦσίν εἰσιν.", "st": "8.26"}, {"sp": "N", "t": "ἡ δὲ Μεγάλη πόλις νεωτάτη πόλεών ἐστιν οὐ τῶν Ἀρκαδικῶν μόνον ἀλλὰ καὶ τῶν ἐν Ἕλλησι, πλὴν ὅσων κατὰ συμφορὰν ἀρχῆς τῆς Ῥωμαίων μεταβεβήκασιν οἰκήτορες· συνῆλθον δὲ ὑπὲρ ἰσχύος ἐς αὐτὴν οἱ Ἀρκάδες, ἅτε καὶ Ἀργείους ἐπιστάμενοι τὰ μὲν ἔτι παλαιότερα μόνον οὐ κατὰ μίαν ἡμέραν ἑκάστην κινδυνεύοντας ὑπὸ Λακεδαιμονίων παραστῆναι τῷ πολέμῳ, ἐπειδὴ δὲ ἀνθρώπων πλήθει τὸ Ἄργος ἐπηύξησαν καταλύσαντες Τίρυνθα καὶ Ὑσιάς τε καὶ Ὀρνεὰς καὶ Μυκήνας καὶ Μίδειαν καὶ εἰ δή τι ἄλλο πόλισμα οὐκ ἀξιόλογον ἐν τῇ Ἀργολίδι ἦν, τά τε ἀπὸ Λακεδαιμονίων ἀδεέστερα τοῖς Ἀργείοις ὑπάρξαντα καὶ ἅμα ἐς τοὺς περιοίκους ἰσχὺν γενομένην αὐτοῖς.", "st": "8.27"}, {"sp": "N", "t": "γνώμῃ μὲν τοιαύτῃ συνῳκίζοντο οἱ Ἀρκάδες, τῆς πόλεως δὲ οἰκιστὴς Ἐπαμινώνδας ὁ Θηβαῖος σὺν τῷ δικαίῳ καλοῖτο ἄν· τούς τε γὰρ Ἀρκάδας οὗτος ἦν ὁ ἐπεγείρας ἐς τὸν συνοικισμὸν Θηβαίων τε χιλίους λογάδας καὶ Παμμένην ἀπέστειλεν ἡγεμόνα ἀμύνειν τοῖς Ἀρκάσιν, εἰ κωλύειν πειρῶνται οἱ Λακεδαιμόνιοι τὸν οἰκισμόν. ᾑρέθησαν δὲ καὶ ὑπὸ τῶν Ἀρκάδων οἰκισταὶ Λυκομήδης καὶ Ὁπολέας καὶ Τίμων τε καὶ Πρόξενος, οὗτοι μὲν ἐκ Τεγέας, Λυκομήδης δὲ καὶ Ὁπολέας Μαντινεῖς, Κλειτορίων δὲ Κλεόλαος καὶ Ἀκρίφιος, Εὐκαμπίδας δὲ καὶ Ἱερώνυμος ἐκ Μαινάλου, Παρρασίων δὲ Ποσσικράτης τε καὶ Θεόξενος.", "st": "8.27"}, {"sp": "N", "t": "πόλεις δὲ τοσαίδε ἦσαν ὁπόσας ὑπό τε προθυμίας καὶ διὰ τὸ ἔχθος τὸ Λακεδαιμονίων πατρίδας σφίσιν οὔσας ἐκλιπεῖν ἐπείθοντο οἱ Ἀρκάδες, Ἀλέα Παλλάντιον Εὐταία Σουμάτειον Ἀσέα Περαιθεῖς Ἑλισσὼν Ὀρεσθάσιον Δίπαια Λύκαια· ταύτας μὲν ἐκ Μαινάλου· ἐκ δὲ Εὐτρησίων Τρικόλωνοι καὶ Ζοίτιον καὶ Χαρισία καὶ Πτολέδερμα καὶ Κναῦσον καὶ Παρώρεια·", "st": "8.27"}, {"sp": "N", "t": "παρὰ δὲ Αἰγυτῶν ⟨Αἴγυς⟩ καὶ Σκιρτώνιον καὶ Μαλέα καὶ Κρῶμοι καὶ Βλένινα καὶ Λεῦκτρον· Παρρασίων ⟨δὲ⟩ Λυκοσουρεῖς Θωκνεῖς Τραπεζούντιοι Προσεῖς Ἀκακήσιον Ἀκόντι⟨ον⟩ Μακαρία Δασέα· ἐκ δὲ Κυνουραίων τῶν ἐν Ἀρκαδίᾳ Γόρτυς καὶ Θεισόα ἡ πρὸς Λυκαίῳ καὶ Λυκαιᾶται καὶ Ἀλίφηρα· ἐκ δὲ τῶν συντελούντων ἐς Ὀρχομενὸν Θεισόα Μεθύδριον Τεῦθις· προσεγένετο δὲ καὶ Τρίπολις ὀνομαζομένη, Καλλία καὶ Δίποινα καὶ Νώνακρις.", "st": "8.27"}, {"sp": "N", "t": "τὸ μὲν δὴ ἄλλο Ἀρκαδικὸν οὔτε τι παρέλυε τοῦ κοινοῦ δόγματος καὶ συνελέγοντο ἐς τὴν Μεγάλην πόλιν σπουδῇ· Λυκαιᾶται δὲ καὶ Τρικολωνεῖς καὶ Λυκοσουρεῖς τε καὶ Τραπεζούντιοι μετεβάλοντο Ἀρκάδων μόνοι, καὶ—οὐ γὰρ συνεχώρουν ἔτι τὰ ἄστη τὰ ἀρχαῖα ἐκλιπεῖν— οἱ μὲν αὐτῶν καὶ ἄκοντες ἀνάγκῃ κατήγοντο ἐς τὴν Μεγάλην πόλιν, Τραπεζούντιοι δὲ ἐκ Πελοποννήσου", "st": "8.27"}, {"sp": "N", "t": "τὸ παράπαν ἐξεχώρησαν, ὅσοι γε αὐτῶν ἐλείφθησαν καὶ μὴ σφᾶς ὑπὸ τοῦ θυμοῦ παραυτίκα διεχρήσαντο οἱ Ἀρκάδες· τοὺς δὲ αὐτῶν ἀνασωθέντας ἀναπλεύσαντας ναυσὶν ἐς τὸν Πόντον συνοίκους ἐδέξαντο μητροπολίτας τ’ ὄντας καὶ ὁμωνύμους οἱ Τραπεζοῦντα ἔχοντες τὴν ἐν τῷ Εὐξείνῳ. Λυκοσουρεῦσι δὲ καὶ ἀπειθήσασιν ἐγένετο ὅμως παρὰ τῶν Ἀρκάδων αἰδὼς Δήμητρός τε ἕνεκα καὶ Δεσποίνης ἐλθοῦσιν ⟨ἐς⟩ τὸ ἱερόν.", "st": "8.27"}, {"sp": "N", "t": "τῶν δὲ ἄλλων τῶν κατειλεγμένων πόλεων αἱ μὲν ἐς ἅπαν εἰσὶν ἐφ’ ἡμῶν ἔρημοι, τὰς δὲ ἔχουσιν οἱ Μεγαλοπολῖται κώμας, Γόρτυνα Διποί⟨ν⟩ας Θεισόαν τὴν πρὸς Ὀρχομενῷ Μεθύδριον Τεῦθιν Καλλιὰς Ἑλισσόντα· μόνη δὲ ἐξ αὐτῶν Παλλάντιον ἔμελλεν ἄρα ἠπιωτέρου πειρᾶσθαι καὶ τότε τοῦ δαίμονος. τοῖς δὲ Ἀλιφηρεῦσι παραμεμένηκεν ἐξ ἀρχῆς πόλιν σφᾶς καὶ ἐς τόδε νομίζεσθαι.", "st": "8.27"}, {"sp": "N", "t": "συνῳκίσθη δὲ ἡ Μεγάλη πόλις ἐνιαυτῷ τε τῷ αὐτῷ καὶ μησίν [τε] ὀλίγοις ὕστερον ἢ τὸ πταῖσμα ἐγένετο Λακεδαιμονίων τὸ ἐν Λεύκτροις, Φρασικλείδου μὲν Ἀθήνησιν ἄρχοντος, δευτέρῳ δὲ ἔτει τῆς ἑκατοστῆς Ὀλυμπιάδος καὶ δευτέρας, ἣν Δάμων Θούριος ἐνίκα στάδιον.", "st": "8.27"}, {"sp": "N", "t": "Μεγαλοπολίταις δὲ ἐς τὴν Θηβαίων συμμαχίαν ἐγγραφεῖσιν ἀπὸ Λακεδαιμονίων δεῖμα ἦν οὐδέν. ὡς δὲ ἐς τὸν πόλεμον τὸν ἱερὸν ὀνομασθέντα οἱ Θηβαῖοι κατέστησαν καὶ αὐτοῖς ἐπέκειντο οἱ Φωκεῖς, τήν τε ὅμορον τῇ Βοιωτῶν ἔχοντες καὶ ὄντες οὐκ ἀδύνατοι χρήμασιν ἅτε τὸ ἱερὸν τὸ ἐν Δελφοῖς κατειληφότες,", "st": "8.27"}, {"sp": "N", "t": "τηνικαῦτα οἱ Λακεδαιμόνιοι προθυμίας μὲν [οὖν] ἕνεκα Ἀρκάδας τε ἂν τοὺς ἄλλους καὶ τοὺς Μεγαλοπολίτας ἐποίησαν ἀναστάτους, ἀμυνομένων δὲ τῶν τότε οὐκ ἀθύμως καὶ ἅμα τῶν περιοίκων ἀπροφασίστως σφίσιν ἐπικουρούντων, λόγου μὲν συνέπεσεν οὐδὲν ἄξιον γενέσθαι παρὰ οὐδετέρων· Φίλιππον δὲ τὸν Ἀμύντου καὶ Μακεδόνων τὴν ἀρχὴν οὐχ ἥκιστα αὐξηθῆναι τὸ ἔχθος τὸ Ἀρκάδων ἐς Λακεδαιμονίους ἐποίησε, καὶ Ἕλλησιν ἐν Χαιρωνείᾳ καὶ αὖθις περὶ Θεσσαλίαν τοῦ ἀγῶνος οὐ μετέσχον οἱ Ἀρκάδες.", "st": "8.27"}, {"sp": "N", "t": "χρόνον δὲ οὐ μετὰ πολὺν Ἀριστόδημος Μεγαλοπολίταις ἀνέφυ τύραννος, Φιγαλεὺς μὲν γένος καὶ υἱὸς Ἀρτύλα, ποιησαμένου δὲ αὐτὸν Τριταίου τῶν οὐκ ἀδυνάτων ἐν Μεγάλῃ πόλει· τούτῳ τῷ Ἀριστοδήμῳ καὶ τυραννοῦντι ἐξεγένετο ὅμως ἐπικληθῆναι Χρηστῷ. ἐπὶ τούτου τυραννοῦντος ἐσβάλλουσιν ἐς τὴν Μεγαλοπολῖτιν στρατιᾷ Λακεδαιμόνιοι καὶ τοῦ βασιλέως Κλεομένους ὁ πρεσβύτατος τῶν παίδων Ἀκρότατος· ἐγενεαλόγησα δὲ ἤδη τά τε ἐς τοῦτον καὶ ἐς τὸ πᾶν γένος τῶν ἐν Σπάρτῃ βασιλέων. γενομένης δὲ ἰσχυρᾶς μάχης καὶ ἀποθανόντων πολλῶν παρ’ ἀμφοτέρων κρατοῦσιν οἱ Μεγαλοπολῖται τῇ συμβολῇ· καὶ ἄλλοι τε διεφθάρησαν Σπαρτιατῶν καὶ Ἀκρότατος, οὐδέ οἱ τὴν πατρῴαν παραλαβεῖν ἐξεγένετο ἀρχήν.", "st": "8.27"}, {"sp": "N", "t": "μετὰ δὲ Ἀριστόδημον τελευτήσαντα δύο μάλιστα ὕστερον γενεαῖς ἐτυράννησε Λυδιάδης, οἴκου μὲν οὐκ ἀφανοῦς, φύσιν δὲ φιλότιμος ὢν καὶ οὐχ ἥκιστα, ὡς ἐπέδειξεν ὕστερον, καὶ φιλόπολις. ἔσχε μὲν γὰρ ἔτι νέος ὢν τὴν ἀρχήν· ἐπεὶ δὲ ἤρχετο φρονεῖν, κατέπαυεν ἑαυτὸν ἑκὼν τυραννίδος, καίπερ ἐς τὸ ἀσφαλὲς ἤδη οἱ τῆς ἀρχῆς καθωρμισμένης. Μεγαλοπολιτῶν δὲ συντελούντων ἤδη τότε ἐς τὸ Ἀχαϊκόν, ὁ Λυδιάδης ἔν τε αὐτοῖς Μεγαλοπολίταις καὶ ἐν τοῖς πᾶσιν Ἀχαιοῖς ἐγένετο οὕτω δόκιμος ὡς Ἀράτῳ παρισωθῆναι τὰ ἐς δόξαν.", "st": "8.27"}, {"sp": "N", "t": "Λακεδαιμόνιοι δὲ αὐτοί τε πανδημεὶ καὶ ὁ τῆς οἰκίας βασιλεὺς τῆς ἑτέρας Ἆγις ὁ Εὐδαμίδου στρατεύουσιν ἐπὶ Μεγάλην πόλιν παρασκευῇ μείζονι καὶ ἀξιολογωτέρᾳ τῆς ὑπὸ Ἀκροτάτου συναχθείσης· καὶ μάχῃ τε ἐπεξελθόντας τοὺς Μεγαλοπολίτας ἐνίκησαν καὶ μηχάνημα ἰσχυρὸν προσάγοντες τῷ τείχει τὸν πύργον τὸν ταύτῃ δι’ αὐτοῦ σείουσι καὶ ἐς τὴν ὑστεραίαν καταρρίψειν τῷ μηχανήματι ἤλπιζον.", "st": "8.27"}, {"sp": "N", "t": "ἔμελλε δὲ ἄρα οὐχ Ἕλλησιν ὁ Βορέας ἔσεσθαι μόνον τοῖς πᾶσιν ὄφελος, τοῦ Μήδων ναυτικοῦ ταῖς Σηπιάσι προσράξας τὰς πολλάς, ἀλλὰ καὶ Μεγαλοπολίτας ὁ ἄνεμος οὗτος ἐρρύσατο μὴ ἁλῶναι· κατέλυσέ τε γὰρ τὸ μηχάνημα τοῦ Ἄγιδος καὶ διεφόρησεν ἐς ἀπώλειαν παντελῆ βιαίῳ τῷ πνεύματι ὁμοῦ καὶ συνεχεῖ. ὁ δὲ Ἆγις ὅτῳ τὰ ἐκ τοῦ Βορέου μὴ ἑλεῖν τὴν Μεγαλόπολιν ἐγένετο ἐμποδών, ἔστιν ὁ τὴν ἐν Ἀχαΐᾳ Πελλήνην ἀφαιρεθεὶς ὑπὸ Ἀράτου καὶ Σικυωνίων καὶ ὕστερον πρὸς Μαντινείᾳ χρησάμενος τῷ τέλει.", "st": "8.27"}, {"sp": "N", "t": "μετὰ δὲ οὐ πολὺν χρόνον Κλεομένης ὁ Λεωνίδου Μεγαλόπολιν κατέλαβεν ἐν σπονδαῖς. Μεγαλοπολιτῶν δὲ οἱ μὲν ἐν τῇ νυκτὶ εὐθὺς τότε ἀμύνοντες τῇ πατρίδι ἐπεπτώκεσαν, ἔνθα καὶ Λυδιάδην ἀγωνιζόμενον ἀξίως λόγου κατέλαβεν ἐν τῇ μάχῃ τὸ χρεών· τοὺς δὲ αὐτῶν Φιλοποίμην ὁ Κραύγιδος ὅσον τε τὰ δύο μέρη τῶν ἐν ἡλικίᾳ καὶ παῖδας ἅμα ἔχων καὶ γυναῖκας διέφυγεν ἐς τὴν Μεσσηνίαν.", "st": "8.27"}, {"sp": "N", "t": "Κλεομένης δὲ τούς τε ἐγκαταληφθέντας ἐφόνευε καὶ κατέσκαπτέ τε καὶ ἔκαιε τὴν πόλιν. Μεγαλοπολῖται μὲν δὴ τρόπον ὁποῖον ἀνεσώσαντο τὴν αὑτῶν καὶ ὁποῖα κατελθοῦσιν αὖθις ἐπράχθη σφίσι, δηλώσει τοῦ λόγου μοι τὰ ἐς Φιλοποίμενα· Λακεδαιμονίων δὲ τῷ δήμῳ τοῦ τῶν Μεγαλοπολιτῶν παθήματος μέτεστιν αἰτίας οὐδέν, ὅτι σφίσιν ἐκ βασιλείας μετέστησεν ἐς τυραννίδα ὁ Κλεομένης τὴν πολιτείαν.", "st": "8.27"}, {"sp": "N", "t": "Μεγαλοπολίταις δὲ καὶ Ἡραιεῦσι κατὰ τὰ εἰρημένα ἤδη μοι τοῦ Βουφάγου ποταμοῦ περὶ τὰς πηγάς εἰσιν ὅροι τῆς χώρας. γενέσθαι δὲ τῷ ποταμῷ τὸ ὄνομα ἀπὸ Βουφάγου φασὶν ἥρωος, εἶναι δὲ Ἰαπετοῦ τε παῖδα αὐτὸν καὶ Θόρνακος. ταύτην καὶ ἐν τῇ Λακωνικῇ Θόρνακα ὀνομάζουσι. λέγουσι δὲ καὶ ὡς ἐν Φολόῃ τῷ ὄρει τοξεύσειεν Ἄρτεμις Βουφάγον ἔργα τολμήσαντα οὐχ ὅσια ἐς τὴν θεόν.", "st": "8.27"}, {"sp": "N", "t": "ἰόντι δὲ ἀπὸ τοῦ ποταμοῦ τῶν πηγῶν, πρῶτα μέν σε ἐκδέξεται Μάραθα χωρίον, μετὰ δὲ αὐτὸ Γόρτυς κώμη τὰ ἐπ’ ἐμοῦ, τὰ δὲ ἔτι ἀρχαιότερα πόλις. ἔστι δὲ αὐτόθι ναὸς Ἀσκληπιοῦ λίθου Πεντελησίου, καὶ αὐτός τε οὐκ ἔχων πω γένεια καὶ Ὑγείας ἄγαλμα· Σκόπα δὲ ἦν ἔργα. λέγουσι δὲ οἱ ἐπιχώριοι καὶ τάδε, ὡς Ἀλέξανδρος ὁ Φιλίππου τὸν θώρακα καὶ δόρυ ἀναθείη τῷ Ἀσκληπιῷ· καὶ ἐς ἐμέ γε ἔτι ὁ θώραξ καὶ τοῦ δόρατος ἦν ἡ αἰχμή.", "st": "8.28"}, {"sp": "N", "t": "τὴν δὲ Γόρτυνα ποταμὸς διέξεισιν ὑπὸ μὲν τῶν περὶ τὰς πηγὰς ὀνομαζόμενος Λούσιος, ἐπὶ λουτροῖς δὴ τοῖς Διὸς τεχθέντος· οἱ δὲ ἀπωτέρω τῶν πηγῶν καλοῦσιν ἀπὸ τῆς κώμης Γορτύνιον. οὗτος ὁ Γορτύνιος ὕδωρ ψυχρότατον παρέχεται ποταμῶν. Ἴστρον μέν γε καὶ Ῥῆνον, ἔτι δὲ Ὕπανίν τε καὶ Βορυσθένην καὶ ὅσων ἄλλων ἐν ὥρᾳ χειμῶνος τὰ ῥεύματα πήγνυται, τούτους μὲν χειμερίους κατὰ ἐμὴν δόξαν ὀρθῶς ὀνομάσαι τις ἄν, οἳ ῥέουσι μὲν διὰ γῆς τὸ πολὺ τοῦ χρόνου νειφομένης, ἀνάπλεως δὲ κρυμοῦ καὶ ὁ περὶ αὐτούς ἐστιν ἀήρ·", "st": "8.28"}, {"sp": "N", "t": "ὅσοι δὲ γῆν διεξίασιν εὖ τῶν ὡρῶν ἔχουσαν καὶ θέρους σφίσι τὸ ὕδωρ πινόμενόν τε καὶ λουομένους ἀνθρώπους ἀναψύχει, χειμῶνος δὲ ἀνιαρὸν οὐκ ἔστι, τούτους ἐγώ φημι παρέχεσθαι σφᾶς ὕδωρ ψυχρόν. ψυχρὸν μὲν δὴ ὕδωρ καὶ Κύδνου τοῦ διεξιόντος Ταρσεῖς καὶ Μέλανος τοῦ παρὰ Σίδην τὴν Παμφύλων· Ἄλεντος δὲ τοῦ ἐν Κολοφῶνι καὶ ἐλεγείων ποιηταὶ τὴν ψυχρότητα ᾄδουσι. Γορτύνιος δὲ προήκει καὶ ἐς πλέον ψυχρότητος, μάλιστα δὲ ὥρᾳ θέρους. ἔχει μὲν δὴ τὰς πηγὰς ἐν Θεισόᾳ τῆ Μεθυδριεῦσιν ὁμόρῳ· καθότι δὲ τῷ Ἀλφειῷ τὸ ῥεῦμα ἀνακοινοῖ, καλοῦσι Ῥαιτέας.", "st": "8.28"}, {"sp": "N", "t": "τῇ χώρᾳ δὲ τῇ Θεισόᾳ προσεχὴς κώμη Τεῦθίς ἐστι· πάλαι δὲ ἦν πόλισμα ἡ Τεῦθις. ἐπὶ δὲ τοῦ πολέμου τοῦ πρὸς Ἰλίῳ ἰδίᾳ παρείχοντο οἱ ἐνταῦθα ἡγεμόνα· ὄνομα δὲ αὐτῷ Τεῦθιν, οἱ δὲ Ὄρνυτόν φασιν εἶναι. ὡς δὲ τοῖς Ἕλλησιν οὐκ ἐγίνετο ἐπίφορα ἐξ Αὐλίδος πνεύματα, ἀλλὰ ἄνεμος σφᾶς βίαιος ἐπὶ χρόνον εἶχεν ἐγκλείσας, ἀφίκετο ὁ Τεῦθις Ἀγαμέμνονι ἐς ἀπέχθειαν καὶ ὀπίσω τοὺς Ἀρκάδας ὧν ἦρχεν ἀπάξειν ἔμελλεν.", "st": "8.28"}, {"sp": "N", "t": "ἐνταῦθα Ἀθηνᾶν λέγουσι Μέλανι τῷ Ὦπος εἰκασμένην ἀποτρέπειν τῆς ὁδοῦ Τεῦθιν τῆς οἴκαδε· ὁ δέ, ἅτε οἰδοῦντος αὐτῷ τοῦ θυμοῦ, παίει τὴν θεὸν τῷ δόρατι ἐς τὸν μηρόν, ἀπήγαγε δὲ καὶ ἐκ τῆς Αὐλίδος ὀπίσω τὸν στρατόν. ἀναστρέψας δὲ ἐς τὴν οἰκείαν, τὴν θεὸν ἔδοξεν αὐτὴν τετρωμένην φανῆναί οἱ τὸν μηρόν· τὸ δὲ ἀπὸ τούτου κατέλαβε Τεῦθιν φθινώδης νόσος, μόνοις τε Ἀρκάδων τοῖς ἐνταῦθα οὐκ ἀπεδίδου καρπὸν οὐδένα ἡ γῆ.", "st": "8.28"}, {"sp": "N", "t": "χρόνῳ δὲ ὕστερον ἄλλα τε ἐχρήσθη σφίσιν ἐκ Δωδώνης, ὁποῖα δρῶντες ἱλάσεσθαι τὴν θεὸν ἔμελλον, καὶ ἄγαλμα ἐποιήσαντο Ἀθηνᾶς ἔχον τραῦμα ἐπὶ τοῦ μηροῦ. τοῦτο καὶ αὐτὸς τὸ ἄγαλμα εἶδον, τελαμῶνι πορφυρῷ τὸν μηρὸν κατειλημένον. καὶ ἄλλα ἐν Τεύθιδι, Ἀφροδίτης τε ἱερὸν καὶ Ἀρτέμιδός ἐστι.", "st": "8.28"}, {"sp": "N", "t": "ταῦτα μὲν δὴ ἐνταῦθά ἐστι· κατὰ δὲ τὴν ὁδὸν τὴν ἐκ Γόρτυνος ἐς Μεγάλην πόλιν πεποίηται μνῆμα τοῖς ἀποθανοῦσιν ἐν τῇ πρὸς Κλεομένην μάχῃ. τὸ δὲ μνῆμα τοῦτο ὀνομάζουσιν οἱ Μεγαλοπολῖται Παραιβασίον, ὅτι ἐς αὐτοὺς παρεσπόνδησεν ὁ Κλεομένης. Παραιβασίου δὲ ἔχεται πεδίον ἑξήκοντα σταδίων μάλιστα· καὶ πόλεως ἐρείπια Βρένθης ἐστὶν ἐν δεξιᾷ τῆς ὁδοῦ, καὶ ποταμὸς ἔξεισιν αὐτόθεν Βρενθεάτης καὶ ὅσον σταδίους προελθόντι πέντε κάτεισιν ἐς τὸν Ἀλφειόν.", "st": "8.28"}, {"sp": "N", "t": "διαβάντων δὲ Ἀλφειὸν χώρα τε καλουμένη Τραπεζουντία καὶ πόλεώς ἐστιν ἐρείπια Τραπεζοῦντος. καὶ αὖθις ἐπὶ τὸν Ἀλφειὸν ἐν ἀριστερᾷ καταβαίνοντι ἐκ Τραπεζοῦντος, οὐ πόρρω τοῦ ποταμοῦ Βάθος ἐστὶν ὀνομαζόμενον, ἔνθα ἄγουσι τελετὴν διὰ ἔτους τρίτου θεαῖς Μεγάλαις· καὶ πηγή τε αὐτόθι ἐστὶν Ὀλυμπιὰς καλουμένη, τὸν ἕτερον τῶν ἐν αὐτῶν οὐκ ἀπορρέουσα, καὶ πλησίον τῆς πηγῆς πῦρ ἄνεισι. λέγουσι δὲ οἱ Ἀρκάδες τὴν λεγομένην γιγάντων μάχην καὶ θεῶν ἐνταῦθα καὶ οὐκ ἐν τῇ Θρᾳκίᾳ γενέσθαι Παλλήνῃ, καὶ θύουσιν ἀστραπαῖς αὐτόθι καὶ θυέλλαις τε καὶ βρονταῖς.", "st": "8.29"}, {"sp": "N", "t": "γιγάντων δὲ ἐν μὲν Ἰλιάδι οὐδεμίαν ἐποιήσατο Ὅμηρος μνήμην· ἐν Ὀδυσσείᾳ δὲ ἔγραψε μὲν ὡς ταῖς Ὀδυσσέως ναυσὶ Λαιστρυγόνες ἐπέλθοιεν γίγασι καὶ οὐκ ἀνδράσιν εἰκασμένοι, ἐποίησε δὲ καὶ τὸν βασιλέα τῶν Φαιάκων λέγοντα εἶναι τοὺς Φαίακας θεῶν ἐγγὺς ὥσπερ Κύκλωπας καὶ τὸ γιγάντων ἔθνος. ἔν τε οὖν τούτοις δηλοῖ θνητοὺς ὄντας καὶ οὐ θεῖον γένος τοὺς γίγαντας καὶ σαφέστερον ἐν τῷδε ἔτι,<br>ὅς ποθ’ ὑπερθύμοισι γιγάντεσσιν βασίλευεν·<br>ἀλλ’ ὁ μὲν ὤλεσε λαὸν ἀτάσθαλον, ὤλετο δ’ αὐτός.<br>ἐθέλουσι δ’ αὐτῷ λαὸς ἐν τοῖς ἔπεσιν ἀνθρώπων οἱ πολλοὶ καλεῖσθαι.", "st": "8.29"}, {"sp": "N", "t": "δράκοντας δὲ ἀντὶ ποδῶν τοῖς γίγασιν εἶναι, πολλαχῇ τε ὁ λόγος ἄλλῃ καὶ ἐν τῷδε ἐδείχθη μάλιστα ὡς ἔστιν εὐήθης. Ὀρόντην τὸν Σύρων ποταμὸν οὐ τὰ πάντα ἐν ἰσοπέδῳ μέχρι θαλάσσης ῥέοντα, ἀλλὰ ἐπὶ κρημνόν τε ἀπορρῶγα καὶ ἐς κάταντες ἀπ’ αὐτοῦ φερόμενον, ἠθέλησεν ὁ Ῥωμαίων βασιλεὺς ἀναπλεῖσθαι ναυσὶν ἐκ θαλάσσης ἐς Ἀντιόχειαν πόλιν· ἔλυτρον οὖν σὺν πόνῳ τε καὶ δαπάνῃ χρημάτων ὀρυξάμενος ἐπιτήδειον ἐς τὸν ἀνάπλουν, ἐξέτρεψεν ἐς τοῦτο τὸν ποταμόν.", "st": "8.29"}, {"sp": "N", "t": "ἀναξηρανθέντος δὲ τοῦ ἀρχαίου ῥεύματος, κεραμεᾶ τε ἐν αὐτῷ σορὸς πλέον ἢ ἑνός τε καὶ δέκα εὑρέθη πηχῶν καὶ ὁ νεκρὸς μέγεθός τε ἦν κατὰ τὴν σορὸν καὶ ἄνθρωπος διὰ παντὸς τοῦ σώματος. τοῦτον τὸν νεκρὸν ⟨ὁ⟩ ἐν Κλάρῳ [ὁ] θεός, ἀφικομένων ἐπὶ τὸ χρηστήριον τῶν Σύρων, εἶπεν Ὀρόντην εἶναι, γένους δὲ αὐτὸν εἶναι τοῦ Ἰνδῶν. εἰ δὲ τὴν γῆν τὸ ἀρχαῖον οὖσαν ὑγρὰν ἔτι καὶ ἀνάπλεων νοτίδος θερμαίνων ὁ ἥλιος τοὺς πρώτους ἐποίησεν ἀνθρώπους, ποίαν εἰκός ἐστιν ἄλλην χώραν ἢ προτέραν τῆς Ἰνδῶν ἢ μείζονας ἀνεῖναι τοὺς ἀνθρώπους, ἥ γε καὶ ἐς ἡμᾶς ἔτι καὶ ὄψεως τῷ παραλόγῳ καὶ μεγέθει διάφορα ἐκτρέφει θηρία;", "st": "8.29"}, {"sp": "N", "t": "τοῦ δὲ χωρίου τοῦ ὀνομαζομένου Βάθους σταδίους ὡς δέκα ἀφέστηκεν ⟨ἡ⟩ καλουμένη Βασιλίς· ταύτης ἐγένετο οἰκιστὴς Κύψελος ὁ Κρεσφόντῃ τῷ Ἀριστομάχου τὴν θυγατέρα ἐκδούς· ἐπ’ ἐμοῦ δὲ ἐρείπια ἡ Βασιλὶς ἦν καὶ Δήμητρος ἱερὸν ἐν αὐτοῖς ἐλείπετο Ἐλευσινίας. ἐντεῦθεν δὲ προϊὼν τὸν Ἀλφειὸν αὖθις διαβήσῃ καὶ ἐπὶ Θωκνίαν ἀφίξῃ, τὸ ὄνομα ἀπὸ Θώκνου τοῦ Λυκάονος ἔχουσαν, ἐς ἅπαν δὲ ἐφ’ ἡμῶν ἔρημον· ἐλέγετο δὲ ὁ Θῶκνος ἐν τῷ λόφῳ κτίσαι τὴν πόλιν. ποταμὸς δὲ ὁ Ἀμίνιος ῥέων παρὰ τὸν λόφον ἐς τὸν Ἑλισσόντα ἐκδίδωσι, καὶ οὐ πολὺ ἄπωθεν ἐς τὸν Ἀλφειὸν ὁ Ἑλισσών.", "st": "8.29"}, {"sp": "N", "t": "ὁ δὲ Ἑλισσὼν οὗτος ἀρχόμενος ἐκ κώμης ὁμωνύμου —καὶ γὰρ τῇ κώμῃ τὸ ὄνομα Ἑλισσών ἐστι—τήν τε Διπαιέων καὶ τὴν Λυκαιᾶτιν χώραν, τρίτα δὲ αὐτὴν διεξελθὼν Μεγάλην πόλιν, ⟨εἴκοσι⟩ σταδίοις ἀπωτέρω Μεγαλοπολιτῶν τοῦ ἄστεως κάτεισιν ἐς τὸν Ἀλφειόν. πλησίον δὲ ἤδη τῆς πόλεως Ποσειδῶνός ἐστιν Ἐπόπτου ναός· ἐλείπετο δὲ τοῦ ἀγάλματος ἡ κεφαλή.", "st": "8.30"}, {"sp": "N", "t": "διαιροῦντος δὲ τὴν Μεγάλην πόλιν τοῦ ποταμοῦ τοῦ Ἑλισσόντος, καθὰ δὴ καὶ Κνίδον καὶ Μιτυλήνην δίχα οἱ εὔριποι νέμουσιν, ἐν μέρει τῷ πρὸς ἄρκτους, δεξιῷ δὲ κατὰ τὸ μετέωρον τοῦ ποταμοῦ, πεποίηταί σφισιν ἀγορά. περίβολος δέ ἐστιν ἐν ταύτῃ λίθων καὶ ἱερὸν Λυκαίου Διός, ἔσοδος δὲ ἐς αὐτὸ οὐκ ἔστι· τὰ γὰρ ἐντός ἐστι δὴ σύνοπτα, βωμοί τέ εἰσι τοῦ θεοῦ καὶ τράπεζαι δύο καὶ ἀετοὶ ταῖς τραπέζαις ἴσοι καὶ ἄγαλμα Πανὸς λίθου πεποιημένον·", "st": "8.30"}, {"sp": "N", "t": "ἐπίκλησις δὲ Σινόεις ἐστὶν αὐτῷ, τήν τε ἐπίκλησιν γενέσθαι τῷ Πανὶ ἀπὸ νύμφης Σινόης λέγουσι, ταύτην δὲ σὺν ἄλλαις τῶν νυμφῶν καὶ ἰδίᾳ γενέσθαι τροφὸν τοῦ Πανός. ἔστι δὲ πρὸ τοῦ τεμένους τούτου χαλκοῦν ἄγαλμα Ἀπόλλωνος θέας ἄξιον, μέγεθος μὲν ἐς πόδας δώδεκα, ἐκομίσθη δὲ ἐκ τῆς Φιγαλέων συντέλεια ἐς κόσμον τῇ Μεγάλῃ πόλει.", "st": "8.30"}, {"sp": "N", "t": "τὸ δὲ χωρίον ἔνθα τὸ ἄγαλμα ἵδρυτο ἐξ ἀρχῆς ὑπὸ Φιγαλέων, ὀνομάζεται Βᾶσσαι· τῷ θεῷ δὲ ἡ ἐπίκλησις ἠκολούθηκε μὲν ἐκ τῆς Φιγαλέων, ἐφ’ ὅτῳ δὲ ὄνομα ἔσχεν Ἐπικούριος, δηλώσει μοι τὰ ἐς Φιγαλέας τοῦ λόγου. ἔστι δὲ ἐν δεξιᾷ τοῦ Ἀπόλλωνος ἄγαλμα οὐ μέγα Μητρὸς θεῶν, τοῦ ναοῦ δέ, ὅτι μὴ οἱ κίονες, ἄλλο ὑπόλοιπον οὐδέν.", "st": "8.30"}, {"sp": "N", "t": "πρὸ δὲ τοῦ ναοῦ τῆς Μητρὸς ἀνδριὰς μὲν οὐδείς ἐστι, δῆλα δὲ ἦν τὰ βάθρα, ἐφ’ ὧν ἀνδριάντες ποτὲ ἑστήκεσαν. ἐλεγεῖον δὲ ἐπὶ ἑνὸς γεγραμμένον τῶν βάθρων Διοφάνους φησὶν εἶναι τὴν εἰκόνα, Διαίου μὲν υἱοῦ, συντάξαντος δὲ ἀνδρὸς πρώτου Πελοπόννησον τὴν πᾶσαν ἐς τὸν ὀνομασθέντα Ἀχαϊκὸν σύλλογον.", "st": "8.30"}, {"sp": "N", "t": "στοὰν δὲ τῆς ἀγορᾶς ὀνομαζομένην Φιλίππειον οὐ Φίλιππος ἐποίησεν ὁ Ἀμύντου, χαριζόμενοι δέ οἱ Μεγαλοπολῖται τὴν ἐπωνυμίαν διδόασιν αὐτῷ τοῦ οἰκοδομήματος. Ἑρμοῦ δὲ Ἀκακησίου πρὸς αὐτῇ ναὸς κατεβέβλητο, καὶ οὐδὲν ἐλείπετο ὅτι μὴ χελώνη λίθου. ταύτης δὲ ἔχεται τῆς Φιλιππείου μέγεθος ἀποδέουσα ἑτέρα στοά, Μεγαλοπολίταις δὲ αὐτόθι ᾠκοδομημένα ἐστὶ τὰ ἀρχεῖα, ἀριθμὸν οἰκήματα ἕξ· ἐν ἑνὶ δέ ἐστιν αὐτῶν Ἐφεσίας ἄγαλμα Ἀρτέμιδος καὶ ἐν ἑτέρῳ χαλκοῦς Πὰν πηχυαῖος ἐπίκλησιν Σκολείτας.", "st": "8.30"}, {"sp": "N", "t": "μετεκομίσθη δὲ ἀπὸ λόφου τοῦ Σκολείτα· καὶ ὁ λόφος οὗτος τοῦ τείχους ἐστὶν ἐντός, ἀπὸ δὲ αὐτοῦ κάτεισιν ὕδωρ ἐς τὸν Ἑλισσόντα ἐκ πηγῆς. τῶν ἀρχείων δὲ ὄπισθε ναὸς Τύχης καὶ ἄγαλμα λίθου πεποίηται ποδῶν πέντε οὐκ ἀποδέον. στοὰν δὲ ἥντινα καλοῦσι Μυρόπωλιν, ἔστι μὲν τῆς ἀγορᾶς, ᾠκοδομήθη δὲ ἀπὸ λαφύρων, ἡνίκα τὸ πταῖσμα ἐγένετο Ἀκροτάτῳ τῷ Κλεομένους καὶ Λακεδαιμονίων τοῖς συστρατεύσασι, μαχεσαμένοις πρὸς Ἀριστόδημον τυραννίδα ἐν Μεγάλῃ πόλει τότε ἔχοντα.", "st": "8.30"}, {"sp": "N", "t": "Μεγαλοπολίταις δὲ ἐπὶ τῆς ἀγορᾶς ἐστιν ὄπισθεν τοῦ περιβόλου τοῦ ἀνειμένου τῷ Λυκαίῳ Διὶ ἀνὴρ ἐπειργασμένος ἐπὶ στήλῃ, Πολύβιος Λυκόρτα· γέγραπται δὲ καὶ ἐλεγεῖα ἐπ’ αὐτῷ λέγοντα ὡς ἐπὶ γῆν καὶ θάλασσαν πᾶσαν πλανηθείη, καὶ ὅτι σύμμαχος γένοιτο Ῥωμαίων καὶ παύσειεν αὐτοὺς ὀργῆς ⟨τῆς⟩ ἐς τὸ Ἑλληνικόν. συνέγραψε δὲ ὁ Πολύβιος οὗτος καὶ ἄλλα ἔργα Ῥωμαίων καὶ ὡς Καρχηδονίοις κατέστησαν ἐς πόλεμον, αἰτία τε ἥτις ἐγένετο αὐτοῦ καὶ ὡς ὀψὲ", "st": "8.30"}, {"sp": "N", "t": "οὐκ ἄνευ κινδύνων μεγάλων Ῥωμαῖοι Σκιπίωνι … ὅν τινα Καρχηδονιακὸν ὀνομάζουσι τέλος τε ἐπιθέντα τῷ πολέμῳ καὶ τὴν Καρχηδόνα καταβαλόντα ἐς ἔδαφος. ὅσα μὲν δὴ Πολυβίῳ παραινοῦντι ὁ Ῥωμαῖος ἐπείθετο, ἐς ὀρθὸν ἐχώρησεν αὐτῷ· ἃ δὲ οὐκ ἠκροᾶτο διδάσκοντος, γενέσθαι οἱ λέγουσιν ἁμαρτήματα. Ἑλλήνων δὲ ὁπόσαι πόλεις ἐς τὸ Ἀχαϊκὸν συνετέλουν, παρὰ Ῥωμαίων εὕραντο αὗται Πολύβιόν σφισι πολιτείας τε καταστήσασθαι καὶ νόμους θεῖναι. τῆς δ’ εἰκόνος τοῦ Πολυβίου τὸ βουλευτήριόν ἐστιν ἐν ἀριστερᾷ.", "st": "8.30"}, {"sp": "N", "t": "τοῦτο μὲν δή ἐστιν ἐνταῦθα, στοὰν δὲ τῆς ἀγορᾶς Ἀριστάνδρειον ἐπίκλησιν ἄνδρα τῶν ἀστῶν Ἀρίστανδρον οἰκοδομῆσαι λέγουσι. ταύτης τῆς στοᾶς ἐστιν ἐγγυτάτω ὡς πρὸς ἥλιον ἀνίσχοντα ἱερὸν Σωτῆρος ἐπίκλησιν Διός· κεκόσμηται δὲ πέριξ κίοσι. καθεζομένῳ δὲ τῷ Διὶ ἐν θρόνῳ παρεστήκασι τῇ μὲν ἡ Μεγάλη πόλις, ἐν ἀριστερᾷ δὲ Ἀρτέμιδος Σωτείρας ἄγαλμα. ταῦτα μὲν λίθου τοῦ Πεντελησίου Ἀθηναῖοι Κηφισόδοτος καὶ Ξενοφῶν εἰργάσαντο·", "st": "8.30"}, {"sp": "N", "t": "τὸ δὲ ἕτερον πέρας τῆς στοᾶς παρέχεται τὸ πρὸς ἡλίου δυσμῶν περίβολον θεῶν ἱερὸν τῶν Μεγάλων. αἱ δέ εἰσιν αἱ Μεγάλαι θεαὶ Δημήτηρ καὶ Κόρη, καθότι ἐδήλωσα ἤδη καὶ ἐν τῇ Μεσσηνίᾳ συγγραφῇ· τὴν Κόρην δὲ Σώτειραν καλοῦσιν οἱ Ἀρκάδες. ἐπειργασμένοι δὲ ἐπὶ τύπων πρὸ τῆς ἐσόδου τῇ μὲν Ἄρτεμις, τῇ δὲ Ἀσκληπιός ἐστι καὶ Ὑγεία.", "st": "8.31"}, {"sp": "N", "t": "θεαὶ δὲ αἱ Μεγάλαι Δημήτηρ μὲν λίθου διὰ πάσης, ἡ δὲ Σώτειρα τὰ ἐσθῆτος ἐχόμενα ξύλου πεποίηται· μέγεθος δὲ ἑκατέρας πέντε που καὶ δέκα εἰσὶ πόδες. τά τε ἀγάλματα ⟨Δαμοφῶν⟩ καὶ πρὸ αὐτῶν κόρας ἐποίησεν οὐ μεγάλας, ἐν χιτῶσί τε καθήκουσιν ἐς σφυρὰ καὶ ἀνθῶν ἀνάπλεων ἑκατέρα τάλαρον ἐπὶ τῇ κεφαλῇ φέρει· εἶναι δὲ θυγατέρες τοῦ Δαμοφῶντος λέγονται, τοῖς δὲ ἐπανάγουσιν ἐς τὸ θειότερον δοκεῖ σφᾶς Ἀθηνᾶν τε εἶναι καὶ Ἄρτεμιν τὰ ἄνθη μετὰ τῆς Περσεφόνης συλλεγούσας.", "st": "8.31"}, {"sp": "N", "t": "ἔστι δὲ καὶ Ἡρακλῆς παρὰ τῇ Δήμητρι μέγεθος μάλιστα πῆχυν· τοῦτον τὸν Ἡρακλέα εἶναι τῶν Ἰδαίων καλουμένων Δακτύλων Ὀνομάκριτός φησιν ἐν τοῖς ἔπεσι. κεῖται δὲ τράπεζα ἔμπροσθεν, ἐπειργασμέναι τε ἐπ’ αὐτῇ δύο τέ εἰσιν Ὧραι καὶ ἔχων Πὰν σύριγγα καὶ Ἀπόλλων κιθαρίζων· ἔστι δὲ καὶ ἐπίγραμμα ἐπ’ αὐτοῖς εἶναι σφᾶς θεῶν τῶν πρώτων.", "st": "8.31"}, {"sp": "N", "t": "πεποίηνται δὲ ἐπὶ τραπέζῃ καὶ Νύμφαι· Νέδα μὲν Δία φέρουσά ἐστι νήπιον παῖδα, Ἀνθρακία δὲ νύμφη τῶν Ἀρκαδικῶν καὶ αὕτη δᾷδα ἔχουσά ἐστιν, Ἁγνὼ δὲ τῇ μὲν ὑδρίαν, ἐν δὲ τῇ ἑτέρᾳ χειρὶ φιάλην· Ἀγχιρόης δὲ καὶ Μυρτωέσσης εἰσὶν ὑδρίαι τὰ φορήματα, καὶ ὕδωρ δῆθεν ἀπ’ αὐτῶν κάτεισιν. τοῦ περιβόλου δέ ἐστιν ἐντὸς Φιλίου Διὸς ναός, Πολυκλείτου μὲν τοῦ Ἀργείου τὸ ἄγαλμα, Διονύσῳ δὲ ἐμφερές· κόθορνοί τε γὰρ τὰ ὑποδήματά ἐστιν αὐτῷ καὶ ἔχει τῇ χειρὶ ἔκπωμα, τῇ δὲ ἑτέρᾳ θύρσον, κάθηται δὲ ἀετὸς ἐπὶ τῷ θύρσῳ· καίτοι ⟨τοῖς⟩ γε ἐς Διόνυσον λεγομένοις τοῦτο οὐχ ὁμολογοῦν ἐστι.", "st": "8.31"}, {"sp": "N", "t": "τούτου δὲ ὄπισθεν τοῦ ναοῦ δένδρων ἐστὶν ἄλσος οὐ μέγα, θριγκῷ περιεχόμενον· ἐς μὲν δὴ τὸ ἐντὸς ἔσοδος οὐκ ἔστιν ἀνθρώποις, πρὸ δὲ αὐτοῦ Δήμητρος καὶ Κόρης ὅσον τε ποδῶν τριῶν εἰσιν ἀγάλματα. ἔστι δὲ ἐντὸς τοῦ περιβόλου τῶν Μεγάλων θεῶν καὶ Ἀφροδίτης ἱερόν. πρὸ μὲν δὴ τῆς ἐσόδου ξόανά ἐστιν ἀρχαῖα, Ἥρα καὶ Ἀπόλλων τε καὶ Μοῦσαι—ταῦτα κομισθῆναί φασιν ἐκ Τραπεζοῦντος—, ἀγάλματα δὲ ἐν τῷ ναῷ Δαμοφῶν", "st": "8.31"}, {"sp": "N", "t": "ἐποίησεν Ἑρμῆν ξύλου καὶ Ἀφροδίτης ξόανον· καὶ ταύτης χεῖρές εἰσι λίθου καὶ πρόσωπόν τε καὶ ἄκροι πόδες. τὴν δὲ ἐπίκλησιν τῇ θεῷ Μαχανῖτιν ὀρθότατα ἔθεντο ἐμοὶ δοκεῖν· Ἀφροδίτης [τε] ⟨γὰρ⟩ ἕνεκα καὶ ἔργων τῶν ταύτης πλεῖσται μὲν ἐπιτεχνήσεις, παντοῖα δὲ ἀνθρώποις ἀνευρημένα ἐς λόγους ἐστίν.", "st": "8.31"}, {"sp": "N", "t": "ἑστήκασι δὲ καὶ ἀνδριάντες ἐν οἰκήματι, Καλλιγνώτου τε καὶ Μέντα καὶ Σωσιγένους τε καὶ Πώλου· καταστήσασθαι δὲ οὗτοι Μεγαλοπολίταις λέγονται πρῶτον τῶν Μεγάλων θεῶν τὴν τελετήν, καὶ τὰ δρώμενα τῶν Ἐλευσῖνί ἐστι μιμήματα. κεῖται δὲ ἐντὸς τοῦ περιβόλου θεῶν τοσάδε ἄλλων ἀγάλματα τὸ τετράγωνον παρεχόμενα σχῆμα, Ἑρμῆς τε ἐπίκλησιν Ἀγήτωρ καὶ Ἀπόλλων καὶ Ἀθηνᾶ τε καὶ Ποσειδῶν, ἔτι δὲ Ἥλιος ἐπωνυμίαν ἔχων Σωτὴρ [δὲ] εἶναι καὶ Ἡρακλῆς. ᾠκοδόμηται δὲ καὶ ⟨ἱερόν⟩ σφισι μεγέθει μέγα, καὶ ἄγουσιν ἐνταῦθα τὴν τελετὴν ταῖς θεαῖς.", "st": "8.31"}, {"sp": "N", "t": "τοῦ ναοῦ δὲ τῶν Μεγάλων θεῶν ἐστιν ἱερὸν ἐν δεξιᾷ καὶ Κόρης· λίθου δὲ τὸ ἄγαλμα ποδῶν ὀκτὼ μάλιστα· ταινίαι δὲ ἐπέχουσι διὰ παντὸς τὸ βάθρον. ἐς τοῦτο τὸ ἱερὸν γυναιξὶ μὲν τὸν πάντα ἐστὶν ἔσοδος χρόνον, οἱ δὲ ἄνδρες οὐ πλέον ἢ ἅπαξ κατὰ ἔτος ἕκαστον ἐς αὐτὸ ἐσίασι. γυμνάσιον δὲ τῇ ἀγορᾷ συνεχὲς κατὰ ἡλίου δυσμάς ἐστιν ᾠκοδομημένον.", "st": "8.31"}, {"sp": "N", "t": "τῆς στοᾶς δὲ ἣν ἀπὸ τοῦ Μακεδόνος Φιλίππου καλοῦσι, ταύτης εἰσὶ δύο ὄπισθεν λόφοι, οὐκ ἐς ὕψος ἀνήκοντες· ἐρείπια δὲ Ἀθηνᾶς ἱεροῦ Πολιάδος ἐπὶ αὐτῷ, καὶ τῷ ἑτέρῳ ναός ἐστιν Ἥρας Τελείας, ὁμοίως καὶ ταῦτα ἐρείπια. ὑπὸ τούτῳ τῷ λόφῳ Βάθυλλος καλουμένη πηγὴ συντελεῖ καὶ αὕτη τῷ ποταμῷ Ἑλισσόντι ἐς μέγεθος.", "st": "8.31"}, {"sp": "N", "t": "τοσάδε ἐνταῦθα ἀξιόχρεα ἦν· ἡ δὲ ἐπέκεινα τοῦ ποταμοῦ μοῖρα ἡ κατὰ μεσημβρίαν παρείχετο ἐς μνήμην θέατρον μέγιστον τῶν ἐν τῇ Ἑλλάδι· ἐν δὲ αὐτῷ καὶ ἀέναός ἐστιν ὕδατος πηγή. τοῦ θεάτρου δὲ οὐ πόρρω λείπεται τοῦ βουλευτηρίου θεμέλια, ὃ τοῖς μυρίοις ἐπεποίητο Ἀρκάδων· ἐκαλεῖτο δὲ ἀπὸ τοῦ ἀναθέντος Θερσίλιον. πλησίον δὲ οἰκίαν, ἰδιώτου κατ’ ἐμὲ κτῆμα ἀνδρός, [ὃ] Ἀλεξάνδρῳ τῷ Φιλίππου τὸ ἐξ ἀρχῆς ἐποίησαν· ἔστι δὲ ἄγαλμα Ἄμμωνος πρὸς τῇ οἰκίᾳ, τοῖς τετραγώνοις Ἑρμαῖς εἰκασμένον, κέρατα ἐπὶ τῆς κεφαλῆς ἔχον κριοῦ.", "st": "8.32"}, {"sp": "N", "t": "τὸ δὲ τῶν Μουσῶν Ἀπόλλωνός τε ἱερὸν καὶ Ἑρμοῦ, κατασκευασθέν σφισιν ἐν κοινῷ, παρείχετο [δὲ] ἐς μνήμην θεμέλια οὐ πολλά· ἦν δὲ καὶ τῶν Μουσῶν μία ἔτι καὶ Ἀπόλλωνος ἄγαλμα κατὰ τοὺς Ἑρμᾶς τοὺς τετραγώνους τέχνην. ἐρείπια δὲ καὶ τῆς Ἀφροδίτης ἦν τὸ ἱερὸν, πλὴν ὅσον πρόναός τε ἐλείπετο ἔτι καὶ ἀγάλματα ἀριθμὸν τρία, ἐπίκλησις δὲ Οὐρανία, τῇ δ’ ἔστι Πάνδημος, τῇ τρίτῃ δὲ οὐδὲν ἐτίθεντο·", "st": "8.32"}, {"sp": "N", "t": "ἀπέχει δὲ οὐ πολὺ Ἄρεως βωμός, ἐλέγετο δὲ ὡς καὶ ἱερὸν ἐξ ἀρχῆς ᾠκοδομήθη τῷ θεῷ. πεποίηται δὲ καὶ στάδιον ὑπὲρ τῆς Ἀφροδίτης τῇ μὲν ἐπὶ τὸ θέατρον καθῆκον—καὶ κρήνη σφίσιν ἐστὶν αὐτόθι, ἣν ἱερὰν Διονύσου νομίζουσι—, κατὰ δὲ τὸ ἕτερον τοῦ σταδίου πέρας Διονύσου ναὸς ἐλέγετο ὑπὸ τοῦ θεοῦ κεραυνωθῆναι γενεαῖς δύο ἐμοῦ πρότερον, καὶ ἐρείπια οὐ πολλὰ ἔτι ἐς ἐμὲ ἦν αὐτοῦ. Ἡρακλέους δὲ κοινὸς καὶ Ἑρμοῦ πρὸς τῷ σταδίῳ ναὸς μὲν οὐκέτι ἦν, μόνος δέ σφισι βωμὸς ἐλείπετο.", "st": "8.32"}, {"sp": "N", "t": "ἔστι δὲ ἐν τῇ μοίρᾳ ταύτῃ λόφος πρὸς ἀνίσχοντα ἥλιον καὶ Ἀγροτέρας ἐν αὐτῷ ναὸς Ἀρτέμιδος, ἀνάθημα Ἀριστοδήμου καὶ τοῦτο. τῆς δὲ Ἀγροτέρας ἐστὶν ἐν δεξιᾷ τέμενος· ἐνταῦθα ἔστι μὲν ἱερὸν Ἀσκληπιοῦ καὶ ἀγάλματα αὐτός τε καὶ Ὑγεία, εἰσὶ δὲ ὑποκαταβάντι ὀλίγον θεοὶ— παρέχονται δὲ καὶ οὗτοι σχῆμα τετράγωνον, Ἐργάται δέ ἐστιν αὐτοῖς ἐπίκλησις—Ἀθηνᾶ τε Ἐργάνη καὶ Ἀπόλλων Ἀγυιεύς· τῷ δὲ Ἑρμῇ καὶ Ἡρακλεῖ καὶ Εἰλειθυίᾳ πρόσεστιν ἐξ ἐπῶν τῶν Ὁμήρου φήμη, τῷ μὲν Διός τε αὐτὸν διάκονον εἶναι καὶ ὑπὸ τὸν Ἅιδην ἄγειν τῶν ἀπογινομένων τὰς ψυχάς, Ἡρακλεῖ δὲ ὡς πολλούς τε καὶ χαλεποὺς τελέσειεν ἄθλους· Εἰλειθυίᾳ δὲ ἐποίησεν ἐν Ἰλιάδι ὠδῖνας γυναικῶν μέλειν.", "st": "8.32"}, {"sp": "N", "t": "ἔστι δὲ καὶ ἄλλο ὑπὸ τὸν λόφον τοῦτον Ἀσκληπιοῦ Παιδὸς ἱερόν· τούτου μὲν δὴ τὸ ἄγαλμα ὀρθὸν πεποίηται πηχυαῖον μάλιστα, Ἀπόλλωνος δὲ ἐν θρόνῳ κάθηται ποδῶν ἓξ οὐκ ἀποδέον μέγεθος. ἀνάκειται δὲ αὐτόθι καὶ ὀστᾶ ὑπερηρκότα ἢ ὡς ἀνθρώπου δοκεῖν· καὶ δὴ καὶ ἐλέγετο ἐπ’ αὐτοῖς εἶναι τῶν γιγάντων ἑνός, οὓς ἐς τὴν συμμαχίαν τῆς Ῥέας ἤθροισεν Ὁπλάδαμος, ἃ δὴ καὶ ἐς ὕστερον ἐπέξεισιν ἡμῖν ὁ λόγος. τούτου δέ ἐστι πηγὴ τοῦ ἱεροῦ πλησίον, καὶ ἀπ’ αὐτῆς ὁ Ἑλισσὼν τὸ ὕδωρ δέχεται κατερχόμενον.", "st": "8.32"}, {"sp": "N", "t": "εἰ δὲ ἡ Μεγάλη πόλις προθυμίᾳ τε τῇ πάσῃ συνοικισθεῖσα ὑπὸ Ἀρκάδων καὶ ἐπὶ μεγίσταις τῶν Ἑλλήνων ἐλπίσιν ἐς αὐτὴν κόσμον τὸν ἅπαντα καὶ εὐδαιμονίαν τὴν ἀρχαίαν ἀφῄρηται καὶ τὰ πολλά ἐστιν αὐτῆς ἐρείπια ἐφ’ ἡμῶν, θαῦμα οὐδὲν ἐποιησάμην, εἰδὼς τὸ δαιμόνιον νεώτερα ἀεί τινα ἐθέλον ἐργάζεσθαι, καὶ ὁμοίως τὰ πάντα τά τε ἐχυρὰ καὶ τὰ ἀσθενῆ καὶ τὰ γινόμενά τε καὶ ὁπόσα ἀπόλλυνται μεταβάλλουσαν τὴν τύχην, καὶ ὅπως ἂν αὐτῇ παριστῆται μετὰ ἰσχυρᾶς ἀνάγκης ἄγουσαν.", "st": "8.33"}, {"sp": "N", "t": "Μυκῆναι μέν γε, τοῦ πρὸς Ἰλίῳ πολέμου τοῖς Ἕλλησιν ἡγησαμένη, καὶ Νῖνος, ἔνθα ἦν Ἀσσυρίοις βασίλεια, καὶ Βοιώτιαι Θῆβαι προστῆναι τοῦ Ἑλληνικοῦ ποτε ἀξιωθεῖσαι, αἱ μὲν ἠρήμωνται πανώλεθροι, τὸ δὲ ὄνομα τῶν Θηβῶν ἐς ἀκρόπολιν μόνην καὶ οἰκήτορας καταβέβηκεν οὐ πολλούς. τὰ δὲ ὑπερηρκότα πλούτῳ τὸ ἀρχαῖον, Θῆβαί τε αἱ Αἰγύπτιοι καὶ ὁ Μινύης Ὀρχομενὸς καὶ ἡ Δῆλος τὸ κοινὸν Ἑλλήνων ἐμπόριον, αἱ μὲν ἀνδρὸς ἰδιώτου μέσου δυνάμει χρημάτων καταδέουσιν ἐς εὐδαιμονίαν, ἡ Δῆλος δέ, ἀφελόντι τοὺς ἀφικνουμένους παρ’ Ἀθηναίων ἐς τοῦ ἱεροῦ τὴν φρουράν, Δηλίων γε ἕνεκα ἔρημός ἐστιν ἀνθρώπων.", "st": "8.33"}, {"sp": "N", "t": "Βαβυλῶνος δὲ τοῦ μὲν Βήλου τὸ ἱερὸν λείπεται, Βαβυλῶνος δὲ ταύτης, ἥντινα εἶδε πόλεων τῶν τότε μεγίστην ἥλιος, οὐδὲν ἔτι ἦν εἰ μὴ τεῖχος, καθὰ καὶ Τίρυνθος τῆς ἐν τῇ Ἀργολίδι. ταῦτα μὲν δὴ ἐποίησεν ὁ δαίμων εἶναι τὸ μηδέν· ἡ δὲ Ἀλεξάνδρου πόλις ἐν Αἰγύπτῳ καὶ ἡ Σελεύκου παρὰ τῷ Ὀρόντῃ χθές τε ᾠκισμέναι καὶ πρῴην ἐς τοσοῦτο ἐπιδεδώκασι μεγέθους καὶ εὐδαιμονίας, ὅτι σφᾶς ἡ τύχη δεξιοῦται.", "st": "8.33"}, {"sp": "N", "t": "ἐπιδείκνυται δὲ καὶ ἐν τῷδε ἔτι τὴν ἰσχὺν μείζονα καὶ θαύματος πλείονος ἢ κατὰ συμφορὰς καὶ εὐπραγίας πόλεων· Λήμνου γὰρ πλοῦν ἀπεῖχεν οὐ πολὺν Χρύση νῆσος, ἐν ᾗ καὶ τῷ Φιλοκτήτῃ γενέσθαι συμφορὰν ἐκ τοῦ ὕδρου φασί· ταύτην κατέλαβεν ὁ κλύδων πᾶσαν, καὶ κατέδυ τε ἡ Χρύση καὶ ἠφάνισται κατὰ τοῦ βυθοῦ. νῆσον δὲ ἄλλην καλουμένην Ἱερὰν … τόνδε οὐκ ἦν χρόνον. οὕτω μὲν τὰ ἀνθρώπινα πρόσκαιρά τε καὶ οὐδαμῶς ἐστιν ἐχυρά·", "st": "8.33"}, {"sp": "N", "t": "ἐκ δὲ Μεγάλης πόλεως ἰόντι ἐς Μεσσήνην καὶ σταδίους μάλιστα προελθόντι ἑπτά, ἔστιν ἐν ἀριστερᾷ τῆς λεωφόρου θεῶν ἱερόν. καλοῦσι δὲ καὶ αὐτὰς τὰς θεὰς καὶ τὴν χώραν τὴν περὶ τὸ ἱερὸν Μανίας· δοκεῖν δέ μοι θεῶν τῶν Εὐμενίδων ἐστὶν ἐπίκλησις, καὶ Ὀρέστην ἐπὶ τῷ φόνῳ τῆς μητρός φασιν αὐτόθι μανῆναι.", "st": "8.34"}, {"sp": "N", "t": "οὐ πόρρω δὲ τοῦ ἱεροῦ γῆς χῶμά ἐστιν οὐ μέγα, ἐπίθημα ἔχον λίθου πεποιημένον δάκτυλον, καὶ δὴ καὶ ὄνομα τῷ χώματί ἐστι Δακτύλου μνῆμα· ἐνταῦθα ἔκφρονα Ὀρέστην γενόμενον λέγουσιν ἕνα τῆς ἑτέρας τῶν χειρῶν ἀποφαγεῖν δάκτυλον. τούτῳ δέ ἐστιν ἕτερον συνεχὲς χωρίον Ἄκη καλούμενον, ὅτι ἐγένετο ἐν αὐτῷ τῆς νόσου τῷ Ὀρέστῃ τὰ ἰάματα· πεποίηται δὲ Εὐμενίσι καὶ αὐτόθι ἱερὸν.", "st": "8.34"}, {"sp": "N", "t": "ταύτας τὰς θεάς, ἡνίκα τὸν Ὀρέστην ἔκφρονα ἔμελλον ποιήσειν, φασὶν αὐτῷ φανῆναι μελαίνας· ὡς δὲ ἀπέφαγε τὸν δάκτυλον, τὰς δὲ αὖθις δοκεῖν οἱ λευκὰς εἶναι, καὶ αὐτὸν σωφρονῆσαί τε ἐπὶ τῇ θέᾳ καὶ οὕτω ταῖς μὲν ἐνήγισεν ἀποτρέπων τὸ μήνιμα αὐτῶν, ταῖς δὲ ἔθυσε ταῖς λευκαῖς. ὁμοῦ δὲ αὐταῖς καὶ Χάρισι θύειν νομίζουσι. πρὸς δὲ τῷ χωρίῳ τοῖς Ἄκεσιν ἕτερόν ἐστιν ⟨Κουρεῖον⟩ ὀνομαζόμενον ἱερόν, ὅτι Ὀρέστης ἐνταῦθα ἐκείρατο τὴν κόμην, ἐπειδὴ ἐντὸς ἐγένετο αὑτοῦ·", "st": "8.34"}, {"sp": "N", "t": "Πελοποννησίων δὲ οἱ τὰ ἀρχαῖα μνημονεύοντες πρότερα τῷ Ὀρέστῃ τὰ ἐν Ἀρκαδίᾳ γενέσθαι φασὶν ὑπὸ Ἐρινύων τῶν Κλυταιμνήστρας ἢ ἐν Ἀρείῳ πάγῳ τὴν κρίσιν, καὶ αὐτῷ κατήγορον ⟨οὐ⟩ τὸν Τυνδάρεων—περιεῖναι γὰρ οὐκέτι ἐκεῖνον—, Περίλαον δὲ ἐπιστῆναι δίκην [καὶ] ἐπὶ τῷ αἵματι τῆς μητρὸς αἰτοῦντα ἅτε ἀνεψιὸν τῆς Κλυταιμνήστρας· Ἰκαρίου γὰρ παῖδα εἶναι Περίλαον, γενέσθαι δὲ ὕστερον καὶ θυγατέρας τῷ Ἰκαρίῳ.", "st": "8.34"}, {"sp": "N", "t": "ἐκ Μανιῶν δὲ ὁδὸς ἐπὶ τὸν Ἀλφειόν ἐστιν ὅσον πέντε σταδίων καὶ δέκα· κατὰ τοῦτο Γαθεάτας ποταμὸς ἐκδίδωσιν ἐς τὸν Ἀλφειόν, ἐς δὲ τὸν Γαθεάταν πρότερον ἔτι κάτεισιν ὁ Καρνίων. τούτῳ μὲν δὴ αἱ πηγαὶ γῆς εἰσι τῆς Αἰγύτιδος ὑπὸ τοῦ Ἀπόλλωνος τοῦ Κερεάτα τὸ ἱερόν, τῷ Γαθεάτᾳ δὲ τῆς Κρωμίτιδος χώρας ἐν Γαθέαις.", "st": "8.34"}, {"sp": "N", "t": "ἡ δὲ Κρωμῖτις ἀνωτέρω τοῦ Ἀλφειοῦ σταδίους ὡς τεσσαράκοντά ἐστι, καὶ ἐν αὐτῇ πόλεως Κρώμων οὐ παντάπασι τὰ ἐρείπια ἦν ἐξίτηλα. ἐκ δὲ Κρώμων ὡς εἴκοσι στάδιά ἐστιν ἐπὶ Νυμφάδα· καταρρεῖται δὲ ὕδατι καὶ δένδρων ἀνάπλεώς ἐστιν ἡ Νυμφάς. καὶ ἀπ’ αὐτῆς στάδια εἴκοσί ἐστιν ἐπὶ τὸ Ἑρμαῖον, ἐς ὃ Μεσσηνίοις καὶ Μεγαλοπολίταις εἰσὶν ὅροι· πεποίηνται δὲ αὐτόθι καὶ Ἑρμῆν ἐπὶ στήλῃ.", "st": "8.34"}, {"sp": "N", "t": "αὕτη μὲν ἐπὶ Μεσσήνην, ἑτέρα δὲ ⟨ὁδὸς⟩ ἐκ Μεγάλης πόλεως ἐπὶ Καρνάσιον ἄγει τὸ Μεσσηνίων· καὶ ταύτῃ πρῶτα μέν σε ὁ Ἀλφειὸς ἐκδέξεται, καθότι καὶ Μαλοῦς καὶ ὁ Σκῦρος ἐς αὐτὸν κατέρχονται προανακοινωσάμενοι τὸ ῥεῦμα. αὐτόθεν δὲ ἔχων τὸν Μαλοῦντα ἐν δεξιᾷ μετὰ σταδίους ὡς τριάκοντα διαβήσῃ τε αὐτὸν καὶ ἀναβήσῃ δι’ ὁδοῦ προσαντεστέρας ἐς χωρίον καλούμενον Φαιδρίαν.", "st": "8.35"}, {"sp": "N", "t": "Φαιδρίου δὲ ὡς πέντε ἀπέχει καὶ δέκα σταδίους ⟨τὸ⟩ κατὰ Δέσποιναν ὀνομαζόμενον Ἑρμαῖον· ὅροι Μεσσηνίων πρὸς Μεγαλοπολίτας καὶ οὗτοι, καὶ ἀγάλματα οὐ μεγάλα Δεσποίνης τε καὶ Δήμητρος, ἔτι δὲ καὶ Ἑρμοῦ πεποίηται [δὲ] καὶ Ἡρακλέους· δοκεῖν δέ μοι καὶ τὸ ὑπὸ Δαιδάλου ποιηθὲν τῷ Ἡρακλεῖ ξόανον ἐν μεθορίῳ τῆς Μεσσηνίας καὶ Ἀρκάδων ἐνταῦθα εἱστήκει.", "st": "8.35"}, {"sp": "N", "t": "ἡ δὲ ἐς Λακεδαίμονα ἐκ Μεγάλης πόλεως ὁδὸς ἐπὶ μὲν τὸν Ἀλφειὸν στάδιοι τριάκοντά εἰσιν, ἀπὸ δὲ τοῦδε παρὰ ποταμὸν ὁδεύσας Θειοῦντα—κάτεισι δὲ καὶ ὁ Θειοῦς οὗτος ἐς τὸν Ἀλφειόν—, ἀπολιπὼν οὖν τὸν Θειοῦντα ἐν ἀριστερᾷ σταδίοις ἀπὸ τοῦ Ἀλφειοῦ τεσσαράκοντα ἥξεις μάλιστα ἐς Φαλαισίας· ἀπέχουσι δὲ αἱ Φαλαισίαι σταδίους εἴκοσι τοῦ Ἑρμαίου τοῦ κατὰ Βελεμίναν.", "st": "8.35"}, {"sp": "N", "t": "λέγουσι μὲν δὴ οἱ Ἀρκάδες τὴν Βελεμίναν τῆς σφετέρας οὖσαν τὸ ἀρχαῖον ἀποτεμέσθαι Λακεδαιμονίους· λέγειν δὲ οὐκ εἰκότα ἐφαίνοντό μοι καὶ ἄλλων ἕνεκα καὶ μάλιστα ὅτι μοι δοκοῦσι Θηβαῖοι μηδ’ ἂν τοῦτο ἐλασσουμένους περιιδεῖν τοὺς Ἀρκάδας, εἴ σφισιν ἔσεσθαι σὺν τῷ δικαίῳ τὸ ἐπανόρθωμα ἔμελλεν.", "st": "8.35"}, {"sp": "N", "t": "εἰσὶ δὲ ἐκ Μεγάλης πόλεως καὶ ἐς τὰ χωρία ὁδοὶ τὰ ἐντὸς Ἀρκαδίας, ἐς ⟨μὲν⟩ Μεθύδριον ἑβδομήκοντα στάδιοι καὶ ἑκατόν, τρισὶ δὲ ἀπὸ Μεγάλης πόλεως ἀπωτέρω σταδίοις καὶ δέκα Σκιάς τε καλούμενον χωρίον καὶ Ἀρτέμιδος Σκιάτιδος ἐρείπιά ἐστιν ἱεροῦ· ποιῆσαι δὲ αὐτὸ ἐλέγετο Ἀριστόδημος ὁ τυραννήσας. ἐντεῦθεν μετὰ σταδίους ὡς δέκα πόλεως Χαρισιῶν ὑπομνήματά ἐστιν οὐ πολλά, σταδίων δὲ ἄλλων δέκα ἐστὶν ἀπὸ Χαρισιῶν ἐς Τρικολώνους ὁδός.", "st": "8.35"}, {"sp": "N", "t": "πόλις δὲ ἦσαν καὶ οἱ Τρικόλωνοί ποτε· μένει δὲ αὐτόθι καὶ ἐς ἡμᾶς ἔτι ἐπὶ λόφου Ποσειδῶνος ἱερὸν καὶ ἄγαλμα τετράγωνον, καὶ δένδρων περὶ τὸ ἱερόν ἐστιν ἄλσος. ταύταις μὲν δὴ οἱ Λυκάονος παῖδες ἐγένοντο οἰκισταί, Ζοιτίαν δὲ ἀπωτέρω μὲν Τρικολώνων πέντε που καὶ δέκα σταδίοις, κειμένην δὲ οὐ κατ’ εὐθὺ ἀλλ’ ἐκ Τρικολώνων ἐν ἀριστερᾷ, Ζοιτέα οἰκίσαι τὸν Τρικολώνου λέγουσι· Παρωρεὺς δὲ ὁ νεώτερος Τρικολώνου τῶν παίδων Παρωρίαν καὶ οὗτος ἔκτισεν, ἀπέχουσαν Ζοιτίας σταδίους δέκα.", "st": "8.35"}, {"sp": "N", "t": "ἔρημοι δὲ [καὶ] ἐς ἐμὲ ἦσαν ἀμφότεραι· μένει δὲ ἐν Ζοιτίᾳ Δήμητρος ναὸς καὶ Ἀρτέμιδος [οἳ καὶ ἐς ἐμὲ ἦσαν]. ἐρείπια δὲ πόλεων καὶ ἄλλα, Θυραίου μὲν σταδίοις πέντε ἀπωτέρω Παρωρίας καὶ δέκα, τὰ δὲ Ὑψοῦντός ἐστιν ἐν ὄρει κειμένῳ μὲν ὑπὲρ τοῦ πεδίου, καλουμένῳ δὲ Ὑψοῦντι. ἡ δὲ Θυραίου τε καὶ Ὑψοῦντος μεταξὺ ὀρεινὴ πᾶσά ἐστι καὶ θηριώδης· Λυκάονος δὲ εἶναι Θυραῖόν τε καὶ Ὑψοῦντα προεδήλωσεν ἡμῖν ὁ λόγος.", "st": "8.35"}, {"sp": "N", "t": "Τρικολώνων δέ ἐστιν ἐν δεξιᾷ πρῶτα μὲν ἀνάντης ὁδὸς ἐπὶ πηγὴν καλουμένους Κρουνούς· σταδίους δὲ ὡς τριάκοντα καταβάντι ἐκ Κρουνῶν τάφος ἐστὶ Καλλιστοῦς, χῶμα γῆς ὑψηλόν, δένδρα ἔχον πολλὰ μὲν τῶν ἀκάρπων, πολλὰ δὲ καὶ ἥμερα. ἐπὶ δὲ ἄκρῳ τῷ χώματι ἱερόν ἐστιν Ἀρτέμιδος ἐπίκλησιν Καλλίστης· δοκεῖν δέ μοι καὶ Πάμφως μαθών τι παρὰ Ἀρκάδων πρῶτος Ἄρτεμιν ἐν τοῖς ἔπεσιν ὠνόμασε Καλλίστην.", "st": "8.35"}, {"sp": "N", "t": "σταδίους δὲ αὐτόθεν μὲν πέντε καὶ εἴκοσι, Τρικολώνων δὲ ἑκατὸν τοὺς σύμπαντας ἀπέχουσα ἐπί γε τοῦ Ἑλισσόντος, κατὰ δὲ τὴν εὐθεῖαν Μεθυδρίου—αὕτη γὰρ δὴ ἐκ Τρικολώνων ἔτι λείπεται—Ἀνεμῶσά τέ ἐστι χωρίον καὶ ὄρος Φάλανθον, ἐν αὐτῷ δὲ ἐρείπιά ἐστι Φαλάνθου πόλεως· Ἀγελάου δὲ τοῦ Στυμφήλου παῖδα εἶναι τὸν Φάλανθον λέγουσιν.", "st": "8.35"}, {"sp": "N", "t": "ὑπὲρ τούτου δὲ πεδίον τέ ἐστι Πώλου καλούμενον καὶ μετ’ αὐτὸ Σχοινοῦς, ἀπὸ ἀνδρὸς Βοιωτοῦ Σχοινέως ἔχων τὴν κλῆσιν. εἰ δὲ ὁ Σχοινεὺς ἀπεδήμησεν οὗτος παρὰ τοὺς Ἀρκάδας, εἶεν ἂν καὶ οἱ τῆς Ἀταλάντης δρόμοι σύνεγγυς τῷ Σχοινοῦντι ὄντες [οἱ] ἀπὸ τῆς τούτου θυγατρὸς τὸ ὄνομα εἰληφότες. ἑξῆς δέ ἐστιν … ἐμοὶ δοκεῖν καλούμενον, καὶ τοῖς πᾶσιν Ἀρκαδίαν εἶναι τὴν χώραν φασὶν ἐνταῦθα.", "st": "8.35"}, {"sp": "N", "t": "τὸ ἀπὸ τούτου δὲ ἐς μνήμην οὐδὲν ἄλλο ὅτι [εἰ] μὴ αὐτὸ τὸ Μεθύδριον λείπεται· ὁδὸς δὲ ἐκ Τρικολώνων ἐς αὐτὸ στάδιοι τριῶν δέοντες τεσσαράκοντα καὶ ἑκατόν. ὠνομάσθη μὲν δὴ Μεθύδριον, ὅτι κολωνός ἐστιν ὑψηλὸς Μαλοίτα τε ποταμοῦ καὶ Μυλάοντος μέσος, ἐφ’ ᾧ τὴν πόλιν ὁ Ὀρχομενὸς ᾤκιζε· πρὶν δὲ ἢ συντελεῖν ἐς τὸ Μεγαλοπολιτικόν, γεγόνασι καὶ Μεθυδριεῦσιν ἀνδράσιν Ὀλυμπικαὶ νῖκαι.", "st": "8.36"}, {"sp": "N", "t": "ἔστι δὲ ἐν Μεθυδρίῳ Ποσειδῶνός τε Ἱππίου ναός, οὗτος μὲν ἐπὶ τῷ Μυλάοντί ἐστι· τὸ δὲ ὄρος τὸ Θαυμάσιον καλούμενον κεῖται μὲν ὑπὲρ τὸν ποταμὸν τὸν Μαλοίταν, ἐθέλουσι δὲ οἱ Μεθυδριεῖς τὴν Ῥέαν, ἡνίκα τὸν Δία εἶχεν ἐν τῇ γαστρί, ἐς τοῦτο ἀφικέσθαι τὸ ὄρος, παρασκευάσασθαι δὲ αὑτῇ καὶ βοήθειαν, ἢν ὁ Κρόνος ἐπ’ αὐτὴν ἴῃ, τόν τε Ὁπλάδαμον καὶ ἄλλους ὅσοι περὶ ἐκεῖνον ἦσαν γίγαντες·", "st": "8.36"}, {"sp": "N", "t": "καὶ τεκεῖν μὲν συγχωροῦσιν αὐτὴν ἐν μοίρᾳ τινὶ τοῦ Λυκαίου, τὴν δὲ ἐς τὸν Κρόνον ἀπάτην καὶ ἀντὶ τοῦ παιδὸς τὴν λεγομένην ὑπὸ Ἑλλήνων ἀντίδοσιν τοῦ λίθου γενέσθαι φασὶν ἐνταῦθα. ἔστι δὲ πρὸς τῇ κορυφῇ τοῦ ὄρους σπήλαιον τῆς Ῥέας, καὶ ἐς αὐτὸ ὅτι μὴ γυναιξὶ μόναις ἱεραῖς τῆς θεοῦ ἀνθρώπων γε οὐδενὶ ἐσελθεῖν ἔστι τῶν ἄλλων.", "st": "8.36"}, {"sp": "N", "t": "Μεθυδρίου δὲ ὡς τριάκοντα ἀπέχει σταδίους Νυμφασία πηγή· τοσοῦτοι δὲ ἀπὸ Νυμφασίας ἕτεροι πρὸς τοὺς Μεγαλοπολιτῶν εἰσι καὶ Ὀρχομενίων τε κοινοὺς καὶ Καφυατῶν ὅρους.", "st": "8.36"}, {"sp": "N", "t": "Μεγαλοπολίταις δὲ διὰ τῶν ἐπὶ τὸ ἕλος ὀνομαζομένων πυλῶν, διὰ τούτων ὁδεύουσιν ἐς Μαίναλον παρὰ τὸν ποταμὸν τὸν Ἑλισσόντα ἔστι τῆς ὁδοῦ ἐν ἀριστερᾷ Ἀγαθοῦ θεοῦ ναός· εἰ δὲ ἀγαθῶν οἱ θεοὶ δοτῆρές εἰσιν ἀνθρώποις, Ζεὺς δὲ ὕπατος θεῶν ἐστιν, ἑπόμενος ἄν τις τῷ λόγῳ τὴν ἐπίκλησιν ταύτην Διὸς τεκμαίροιτο εἶναι. προελθόντι δὲ οὐ πολὺ ἔστι μὲν γῆς χῶμα Ἀριστοδήμου τάφος, ὃν οὐδὲ τυραννοῦντα ἀφείλοντο μὴ ἐπονομάσαι Χρηστόν, ἔστι δὲ Ἀθηνᾶς ἱερὸν ἐπίκλησιν Μαχανίτιδος, ὅτι βουλευμάτων ἐστὶν ἡ θεὸς παντοίων καὶ ἐπιτεχνημάτων εὑρέτις.", "st": "8.36"}, {"sp": "N", "t": "πεποίηται δὲ ἐν δεξιᾷ τῆς ὁδοῦ Βορέᾳ τῷ ἀνέμῳ τέμενος, καί οἱ Μεγαλοπολῖται θυσίας θύουσιν ἀνὰ πᾶν ἔτος καὶ θεῶν οὐδενὸς Βορέαν ὕστερον ἄγουσιν ἐν τιμῇ, ἅτε σωτῆρα γενόμενόν σφισιν ἀπὸ Λακεδαιμονίων τε καὶ Ἄγιδος. ἑξῆς δὲ Ὀικλέους τοῦ Ἀμφιαράου πατρὸς μνῆμά ἐστιν, εἴ γε δὴ ἐπέλαβεν αὐτὸν τὸ χρεὼν ἐν Ἀρκαδίᾳ καὶ μὴ τῆς ἐπὶ Λαομέδοντα Ἡρακλεῖ στρατείας μετασχόντα. μετὰ τοῦτό ἐστι Δήμητρος καλουμένης ἐν ἕλει ναός τε καὶ ἄλσος· τοῦτο σταδίοις πέντε ἀπωτέρω τῆς πόλεως, γυναιξὶ δὲ ἐς αὐτὸ ἔσοδός ἐστι μόναις.", "st": "8.36"}, {"sp": "N", "t": "τριάκοντα δέ ἐστιν ἀπωτέρω σταδίοις Παλίσκιος ὀνομαζομένη χώρα· ἐκ Παλισκίου δὲ ἀφιέντι μὲν ἐν ἀριστερᾷ τὸν Ἔλαφον ὄντα οὐκ ἀέναον καὶ προελθόντι ὅσον εἴκοσι σταδίους, ἄλλα τε ἐρείπια Περαιθέων καὶ ἱερὸν λείπεται Πανός. ἢν δὲ τὸν χειμάρρουν διαβῇς, κατ’ εὐθὺ πέντε μὲν σταδίοις καὶ δέκα ἀπωτέρω τοῦ ποταμοῦ πεδίον ἐστί, διελθόντι δὲ τοῦτο, τὸ ὄρος ὁμώνυμον τῷ πεδίῳ τὸ Ναινάλιον. τοῦ δὲ ὄρους ὑπὸ τοῖς καταλήγουσι πόλεως σημεῖα Λυκόας καὶ Ἀρτέμιδος ἱερὸν καὶ ἄγαλμά ἐστι χαλκοῦν Λυκοάτιδος·", "st": "8.36"}, {"sp": "N", "t": "ἐν δὲ τοῖς κατὰ μεσημβρίαν τοῦ ὄρους Σουμητία ᾤκιστο. ἐν τούτῳ δέ εἰσι τῷ ὄρει καὶ αἱ καλούμεναι Τρίοδοι, καὶ τὰ ὀστᾶ Ἀρκάδος τοῦ Καλλιστοῦς ἀνείλοντο ἐντεῦθεν κατὰ τὸ ἐκ Δελφῶν μάντευμα οἱ Μαντινεῖς. λείπεται δὲ καὶ αὐτῆς ἔτι ἐρείπια Μαινάλου, ναοῦ τε σημεῖα Ἀθηνᾶς καὶ στάδιον ἐς ἀθλητῶν ἀγῶνα καὶ τὸ ἕτερον αὐτῶν ἐς ἵππων δρόμον· τὸ δὲ ὄρος τὸ Μαινάλιον ἱερὸν μάλιστα εἶναι Πανὸς νομίζουσιν, ὥστε οἱ περὶ αὐτὸ καὶ ἐπακροᾶσθαι συρίζοντος τοῦ Πανὸς λέγουσι.", "st": "8.36"}, {"sp": "N", "t": "τοῦ δὲ τῆς Δεσποίνης ἱεροῦ καὶ Μεγαλοπολιτῶν τοῦ ἄστεως στάδιοι τεσσαράκοντα μεταξύ εἰσιν, ἥμισυ μὲν τῆς ὁδοῦ πρὸς τοῦ Ἀλφειοῦ τὸ ῥεῦμα· διαβάντων ⟨δὲ⟩ μετὰ μὲν δύο ἀπὸ τοῦ Ἀλφειοῦ σταδίους Μακαρεῶν ἐστιν ἐρείπια, αὐτόθεν δὲ ἐς ἐρείπια ἄλλα τὰ Δασεῶν ἑπτά εἰσι στάδιοι, τοσοῦτοι δὲ ἐκ Δασεῶν πρὸς τὸν Ἀκακήσιον ὀνομαζόμενον λόφον.", "st": "8.36"}, {"sp": "N", "t": "ὑπὸ τούτῳ δὲ τῷ λόφῳ πόλις τε ἦν Ἀκακήσιον Ἑρμοῦ τε Ἀκακησίου λίθου πεποιημένον ἄγαλμα καὶ ἐς ἡμᾶς ἐστιν ἐπὶ τοῦ λόφου, τραφῆναι δὲ Ἑρμῆν παῖδα αὐτόθι καὶ Ἄκακον τὸν Λυκάονος γενέσθαι οἱ τροφέα Ἀρκάδων ἐστὶν ἐς αὐτὸν λόγος· διάφορα δὲ τούτοις Θηβαῖοι καὶ αὖθις οὐχ ὁμολογοῦντα τοῖς Θηβαίων Ταναγραῖοι λέγουσιν.", "st": "8.36"}, {"sp": "N", "t": "ἀπὸ δὲ Ἀκακησίου τέσσαρας σταδίους ἀπέχει τὸ ἱερὸν τῆς Δεσποίνης. πρῶτα μὲν δὴ αὐτόθι Ἡγεμόνης ναός ἐστιν Ἀρτέμιδος καὶ χαλκοῦν ἄγαλμα ἔχον δᾷδας —ποδῶν ἓξ εἶναι μάλιστα αὐτὸ εἰκάζομεν—, ἐντεῦθεν δὲ ἐς τὸν ἱερὸν περίβολον τῆς Δεσποίνης ἐστὶν ἔσοδος. ἰόντων δὲ ἐπὶ τὸν ναὸν στοά τέ ἐστιν ἐν δεξιᾷ καὶ ἐν τῷ τοίχῳ λίθου λευκοῦ τύποι πεποιημένοι, καὶ τῷ μέν εἰσιν ἐπειργασμέναι Μοῖραι καὶ Ζεὺς ἐπίκλησιν Μοιραγέτης, δευτέρῳ δὲ Ἡρακλῆς τρίποδα Ἀπόλλωνα ἀφαιρούμενος· ὁποῖα δὲ ἐς αὐτοὺς ἐπυνθανόμην γενέσθαι, δηλώσω καὶ τοῦτο, ἢν ἐς τοῦ Φωκικοῦ λόγου τὰ ἔχοντα ἐς Δελφοὺς ἀφικώμεθα.", "st": "8.37"}, {"sp": "N", "t": "ἐν δὲ τῇ στοᾷ τῇ παρὰ τῇ Δεσποίνῃ μεταξὺ τῶν τύπων τῶν κατειλεγμένων πινάκιόν ἐστι γεγραμμένον, ἔχον τὰ ἐς τὴν τελετήν· Νύμφαι δέ εἰσι καὶ Πᾶνες ἐπὶ τῷ τρίτῳ, ἐπὶ δὲ τῷ τετάρτῳ Πολύβιος ὁ Λυκόρτα· καί οἱ ἐπίγραμμά ἐστιν ἐξ ἀρχῆς τε μὴ ἂν σφαλῆναι τὴν Ἑλλάδα, εἰ Πολυβίῳ τὰ πάντα ἐπείθετο, καὶ ἁμαρτούσῃ δι’ ἐκείνου βοήθειαν αὐτῇ γενέσθαι μόνου. πρὸ δὲ τοῦ ναοῦ Δήμητρί τέ ἐστι βωμὸς καὶ ἕτερος Δεσποίνῃ, μετ’ αὐτὸν δὲ μεγάλης Μητρός.", "st": "8.37"}, {"sp": "N", "t": "θεῶν δὲ αὐτὰ τὰ ἀγάλματα, Δέσποινα καὶ ἡ Δημήτηρ τε καὶ ὁ θρόνος ἐν ᾧ καθέζονται, καὶ τὸ ὑπόθημα τὸ ὑπὸ τοῖς ποσίν ἐστιν ἑνὸς ὁμοίως λίθου· καὶ οὔτε τῶν ἐπὶ τῇ ἐσθῆτι οὔτε ὁπόσα εἴργασται περὶ τὸν θρόνον οὐδέν ἐστιν ἑτέρου λίθου προσεχὲς σιδήρῳ καὶ κόλλῃ, ἀλλὰ τὰ πάντα ἐστὶν εἷς λίθος. οὗτος οὐκ ἐσεκομίσθη σφίσιν ὁ λίθος, ἀλλὰ κατὰ ὄψιν ὀνείρατος λέγουσιν αὐτὸν ἐξευρεῖν ἐντὸς τοῦ περιβόλου τὴν γῆν ὀρύξαντες. τῶν δὲ ἀγαλμάτων ἐστὶν ἑκατέρου μέγεθος κατὰ τὸ Ἀθήνῃσιν ἄγαλμα μάλιστα τῆς Μητρός·", "st": "8.37"}, {"sp": "N", "t": "Δαμοφῶντος δὲ καὶ ταῦτα ἔργα. ἡ μὲν οὖν Δημήτηρ δᾷδα ἐν δεξιᾷ φέρει, τὴν δὲ ἑτέραν χεῖρα ἐπιβέβληκεν ἐπὶ τὴν Δέσποιναν· ἡ δὲ Δέσποινα σκῆπτρόν τε καὶ ⟨τὴν⟩ καλουμένην κίστην ἐπὶ τοῖς γόνασιν ἔχει, τῆς δὲ ἔχεται τῇ δεξιᾷ τῆς κίστης. τοῦ θρόνου δὲ ἑκατέρωθεν Ἄρτεμις μὲν παρὰ τὴν Δήμητρα ἕστηκεν ἀμπεχομένη δέρμα ἐλάφου καὶ ἐπὶ τῶν ὤμων φαρέτραν ἔχουσα, ἐν δὲ ταῖς χερσὶ τῇ μὲν λαμπάδα ἔχει, τῇ δὲ δράκοντας δύο. παρὰ δὲ τὴν Ἄρτεμιν κατάκειται κύων, οἷαι θηρεύειν εἰσὶν ἐπιτήδειοι.", "st": "8.37"}, {"sp": "N", "t": "πρὸς δὲ τῆς Δεσποίνης τῷ ἀγάλματι ἕστηκεν Ἄνυτος σχῆμα ὡπλισμένου παρεχόμενος· φασὶ δὲ οἱ περὶ τὸ ἱερὸν τραφῆναι τὴν Δέσποιναν ὑπὸ τοῦ Ἀνύτου, καὶ εἶναι τῶν Τιτάνων καλουμένων καὶ τὸν Ἄνυτον. Τιτᾶνας δὲ πρῶτος ἐς ποίησιν ἐσήγαγεν Ὅμηρος, θεοὺς εἶναι σφᾶς ὑπὸ τῷ καλουμένῳ Ταρτάρῳ, καὶ ἔστιν ἐν Ἥρας ὅρκῳ τὰ ἔπη· παρὰ δὲ Ὁμήρου Ὀνομάκριτος παραλαβὼν τῶν Τιτάνων τὸ ὄνομα Διονύσῳ τε συνέθηκεν ὄργια καὶ εἶναι τοὺς Τιτᾶνας τῷ Διονύσῳ τῶν παθημάτων ἐποίησεν αὐτουργούς.", "st": "8.37"}, {"sp": "N", "t": "τὰ μὲν δὴ ἐς τὸν Ἄνυτον ὑπὸ Ἀρκάδων λέγεται· Δήμητρος δὲ Ἄρτεμιν θυγατέρα εἶναι καὶ οὐ Λητοῦς, ὄντα Αἰγυπτίων τὸν λόγον Αἰσχύλος ἐδίδαξεν Εὐφορίωνος τοὺς Ἕλληνας. τὰ δὲ ἐς Κούρητας—οὗτοι γὰρ ὑπὸ τῶν ἀγαλμάτων πεποίηνται—καὶ τὰ ἐς Κορύβαντας ἐπειργασμένους ἐπὶ τοῦ βάθρου—γένος δὲ οἵδε ἀλλοῖον καὶ οὐ Κούρητες—, τὰ ἐς τούτους παρίημι ἐπιστάμενος.", "st": "8.37"}, {"sp": "N", "t": "τῶν δὲ ἡμέρων οἱ Ἀρκάδες δένδρων ἁπάντων πλὴν ῥοιᾶς ἐσκομίζουσιν ἐς τὸ ἱερόν. ἐν δεξιᾷ δὲ ἐξιόντι ἐκ τοῦ ναοῦ κάτοπτρον ἡρμοσμένον ἐστὶν ἐν τῷ τοίχῳ· τοῦτο ἤν τις προσβλέπῃ τὸ κάτοπτρον, ἑαυτὸν μὲν ἤτοι παντάπασιν ἀμυδρῶς ἢ οὐδὲ ὄψεται [τὴν] ἀρχήν, τὰ δὲ ἀγάλματα τῶν θεῶν καὶ αὐτὰ καὶ τὸν θρόνον ἔστιν ἐναργῶς θεάσασθαι.", "st": "8.37"}, {"sp": "N", "t": "παρὰ δὲ τὸν ναὸν τῆς Δεσποίνης ὀλίγον ἐπαναβάντι ἐν δεξιᾷ Μέγαρόν ἐστι καλούμενον, καὶ τελετήν τε δρῶσιν ἐνταῦθα καὶ τῇ Δεσποίνῃ θύουσιν ἱερεῖα οἱ Ἀρκάδες πολλά τε καὶ ἄφθονα. θύει μὲν δὴ αὐτῶν ἕκαστος ὅ τι κέκτηται· τῶν ἱερείων δὲ οὐ τὰς φάρυγγας ἀποτέμνει ὥσπερ ἐπὶ ταῖς ἄλλαις θυσίαις, κῶλον δὲ ὅ τι ἂν τύχῃ, τοῦτο ἕκαστος ἀπέκοψε τοῦ θύματος.", "st": "8.37"}, {"sp": "N", "t": "ταύτην μάλιστα θεῶν σέβουσιν οἱ Ἀρκάδες τὴν Δέσποιναν, θυγατέρα δὲ αὐτὴν Ποσειδῶνός φασιν εἶναι καὶ Δήμητρος. ἐπίκλησις ἐς τοὺς πολλούς ἐστιν αὐτῇ Δέσποινα, καθάπερ καὶ τὴν ἐκ Διὸς Κόρην ἐπονομάζουσιν, ἰδίᾳ δέ ἐστιν ὄνομα Περσεφόνη, καθὰ Ὅμηρος καὶ ἔτι πρότερον Πάμφως ἐποίησαν· τῆς ⟨δὲ⟩ Δεσποίνης τὸ ὄνομα ἔδεισα ἐς τοὺς ἀτελέστους γράφειν.", "st": "8.37"}, {"sp": "N", "t": "ὑπὲρ δὲ τὸ καλούμενον Μέγαρόν ἐστιν ἄλσος τῆς Δεσποίνης ἱερὸν θριγκῷ λίθων περιεχόμενον, ἐντὸς δὲ αὐτοῦ δένδρα καὶ ἄλλα καὶ ἐλαία καὶ πρῖνος ἐκ ῥίζης μιᾶς πεφύκασι· τοῦτο οὐ γεωργοῦ σοφίας ἐστὶν ἔργον. ὑπὲρ δὲ τὸ ἄλσος καὶ Ἱππίου Ποσειδῶνος, ἅτε πατρὸς τῆς Δεσποίνης, καὶ θεῶν ἄλλων εἰσὶ βωμοί· τῷ τελευταίῳ δὲ ἐπίγραμμά ἐστι θεοῖς αὐτὸν τοῖς πᾶσιν εἶναι κοινόν.", "st": "8.37"}, {"sp": "N", "t": "ἐντεῦθεν δὲ ἀναβήσῃ διὰ κλίμακος ἐς ἱερὸν Πανός· πεποίηται δὲ καὶ στοὰ ἐς τὸ ἱερὸν καὶ ἄγαλμα οὐ μέγα, θεῶν δὲ ὁμοίως τοῖς δυνατωτάτοις καὶ τούτῳ μέτεστι τῷ Πανὶ ἀνθρώπων τε εὐχὰς ἄγειν ἐς τέλος καὶ ὁποῖα ἔοικεν ἀποδοῦναι πονηροῖς. παρὰ τούτῳ τῷ Πανὶ πῦρ οὔ ποτε ἀποσβεννύμενον καίεται. λέγεται δὲ ὡς τὰ ἔτι παλαιότερα καὶ μαντεύοιτο οὗτος ὁ θεός, προφῆτιν δὲ Ἐρατὼ Νύμφην αὐτῷ γενέσθαι ταύτην ἣ Ἀρκάδι τῷ Καλλιστοῦς συνῴκησε·", "st": "8.37"}, {"sp": "N", "t": "μνημονεύουσι δὲ καὶ ἔπη τῆς Ἐρατοῦς, ἃ δὴ καὶ αὐτὸς ἐπελεξάμην. ἐνταῦθα ἔστι μὲν βωμὸς Ἄρεως, ἔστι δὲ ἀγάλματα Ἀφροδίτης ἐν ναῷ, λίθου τὸ ἕτερον λευκοῦ, τὸ δὲ ἀρχαιότερον αὐτῶν ξύλου. ὡσαύτως δὲ καὶ Ἀπόλλωνός τε καὶ Ἀθηνᾶς ξόανά ἐστι· τῇ δὲ Ἀθηνᾷ καὶ ἱερὸν πεποίηται.", "st": "8.37"}, {"sp": "N", "t": "ἀνωτέρω δὲ ὀλίγον τείχους τε περίβολος τῆς Λυκοσούρας ἐστὶ καὶ οἰκήτορες ἔνεισιν οὐ πολλοί. πόλεων δέ, ὁπόσας ἐπὶ τῇ ἠπείρῳ ἔδειξε γῆ καὶ ἐν νήσοις, Λυκόσουρά ἐστι πρεσβυτάτη, καὶ ταύτην εἶδεν ὁ ἥλιος πρώτην· ἀπὸ ταύτης δὲ οἱ λοιποὶ ποιεῖσθαι πόλεις μεμαθήκασιν ἄνθρωποι.", "st": "8.38"}, {"sp": "N", "t": "ἐν ἀριστερᾷ δὲ τοῦ ἱεροῦ τῆς Δεσποίνης τὸ ὄρος ἐστὶ τὸ Λύκαιον· καλοῦσι δὲ αὐτὸ καὶ Ὄλυμπον καὶ Ἱεράν γε ἕτεροι τῶν Ἀρκάδων κορυφήν. τραφῆναι δὲ τὸν Δία φασὶν ἐν τῷ ὄρει τούτῳ· καὶ χώρα τέ ἐστιν ἐν τῷ Λυκαίῳ Κρητέα καλουμένη—αὕτη δὲ ἡ Κρητέα ἐστὶν ἐξ ἀριστερᾶς Ἀπόλλωνος ἄλσους ἐπίκλησιν Παρρασίου—καὶ τὴν Κρήτην, ἔνθα ὁ Κρητῶν ἔχει λόγος τραφῆναι Δία, τὸ χωρίον τοῦτο εἶναι καὶ οὐ [διὰ] τὴν νῆσον ἀμφισβητοῦσιν οἱ Ἀρκάδες.", "st": "8.38"}, {"sp": "N", "t": "ταῖς Νύμφαις δὲ ὀνόματα, ὑφ’ ὧν τὸν Δία τραφῆναι λέγουσι, τίθενται Θεισόαν καὶ Νέδαν καὶ Ἁγνώ· καὶ ἀπὸ μὲν τῆς Θεισόας πόλις ᾠκεῖτο ἐν τῇ Παρρασίᾳ, τὰ δὲ ἐπ’ ἐμοῦ μοίρας τῆς Μεγαλοπολίτιδός ἐστιν ἡ Θεισόα κώμη· τῆς Νέδας δὲ ὁ ποταμὸς τὸ ὄνομα ἔσχηκε· τῆς δὲ Ἁγνοῦς, ἣ ἐν τῷ ὄρει τῷ Λυκαίῳ πηγὴ κατὰ τὰ αὐτὰ ποταμῷ τῷ Ἴστρῳ πέφυκεν ἴσον παρέχεσθαι τὸ ὕδωρ ἐν χειμῶνι ὁμοίως καὶ ἐν ὥρᾳ θέρους.", "st": "8.38"}, {"sp": "N", "t": "ἢν δὲ αὐχμὸς χρόνον ἐπέχῃ πολὺν καὶ ἤδη σφίσι τὰ σπέρματα ἐν τῇ γῇ καὶ τὰ δένδρα αὐαίνηται, τηνικαῦτα ὁ ἱερεὺς τοῦ Λυκαίου Διὸς προσευξάμενος ἐς τὸ ὕδωρ καὶ θύσας ὁπόσα ἐστὶν αὐτῷ νόμος, καθίησι δρυὸς κλάδον ἐπιπολῆς καὶ οὐκ ἐς βάθος τῆς πηγῆς· ἀνακινηθέντος δὲ τοῦ ὕδατος ἄνεισιν ἀχλὺς ἐοικυῖα ὁμίχλῃ, διαλιποῦσα δὲ ὀλίγον γίνεται νέφος ἡ ἀχλὺς καὶ ἐς αὑτὴν ἄλλα ἐπαγομένη τῶν νεφῶν ὑετὸν τοῖς Ἀρκάσιν ἐς τὴν γῆν κατιέναι ποιεῖ.", "st": "8.38"}, {"sp": "N", "t": "ἔστι δὲ ἐν τῷ Λυκαίῳ Πανός τε ἱερὸν καὶ περὶ αὐτὸ ἄλσος δένδρων καὶ ἱππόδρομός τε καὶ πρὸ αὐτοῦ στάδιον· τὸ δὲ ἀρχαῖον τῶν Λυκαίων ἦγον τὸν ἀγῶνα ἐνταῦθα. ἔστι δὲ αὐτόθι καὶ ἀνδριάντων βάθρα, οὐκ ἐπόντων ἔτι ἀνδριάντων· ἐλεγεῖον δὲ ἐπὶ τῶν βάθρων ἑνὶ Ἀστυάνακτός φησιν εἶναι τὴν εἰκόνα, τὸν δὲ Ἀστυάνακτα εἶναι γένος τῶν ἀπὸ Ἀρκάδος.", "st": "8.38"}, {"sp": "N", "t": "τὸ δὲ ὄρος παρέχεται τὸ Λύκαιον καὶ ἄλλα ἐς θαῦμα καὶ μάλιστα τόδε. τέμενός ἐστιν ἐν αὐτῷ Λυκαίου Διός, ἔσοδος δὲ οὐκ ἔστιν ἐς αὐτὸ ἀνθρώποις· ὑπεριδόντα δὲ τοῦ νόμου καὶ ἐσελθόντα ἀνάγκη πᾶσα αὐτὸν ἐνιαυτοῦ πρόσω μὴ βιῶναι. καὶ τάδε ἔτι ἐλέγετο, τὰ ἐντὸς τοῦ τεμένους γενόμενα ὁμοίως πάντα καὶ θηρία καὶ ἀνθρώπους οὐ παρέχεσθαι σκιάν· καὶ διὰ τοῦτο ἐς τὸ τέμενος θηρίου καταφεύγοντος οὐκ ἐθέλει οἱ συνεσπίπτειν ὁ κυνηγέτης, ἀλλὰ ὑπομένων ἐκτὸς καὶ ὁρῶν τὸ θηρίον οὐδεμίαν ἀπ’ αὐτοῦ θεᾶται σκιάν. χρόνον μὲν δὴ τὸν ἴσον ἔπεισί τε ὁ ἥλιος τὸν ἐν τῷ οὐρανῷ καρκίνον καὶ ἐν Συήνῃ τῇ πρὸ Αἰθιοπίας οὔτε ἀπὸ δένδρων οὔτε ἀπὸ τῶν ζῴων γενέσθαι σκιὰν ἔστι· τὸ δὲ ἐν τῷ Λυκαίῳ τέμενος τὸ αὐτὸ ἐς τὰς σκιὰς ἀεί τε καὶ ἐπὶ πασῶν πέπονθε τῶν ὡρῶν.", "st": "8.38"}, {"sp": "N", "t": "ἔστι δὲ ἐπὶ τῇ ἄκρᾳ τῇ ἀνωτάτω τοῦ ὄρους γῆς χῶμα, Διὸς τοῦ Λυκαίου βωμός, καὶ ἡ Πελοπόννησος τὰ πολλά ἐστιν ἀπ’ αὐτοῦ σύνοπτος· πρὸ δὲ τοῦ βωμοῦ κίονες δύο ὡς ἐπὶ ἀνίσχοντα ἑστήκασιν ἥλιον, ἀετοὶ δὲ ἐπ’ αὐτοῖς ἐπίχρυσοι τά γε ἔτι παλαιότερα ἐπεποίηντο. ἐπὶ τούτου τοῦ βωμοῦ τῷ Λυκαίῳ Διὶ θύουσιν ἐν ἀπορρήτῳ· πολυπραγμονῆσαι δὲ οὔ μοι τὰ ἐς τὴν θυσίαν ἡδὺ ἦν, ἐχέτω δὲ ὡς ἔχει καὶ ὡς ἔσχεν ἐξ ἀρχῆς.", "st": "8.38"}, {"sp": "N", "t": "ἔστι δὲ ἐν τοῖς πρὸς ἀνατολὰς τοῦ ὄρους Ἀπόλλωνος ἱερὸν ἐπίκλησιν Παρρασίου· τίθενται δὲ αὐτῷ καὶ Πύθιον ὄνομα. ἄγοντες δὲ τῷ θεῷ κατὰ ἔτος ἑορτὴν θύουσι μὲν ἐν τῇ ἀγορᾷ κάπρον τῷ Ἀπόλλωνι τῷ Ἐπικουρίῳ, θύσαντες δὲ ἐνταῦθα αὐτίκα τὸ ἱερεῖον κομίζουσιν ἐς τὸ ἱερὸν τοῦ Ἀπόλλωνος τοῦ Παρρασίου σὺν αὐλῷ τε καὶ πομπῇ, καὶ τά τε μηρία ἐκτεμόντες καίουσι καὶ δὴ καὶ ἀναλίσκουσιν αὐτόθι τοῦ ἱερείου τὰ κρέα.", "st": "8.38"}, {"sp": "N", "t": "ταῦτα μὲν οὕτω ποιεῖν νομίζουσι, τοῦ Λυκαίου δὲ τὰ πρὸς τῆς ἄρκτου γῆ ἐστιν ἡ Θεισοαία· οἱ δὲ ἄνθρωποι μάλιστα οἱ ταύτῃ νύμφην τὴν Θεισόαν ἄγουσιν ἐν τιμῇ. διὰ δὲ τῆς χώρας τῆς Θεισοαίας ῥέοντες ἐμβάλλουσιν ἐς τὸν Ἀλφειὸν Μυλάων, ἐπὶ δὲ αὐτῷ Νοῦς καὶ Ἀχελῷος καὶ Κέλαδός τε καὶ Νάλιφος. Ἀχελῴω δὲ τῷ Ἀρκάδι εἰσὶν ἄλλοι δύο ὁμώνυμοί τε αὐτῷ ποταμοὶ καὶ τὰ ἐς δόξαν φανερώτεροι·", "st": "8.38"}, {"sp": "N", "t": "τὸν μέν γε ἐπὶ τὰς Ἐχινάδας κατιόντα Ἀχελῷον διὰ τῆς Ἀκαρνάνων καὶ δι’ Αἰτωλίας ἔφησεν ἐν Ἰλιάδι Ὅμηρος ποταμῶν τῶν πάντων ἄρχοντα εἶναι, ἕτερον δὲ Ἀχελῷον ῥέοντα ἐκ Σιπύλου τοῦ ὄρους ἐποιήσατο αὐτόν τε τὸν ποταμὸν καὶ τὸ ὄρος τὸν Σίπυλον τοῦ λόγου προσθήκην τοῦ ἐς Νιόβην· τρίτῳ δ’ οὖν καὶ τῷ περὶ τὸ ὄρος τὸ Λύκαιόν ἐστιν ὄνομα Ἀχελῷος.", "st": "8.38"}, {"sp": "N", "t": "τῆς Λυκοσούρας δέ ἐστιν ἐν δεξιᾷ Νόμια ὄρη καλούμενα, καὶ Πανός τε ἱερὸν ἐν αὐτοῖς ἐστι Νομίου καὶ τὸ χωρίον ὀνομάζουσι Μέλπειαν, τὸ ἀπὸ τῆς σύριγγος μέλος ἐνταῦθα Πανὸς εὑρεθῆναι λέγοντες. κληθῆναι δὲ τὰ ὄρη Νόμια προχειρότατον μέν ἐστιν εἰκάζειν ἐπὶ τοῦ Πανὸς ταῖς νομαῖς, αὐτοὶ δὲ οἱ Ἀρκάδες νύμφης εἶναί φασιν ὄνομα.", "st": "8.38"}, {"sp": "N", "t": "παρὰ δὲ τὴν Λυκόσουραν ὡς ἐπὶ ἡλίου δυσμὰς ποταμὸς Πλατανιστὼν παρέξεισιν· ἀνδρὶ δὲ ἰόντι ἐς Φιγαλίαν ἀνάγκη πᾶσα διαβῆναι τὸν Πλατανιστῶνα, μετὰ δὲ αὐτόν ἐστιν ἄνοδος ὅσον τε σταδίους τριάκοντα ἢ πλείους τῶν τριάκοντα οὐ πολλῷ.", "st": "8.39"}, {"sp": "N", "t": "τὰ δὲ ἐς τὸν Λυκάονος Φίγαλον—οὗτος γὰρ δὴ τῇ πόλει τὸ ἐξ ἀρχῆς ἐγένετο οἰκιστής—καὶ ὡς μετέβαλεν ἀνὰ χρόνον ἀπὸ Φιάλου Βουκολίωνος τὸ ὄνομα ἡ πόλις καὶ αὖθις [τε] ἀνεσώσατο τὸ ἀρχαῖον, τόδε μὲν καὶ πρότερον ἔτι ἐσήμαινεν ἡμῖν ὁ λόγος· λέγεται δὲ καὶ ἄλλα οὐκ ἀξιόχρεα ἐς πίστιν, ἄνδρα αὐτόχθονα εἶναι τὸν Φίγαλον καὶ οὐ Λυκάονος παῖδα· τοῖς δὲ εἰρημένον ἐστὶν ὡς ἡ Φιγαλία νύμφη τῶν καλουμένων εἴη Δρυάδων.", "st": "8.39"}, {"sp": "N", "t": "Λακεδαιμόνιοι δὲ ἡνίκα Ἀρκάσιν ἐπεχείρησαν καὶ ἐσέβαλον ἐς τὴν Φιγαλίαν στρατιᾷ, μάχῃ τε νικῶσι τοὺς ἐπιχωρίους καὶ ἐπολιόρκουν προσκαθεζόμενοι· κινδυνεύοντος δὲ ἁλῶναι τοῦ τείχους ἐκδιδράσκουσιν οἱ Φιγαλεῖς, ἢ καὶ οἱ Λακεδαιμόνιοι σφᾶς ἀφιᾶσιν ἐξελθεῖν ὑποσπόνδους. ἐγένετο δὲ ἡ τῆς Φιγαλίας ἅλωσις καὶ Φιγαλέων ἡ ἐξ αὐτῆς φυγὴ Μιλτιάδου μὲν Ἀθήνῃσιν ἄρχοντος, δευτέρῳ δὲ ἔτει τῆς τριακοστῆς Ὀλυμπιάδος, ἣν Χίονις Λάκων ἐνίκα τὸ τρίτον.", "st": "8.39"}, {"sp": "N", "t": "Φιγαλέων δὲ τοῖς διαπεφευγόσιν ἔδοξεν ἀφικομένοις ἐς Δελφοὺς ἐρωτᾶν ὑπὲρ καθόδου τὸν θεόν· καί σφισιν ἡ Πυθία καθ’ αὑτοὺς μὲν πειρωμένοις ἐς Φιγαλίαν κατελθεῖν οὐχ ὁρᾶν ἔφη κάθοδον, εἰ δὲ λογάδας ἑκατὸν ἐξ Ὀρεσθασίου προσλάβοιεν, τοὺς μὲν ἀποθανεῖσθαι παρὰ τὴν μάχην, Φιγαλεῦσι δὲ ἔσεσθαι δι’ αὐτῶν κάθοδον. Ὀρεσθάσιοι δὲ ὡς τὴν γενομένην τοῖς Φιγαλεῦσιν ἐπύθοντο μαντείαν, ἄλλος ἔφθανεν ἄλλον σπουδῇ λογάδων τε τῶν ἑκατὸν αὐτὸς ἕκαστος γενέσθαι καὶ ἐξόδου τῆς ἐς Φιγαλίαν μετασχεῖν.", "st": "8.39"}, {"sp": "N", "t": "παρελθόντες δὲ ἐπὶ τὴν Λακεδαιμονίων φρουρὰν ἄγουσιν ἐς πάντα ἐπὶ τέλος τὸν χρησμόν· καὶ γὰρ αὐτοῖς λόγου μαχεσαμένοις ἀξίως ἐπεγένετο ἡ τελευτὴ καὶ ἐξελάσαντες τοὺς Σπαρτιάτας παρέσχον Φιγαλεῦσιν ἀπολαβεῖν τὴν πατρίδα. κεῖται δὲ ἡ Φιγαλία ἐπὶ μετεώρου μὲν καὶ ἀποτόμου ⟨τὰ⟩ πλέονα, καὶ ἐπὶ τῶν κρημνῶν ᾠκοδομημένα ἐστὶ τείχη σφίσιν· ἀνελθόντι δὲ ὁμαλής ἐστιν ὁ λόφος ἤδη καὶ ἐπίπεδος. ἔστι δὲ Σωτείρας τε ἱερὸν ἐνταῦθα Ἀρτέμιδος καὶ ἄγαλμα ὀρθὸν λίθου· ἐκ τούτου δὲ τοῦ ἱεροῦ καὶ τὰς πομπάς σφισι πέμπειν κατέστη.", "st": "8.39"}, {"sp": "N", "t": "ἐν δὲ τῷ γυμνασίῳ τὸ ἄγαλμα τοῦ Ἑρμοῦ ἀμπεχομένῳ μὲν ἔοικεν ἱμάτιον, καταλήγει δὲ οὐκ ἐς πόδας, ἀλλὰ ἐς τὸ τετράγωνον σχῆμα. πεποίηται δὲ καὶ Διονύσου ναός· ἐπίκλησις μέν ἐστιν αὐτῷ παρὰ τῶν ἐπιχωρίων Ἀκρατοφόρος, τὰ κάτω δὲ οὐκ ἔστι σύνοπτα τοῦ ἀγάλματος ὑπὸ δάφνης τε φύλλων καὶ κισσῶν. ὁπόσον δὲ αὐτοῦ καθορᾶν ἔστιν, ἐπαλήλιπται … κιννάβαρι ἐκλάμπειν· εὑρίσκεσθαι δὲ ὑπὸ τῶν Ἰβήρων ὁμοῦ τῷ χρυσῷ λέγεται.", "st": "8.39"}, {"sp": "N", "t": "Φιγαλεῦσι δὲ ἀνδριάς ἐστιν ἐπὶ τῆς ἀγορᾶς Ἀρ⟨ρα⟩χίωνος τοῦ παγκρατιαστοῦ, τά τε ἄλλα ἀρχαῖος καὶ οὐχ ἥκιστα ἐπὶ τῷ σχήματι· οὐ διεστᾶσι μὲν πολὺ οἱ πόδες, καθεῖνται δὲ παρὰ πλευρὰν αἱ χεῖρες ἄχρι τῶν γλουτῶν. πεποίηται μὲν δὴ ἡ εἰκὼν λίθου, λέγουσι δὲ καὶ ἐπίγραμμα ἐπ’ αὐτὴν γραφῆναι· καὶ τοῦτο μὲν ἠφάνιστο ὑπὸ τοῦ χρόνου, τῷ δὲ Ἀρραχίωνι ἐγένοντο Ὀλυμπικαὶ νῖκαι δύο μὲν Ὀλυμπιάσι ταῖς πρὸ τῆς τετάρτης καὶ πεντηκοστῆς, ἐγένετο δὲ καὶ ἐν αὐτῇ σὺν δικαίῳ τε ἐκ τῶν Ἑλλανοδικῶν καὶ Ἀρραχίωνος αὐτοῦ τῇ ἀρετῇ.", "st": "8.40"}, {"sp": "N", "t": "ὡς γὰρ δὴ πρὸς τὸν καταλειπόμενον ἔτι τῶν ἀνταγωνιστῶν ἐμάχετο ὑπὲρ τοῦ κοτίνου, ὁ μὲν προέλαβεν ὅστις δὴ ὁ ἀνταγωνιζόμενος καὶ τοῖς ποσὶ τὸν Ἀρραχίωνα εἶχεν ἐζωκὼς καὶ τὸν τράχηλον ἐπίεζεν ἅμα αὐτοῦ ταῖς χερσίν· ὁ δὲ Ἀρραχίων ἐκκλᾷ τῶν ἐν τῷ ποδὶ τοῦ ἀνταγωνιζομένου δάκτυλον, καὶ Ἀρραχίων τε τὴν ψυχὴν ἀφίησιν ἀγχόμενος καὶ ὁ ἄγχων τὸν Ἀρραχίωνα ὑπὸ τοῦ δακτύλου τῆς ὀδύνης κατὰ τὸν καιρὸν ἀπαγορεύει τὸν αὐτόν. Ἠλεῖοι δὲ ἐστεφάνωσάν τε καὶ ἀνηγόρευσαν νικῶντα τοῦ Ἀρραχίωνος τὸν νεκρόν.", "st": "8.40"}, {"sp": "N", "t": "ἐοικὸς δὲ καὶ Ἀργείους οἶδα ἐπὶ Κρεύγᾳ ποιήσαντας Ἐπιδαμνίῳ πύκτῃ· καὶ γὰρ Ἀργεῖοι τεθνεῶτι ἔδοσαν τῷ Κρεύγᾳ τῶν Νεμείων τὸν στέφανον, ὅτι ὁ πρὸς αὐτὸν μαχόμενος Δαμόξενος Συρακόσιος παρέβη τὰ ὡμολογημένα σφίσιν ἐς ἀλλήλους. ἐφήξειν μὲν γὰρ ἔμελλεν ἑσπέρα πυκτεύουσιν αὐτοῖς, συνέθεντο δὲ ἐς ἐπήκοον ἀνὰ μέρος τὸν ἕτερον ὑποσχεῖν αὐτῶν τῷ ἑτέρῳ πληγήν. τοῖς δὲ πυκτεύουσιν οὐκ ἦν πω τηνικαῦτα ἱμὰς ὀξὺς ἐπὶ τῷ καρπῷ τῆς χειρὸς ἑκατέρας, ἀλλὰ ταῖς μειλίχαις ἔτι ἐπύκτευον, ὑπὸ τὸ κοῖλον δέοντες τῆς χειρός, ἵνα οἱ δάκτυλοί σφισιν ἀπολείπωνται γυμνοί· αἱ δὲ ἐκ βοέας ὠμῆς ἱμάντες λεπτοὶ τρόπον τινὰ ἀρχαῖον πεπλεγμένοι δι’ ἀλλήλων ἦσαν αἱ μειλίχαι.", "st": "8.40"}, {"sp": "N", "t": "τότε οὖν ὁ μὲν τὴν πληγὴν ἀφῆκεν ἐς τοῦ Δαμοξένου τὴν κεφαλήν· ὁ δὲ ἀνασχεῖν τὴν χεῖρα ὁ Δαμόξενος ἐκέλευσε τὸν Κρεύγαν, ἀνασχόντος δὲ παίει τοῖς δακτύλοις ὀρθοῖς ὑπὸ τὴν πλευράν, ὑπὸ δὲ ἀκμῆς τε τῶν ὀνύχων καὶ βίας τῆς πληγῆς τὴν χεῖρα ἐς τὸ ἐντὸς καθεὶς καὶ ἐπιλαβόμενος τῶν σπλάγχνων ἐς τὸ ἐκτὸς ἕλκων ἀπέρρηξε.", "st": "8.40"}, {"sp": "N", "t": "καὶ ὁ μὲν τὴν ψυχὴν αὐτίκα ὁ Κρεύγας ἀφίησιν, οἱ δὲ Ἀργεῖοι τὸν Δαμόξενον ἅτε τὰ συγκείμενα ὑπερβάντα καὶ ἀντὶ μιᾶς κεχρημένον πολλαῖς ἐς τὸν ἀντίπαλον ταῖς πληγαῖς ἐξελαύνουσι, τῷ Κρεύγᾳ δὲ τὴν νίκην τεθνεῶτι ἔδοσαν καὶ ἐποιήσαντο εἰκόνα ἐν Ἄργει· καὶ ἐς ἐμὲ ἔκειτο ἐν τοῦ Ἀπόλλωνος τοῦ Λυκίου.", "st": "8.40"}, {"sp": "N", "t": "Φιγαλεῦσι δὲ ἐπὶ τῆς ἀγορᾶς καὶ πολυάνδριον τῶν λογάδων τῶν Ὀρεσθασίων ἐστί, καὶ ὡς ἥρωσιν αὐτοῖς ἐναγίζουσιν ἀνὰ πᾶν ἔτος.", "st": "8.41"}, {"sp": "N", "t": "ποταμὸς δὲ ὁ καλούμενος Λύμαξ ἐκδίδωσι μὲν ἐς τὴν Νέδαν παρ’ αὐτὴν ῥέων Φιγαλίαν, γενέσθαι δὲ τοὔνομά φασι τῷ ποταμῷ καθαρσίων τῶν Ῥέας ἕνεκα. ὡς γὰρ δὴ τεκοῦσαν τὸν Δία ἐκάθηραν ἐπὶ ταῖς ὠδῖσιν αἱ Νύμφαι, τὰ καθάρματα ἐς τοῦτον ἐμβάλλουσι τὸν ποταμόν· ὠνόμαζον δὲ ἄρα οἱ ἀρχαῖοι αὐτὰ λύματα. μαρτυρεῖ δὲ καὶ Ὅμηρος, ἀπολυμαίνεσθαί τε ἐπὶ λύσει τοῦ λοιμοῦ τοὺς Ἕλληνας καὶ ἐμβάλλειν τὰ λύματα εἰπὼν σφᾶς ἐς θάλασσαν.", "st": "8.41"}, {"sp": "N", "t": "εἰσὶ δὲ αἱ πηγαὶ τῆς Νέδας ἐν ὄρει τῷ Κεραυσίῳ· τοῦ Λυκαίου δὲ μοῖρά ἐστι. καθότι ⟨δὲ⟩ ἐγγύτατα ἡ Νέδα Φιγαλέων τῆς πόλεως γίνεται, κατὰ τοῦτο οἱ Φιγαλέων παῖδες ἀποκείρονται τῷ ποταμῷ τὰς κόμας· τὰ ⟨δὲ⟩ πρὸς θαλάσσῃ καὶ ἀναπλεῖται ναυσὶν οὐ μεγάλαις ἡ Νέδα. ποταμῶν δὲ ὁπόσους ἴσμεν Μαίανδρος μὲν σκολιῷ μάλιστα κάτεισι τῷ ῥεύματι, ἔς τε τὸ ἄνω καμπὰς καὶ αὖθις ἐπιστροφὰς παρεχόμενος πλείστας· δεύτερα δὲ ἑλιγμῶν γε ἕνεκα φέροιτο ἂν ἡ Νέδα.", "st": "8.41"}, {"sp": "N", "t": "σταδίοις δὲ ὅσον δώδεκα ἀνωτέρω Φιγαλίας θερμά τέ ἐστι λουτρὰ καὶ τούτων οὐ πόρρω κάτεισιν ὁ Λύμαξ ἐς τὴν Νέδαν· ᾗ δὲ συμβάλλουσι τὰ ῥεύματα, ἔστι τῆς Εὐρυνόμης τὸ ἱερόν, ἅγιόν τε ἐκ παλαιοῦ καὶ ὑπὸ τραχύτητος τοῦ χωρίου δυσπρόσοδον· περὶ αὐτὸ καὶ κυπάρισσοι πεφύκασι πολλαί τε καὶ ἀλλήλαις συνεχεῖς.", "st": "8.41"}, {"sp": "N", "t": "τὴν δὲ Εὐρυνόμην ὁ μὲν τῶν Φιγαλέων δῆμος ἐπίκλησιν εἶναι πεπίστευκεν Ἀρτέμιδος· ὅσοι δὲ αὐτῶν παρειλήφασιν ὑπομνήματα ἀρχαῖα, θυγατέρα Ὠκεανοῦ φασιν εἶναι τὴν Εὐρυνόμην, ἧς δὴ καὶ Ὅμηρος ἐν Ἰλιάδι ἐποιήσατο μνήμην ὡς ὁμοῦ Θέτιδι ὑποδέξαιτο Ἥφαιστον. ἡμέρᾳ δὲ τῇ αὐτῇ κατὰ ἔτος ἕκαστον τὸ ἱερὸν ἀνοιγνύουσι τῆς Εὐρυνόμης, τὸν δὲ ἄλλον χρόνον οὔ σφισιν ἀνοιγνύναι καθέστηκε·", "st": "8.41"}, {"sp": "N", "t": "τηνικαῦτα δὲ καὶ θυσίας δημοσίᾳ τε καὶ ἰδιῶται θύουσιν. ἀφικέσθαι μὲν δή μοι τῆς ἑορτῆς οὐκ ἐξεγένετο ἐς καιρὸν οὐδὲ τῆς Εὐρυνόμης τὸ ἄγαλμα εἶδον· τῶν Φιγαλέων ⟨δ’⟩ ἤκουσα ὡς χρυσαῖ τε τὸ ξόανον συνδέουσιν ἁλύσεις καὶ εἰκὼν γυναικὸς τὰ ἄχρι τῶν γλουτῶν, τὸ ἀπὸ τούτου δέ ἐστιν ἰχθύς. θυγατρὶ μὲν δὴ Ὠκεανοῦ καὶ ἐν βυθῷ τῆς θαλάσσης ὁμοῦ Θέτιδι οἰκούσῃ παρέχοιτο ἄν τι ἐς γνώρισμα αὐτῆς ὁ ἰχθύς· Ἀρτέμιδι δὲ οὐκ ἔστιν ὅπως ἂν μετά γε τοῦ εἰκότος λόγου μετείη τοιούτου σχήματος.", "st": "8.41"}, {"sp": "N", "t": "περιέχεται δὲ ἡ Φιγαλία ὄρεσιν, ἐν ἀριστερᾷ μὲν ὑπὸ τοῦ καλουμένου Κωτιλίου, τὰ δὲ ἐς δεξιὰν ἕτερον προβεβλημένον ἐστὶν αὐτῆς ὄρος τὸ Ἐλάιον. ἀπέχει δὲ τῆς πόλεως ἐς τεσσαράκοντα τὸ Κωτίλιον μάλιστα σταδίους· ἐν δὲ [τῷ] αὐτῷ χωρίον τέ ἐστι καλούμενον Βᾶσσαι καὶ ὁ ναὸς τοῦ Ἀπόλλωνος τοῦ Ἐπικουρίου, λίθου καὶ αὐτὸς ⟨καὶ ὁ⟩ ὄροφος.", "st": "8.41"}, {"sp": "N", "t": "ναῶν δὲ ὅσοι Πελοποννησίοις εἰσί, μετά γε τὸν ἐν Τεγέᾳ προτιμῷτο οὗτος ἂν τοῦ λίθου τε ἐς κάλλος καὶ τῆς ἁρμονίας ἕνεκα. τὸ δὲ ὄνομα ἐγένετο τῷ Ἀπόλλωνι ἐπικουρήσαντι ἐπὶ νόσῳ λοιμώδει, καθότι καὶ παρὰ Ἀθηναίοις ἐπωνυμίαν ἔλαβεν Ἀλεξίκακος ἀποτρέψας καὶ τούτοις τὴν νόσον.", "st": "8.41"}, {"sp": "N", "t": "ἔπαυσε δὲ ὑπὸ τὸν Πελοποννησίων καὶ Ἀθηναίων πόλεμον καὶ τοὺς Φιγαλέας καὶ οὐκ ἐν ἑτέρῳ καιρῷ· μαρτύρια δὲ αἵ τε ἐπικλήσεις ἀμφότεραι τοῦ Ἀπόλλωνος ἐοικός τι ὑποσημαίνουσαι καὶ Ἰκτῖνος ὁ ἀρχιτέκτων τοῦ ἐν Φιγαλίᾳ ναοῦ γεγονὼς τῇ ἡλικίᾳ κατὰ Περικλέα καὶ Ἀθηναίοις τὸν Παρθενῶνα καλούμενον κατασκευάσας. ἐδίδαξε δὲ ὁ λόγος ἤδη μοι τὸ ἄγαλμα εἶναι τοῦ Ἀπόλλωνος Μεγαλοπολιτῶν ἐν τῇ ἀγορᾷ.", "st": "8.41"}, {"sp": "N", "t": "ἔστι δὲ ὕδατος ἐν τῷ ὄρει τῷ Κωτιλίῳ πηγή, καὶ ὅπου συνέγραψεν ἤδη τις ἀπὸ ταύτης τῷ ποταμῷ τὸ ῥεῦμα τῷ Λύμακι ἄρχεσθαι, συνέγραψεν οὔτε αὐτὸς θεασάμενος οὔτε ἀνδρὸς ἀκοὴν ἰδόντος· ἃ καὶ ἀμφότερα παρῆσαν ἐμοί· τὸ μὲν ποταμοῦ ῥεῦμα ὂν ἑωρῶμεν, τῆς δὲ ἐν τῷ Κωτιλίῳ πηγῆς οὐκ ἐπὶ πολὺ ἐξικνούμενον τὸ ὕδωρ ἀλλὰ ἐντὸς ὀλίγου παντάπασιν ἀφανὲς γινόμενον. οὐ μὴν οὐδὲ ὅπου τῆς Ἀρκάδων ἐστὶν ἡ πηγὴ τῷ Λύμακι, ἐπῆλθε πολυπραγμονῆσαί μοι. ἔστι δὲ ὑπὲρ τὸ ἱερὸν τοῦ Ἀπόλλωνος τοῦ Ἐπικουρίου ⟨χωρίον⟩ Κώτιλον μὲν ἐπίκλησιν, Ἀφροδίτη δέ ἐστιν ἐν Κωτίλῳ· καὶ αὐτῇ [τε] ναός τε ἦν οὐκ ἔχων ἔτι ὄροφον καὶ ἄγαλμα ἐπεποίητο.", "st": "8.41"}, {"sp": "N", "t": "τὸ δὲ ἕτερον τῶν ὀρῶν τὸ Ἐλάιον ἀπωτέρω μὲν Φιγαλίας ὅσον τε σταδίοις τριάκοντά ἐστι, Δήμητρος δὲ ἄντρον αὐτόθι ἱερὸν ἐπίκλησιν Μελαίνης. ὅσα μὲν δὴ οἱ ἐν Θελπούσῃ λέγουσιν ἐς μῖξιν τὴν Ποσειδῶνός τε καὶ Δήμητρος, κατὰ ταὐτά σφισιν οἱ Φιγαλεῖς νομίζουσι, τεχθῆναι δὲ ὑπὸ τῆς Δήμητρος οἱ Φιγαλεῖς φασιν οὐχ ἵππον ἀλλὰ τὴν Δέσποιναν ἐπονομαζομένην ὑπὸ Ἀρκάδων·", "st": "8.42"}, {"sp": "N", "t": "τὸ δὲ ἀπὸ τούτου λέγουσι θυμῷ τε ἅμα ἐς τὸν Ποσειδῶνα αὐτὴν καὶ ἐπὶ τῆς Περσεφόνης τῇ ἁρπαγῇ πένθει χρωμένην μέλαιναν ἐσθῆτα ἐνδῦναι καὶ ἐς τὸ σπήλαιον τοῦτο ἐλθοῦσαν ἐπὶ χρόνον ἀπεῖναι πολύν. ὡς δὲ ἐφθείρετο μὲν πάντα ὅσα ἡ γῆ τρέφει, τὸ δὲ ἀνθρώπων γένος καὶ ἐς πλέον ἀπώλλυτο ὑπὸ τοῦ λιμοῦ, θεῶν μὲν ἄλλων ἠπίστατο ἄρα οὐδεὶς ἔνθα ἀπεκέκρυπτο ἡ Δημήτηρ, τὸν δὲ Πᾶνα ἐπιέναι μὲν", "st": "8.42"}, {"sp": "N", "t": "τὴν Ἀρκαδίαν καὶ ἄλλοτε αὐτὸν ἐν ἄλλῳ θηρεύειν τῶν ὀρῶν, ἀφικόμενον δὲ καὶ πρὸς τὸ Ἐλάιον κατοπτεῦσαι τὴν Δήμητρα σχήματός τε ὡς εἶχε καὶ ἐσθῆτα ἐνεδέδυτο ποίαν· πυθέσθαι δὴ τὸν Δία ταῦτα παρὰ τοῦ Πανὸς καὶ οὕτως ὑπ’ αὐτοῦ πεμφθῆναι τὰς Μοίρας παρὰ τὴν Δήμητρα, τὴν δὲ πεισθῆναί τε ταῖς Μοίραις καὶ ἀποθέσθαι μὲν τὴν ὀργήν, ὑφεῖναι δὲ καὶ τῆς λύπης. σφᾶς δὲ ἀντὶ τούτων φασὶν οἱ Φιγαλεῖς τό τε σπήλαιον νομίσαι τοῦτο ἱερὸν Δήμητρος καὶ ἐς αὐτὸ ἄγαλμα ἀναθεῖναι ξύλου.", "st": "8.42"}, {"sp": "N", "t": "πεποιῆσθαι δὲ οὕτω σφίσι τὸ ἄγαλμα· καθέζεσθαι μὲν ἐπὶ πέτρᾳ, γυναικὶ δὲ ἐοικέναι τἄλλα πλὴν κεφαλήν· κεφαλὴν δὲ καὶ κόμην εἶχεν ἵππου, καὶ δρακόντων τε καὶ ἄλλων θηρίων εἰκόνες προσεπεφύκεσαν τῇ κεφαλῇ· χιτῶνα δὲ ἐνεδέδυτο καὶ ⟨ἐς⟩ ἄκρους τοὺς πόδας· δελφὶς δὲ ἐπὶ τῆς χειρὸς ἦν αὐτῇ, περιστερὰ δὲ ἡ ὄρνις ἐπὶ τῇ ἑτέρᾳ. ἐφ’ ὅτῳ μὲν δὴ τὸ ξόανον ἐποιήσαντο οὕτως, ἀνδρὶ οὐκ ἀσυνέτῳ γνώμην ἀγαθῷ δὲ καὶ τὰ ἐς μνήμην δῆλά ἐστι· Μέλαιναν δὲ ἐπονομάσαι φασὶν αὐτήν, ὅτι καὶ ἡ θεὸς μέλαιναν τὴν ἐσθῆτα εἶχε.", "st": "8.42"}, {"sp": "N", "t": "τοῦτο μὲν δὴ τὸ ξόανον οὔτε ὅτου ποίημα ἦν οὔτε ἡ φλὸξ τρόπον ὅντινα ἐπέλαβεν αὐτό, μνημονεύουσιν· ἀφανισθέντος δὲ τοῦ ἀρχαίου Φιγαλεῖς οὔτε ἄγαλμα ἄλλο ἀπεδίδοσαν τῇ θεῷ καὶ ὁπόσα ἐς ἑορτὰς καὶ θυσίας τὰ πολλὰ δὴ παρῶπτό σφισιν, ἐς ὃ ἡ ἀκαρπία ἐπιλαμβάνει τὴν γῆν· καὶ ἱκετεύσασιν αὐτοῖς χρᾷ τάδε ἡ Πυθία·", "st": "8.42"}, {"sp": "N", "t": "Ἀρκάδες Ἀζᾶνες βαλανηφάγοι, οἳ Φιγάλειαν<br>νάσσασθ’, ἱππολεχοῦς Δῃοῦς κρυπτήριον ἄντρον,<br>ἥκετε πευσόμενοι λιμοῦ λύσιν ἀλγινόεντος,<br>μοῦνοι δὶς νομάδες, μοῦνοι πάλιν ἀγριοδαῖται.<br>Δῃὼ μέν σε ἔπαυσε νομῆς, Δῃὼ δὲ νομῆας<br>ἐκ δησισταχύων καὶ ἀναστοφάγων πάλι θῆκε,<br>νοσφισθεῖσα γέρα προτέρων τιμάς τε παλαιάς.<br>καί σ’ ἀλληλοφάγον θήσει τάχα καὶ τεκνοδαίτην,<br>εἰ μὴ πανδήμοις λοιβαῖς χόλον ἱλάσσεσθε<br>σήραγγός τε μυχὸν θείαις κοσμήσετε τιμαῖς.", "st": "8.42"}, {"sp": "N", "t": "ὡς δὲ οἱ Φιγαλεῖς ἀνακομισθὲν τὸ μάντευμα ἤκουσαν, τά τε ἄλλα ἐς πλέον τιμῆς ἢ τὰ πρότερα τὴν Δήμητρα ἦγον καὶ Ὀνάταν τὸν Μίκωνος Αἰγινήτην πείθουσιν ἐφ’ ὅσῳ δὴ μισθῷ ποιῆσαί σφισιν ἄγαλμα Δήμητρος· τοῦ δὲ Ὀνάτα τούτου Περγαμηνοῖς ἐστιν Ἀπόλλων χαλκοῦς, θαῦμα ἐν τοῖς μάλιστα μεγέθους τε ἕνεκα καὶ ἐπὶ τῇ τέχνῃ. τότε δὴ ὁ ἀνὴρ οὗτος ἀνευρὼν γραφὴν ἢ μίμημα τοῦ ἀρχαίου ξοάνου—τὰ πλείω δέ, ὡς λέγεται, καὶ κατὰ ὀνειράτων ὄψιν—ἐποίησε χαλκοῦν Φιγαλεῦσιν ἄγαλμα, γενεαῖς μάλιστα ⟨δυσὶν⟩ ὕστερον τῆς ἐπὶ τὴν Ἑλλάδα ἐπιστρατείας τοῦ Μήδου.", "st": "8.42"}, {"sp": "N", "t": "μαρτυρεῖ δέ μοι τῷ λόγῳ· κατὰ γὰρ τὴν Ξέρξου διάβασιν ἐς τὴν Εὐρώπην Συρακουσῶν τε ἐτυράννει καὶ Σικελίας τῆς ἄλλης Γέλων ὁ Δεινομένους· ἐπεὶ δὲ ἐτελεύτησε Γέλων, ἐς Ἱέρωνα ἀδελφὸν Γέλωνος περιῆλθεν ἡ ἀρχή· Ἱέρωνος δὲ ἀποθανόντος πρότερον πρὶν ἢ τῷ Ὀλυμπίῳ Διὶ ἀναθεῖναι τὰ ἀναθήματα ἃ εὔξατο ἐπὶ τῶν ἵππων ταῖς νίκαις, οὕτω Δεινομένης ὁ Ἱέρωνος ἀπέδωκεν ὑπὲρ τοῦ πατρός.", "st": "8.42"}, {"sp": "N", "t": "Ὀνάτα καὶ ταῦτα ποιήματα, καὶ ἐπιγράμματα ἐν Ὀλυμπίᾳ, τὸ μὲν ὑπὲρ τοῦ ἀναθήματός ἐστιν αὐτῶν,<br>σόν ποτε νικήσας, Ζεῦ Ὀλύμπιε, σεμνὸν ἀγῶνα<br>τεθρίππῳ μὲν ἅπαξ, μουνοκέλητι δὲ δίς,<br>δῶρα Ἱέρων τάδε σοι ἐχαρίσσατο· παῖς δ’ ἀνέθηκε<br>Δεινομένης πατρὸς μνῆμα Συρακοσίου·", "st": "8.42"}, {"sp": "N", "t": "τὸ δὲ ἕτερον λέγει τῶν ἐπιγραμμάτων·<br>υἱὸς ⟨μέν⟩ με Μίκωνος Ὀνάτας ἐξετέλεσσεν,<br>νάσῳ ἐν Αἰγίνᾳ δώματα ναιετάων.<br>ἡ δὲ ἡλικία τοῦ Ὀνάτα κατὰ τὸν Ἀθηναῖον Ἡγίαν καὶ Ἀγελάδαν συμβαίνει τὸν Ἀργεῖον.", "st": "8.42"}, {"sp": "N", "t": "ταύτης μάλιστα ἐγὼ τῆς Δήμητρος ἕνεκα ἐς Φιγαλίαν ἀφικόμην. καὶ ἔθυσα τῇ θεῷ, καθὰ καὶ οἱ ἐπιχώριοι νομίζουσιν, οὐδέν· τὰ δὲ ἀπὸ τῶν δένδρων τῶν ἡμέρων τά τε ἄλλα καὶ ἀμπέλου καρπὸν καὶ μελισσῶν τε κηρία καὶ ἐρίων τὰ μὴ ἐς ἐργασίαν πω ἥκοντα ἀλλὰ ἔτι ἀνάπλεα τοῦ οἰσύπου, ἃ τιθέασιν ἐπὶ τὸν βωμὸν ⟨τὸν⟩ ᾠκοδομημένον πρὸ τοῦ σπηλαίου, θέντες δὲ καταχέουσιν αὐτῶν ἔλαιον, ταῦτα ἰδιώταις τε ἀνδράσι καὶ ἀνὰ πᾶν ἔτος Φιγαλέων τῷ κοινῷ καθέστηκεν ἐς τὴν θυσίαν.", "st": "8.42"}, {"sp": "N", "t": "ἱέρεια δέ σφισίν ἐστιν ἡ δρῶσα, σὺν δὲ αὐτῇ καὶ τῶν ἱεροθυτῶν καλουμένων ὁ νεώτατος· οἱ δέ εἰσι τῶν ἀστῶν τρεῖς ἀριθμόν. ἔστι δὲ δρυῶν τε ἄλσος περὶ τὸ σπήλαιον καὶ ὕδωρ ψυχρὸν ἄνεισιν ἐκ τῆς γῆς. τὸ δὲ ἄγαλμα τὸ ὑπὸ τοῦ Ὀνάτα ποιηθὲν οὔτε ἦν κατ’ ἐμὲ οὔτε εἰ ἐγένετο ἀρχὴν Φιγαλεῦσιν ἠπίσταντο οἱ πολλοί·", "st": "8.42"}, {"sp": "N", "t": "τῶν δὲ ἐντυχόντων ἡμῖν ἔλεγεν ὁ πρεσβύτατος γενεαῖς πρότερον τρισὶν ἢ κατ’ αὐτὸν ἐμπεσεῖν ἐς τὸ ἄγαλμα ἐκ τοῦ ὀρόφου πέτρας, ὑπὸ τούτων δὲ καταγῆναι καὶ ἐς ἅπαν ἔφασκεν αὐτὸ ἀφανισθῆναι· καὶ ἔν γε τῷ ὀρόφῳ δῆλα καὶ ἡμῖν ἔτι ἦν, καθὰ ἀπερρώγεσαν αἱ πέτραι.", "st": "8.42"}, {"sp": "N", "t": "ἀπαιτεῖ δὲ ἡμᾶς τὸ μετὰ τοῦτο ὁ λόγος τό τε Παλλάντιον, εἰ δή τι αὐτόθι ἐστὶν ἐς μνήμην, καὶ καθ’ ἥντινα βασιλεὺς αἰτίαν Ἀντωνῖνος ὁ πρότερος πόλιν τε ἀντὶ κώμης ἐποίησε Παλλάντιον καί σφισιν ἐλευθερίαν καὶ ἀτέλειαν ἔδωκεν εἶναι φόρων.", "st": "8.43"}, {"sp": "N", "t": "φασὶ δὴ γενέσθαι καὶ γνώμην καὶ τὰ ἐς πόλεμον ἄριστον τῶν Ἀρκάδων ὄνομα Εὔανδρον, παῖδα δὲ αὐτὸν νύμφης τε εἶναι, θυγατρὸς τοῦ Λάδωνος, καὶ Ἑρμοῦ. σταλέντα δὲ ἐς ἀποικίαν καὶ ἄγοντα Ἀρκάδων τῶν ἐκ Παλλαντίου στρατιάν, παρὰ τῷ ποταμῷ πόλιν τῷ Θύβριδι οἰκίσαι· καὶ Ῥωμαίων μέρος τῆς καθ’ ἡμᾶς πόλεως, ὃ ᾠκεῖτο ὑπὸ τοῦ Εὐάνδρου καὶ Ἀρκάδων τῶν συνακολουθησάντων, ὄνομα ἔσχε Παλλάντιον κατὰ μνήμην τῆς ἐν Ἀρκαδίᾳ· χρόνῳ δὲ ὕστερον μετέπεσε τὸ ὄνομα ἐν ἀναιρέσει γραμμάτων τοῦ τε λ καὶ τοῦ ν. τούτων μὲν τῶν λελεγμένων ἕνεκα Παλλαντιεῦσιν ἐκ βασιλέως ἐγένοντο δωρεαί·", "st": "8.43"}, {"sp": "N", "t": "ὁ δὲ Ἀντωνῖνος, ὅτῳ καὶ ἐς Παλλαντιεῖς ἐστιν εὐεργετήματα, πόλεμον μὲν Ῥωμαίοις ἐθελοντὴς ἐπηγάγετο οὐδένα, πολέμου δὲ ἄρξαντας Μαύρους, Λιβύων τῶν αὐτονόμων τὴν μεγίστην μοῖραν, νομάδας τε ὄντας καὶ τοσῷδε ἔτι δυσμαχωτέρους τοῦ Σκυθικοῦ γένους ὅσῳ μὴ ἐπὶ ἁμαξῶν, ἐπὶ ἵππων δὲ αὐτοί τε καὶ αἱ γυναῖκες ἠλῶντο, τούτους μὲν ἐξ ἁπάσης ἐλαύνων τῆς χώρας ἐς τὰ ἔσχατα ἠνάγκασεν ἀναφυγεῖν Λιβύης, ἐπί τε Ἄτλαντα τὸ ὄρος καὶ ἐς τοὺς πρὸς τῷ Ἄτλαντι ἀνθρώπους·", "st": "8.43"}, {"sp": "N", "t": "ἀπετέμετο δὲ καὶ τῶν ἐν Βριττανίᾳ Βριγάντων τὴν πολλήν, ὅτι ἐπεσβαίνειν καὶ οὗτοι σὺν ὅπλοις ἦρξαν ἐς τὴν Γενουνίαν μοῖραν, ὑπηκόους Ῥωμαίων. Λυκίων δὲ καὶ Καρῶν τὰς πόλεις Κῶν τε καὶ Ῥόδον ἀνέτρεψε μὲν βίαιος ἐς αὐτὰς κατασκήψας σεισμός· βασιλεὺς δὲ Ἀντωνῖνος καὶ ταύτας ἀνεσώσατο δαπανημάτων τε ὑπερβολῇ καὶ ἐς τὸν ἀνοικισμὸν προθυμίᾳ. χρημάτων δὲ ἐπιδόσεις ὁπόσας καὶ Ἕλλησι καὶ τοῦ βαρβαρικοῦ τοῖς δεηθεῖσι, καὶ ἔργων κατασκευὰς ἔν τε τῇ Ἑλλάδι καὶ περὶ Ἰωνίαν καὶ περὶ Καρχηδόνα τε καὶ ἐν γῇ τῇ Σύρων, τάδε μὲν ἄλλοι ἔγραψαν ἐς τὸ ἀκριβέστατον·", "st": "8.43"}, {"sp": "N", "t": "ὁ δὲ βασιλεὺς ὑπελίπετο οὗτος καὶ ἄλλο τοιόνδε ἐς μνήμην. ὅσοις τῶν ὑπηκόων πολίταις ὑπῆρχεν εἶναι Ῥωμαίων, οἱ δὲ παῖδες ἐτέλουν σφίσιν ἐς τὸ Ἑλληνικόν, τούτοις ἐλείπετο ἢ κατανεῖμαι τὰ χρήματα ἐς οὐ προσήκοντας ἢ ἐπαυξῆσαι τὸν βασιλέως πλοῦτον κατὰ νόμον δή τινα· Ἀντωνῖνος δὲ ἐφῆκε καὶ τούτοις διδόναι σφᾶς παισὶ τὸν κλῆρον, [ὁ] προτιμήσας φανῆναι φιλάνθρωπος ἢ ὠφέλιμον ἐς χρήματα φυλάξαι νόμον. τοῦτον Εὐσεβῆ τὸν βασιλέα ἐκάλεσαν οἱ Ῥωμαῖοι, διότι τῇ ἐς τὸ θεῖον τιμῇ μάλιστα ἐφαίνετο χρώμενος·", "st": "8.43"}, {"sp": "N", "t": "δόξῃ δὲ ἐμῇ καὶ τὸ ὄνομα τὸ Κύρου φέροιτο ἂν τοῦ πρεσβυτέρου, πατὴρ ἀνθρώπων καλούμενος. ἀπέλιπε δὲ καὶ ἐπὶ τῇ βασιλείᾳ παῖδα ὁμώνυμον· ὁ δὲ Ἀντωνῖνος οὗτος ὁ δεύτερος καὶ τούς τε Γερμανούς, μαχιμωτάτους καὶ πλείστους τῶν ἐν τῇ Εὐρώπῃ βαρβάρων, καὶ ἔθνος τὸ Σαυροματῶν, πολέμου καὶ ἀδικίας ἄρξαντας, τιμωρούμενος ἐπεξῆλθε.", "st": "8.43"}, {"sp": "N", "t": "τὰ δὲ [δὴ] ἐπίλοιπα ἡμῖν τοῦ Ἀρκαδικοῦ λόγου ἔστιν ἐκ Μεγάλης πόλεως ἐς Παλλάντιον ὁδὸς καὶ ἐς Τεγέαν, ἄγουσα αὕτη μέχρι τοῦ καλουμένου Χώματος. κατὰ ταύτην τὴν ὁδὸν Λαδόκειά σφισιν ὠνόμασται τὰ πρὸ τοῦ ἄστεως ἀπὸ Λαδόκου τοῦ Ἐχέμου, καὶ μετὰ ταῦτα Αἱμονιαὶ πόλις ἦσαν τὸ ἀρχαῖον· οἰκιστὴς δὲ Αἵμων ἐγένετο αὐταῖς ὁ Λυκάονος, διαμεμένηκε δὲ καὶ ἐς τόδε Αἱμονιὰς τὸ χωρίον τοῦτο ὀνομάζεσθαι.", "st": "8.44"}, {"sp": "N", "t": "μετὰ δὲ Αἱμονιὰς ἐν δεξιᾷ τῆς ὁδοῦ πόλεώς ἐστιν Ὀρεσθασίου καὶ ἄλλα ὑπολειπόμενα ἐς μνήμην καὶ Ἀρτέμιδος ἱεροῦ κίονες ἔτι· ἐπίκλησις δὲ Ἱέρεια τῇ Ἀρτέμιδί ἐστι. τὴν δὲ εὐθεῖαν ἰόντι ἐξ Αἱμονιῶν Ἀφροδίσιόν τέ ἐστιν ὀνομαζόμενον καὶ μετ’ αὐτὸ ἄλλο χωρίον τὸ Ἀθήναιον· τούτου δὲ ἐν ἀριστερᾷ ναός ἐστιν Ἀθηνᾶς καὶ ἄγαλμα ἐν αὐτῷ λίθου.", "st": "8.44"}, {"sp": "N", "t": "τοῦ Ἀθηναίου δὲ μάλιστα εἴκοσιν ἀπωτέρω σταδίοις ἐρείπια Ἀσέας ἐστί, καὶ ὁ λόφος ἀκρόπολις τότε οὖσα τείχους σημεῖα ἔχει καὶ ἐς τόδε. σταδίους δὲ ὅσον πέντε ἀπὸ Ἀσέας τοῦ Ἀλφειοῦ μὲν ὀλίγον ἄπο τῆς ὁδοῦ, τοῦ δὲ Εὐρώτα παρ’ αὐτήν ἐστιν ἡ πηγὴ τὴν ὁδόν· πρός τε τοῦ Ἀλφειοῦ τῇ πηγῇ ναός τε Μητρὸς θεῶν ἐστιν οὐκ ἔχων ὄροφον καὶ λέοντες λίθου δύο πεποιημένοι.", "st": "8.44"}, {"sp": "N", "t": "τοῦ δὲ Εὐρώτα τὸ ὕδωρ ἀνακεράννυταί τε πρὸς τὸν Ἀλφειὸν καὶ ὅσον ἐπὶ εἴκοσι σταδίους κοινῷ προΐασι τῷ ῥεύματι· κατελθόντες δὲ ἐς χάσμα ὁ μὲν αὐτῶν ἄνεισιν αὖθις ἐν τῇ γῇ τῇ Λακεδαιμονίων ὁ Εὐρώτας, ὁ δὲ Ἀλφειὸς ἐν Πηγαῖς τῆς Μεγαλοπολίτιδος. ἔστι δὲ ἄνοδος ἐξ Ἀσέας ἐς τὸ ὄρος τὸ Βόρειον καλούμενον, καὶ ἐπὶ τῇ ἄκρᾳ τοῦ ὄρους σημεῖά ἐστιν ἱεροῦ· ποιῆσαι δὲ τὸ ἱερὸν Ἀθηνᾷ τε Σωτείρᾳ καὶ Ποσειδῶνι Ὀδυσσέα ἐλέγετο ἀνακομισθέντα ἐξ Ἰλίου.", "st": "8.44"}, {"sp": "N", "t": "τὸ δὲ ὀνομαζόμενον Χῶμα ὅροι Μεγαλοπολίταις τῆς γῆς πρὸς Τεγεάτας καὶ Παλλαντιεῖς εἰσι· καὶ τὸ Παλλαντικὸν πεδίον ἐστὶν ἐκτραπεῖσιν ἐς ἀριστερὰν ἀπὸ τοῦ Χώματος. ἐν δὲ Παλλαντίῳ ναός τε καὶ ἀγάλματα λίθου Πάλλαντος, τὸ δὲ ἕτερόν ἐστιν Εὐάνδρου· καὶ Κόρης τε τῆς Δήμητρος ἱερὸν καὶ οὐ πολὺ ἀπωτέρω Πολυβίου σφίσιν ἀνδριάς ἐστι. τῷ λόφῳ δὲ τῷ ὑπὲρ τῆς πόλεως ὅσα ἀκροπόλει τὸ ἀρχαῖον ἐχρῶντο· λείπεται δὲ καὶ ἐς ἡμᾶς ἔτι ἐπὶ κορυφῇ τοῦ λόφου θεῶν ἱερόν.", "st": "8.44"}, {"sp": "N", "t": "ἐπίκλησις μὲν δή ἐστιν αὐτοῖς Καθαροί, περὶ μεγίστων δὲ αὐτόθι καθεστήκασιν οἱ ὅρκοι· καὶ ὀνόματα μὲν τῶν θεῶν οὐκ ἴσασιν ἢ καὶ εἰδότες οὐ θέλουσιν ἐξαγορεύειν, Καθαροὺς δὲ ἐπὶ τοιῷδε ἄν τις κληθῆναι τεκμαίροιτο, ὅτι αὐτοῖς οὐ κατὰ ταὐτὰ ὁ Πάλλας ἔθυσε καθὰ καὶ ὁ πατήρ οἱ τῷ Λυκαίῳ Διί.", "st": "8.44"}, {"sp": "N", "t": "τοῦ δὲ καλουμένου Χώματος ἐν δεξιᾷ πεδίον ἐστὶ τὸ Μανθουρικόν· ἔστι δὲ ἐν ὅροις ἤδη Τεγεατῶν τὸ πεδίον, ὂν σταδίων που πεντήκοντα μάλιστα ἄχρι Τεγέας. ἔστι δὲ ὄρος οὐ μέγα ἐν δεξιᾷ τῆς ὁδοῦ καλούμενον Κρήσιον· ἐν δὲ αὐτῷ τὸ ἱερὸν τοῦ Ἀφνειοῦ πεποίηται. Ἀερόπῃ γὰρ Κηφέως τοῦ Ἀλέου συνεγένετο Ἄρης, καθὰ οἱ Τεγεᾶται λέγουσι· καὶ ἡ μὲν ἀφίησιν ἐν ταῖς ὠδῖσι τὴν ψυχήν, ὁ δὲ παῖς καὶ τεθνηκυίας", "st": "8.44"}, {"sp": "N", "t": "εἴχετο ἔτι τῆς μητρὸς καὶ ἐκ τῶν μαστῶν εἷλκεν αὐτῆς γάλα πολὺ καὶ ἄφθονον, καὶ—ἦν γὰρ τοῦ Ἄρεως γνώμῃ τὰ γινόμενα—τούτων ἕνεκα Ἀφνειὸν τὸν θεὸν ὀνομάζουσι· τῷ δὲ παιδίῳ ὄνομα τεθῆναί φασιν Ἀέροπον. ἔστι δὲ κατὰ τὴν ἐς Τεγέαν ὁδὸν Λευκώνιος καλουμένη κρήνη· θυγατέρα δὲ Ἀφείδαντος λέγουσιν εἶναι τὴν Λευκώνην, καὶ οὐ πόρρω τοῦ Τεγεατῶν οἱ ἄστεως μνῆμά ἐστιν.", "st": "8.44"}, {"sp": "N", "t": "Τεγεᾶται δὲ ἐπὶ μὲν Τεγεάτου τοῦ Λυκάονος τῇ χώρᾳ φασὶν ἀπ’ αὐτοῦ γενέσθαι μόνῃ τὸ ὄνομα, τοῖς δὲ ἀνθρώποις κατὰ δήμους εἶναι τὰς οἰκήσεις, Γαρεάτας καὶ Φυλακεῖς καὶ Καρυάτας τε καὶ Κορυθεῖς, ἔτι δὲ Πωταχίδας καὶ Οἰάτας Μανθυρεῖς τε καὶ Ἐχευήθεις· ἐπὶ δὲ Ἀφείδαντος βασιλεύοντος καὶ ἔνατός σφισι δῆμος προσεγένετο Ἀφείδαντες· τῆς δὲ ἐφ’ ἡμῶν πόλεως οἰκιστὴς ἐγένετο Ἄλεος.", "st": "8.45"}, {"sp": "N", "t": "Τεγεάταις δὲ παρὲξ ἢ τὰ Ἀρκάδων κοινά, ἐν οἷς ἔστι μὲν ὁ πρὸς Ἰλίῳ πόλεμος, ἔστι δὲ τὰ Μηδικά τε καὶ ἐν Διπαιεῦσιν ὁ πρὸς Λακεδαιμονίους ἀγών, παρὲξ οὖν τῶν καταλελεγμένων ἰδίᾳ Τεγεάταις ἐστὶν αὐτοῖς τοσάδε ἐς δόξαν. τὸν γὰρ ἐν Καλυδῶνι ὗν Ἀγκαῖος ὑπέμεινεν ὁ Λυκούργου τρωθείς, καὶ Ἀταλάντη τοξεύει τὸν ὗν καὶ ἔτυχε πρώτη τοῦ θηρίου· τούτων ἕνεκα αὐτῇ ἡ κεφαλή τε τοῦ ὑὸς καὶ τὸ δέρμα ἀριστεῖα ἐδόθη.", "st": "8.45"}, {"sp": "N", "t": "Ἡρακλειδῶν δὲ ἐς Πελοπόννησον κατιόντων Ἔχεμος ὁ Ἀερόπου Τεγεάτης ἐμονομάχησεν ἰδίᾳ πρὸς Ὕλλον, καὶ ἐκράτησε τοῦ Ὕλλου τῇ μάχῃ. Λακεδαιμονίους τε οἱ Τεγεᾶται πρῶτοι Ἀρκάδων σφίσιν ἐπιστρατεύσαντας ἐνίκησαν καὶ αἰχμαλώτους αἱροῦσιν αὐτῶν τοὺς πολλούς.", "st": "8.45"}, {"sp": "N", "t": "Τεγεάταις δὲ Ἀθηνᾶς τῆς Ἀλέας τὸ ἱερὸν τὸ ἀρχαῖον ἐποίησεν Ἄλεος· χρόνῳ δὲ ὕστερον κατεσκευάσαντο οἱ Τεγεᾶται τῇ θεῷ ναὸν μέγαν τε καὶ θέας ἄξιον. ἐκεῖνο μὲν δὴ πῦρ ἠφάνισεν ἐπινεμηθὲν ἐξαίφνης, Διοφάντου παρ’ Ἀθηναίοις ἄρχοντος, δευτέρῳ δὲ ἔτει τῆς ἕκτης καὶ ἐνενηκοστῆς Ὀλυμπιάδος, ἣν Εὐπόλεμος Ἠλεῖος ἐνίκα στάδιον.", "st": "8.45"}, {"sp": "N", "t": "ὁ δὲ ναὸς ὁ ἐφ’ ἡμῶν πολὺ δή τι τῶν ναῶν, ὅσοι Πελοποννησίοις εἰσίν, ἐς κατασκευὴν προέχει τὴν ἄλλην καὶ ἐς μέγεθος. ὁ μὲν δὴ πρῶτός ἐστιν αὐτῷ κόσμος τῶν κιόνων Δώριος, ὁ δὲ ἐπὶ τούτῳ Κορίνθιος· ἑστήκασι δὲ καὶ ἐντὸς τοῦ ναοῦ κίονες ἐργασίας τῆς Ἰώνων. ἀρχιτέκτονα δὲ ἐπυνθανόμην Σκόπαν αὐτοῦ γενέσθαι τὸν Πάριον, ὃς καὶ ἀγάλματα πολλαχοῦ τῆς ἀρχαίας Ἑλλάδος, τὰ δὲ καὶ περὶ Ἰωνίαν τε καὶ Καρίαν ἐποίησε.", "st": "8.45"}, {"sp": "N", "t": "τὰ δὲ ἐν τοῖς ἀετοῖς ἐστιν ἔμπροσθεν ἡ θήρα τοῦ ὑὸς τοῦ Καλυδωνίου· πεποιημένου δὲ κατὰ μέσον μάλιστα τοῦ ὑὸς τῇ μέν ἐστιν Ἀταλάντη καὶ Μελέαγρος καὶ Θησεὺς Τελαμών τε καὶ Πηλεὺς καὶ Πολυδεύκης καὶ Ἰόλαος, ὃς τὰ πλεῖστα Ἡρακλεῖ συνέκαμνε τῶν ἔργων, καὶ Θεστίου παῖδες, ἀδελφοὶ δὲ Ἀλθαίας, Πρόθους καὶ Κομήτης·", "st": "8.45"}, {"sp": "N", "t": "κατὰ δὲ τοῦ ὑὸς τὰ ἕτερα Ἀγκαῖον ἔχοντα ἤδη τραύματα καὶ ἀφέντα τὸν πέλεκυν ἀνέχων ἐστὶν Ἔποχος, παρὰ δὲ αὐτὸν Κάστωρ καὶ Ἀμφιάραος Ὀικλέους, ἐπὶ δὲ αὐτοῖς Ἱππόθους ὁ Κερκυόνος ⟨τοῦ⟩ Ἀγαμήδους τοῦ Στυμφήλου· τελευταῖος δέ ἐστιν εἰργασμένος Πειρίθους. τὰ δὲ ὄπισθεν πεποιημένα ἐν τοῖς ἀετοῖς Τηλέφου πρὸς Ἀχιλλέα ἐστὶν ⟨ἡ⟩ ἐν Καΐκου πεδίῳ μάχη.", "st": "8.45"}, {"sp": "N", "t": "τῆς δὲ Ἀθηνᾶς τὸ ἄγαλμα τῆς Ἀλέας τὸ ἀρχαῖον, σὺν δὲ αὐτῇ καὶ ὑὸς τοῦ Καλυδωνίου τοὺς ὀδόντας ἔλαβεν ὁ Ῥωμαίων βασιλεὺς Αὔγουστος, Ἀντώνιον πολέμῳ καὶ τὸ Ἀντωνίου νικήσας συμμαχικόν, ἐν ᾧ καὶ οἱ Ἀρκάδες πλὴν Μαντινέων ἦσαν οἱ ἄλλοι.", "st": "8.46"}, {"sp": "N", "t": "φαίνεται δὲ οὐκ ἄρξας ὁ Αὔγουστος ἀναθήματα καὶ ἕδη θεῶν ἀπάγεσθαι παρὰ τῶν κρατηθέντων, καθεστηκότι δὲ ἐκ παλαιοῦ χρησάμενος. Ἰλίου τε γὰρ ἁλούσης καὶ νεμομένων τὰ λάφυρα Ἑλλήνων, Σθενέλῳ τῷ Καπανέως τὸ ξόανον τοῦ Διὸς ἐδόθη τοῦ Ἑρκείου· καὶ ἔτεσιν ὕστερον πολλοῖς Δωριέων ἐς Σικελίαν ἐσοικιζομένων, Ἀντίφημος ὁ Γέλας οἰκιστὴς πόλισμα Σικανῶν Ὀμφάκην πορθήσας μετεκόμισεν ἐς Γέλαν ἄγαλμα ὑπὸ Δαιδάλου πεποιημένον.", "st": "8.46"}, {"sp": "N", "t": "βασιλέα τε τῶν Περσῶν Ξέρξην τὸν Δαρείου, χωρὶς ἢ ὅσα ἐξεκόμισε τοῦ Ἀθηναίων ἄστεως, τοῦτο μὲν ἐκ Βραυρῶνος καὶ ἄγαλμα ἴσμεν τῆς Βραυρωνίας λαβόντα Ἀρτέμιδος, τοῦτο δὲ αἰτίαν ἐπενεγκὼν Μιλησίοις, ἐθελοκακῆσαι σφᾶς ἐναντία Ἀθηναίων ἐν τῇ Ἑλλάδι ναυμαχήσαντας, τὸν χαλκοῦν ἔλαβεν Ἀπόλλωνα τὸν ἐν Βραγχίδαις· καὶ τὸν μὲν ὕστερον ἔμελλε χρόνῳ Σέλευκος καταπέμψειν Μιλησίοις, Ἀργείοις δὲ τὰ ἐκ Τίρυνθος ἔτι καὶ ἐς ἐμὲ τὸ μὲν παρὰ τῇ Ἥρᾳ ξόανον, τὸ δὲ ἐν τοῦ Ἀπόλλωνός ἐστιν ἀνακείμενον τοῦ Λυκίου·", "st": "8.46"}, {"sp": "N", "t": "Κυζικηνοί τε, ἀναγκάσαντες πολέμῳ Προκοννησίους γενέσθαι σφίσι συνοίκους, Μητρὸς Δινδυμήνης ἄγαλμα ἔλαβον ἐκ Προκοννήσου· τὸ δὲ ἄγαλμά ἐστι χρυσοῦ, καὶ αὐτοῦ τὸ πρόσωπον ἀντὶ ἐλέφαντος ἵππων τῶν ποταμίων ὀδόντες εἰσὶν εἰργασμένοι. βασιλεὺς μὲν δὴ Αὔγουστος καθεστηκότα ἐκ παλαιοῦ καὶ ὑπό τε Ἑλλήνων νομιζόμενα καὶ βαρβάρων εἰργάσατο· Ῥωμαίοις δὲ τῆς Ἀθηνᾶς τὸ ἄγαλμα τῆς Ἀλέας ἐς τὴν ἀγορὰν τὴν ὑπὸ Αὐγούστου ποιηθεῖσαν, ἐς ταύτην ἐστὶν ἰόντι.", "st": "8.46"}, {"sp": "N", "t": "τοῦτο μὲν δὴ ἐνταῦθα ἀνάκειται ἐλέφαντος διὰ παντὸς πεποιημένον, τέχνη δὲ Ἐνδοίου· τοῦ δὲ ὑὸς τῶν ὀδόντων κατεᾶχθαι μὲν τὸν ἕτερόν φασιν οἱ ἐπὶ τοῖς θαύμασιν, ὁ δ’ ἔτι ἐξ αὐτῶν λειπόμενος ἀνέκειτο ἐν βασιλέως κήποις ἐν ἱερῷ Διονύσου, τὴν περίμετρον τοῦ μήκους παρεχόμενος ἐς ἥμισυ μάλιστα ὀργυιᾶς.", "st": "8.46"}, {"sp": "N", "t": "τὸ δὲ ἄγαλμα ἐν Τεγέᾳ τὸ ἐφ’ ἡμῶν ἐκομίσθη μὲν ἐκ δήμου τοῦ Μανθουρέων, Ἱππία δὲ παρὰ τοῖς Μανθουρεῦσιν εἶχεν ἐπίκλησιν, ὅτι τῷ ἐκείνων λόγῳ γινομένης τοῖς θεοῖς πρὸς γίγαντας μάχης ἐπήλασεν Ἐγκελάδῳ ἵππων τὸ ἅρμα· Ἀλέαν μέντοι καλεῖσθαι καὶ ταύτην ἔς τε Ἕλληνας τοὺς ἄλλους καὶ ἐς αὐτοὺς Πελοποννησίους ἐκνενίκηκε. τῷ δὲ ἀγάλματι τῆς Ἀθηνᾶς τῇ μὲν Ἀσκληπιός, τῇ δὲ Ὑγείᾳ παρεστῶσά ἐστι λίθου τοῦ Πεντελησίου, Σκόπα δὲ ἔργα Παρίου.", "st": "8.47"}, {"sp": "N", "t": "ἀναθήματα δὲ ἐν τῷ ναῷ τὰ ἀξιολογώτατα, ἔστι μὲν τὸ δέρμα ὑὸς τοῦ Καλυδωνίου, διεσήπετο δὲ ὑπὸ τοῦ χρόνου καὶ ἐς ἅπαν ἦν τριχῶν ἤδη ψιλόν· εἰσὶ δὲ αἱ πέδαι κρεμάμεναι, πλὴν ὅσας ἠφάνισεν αὐτῶν ἰός, ἅς γε ἔχοντες Λακεδαιμονίων οἱ αἰχμάλωτοι τὸ πεδίον Τεγεάταις ἔσκαπτον· κλίνη τε ἱερὰ τῆς Ἀθηνᾶς καὶ Αὔγης εἰκὼν γραφῇ μεμιμημένη Μαρπήσσης τε ἐπίκλησιν Χοίρας, γυναικὸς Τεγεάτιδος, ἀνάκειται τὸ ὅπλον.", "st": "8.47"}, {"sp": "N", "t": "ταύτης μὲν δὴ ποιησόμεθα καὶ ὕστερον μνήμην· ἱερᾶται δὲ τῇ Ἀθηνᾷ παῖς χρόνον οὐκ οἶδα ὅσον τινά, πρὶν δὲ ἡβάσκειν καὶ οὐ πρόσω, τὴν ἱερωσύνην. τῇ θεῷ δὲ ποιηθῆναι τὸν βωμὸν ὑπὸ Μελάμποδος τοῦ Ἀμυθάονος λέγουσιν· εἰργασμέναι δὲ ἐπὶ τῷ βωμῷ Ῥέα μὲν καὶ Οἰνόη νύμφη παῖδα ἔτι νήπιον Δία ἔχουσιν, ἑκατέρωθεν δέ εἰσι τέσσαρες ἀριθμόν, Γλαύκη καὶ Νέδα καὶ Θεισόα καὶ Ἀνθρακία, τῇ δὲ Ἴδη καὶ Ἁγνὼ καὶ Ἀλκινόη τε καὶ Φρίξα. πεποίηται δὲ καὶ Μουσῶν καὶ Μνημοσύνης ἀγάλματα.", "st": "8.47"}, {"sp": "N", "t": "τοῦ ναοῦ δὲ οὐ πόρρω στάδιον χῶμα γῆς ἐστι, καὶ ἄγουσιν ἀγῶνας ἐνταῦθα, Ἀλεαῖα ὀνομάζοντες ἀπὸ τῆς Ἀθηνᾶς, τὸν δὲ Ἁλώτια, ὅτι Λακεδαιμονίων τὸ πολὺ ἐν τῇ μάχῃ ζῶντας εἷλον. ἔστι δὲ ἐν τοῖς πρὸς ἄρκτον τοῦ ναοῦ κρήνη, καὶ ἐπὶ ταύτῃ βιασθῆναι τῇ κρήνῃ φασὶν Αὔγην ὑπὸ Ἡρακλέους, οὐχ ὁμολογοῦντες Ἑκαταίῳ τὰ ἐς αὐτήν. ἀπωτέρω δὲ τῆς κρήνης ὅσον σταδίοις τρισίν ἐστιν Ἑρμοῦ ναὸς Αἰπύτου.", "st": "8.47"}, {"sp": "N", "t": "Τεγεάταις δέ ἐστι καὶ ἄλλο ἱερὸν Ἀθηνᾶς Πολιάτιδος, ἑκάστου δὲ ἅπαξ ἔτους ἱερεὺς ἐς αὐτὸ ἔσεισι· τοῦτο Ἔρυμα τὸ ἱερὸν ὀνομάζουσι, λέγοντες ὡς Κηφεῖ τῷ Ἀλέου γένοιτο δωρεὰ παρὰ Ἀθηνᾶς ἀνάλωτον ἐς τὸν πάντα χρόνον εἶναι Τεγέαν, καὶ αὐτῷ φασιν ἐς φυλακὴν τῆς πόλεως ἀποτεμοῦσαν τὴν θεὸν δοῦναι τριχῶν τῶν Μεδούσης.", "st": "8.47"}, {"sp": "N", "t": "ἐς δὲ τὴν Ἄρτεμιν, [τὴν] Ἡγεμόνην τὴν αὐτήν, τοιάδε λέγουσιν. Ὀρχομενίων τῶν ἐν Ἀρκαδίᾳ τυραννίδα ἔσχεν Ἀριστομηλίδας, ἐρασθεὶς δὲ Τεγεάτιδος παρθένου καὶ ἐγκρατὴς ὅτῳ δὴ τρόπῳ γενόμενος ἐπιτρέπει τὴν φρουρὰν αὐτῆς Χρονίῳ· καὶ ἡ μέν, πρὶν ἀναχθῆναι παρὰ τὸν τύραννον, ἀποκτίννυσιν ἑαυτὴν ὑπὸ δείματός τε καὶ αἰδοῦς, Χρόνιον δὲ Ἀρτέμιδος ἐπήγειρεν ὄψις ἐπὶ Ἀριστομηλίδαν· φονεύσας δὲ ἐκεῖνον καὶ ἐς Τεγέαν φυγὼν ἐποίησεν ἱερὸν τῇ Ἀρτέμιδι.", "st": "8.47"}, {"sp": "N", "t": "τῆς ἀγορᾶς δὲ μάλιστα ἐοικυίας πλίνθῳ κατὰ τὸ σχῆμα, Ἀφροδίτης ἐστὶν ἐν αὐτῇ ναὸς καλούμενος ἐν πλινθίῳ καὶ ἄγαλμα λίθου. στήλαις δὲ ἐπειργασμένοι τῇ μὲν Ἀντιφάνης ἐστὶ καὶ Κρῖσος καὶ Τυρωνίδας τε καὶ Πυρρίας, οἳ νόμους Τεγεάταις θέμενοι τιμὰς καὶ ἐς τόδε παρ’ αὐτῶν ἔχουσιν· ἐπὶ δὲ τῇ ἑτέρᾳ στήλῃ πεποιημένος ἐστὶν Ἰάσιος ἵππου τε ἐχόμενος καὶ κλάδον ἐν τῇ δεξιᾷ φέρων φοίνικος· νικῆσαι δὲ ἵππῳ φασὶν ἐν Ὀλυμπίᾳ τὸν Ἰάσιον, ὅτε Ἡρακλῆς ἔθετο ὁ Θηβαῖος τὰ Ὀλύμπια.", "st": "8.48"}, {"sp": "N", "t": "ἐν μὲν δὴ Ὀλυμπίᾳ κοτίνου τῷ νικῶντι δίδοσθαι στέφανον καὶ ἐν Δελφοῖς δάφνης, τοῦ μὲν ἤδη τὴν αἰτίαν ἀπέδωκα ἐν τοῖς ἐς Ἠλείους, τοῦ δὲ καὶ ἐν τοῖς ἔπειτα δηλώσω· ἐν Ἰσθμῷ δὲ ἡ πίτυς καὶ τὰ ἐν Νεμέᾳ σέλινα ἐπὶ τοῦ Παλαίμονος καὶ τοῦ Ἀρχεμόρου τοῖς παθήμασιν ἐνομίσθησαν. οἱ δὲ ἀγῶνες φοίνικος ἔχουσιν οἱ πολλοὶ στέφανον· ἐς δὲ τὴν δεξιάν ἐστι καὶ πανταχοῦ τῷ νικῶντι ἐστιθέμενος φοῖνιξ.", "st": "8.48"}, {"sp": "N", "t": "ἐνομίσθη δὲ ἐπὶ τοιῷδε· Θησέα ἀνακομιζόμενον ἐκ Κρήτης φασὶν ἐν Δήλῳ ἀγῶνα ποιήσασθαι τῷ Ἀπόλλωνι, στεφανοῦν δὲ αὐτὸν τοὺς νικῶντας τῷ φοίνικι. τοῦτο μὲν δὴ ἄρξαι λέγουσιν ἐντεῦθεν· τοῦ δὲ φοίνικος τοῦ ἐν Δήλῳ μνήμην ἐποιήσατο καὶ Ὅμηρος ἐν Ὀδυσσέως ἱκεσίᾳ πρὸς τὴν Ἀλκίνου θυγατέρα.", "st": "8.48"}, {"sp": "N", "t": "ἔστι δὲ καὶ Ἄρεως ἄγαλμα ἐν τῇ Τεγεατῶν ἀγορᾷ. τοῦτο ἐκτετύπωται μὲν ἐπὶ [τῇ] στήλῃ, Γυναικοθοίναν δὲ ὀνομάζουσιν αὐτόν. ὑπὸ γὰρ τὸν Λακωνικὸν πόλεμον καὶ Χαρίλλου τοῦ Λακεδαιμονίων βασιλέως τὴν πρώτην ἐπιστρατείαν λαβοῦσαι αἱ γυναῖκές σφισιν ὅπλα ἐλόχων ὑπὸ τὸν λόφον ὃν Φυλακτρίδα ἐφ’ ἡμῶν ὀνομάζουσι· συνελθόντων δὲ τῶν στρατοπέδων καὶ τολμήματα ἀποδεικνυμένων ἑκατέρωθεν τῶν ἀνδρῶν πολλά τε καὶ ἄξια μνήμης, οὕτω φασὶν ἐπιφανῆναί σφισι τὰς", "st": "8.48"}, {"sp": "N", "t": "γυναῖκας καὶ εἶναι τὰς ἐργασαμένας ταύτας τῶν Λακεδαιμονίων τὴν τροπήν, Μάρπησσαν δὲ τὴν Χοίραν ἐπονομαζομένην ὑπερβαλέσθαι τῇ τόλμῃ τὰς ἄλλας γυναῖκας, ἁλῶναι δὲ ἐν τοῖς Σπαρτιάταις καὶ αὐτὸν Χάριλλον· καὶ τὸν μὲν ἀφεθέντα ἄνευ λύτρων, καὶ ὅρκον Τεγεάταις δόντα μήποτε Λακεδαιμονίους στρατεύσειν ἔτι ἐπὶ Τεγέαν, παραβῆναι τὸν ὅρκον, τὰς γυναῖκας δὲ τῷ Ἄρει θῦσαί τε ἄνευ τῶν ἀνδρῶν ἰδίᾳ τὰ ἐπινίκια καὶ τοῦ ἱερείου τῶν κρεῶν οὐ μεταδοῦναι σφᾶς τοῖς ἀνδράσιν. ἀντὶ τούτων μὲν τῷ Ἄρει γέγονεν ⟨ἡ⟩ ἐπίκλησις·", "st": "8.48"}, {"sp": "N", "t": "πεποίηται δὲ καὶ Διὸς Τελείου βωμὸς καὶ ἄγαλμα τετράγωνον· περισσῶς γὰρ δή τι τῷ σχήματι τούτῳ φαίνονταί μοι χαίρειν οἱ Ἀρκάδες. καὶ μνήματά ἐστιν ἐνταῦθα Τεγεάτου τοῦ Λυκάονος καὶ Μαιρᾶς γυναικὸς τοῦ Τεγεάτου· θυγατέρα Ἄτλαντός φασιν εἶναι τὴν Μαιράν, ἧς δὴ καὶ Ὅμηρος ἐποιήσατο μνήμην ἐν Ὀδυσσέως λόγοις πρὸς Ἀλκίνουν περί τε ὁδοῦ τῆς ἐς Ἅιδην καὶ ὁπόσων ἐθεάσατο ἐκεῖ τὰς ψυχάς.", "st": "8.48"}, {"sp": "N", "t": "τὴν δὲ Εἰλείθυιαν οἱ Τεγεᾶται—καὶ γὰρ ταύτης ἔχουσιν ἐν τῇ ἀγορᾷ ναὸν καὶ ἄγαλμα— ἐπονομάζουσιν Αὔγην ἐν γόνασι, λέγοντες ὡς Ναυπλίῳ παραδοίη τὴν θυγατέρα Ἄλεος ἐντειλάμενος ἐπαναγαγόντα αὐτὴν ἐς θάλασσαν καταποντῶσαι· τὴν δὲ ὡς ἤγετο πεσεῖν τε ἐς γόνατα καὶ οὕτω τεκεῖν τὸν παῖδα, ἔνθα τῆς Εἰλειθυίας ἐστὶ τὸ ἱερόν. οὗτος ὁ λόγος διάφορος μέν ἐστιν ἑτέρῳ λόγῳ, λάθρᾳ τὴν Αὔγην τεκεῖν τοῦ πατρὸς καὶ ἐκτεθῆναι τὸν Τήλεφον λέγοντι ἐς τὸ ὄρος τὸ Παρθένιον καὶ τῷ παιδὶ ἐκκειμένῳ διδόναι γάλα ἔλαφον· λέγεται δὲ οὐδὲν ἧσσον καὶ οὗτος ὑπὸ Τεγεατῶν ὁ λόγος.", "st": "8.48"}, {"sp": "N", "t": "πρὸς δὲ τῷ ἱερῷ τῆς Εἰλειθυίας ἐστὶ Γῆς βωμός, ἔχεται δὲ τοῦ βωμοῦ λίθου λευκοῦ στήλη· ἐπὶ δὲ αὐτῆς Πολύβιος ὁ Λυκόρτα καὶ ἐπὶ ἑτέρᾳ στήλῃ τῶν παίδων τῶν Ἀρκάδος Ἔλατός ἐστιν εἰργασμένος.", "st": "8.48"}, {"sp": "N", "t": "οὐ πόρρω δὲ τῆς ἀγορᾶς θέατρόν τέ ἐστι καὶ πρὸς αὐτῷ βάθρα εἰκόνων χαλκῶν, αὐταὶ δὲ οὐκ εἰσὶν ἔτι αἱ εἰκόνες· ἐλεγεῖον δὲ ἐφ’ ἑνὶ τῶν βάθρων ἐστὶ Φιλοποίμενος τὸν ἀνδριάντα εἶναι. τούτου δὲ Ἕλληνες τοῦ Φιλοποίμενος οὐχ ἥκιστα ἀλλὰ καὶ μάλιστα ἔχουσι μνήμην, γνώμης τε ἕνεκα ἣν παρέσχετο καὶ ἐπὶ τοῖς ἔργοις ὁπόσα ἐτόλμησε.", "st": "8.49"}, {"sp": "N", "t": "τὰ μὲν δὴ ἐς γένους δόξαν ὁ πατήρ οἱ Κραῦγις Ἀρκάδων ἐλείπετο οὐδενὸς τῶν ἐν Μεγάλῃ πόλει· τελευτήσαντος δὲ τοῦ Κραύγιδος ἐπὶ παιδὶ ἔτι νηπίῳ τῷ Φιλοποίμενι, ἐπετρόπευσεν αὐτὸν ἀνὴρ Μαντινεὺς Κλέανδρος, φεύγων μὲν ἐκ Μαντινείας καὶ ἐν Μεγάλῃ πόλει μετοικῶν κατὰ τὴν οἴκοθεν συμφοράν, ξενίας δὲ ὑπαρχούσης αὐτῷ πατρικῆς ἐς οἶκον τὸν Κραύγιδος. διδασκάλοις δὲ ὁμιλῆσαι τὸν Φιλοποίμενα καὶ ἄλλοις καὶ Μεγαλοφάνει τε καὶ Ἐκδήλῳ λέγουσι· τοὺς δὲ Ἀρκεσιλάου φασὶν εἶναι Πιταναίου μαθητάς.", "st": "8.49"}, {"sp": "N", "t": "μέγεθος μὲν δὴ καὶ σώματος ῥώμην ἀπέδει Πελοποννησίων οὐδενός, τὸ δὲ εἶδος ἦν τοῦ προσώπου κακός· καὶ ἐπὶ μὲν τοὺς στεφανίτας ἀγῶνας ὑπερεφρόνησεν ἀσκῆσαι, γῆν δὲ ἣν ἐκέκτητο ἐργαζόμενος οὐδὲ τὰ θηρία ἠμέλει τὰ ἄγρια ἐξαίρειν. ἐπιλέγεσθαι δὲ καὶ βιβλία φασὶν αὐτὸν σοφιστῶν τε τῶν εὐδοκιμούντων παρ’ Ἕλλησι καὶ ὅσα ἐς πολέμων μνήμην καὶ εἰ δή τι ἔχει διδασκαλίαν στρατηγημάτων· καταστήσασθαι δὲ τὸν βίον πάντα ἐθέλων γνώμης τῆς Ἐπαμινώνδου καὶ ἔργων εἶναι τῶν ἐκείνου μίμησιν, οὐ τὰ πάντα ἦν ἐξισωθῆναι δυνατός· Ἐπαμινώνδᾳ γὰρ τά τε ἄλλα ἡ ψυχὴ καὶ μάλιστα πρᾴως εἶχε τὰ ἐς ὀργήν, τῷ δὲ Ἀρκάδι μετῆν γε θυμοῦ.", "st": "8.49"}, {"sp": "N", "t": "καταλαβόντος δὲ Κλεομένους Μεγάλην πόλιν, Φιλοποίμην οὔτε τῆς συμφορᾶς ἐξεπλάγη τὸ ἀπροσδόκητον καὶ τῶν ἐν ἡλικίᾳ τὰ δύο μάλιστα μέρη καὶ γυναῖκας καὶ παῖδας ἀπέσωσεν ἐς Μεσσήνην, συμμάχων σφίσιν ἐν τῷ τότε καὶ εὔνων τῶν Μεσσηνίων ὄντων· καὶ—ἦσαν γὰρ τῶν διαπεφευγότων οἷς ὁ Κλεομένης ἐπεκηρυκεύετο μεταγινώσκειν τε ἐπὶ τῷ τολμήματι ⟨καὶ⟩ πρὸς Μεγαλοπολίτας ἐθέλειν σπένδεσθαι κατιόντας ἐπὶ τὴν ἑαυτῶν —ἔπεισεν ἐν κοινῷ τοὺς πολίτας ὁ Φιλοποίμην μεθ’ ὅπλων τὴν κάθοδον οἴκαδε εὑρίσκεσθαι μηδὲ ἐς ὁμολογίας τε καὶ σπονδὰς ἰέναι.", "st": "8.49"}, {"sp": "N", "t": "γενομένης δὲ ἐν Σελλασίᾳ πρὸς Κλεομένην τε καὶ Λακεδαιμονίους μάχης, ἣν Ἀχαιοὶ καὶ Ἀρκάδες ἀπὸ τῶν πόλεων πασῶν, σὺν δέ σφισι καὶ Ἀντίγονος ἐμαχέσατο ἄγων ἐκ Μακεδονίας στρατιάν, ἐτέτακτο μὲν τηνικαῦτα ὁ Φιλοποίμην ἐν τοῖς ἱππεῦσιν· ἐπεὶ δὲ ἐν τῷ πεζῷ τοῦ ἔργου τὸ πλεῖστον ἑώρα ληψόμενον τὴν κρίσιν, ὁπλίτης ἑκὼν ἐγένετο, καὶ αὐτὸν λόγου κινδυνεύοντα ἀξίως τῶν τις ἐναντίων δι’ ἀμφοτέρων ἔπειρε τῶν μηρῶν.", "st": "8.49"}, {"sp": "N", "t": "ὁ δὲ καὶ ἐς τοσοῦτο ὅμως πεπεδημένος τά τε γόνατα ἐνέκλινε καὶ ἐς τὸ πρόσω χωρεῖν ἐβιάζετο, ὥστε καὶ ὑπὸ τῶν ποδῶν τοῦ κινήματος τὸ δόρυ ἔκλασεν· ἐπεὶ δὲ οἱ Λακεδαιμόνιοι καὶ ὁ Κλεομένης ἐκρατήθησαν καὶ ἐς τὸ στρατόπεδον ἀνέστρεψε Φιλοποίμην, ἐνταῦθα ἐξ ἀμφοτέρων αὐτοῦ τῶν μηρῶν οἱ ἰατροὶ τῇ μὲν τὸν σαυρωτῆρα ἐξεῖλκον, τῇ δὲ τὴν αἰχμήν. Ἀντίγονος δὲ ὡς ἐπύθετο καὶ εἶδεν αὐτοῦ τὰ τολμήματα, ἐποιεῖτο σπουδὴν ἐπάγεσθαι Φιλοποίμενα ἐς Μακεδονίαν.", "st": "8.49"}, {"sp": "N", "t": "τῷ δὲ Ἀντιγόνου μὲν ὀλίγον μελήσειν ἔμελλε· περαιωσάμενος δὲ νηὶ ἐς Κρήτην—πόλεμος γὰρ κατεῖχεν αὐτὴν ἐμφύλιος— ἐπετέτακτο ἡγεμὼν μισθοφόροις· ἐπανήκων δὲ ἐς Μεγάλην πόλιν αὐτίκα ὑπὸ τῶν Ἀχαιῶν ᾕρητο ἄρχειν [καὶ] τοῦ ἱππικοῦ, καὶ σφᾶς ἀρίστους Ἑλλήνων ἀπέφαινεν ἱππεύειν. Ἀχαιῶν δὲ καὶ ὅσοι συντεταγμένοι τοῖς Ἀχαιοῖς ἦσαν περὶ Λάρισον μαχομένων ποταμὸν πρὸς Ἠλείους καὶ τὸ Αἰτωλικὸν ἐπικουροῦντας κατὰ συγγένειαν Ἠλείοις, πρῶτα μὲν Δημόφαντον ἀπέκτεινεν αὐτοχειρίᾳ τοῖς ἐναντίοις ἡγεμόνα ὄντα τῆς ἵππου, δεύτερα δὲ καὶ τὸ ἄλλο ἱππικὸν τῶν Αἰτωλῶν καὶ τῶν Ἠλείων ἐτρέψατο.", "st": "8.49"}, {"sp": "N", "t": "ἅτε δὲ ἤδη τῶν Ἀχαιῶν ἀφορώντων ἐς αὐτὸν καὶ τὰ πάντα ἐκεῖνον ποιουμένων, τοῖς τεταγμένοις αὐτῶν ἐν τῷ πεζῷ μετέβαλε τῶν ὅπλων τὴν σκευήν· φοροῦντας γὰρ μικρὰ δοράτια καὶ ἐπιμηκέστερα ὅπλα κατὰ τοὺς Κελτικοὺς θυρεοὺς ἢ τὰ γέρρα τὰ Περσῶν, ἔπεισε θώρακάς τε ἐνδύεσθαι καὶ ἐπιτίθεσθαι κνημῖδας, πρὸς δὲ ἀσπίσιν Ἀργολικαῖς χρῆσθαι καὶ τοῖς δόρασι μεγάλοις.", "st": "8.50"}, {"sp": "N", "t": "Μαχανίδου δὲ ἐν Λακεδαίμονι ἀναφύντος τυράννου καὶ αὖθις πολέμου τοῖς Ἀχαιοῖς πρὸς Λακεδαιμονίους καὶ Μαχανίδαν συνεστηκότος, ἡγεῖτο μὲν τοῦ Ἀχαϊκοῦ Φιλοποίμην· γινομένης δὲ πρὸς Μαντινείᾳ μάχης Λακεδαιμονίων μὲν οἱ ψιλοὶ τοὺς ἀσκεύους τῶν Ἀχαιῶν νικῶσι καὶ φεύγουσιν αὐτοῖς ἐπέκειτο ὁ Μαχανίδας, τῇ δὲ φάλαγγι ὁ Φιλοποίμην τῶν πεζῶν τρέπεται τῶν Λακεδαιμονίων τοὺς ὁπλίτας καὶ ἀναχωροῦντι ἀπὸ τῆς διώξεως Μαχανίδᾳ συντυχὼν ἀποκτίννυσιν αὐτόν. Λακεδαιμονίοις δὲ ἠτυχηκόσι τῇ μάχῃ περιεγεγόνει μείζων ἢ κατὰ τὸ πταῖσμα εὐτυχία, γεγονόσιν ἐλευθέροις ἀπὸ τοῦ τυράννου.", "st": "8.50"}, {"sp": "N", "t": "μετὰ δὲ οὐ πολὺ ἀγόντων Νέμεια Ἀργείων ἔτυχε μὲν τῶν κιθαρῳδῶν τῷ ἀγῶνι ὁ Φιλοποίμην παρών· Πυλάδου δὲ Μεγαλοπολίτου μὲν ἀνδρὸς γένος, κιθαρῳδοῦ δὲ τῶν ἐφ’ αὑτοῦ δοκιμωτάτου καὶ ἀνῃρημένου Πυθικὴν νίκην, τότε [δὲ] ᾄδοντος Τιμοθέου νόμον τοῦ Μιλησίου Πέρσας καὶ καταρξαμένου τῆς ᾠδῆς<br>Κλεινὸν ἐλευθερίας τεύχων μέγαν Ἑλλάδι κόσμον,<br>ἀπεῖδεν ἐς τὸν Φιλοποίμενα τὸ Ἑλληνικὸν καὶ ἐπεσημήναντο τῷ κρότῳ φέρειν ἐς ἐκεῖνον τὸ ᾆσμα. τοιοῦτο ἐς Θεμιστοκλέα ἄλλο ἐν Ὀλυμπίᾳ πυνθάνομαι συμβῆναι· καὶ γὰρ Θεμιστοκλέους ἐς τιμὴν ἐπανέστη τὸ ἐν Ὀλυμπίᾳ θέατρον.", "st": "8.50"}, {"sp": "N", "t": "Φίλιππος δὲ ὁ Δημητρίου Μακεδόνων βασιλεύς, ὃς καὶ Ἄρατον φαρμάκῳ τὸν Σικυώνιον ἀπέκτεινεν, ἀπέστειλεν ἄνδρας ἐς Μεγάλην πόλιν φονεῦσαί σφισι Φιλοποίμενα ἐντειλάμενος· ἁμαρτὼν δὲ ἀνὰ τὴν Ἑλλάδα ἐμισήθη πᾶσαν. Θηβαῖοι δὲ κεκρατηκότες μάχῃ Μεγαρέας καὶ ἤδη τοῦ Μεγαρικοῦ τείχους ἐπιβαίνοντες, ἀπάτῃ τῶν Μεγαρέων μετελθόντων αὐτοὺς ὡς ἥκοι Φιλοποίμην σφίσιν ἐς τὴν πόλιν, ἐς τοσοῦτο εὐλαβείας προῆλθον ὡς οἴκαδε ἀποχωρῆσαι καταλιπόντες ἄπρακτον τοῦ πολέμου τὸ ἔργον.", "st": "8.50"}, {"sp": "N", "t": "ἐν δὲ Λακεδαίμονι αὖθις ἐπανέστη τύραννος Νάβις, ὃς Πελοποννησίων πρώτοις ἐπέθετο Μεσσηνίοις· ἐπελθὼν δέ σφισιν ἐν νυκτὶ καὶ οὐδαμῶς τὴν ἔφοδον ἐλπίζουσιν εἷλε μὲν πλὴν τῆς ἀκροπόλεως τὸ ἄστυ, ἀφικομένου δὲ ἐς τὴν ὑστεραίαν στρατιᾷ Φιλοποίμενος ἐξέπεσεν ὑπόσπονδος ἐκ Μεσσήνης.", "st": "8.50"}, {"sp": "N", "t": "Φιλοποίμην δέ, ὡς ἐξῆκέν οἱ στρατηγοῦντι ὁ χρόνος καὶ ἄρχειν ἄλλοι τῶν Ἀχαιῶν ᾕρηντο, αὖθις ἐς Κρήτην διέβη καὶ ἐπεκούρησε Γορτυνίοις πολέμῳ πιεζομένοις. ποιουμένων δὲ ἐν ὀργῇ διὰ τὴν ἀποδημίαν τῶν Ἀρκάδων αὐτόν, ἐπάνεισί τε ἐκ Κρήτης καὶ Ῥωμαίους πόλεμον κατελάμβανεν ἐπανῃρημένους πρὸς Νάβιν.", "st": "8.50"}, {"sp": "N", "t": "παρεσκευασμένων δὲ ἐπὶ τὸν Νάβιν ναυτικὸν τῶν Ῥωμαίων, ὁ Φιλοποίμην ὑπὸ προθυμίας μεθέξειν ἔμελλε τοῦ ἀγῶνος· ἅτε δὲ ἐς ἅπαν ἀπείρως θαλάσσης ἔχων τριήρους ἔλαθεν ἐπιβὰς ῥεούσης, ὥστε καὶ ἐσῆλθε Ῥωμαίους καὶ τὸ ἄλλο συμμαχικὸν μνήμη τῶν ἐπῶν ὧν ἐν καταλόγῳ πεποίηκεν Ὅμηρος ἐπὶ τῇ Ἀρκάδων ἀμαθίᾳ τῇ ἐς θάλασσαν.", "st": "8.50"}, {"sp": "N", "t": "ἡμέραις δὲ ὕστερον τῆς ναυμαχίας οὐ πολλαῖς Φιλοποίμην καὶ ὁ σὺν αὐτῷ λόχος φυλάξαντες νύκτα ἀσέληνον τὸ στρατόπεδον τῶν Λακεδαιμονίων κατεμπιπρᾶσιν ἐν Γυθίῳ. ἐνταῦθα ἀπέλαβεν ἐν δυσχωρίαις Νάβις Φιλοποίμενά τε αὐτὸν καὶ ὅσοι περὶ αὐτὸν τῶν Ἀρκάδων ἦσαν· ἦσαν δὲ ἄλλως μὲν ἀγαθοὶ τὰ ἐς πόλεμον, ἀριθμὸν δὲ οὐ πολλοί.", "st": "8.50"}, {"sp": "N", "t": "Φιλοποίμην δὲ τὴν τάξιν, ἣν τεταγμένους ἀπῆγεν ὀπίσω, ταύτην ὑπαλλάξας τὰ μάλιστα ἰσχυρὰ τῶν χωρίων πρὸς αὑτοῦ καὶ οὐ πρὸς τῶν πολεμίων ἐποίησεν εἶναι· κρατήσας δὲ τῇ μάχῃ Νάβιν καὶ τῶν Λακεδαιμονίων ἐν τῇ νυκτὶ καταφονεύσας πολλούς, δόξης ἔτι ἐς πλέον παρὰ τοῖς Ἕλλησιν ἤρθη.", "st": "8.50"}, {"sp": "N", "t": "μετὰ δὲ ταῦτα Νάβις μὲν ἐς εἰρημένον χρόνον σπονδὰς παρὰ Ῥωμαίων εὑράμενος τελευτᾷ, πρὶν ἤ οἱ τοῦ πολέμου τὰς ἀνοχὰς ἐξήκειν, ὑπὸ ἀνδρὸς Καλυδωνίου κατὰ δὴ συμμαχίας πρόφασιν ἥκοντος, πολεμίου δὲ τῷ ἔργῳ καὶ ἐπ’ αὐτὸ ἐσταλμένου τοῦτο ὑπὸ τῶν Αἰτωλῶν.", "st": "8.50"}, {"sp": "N", "t": "Φιλοποίμην δὲ ὑπὸ τὸν καιρὸν ἐσπεσὼν τοῦτον ἐς τὴν Σπάρτην ἠνάγκασεν ἐς τὸ Ἀχαϊκὸν Λακεδαιμονίους συντελέσαι. μετὰ δὲ οὐ πολὺν χρόνον Τίτος μὲν Ῥωμαίων τῶν περὶ τὴν Ἑλλάδα ἡγεμὼν καὶ Διοφάνης ὁ Διαίου Μεγαλοπολίτης, ἄρχειν ἐν τῷ τότε ᾑρημένος τῶν Ἀχαιῶν, ἤλαυνον ἐπὶ τὴν Λακεδαίμονα, ἐπενεγκόντες αἰτίαν Λακεδαιμονίοις βουλεύειν σφᾶς νεώτερα ἐς Ῥωμαίους· Φιλοποίμην δέ, καίπερ ἐν τῷ παρόντι ἰδιώτης ὤν, ἀπέκλεισαν ὅμως ἐπιοῦσιν αὐτοῖς ⟨τὰς⟩ πύλας.", "st": "8.51"}, {"sp": "N", "t": "Λακεδαιμόνιοι δὲ τούτων τε ἕνεκα καὶ ὧν ἐς ἀμφοτέρους τοὺς τυράννους ἐτόλμησεν, ἐδίδοσαν οἶκον αὐτῷ τὸν Νάβιδος ἐς πλέον ἢ τάλαντα ἑκατόν· ὁ δὲ ὑπερεφρόνησέ τε τῶν χρημάτων καὶ ἐκέλευε τοὺς Λακεδαιμονίους θεραπεύειν δόσεσιν ἀνθ’ αὑτοῦ τοὺς ἐν τῷ συλλόγῳ τῶν Ἀχαιῶν πιθανοὺς τῷ πλήθει, ταῦτα δὲ ἐς Τιμόλαον αὐτῷ λέγουσιν ὑποσημαίνεσθαι. ἀπεδείχθη δὲ καὶ αὖθις Ἀχαιῶν στρατηγῆσαι.", "st": "8.51"}, {"sp": "N", "t": "Λακεδαιμονίων δὲ τηνικαῦτα ἐς ἔμφυλον προηγμένων στάσιν, τριακοσίους μὲν τῆς στάσεως μάλιστα αἰτίους ἐξέβαλεν ἐκ Πελοποννήσου καὶ τῶν εἱλώτων [τε] ἀπέδοτο ὅσον τρισχιλίους, τείχη δὲ περιεῖλε τῆς Σπάρτης καὶ τοῖς ἐφήβοις προεῖπε μὴ τὰ ἐκ τῶν νόμων τῶν Λυκούργου μελετᾶν, ἐφήβοις δὲ τοῖς Ἀχαιῶν κατὰ ταὐτὰ ἀσκεῖσθαι. καὶ τοῖς μὲν ὕστερον ἀποδώσειν ἔμελλον Ῥωμαῖοι παιδείαν τὴν ἐπιχώριον·", "st": "8.51"}, {"sp": "N", "t": "Ἀντίοχον δὲ ἀπόγονον Σελεύκου τοῦ ὀνομασθέντος Νικάτορος καὶ Σύρων τὴν σὺν αὐτῷ στρατιὰν Μανίου καὶ Ῥωμαίων ἐν Θερμοπύλαις ⟨νικησάντων⟩ καὶ Ἀρισταίνου τοῖς Ἀχαιοῖς τοῦ Μεγαλοπολίτου παραινοῦντος ἐπαινεῖν τὰ Ῥωμαίοις ἀρέσκοντα ἐπὶ παντὶ μηδὲ ἀνθίστασθαί σφισιν ὑπὲρ μηδενός, ὁ Φιλοποίμην ἀπεῖδεν ἐς τὸν Ἀρίσταινον σὺν ὀργῇ καὶ αὐτὸν τῇ Ἑλλάδι ἔφη τὴν πεπρωμένην ἐπιταχύνειν· Λακεδαιμονίων δὲ τοὺς φεύγοντας Μανίου καταδέξασθαι θέλοντος τῷ μὲν ἀντέπραξεν ἐς τὸ βούλευμα, ἐκείνου δὲ ἀπελθόντος τότε ἤδη κατελθεῖν τοὺς φυγάδας ἐφίησιν ἐς Σπάρτην.", "st": "8.51"}, {"sp": "N", "t": "ἔμελλε δ’ ἄρα ὑπεροψίας δίκη περιήξειν καὶ Φιλοποίμενα. ὡς γὰρ δὴ τῶν Ἀχαιῶν ὄγδοον ἀπεδείχθη τότε ἡγεμών, ἀνδρὶ οὐ τῶν ἀδόξων ὠνείδισεν ἁλῶναι ζῶντα ὑπὸ τῶν πολεμίων αὐτόν· καὶ—ἦν γὰρ τηνικαῦτα ἐς Μεσσηνίους Ἀχαιοῖς ἔγκλημα—Λυκόρταν σὺν τῇ στρατιᾷ ὁ Φιλοποίμην ἀποστέλλει δῃώσοντα τῶν Μεσσηνίων τὴν χώραν, αὐτὸς δὲ τρίτῃ μάλιστα ὕστερον ἡμέρᾳ, πυρετῷ τε ἐχόμενος πολλῷ καὶ πρόσω βεβιωκὼς ἑβδομήκοντα ἐτῶν, ὅμως ἠπείγετο μετασχεῖν Λυκόρτᾳ τοῦ ἔργου· ἱππέας δὲ καὶ πελταστὰς ἦγεν ὅσον ἑξήκοντα.", "st": "8.51"}, {"sp": "N", "t": "Λυκόρτας μὲν δὴ καὶ ὁ σὺν αὐτῷ στρατὸς ἀνέστρεφον ἤδη τηνικαῦτα ἐς τὴν οἰκείαν, οὔτε ἐργασάμενοι μέγα Μεσσηνίους οὐδὲν οὔτε αὐτοὶ παθόντες· Φιλοποίμενα δὲ—ἐβλήθη γὰρ ἐν τῇ μάχῃ τὴν κεφαλὴν καὶ ἀπέπεσεν ἀπὸ τοῦ ἵππου—ζῶντα ἐς Μεσσήνην ἄγουσιν αὐτόν. συνελθόντων δὲ αὐτίκα ἐς ἐκκλησίαν, διάφοροι παρὰ πολὺ καὶ οὐ πάντων κατὰ ταὐτὰ ἐγίνοντο αἱ γνῶμαι·", "st": "8.51"}, {"sp": "N", "t": "Δεινοκράτης μὲν καὶ ὅσοι τῶν Μεσσηνίων ἦσαν δυνατοὶ χρήμασι, παρεκελεύοντο ἀποκτεῖναι Φιλοποίμενα· οἱ δὲ τοῦ δήμου περιποιῆσαι τὰ μάλιστα εἶχον σπουδήν, πλέον τι ἢ παντὸς τοῦ Ἑλληνικοῦ πατέρα ὀνομάζοντες. Δεινοκράτης δὲ καὶ ἀκόντων Μεσσηνίων ἔμελλεν [τε] ἄρα Φιλοποίμενα ἀναιρήσειν ἐσπέμψας φάρμακον.", "st": "8.51"}, {"sp": "N", "t": "Λυκόρτας δὲ μετ’ οὐ πολὺ ἀθροίσας ἔκ τε Ἀρκαδίας καὶ παρ’ Ἀχαιῶν δύναμιν ἐστράτευσεν ἐπὶ Μεσσήνην· καὶ ὁ δῆμος αὐτίκα ὁ τῶν Μεσσηνίων προσεχώρησε τοῖς Ἀρκάσι, καὶ οἱ Φιλοποίμενι αἰτίαν θανάτου παρασχόντες ἁλόντες πλὴν Δεινοκράτους ὑπέσχον τιμωρίαν οἱ ἄλλοι, Δεινοκράτης δὲ ἀφίησιν αὐτοχειρίᾳ τὴν ψυχήν. κατάγουσι δὲ καὶ ἐς Μεγάλην πόλιν τοῦ Φιλοποίμενος τὰ ὀστᾶ οἱ Ἀρκάδες.", "st": "8.51"}, {"sp": "N", "t": "καὶ ἤδη τὸ μετὰ τοῦτο ἐς ἀνδρῶν ἀγαθῶν φορὰν ἔληξεν ἡ Ἑλλάς. Μιλτιάδης μὲν γὰρ ὁ Κίμωνος τούς τε ἐς Μαραθῶνα ἀποβάντας τῶν βαρβάρων κρατήσας μάχῃ καὶ τοῦ πρόσω τὸν Μήδων ἐπισχὼν στόλον ἐγένετο εὐεργέτης πρῶτος κοινῇ τῆς Ἑλλάδος, Φιλοποίμην δὲ ὁ Κραύγιδος ἔσχατος· οἱ δὲ πρότερον Μιλτιάδου λαμπρὰ ἔργα ἀποδειξάμενοι, Κόδρος τε ὁ Μελάνθου καὶ ὁ Σπαρτιάτης Πολύδωρος καὶ Ἀριστομένης ὁ Μεσσήνιος καὶ εἰ δή τις ἄλλος, πατρίδας ἕκαστοι τὰς αὑτῶν καὶ οὐκ ἀθρόαν φανοῦνται τὴν Ἑλλάδα ὠφελήσαντες.", "st": "8.52"}, {"sp": "N", "t": "Μιλτιάδου δὲ ὕστερον Λεωνίδας ὁ Ἀναξανδρίδου καὶ Θεμιστοκλῆς ὁ Νεοκλέους ἀπώσαντο ἐκ τῆς Ἑλλάδος Ξέρξην, ὁ μὲν ταῖς ναυμαχίαις ἀμφοτέραις, Λεωνίδας δὲ ἀγῶνι τῷ ἐν Θερμοπύλαις. Ἀριστείδην δὲ τὸν Λυσιμάχου καὶ Παυσανίαν τὸν Κλεομβρότου Πλαταιᾶσιν ἡγησαμένους, τὸν μὲν τὰ ὕστερον ἀφείλετο ἀδικήματα εὐεργέτην μὴ ὀνομασθῆναι τῆς Ἑλλάδος, Ἀριστείδην δὲ ὅτι ἔταξε φόρους τοῖς τὰς νήσους ἔχουσιν Ἕλλησι· πρὸ Ἀριστείδου δὲ ἦν ἅπαν τὸ Ἑλληνικὸν ἀτελὲς φόρων.", "st": "8.52"}, {"sp": "N", "t": "Ξάνθιππος δὲ ὁ Ἀρίφρονος καὶ Κίμων, ὁ μὲν ὁμοῦ Λεωτυχίδῃ τῷ βασιλεύοντι ἐν Σπάρτῃ τὸ Μήδων ναυτικὸν ἔφθειρεν ἐν Μυκάλῃ, Κίμωνι δὲ πολλὰ καὶ ἄξια ζήλου κατειργασμένα ἐστὶν ὑπὲρ τῶν Ἑλλήνων. τοὺς δὲ ἐπὶ τοῦ Πελοποννησιακοῦ πρὸς Ἀθηναίους πολέμου, καὶ μάλιστα αὐτῶν τοὺς εὐδοκιμήσαντας, φαίη τις ἂν αὐτόχειρας καὶ ὅτι ἐγγύτατα καταποντιστὰς εἶναι σφᾶς τῆς Ἑλλάδος.", "st": "8.52"}, {"sp": "N", "t": "κεκακωμένον δὲ ἤδη τὸ Ἑλληνικὸν Κόνων ὁ Τιμοθέου καὶ Ἐπαμινώνδας ἀνεκτήσατο ὁ Πολύμνιδος, ὁ μὲν ἐκ τῶν νήσων καὶ ὅσα ἐγγυτάτω θαλάσσης, Ἐπαμινώνδας δὲ ἐκ τῶν πόλεων τῶν ἀπὸ θαλάσσης ἄνω Λακεδαιμονίων τὰς φρουρὰς καὶ ἁρμοστὰς ἐκβαλόντες καὶ δεκαδαρχίας καταπαύσαντες· Ἐπαμινώνδας δὲ καὶ πόλεσιν οὐκ ἀφανέσι, Μεσσήνῃ καὶ Μεγάλῃ πόλει τῇ Ἀρκάδων, λογιμωτέραν τὴν Ἑλλάδα ἐποίησεν.", "st": "8.52"}, {"sp": "N", "t": "εἶναι δὲ ἁπάντων Ἑλλήνων καὶ Λεωσθένην τίθεμαι καὶ Ἄρατον εὐεργέτας· ὁ μέν γε τὸ Ἑλλήνων μισθοφορικὸν ⟨τὸ⟩ [καὶ] ἐν Πέρσαις περὶ πέντε που μυριάδας ἐπὶ θάλασσαν καταβάντας ναυσὶν ἐς τὴν Ἑλλάδα ἀνέσωσε καὶ ἄκοντος Ἀλεξάνδρου· τὰ δὲ ἐς Ἄρατον ἐδήλωσε δή μοι τοῦ λόγου τὰ ἐς Σικυωνίους.", "st": "8.52"}, {"sp": "N", "t": "τὸ δὲ ἐπίγραμμά ἐστιν ἐπὶ τῷ Φιλοποίμενι τὸ ἐν Τεγέᾳ·<br>τοῦδ’ ἀρετὰ καὶ δόξα καθ’ Ἑλλάδα, πολλὰ μὲν ἀλκαῖς,<br>πολλὰ δὲ καὶ βουλαῖς ἔργα πονησαμένου,<br>Ἀρκάδος αἰχμητᾶ Φιλοποίμενος, ᾧ μέγα κῦδος<br>ἕσπετ’ ἐνὶ πτολέμῳ δούρατος ἁγεμόνι.<br>μανύει δὲ τρόπαια τετυγμένα δισσὰ τυράννων<br>Σπάρτας· αὐξομέναν δ’ ἄρατο δουλοσύναν.<br>ὧν ἕνεκεν Τεγέα μεγαλόφρονα Κραύγιδος υἱόν<br>στᾶσεν, ἀμωμήτου κράντορ’ ἐλευθερίας.<br>τοῦτο μὲν δὴ ἐνταῦθά ἐστιν ἐπίγραμμα·", "st": "8.52"}, {"sp": "N", "t": "τῷ δὲ Ἀπόλλωνι οἱ Τεγεᾶται τῷ Ἀγυιεῖ τὰ ἀγάλματα ἐπ’ αἰτίᾳ φασὶν ἱδρύσασθαι τοιᾷδε. Ἀπόλλωνα καὶ Ἄρτεμιν ἐπὶ πᾶσαν λέγουσι χώραν τιμωρεῖσθαι τῶν τότε ἀνθρώπων ὅσοι Λητοῦς, ἡνίκα εἶχεν ἐν τῇ γαστρί, πλανωμένης καὶ ἀφικομένης ἐς τὴν γῆν ἐκείνην οὐδένα ἐποιήσαντο αὐτῆς λόγον.", "st": "8.53"}, {"sp": "N", "t": "ὡς δὲ ἄρα καὶ ἐς τὴν Τεγεατῶν ἐληλυθέναι τοὺς θεούς, ἐνταῦθα υἱὸν Τεγεάτου Σκέφρον προσελθόντα τῷ Ἀπόλλωνι ἐν ἀπορρήτῳ διαλέγεσθαι πρὸς αὐτόν· Λειμὼν δὲ—ἦν δὲ καὶ ὁ Λειμὼν οὗτος Τεγεάτου τῶν παίδων—ὑπονοήσας ἔγκλημα ἔχειν ἐς ἑαυτὸν τὰ ὑπὸ Σκέφρου λεγόμενα, ἀποκτίννυσιν ἐπιδραμὼν τὸν ἀδελφόν.", "st": "8.53"}, {"sp": "N", "t": "καὶ Λειμῶνα μὲν τοξευθέντα ὑπὸ Ἀρτέμιδος περιῆλθεν αὐτίκα ἡ δίκη τοῦ φόνου· Τεγεάτης δὲ καὶ Μαιρὰ τὸ μὲν παραυτίκα Ἀπόλλωνι καὶ Ἀρτέμιδι θύουσιν, ὕστερον δὲ ἐπιλαβούσης ἀκαρπίας ἰσχυρᾶς ἦλθε μάντευμα ἐκ Δελφῶν Σκέφρον θρηνεῖν. καὶ ἄλλα τε ἐν τοῦ Ἀγυιέως τῇ ἑορτῇ δρῶσιν ἐς τιμὴν τοῦ Σκέφρου καὶ ἡ τῆς Ἀρτέμιδος ἱέρεια διώκει τινὰ ἅτε αὐτὴ τὸν Λειμῶνα ἡ Ἄρτεμις.", "st": "8.53"}, {"sp": "N", "t": "λέγουσι δὲ καὶ ὅσοι Τεγεάτου τῶν παίδων ἐλείποντο, μετοικῆσαι σφᾶς ἑκουσίως ἐς Κρήτην, Κύδωνα καὶ Ἀρχήδιον καὶ Γόρτυνα· καὶ ἀπὸ τούτων φασὶν ὀνομασθῆναι τὰς πόλεις Κυδωνίαν καὶ Γόρτυνά τε καὶ Κατρέα. Κρῆτες δὲ οὐχ ὁμολογοῦντες τῷ Τεγεατῶν λόγῳ Κύδωνα μὲν Ἀκακαλλίδος θυγατρὸς Μίνω καὶ Ἑρμοῦ, Κατρέα δέ φασιν εἶναι Μίνω, τὸν δὲ Γόρτυνα Ῥαδαμάνθυος.", "st": "8.53"}, {"sp": "N", "t": "ἐς δὲ αὐτὸν Ῥαδάμανθυν Ὁμήρου μέν ἐστιν ἐν Πρωτέως πρὸς Μενέλαον λόγοις ὡς ἐς τὸ πεδίον ἥξοι Μενέλαος τὸ Ἠλύσιον, πρότερον δὲ ἔτι Ῥαδάμανθυν ἐνταῦθα ἥκειν· Κιναίθων δὲ ἐν τοῖς ἔπεσιν ἐποίησεν ⟨ὡς⟩ Ῥαδάμανθυς μὲν Ἡφαίστου, Ἥφαιστος δὲ εἴη Τάλω, Τάλων δὲ εἶναι Κρητὸς παῖδα. οἱ μὲν δὴ Ἑλλήνων λόγοι διάφοροι τὰ πλέονα καὶ οὐχ ἥκιστα ἐπὶ τοῖς γένεσίν εἰσι·", "st": "8.53"}, {"sp": "N", "t": "Τεγεάταις δὲ τοῦ Ἀγυιέως τὰ ἀγάλματα τέσσαρά εἰσιν ἀριθμόν, ὑπὸ φυλῆς ἓν ἑκάστης ἱδρυμένον. ὀνόματα δὲ αἱ φυλαὶ παρέχονται Κλαρεῶτις Ἱπποθοῖτις Ἀπολλωνιᾶτις Ἀθανεᾶτις· καλοῦνται δὲ ἀπὸ τοῦ κλήρου ὃν τοῖς παισὶν Ἀρκὰς ἐποίησεν ὑπὲρ τῆς χώρας καὶ ἀπὸ Ἱππόθου τοῦ Κερκυόνος.", "st": "8.53"}, {"sp": "N", "t": "ἔστι δὲ καὶ Δήμητρος ἐν Τεγέᾳ καὶ Κόρης ναός, ἃς ἐπονομάζουσι Καρποφόρους, πλησίον δὲ Ἀφροδίτης καλουμένης Παφίας· ἱδρύσατο αὐτὴν Λαοδίκη, γεγονυῖα μέν, ὡς καὶ πρότερον ἐδήλωσα, ἀπὸ Ἀγαπήνορος ὃς ἐς Τροίαν ἡγήσατο Ἀρκάσιν, οἰκοῦσα δὲ ἐν Πάφῳ. τούτου δέ ἐστιν οὐ πόρρω Διονύσου τε ἱερὰ δύο καὶ Κόρης βωμὸς καὶ Ἀπόλλωνος ναὸς καὶ ἄγαλμα ἐπίχρυσον·", "st": "8.53"}, {"sp": "N", "t": "Χειρίσοφος δὲ ἐποίησε, Κρὴς μὲν γένος, ἡλικίαν δὲ αὐτοῦ καὶ τὸν διδάξαντα οὐκ ἴσμεν· ἡ δὲ δίαιτα ἡ ἐν Κνωσσῷ Δαιδάλῳ παρὰ Μίνῳ συμβᾶσα ἐπὶ μακρότερον δόξαν τοῖς Κρησὶ καὶ ἐπὶ ξοάνων ποιήσει παρεσκεύασε. παρὰ δὲ τῷ Ἀπόλλωνι ὁ Χειρίσοφος ἕστηκε λίθου πεποιημένος.", "st": "8.53"}, {"sp": "N", "t": "καλοῦσι δὲ οἱ Τεγεᾶται καὶ ἑστίαν Ἀρκάδων κοινήν· ἐνταῦθά ἐστιν ἄγαλμα Ἡρακλέους, πεποίηται δέ οἱ ἐπὶ τοῦ μηροῦ τραῦμα ἀπὸ τῆς μάχης ἣν πρώτην Ἱπποκόωντος τοῖς παισὶν ἐμαχέσατο. τὸ δὲ χωρίον τὸ ὑψηλόν, ἐφ’ οὗ καὶ οἱ βωμοὶ Τεγεάταις εἰσὶν οἱ πολλοί, καλεῖται μὲν Διὸς Κλαρίου, δῆλα δὲ ὡς ἐγένετο ἡ ἐπίκλησις τῷ θεῷ τοῦ κλήρου τῶν παίδων ἕνεκα τῶν Ἀρκάδος.", "st": "8.53"}, {"sp": "N", "t": "ἄγουσι δὲ ἑορτὴν αὐτόθι Τεγεᾶται κατὰ ἔτος· καί σφισιν ἐπιστρατεῦσαι Λακεδαιμονίους ποτὲ ὑπὸ τὸν καιρὸν τῆς ἑορτῆς λέγουσι, καὶ—νείφειν γὰρ τὸν θεόν—τοὺς μὲν ῥιγοῦν καὶ ὄντας ἐν τοῖς ὅπλοις κάμνειν, αὐτοὶ δὲ ἐκείνων κρύφα πῦρ καῦσαι, καὶ ὡς οὐκ ἠνωχλοῦντο ὑπὸ τοῦ κρυμοῦ, τὰ ὅπλα ἐνδύντες ἐξελθεῖν τε ἐπὶ τοὺς Λακεδαιμονίους καὶ σχεῖν ἐν τῷ ἔργῳ τὸ πλέον φασίν. ἐθεασάμην δὲ καὶ ἄλλα ἐν Τεγέᾳ τοσάδε, Ἀλέου οἰκίαν καὶ Ἐχέμου μνῆμα καὶ ἐπειργασμένην ἐς στήλην τὴν Ἐχέμου πρὸς Ὕλλον μάχην.", "st": "8.53"}, {"sp": "N", "t": "ἐκ Τεγέας δὲ ἰόντι ἐς τὴν Λακωνικὴν ἔστι μὲν βωμὸς ἐν ἀριστερᾷ τῆς ὁδοῦ Πανός, ἔστι δὲ καὶ Λυκαίου Διός· λείπεται δὲ καὶ θεμέλια ἱερῶν. οὗτοι μὲν δή εἰσιν οἱ βωμοὶ σταδίοις δύο ἀπωτέρω τοῦ τείχους, προελθόντι δὲ ἀπ’ αὐτῶν μάλιστά που σταδίους ἑπτὰ ἱερὸν Ἀρτέμιδος ἐπίκλησιν Λιμνάτιδος καὶ ἄγαλμά ἐστιν ἐβένου ξύλου· τρόπος δὲ τῆς ἐργασίας ὁ Αἰγιναῖος καλούμενος ὑπὸ Ἑλλήνων. τούτου δὲ ὅσον δέκα ἀπωτέρω σταδίοις Ἀρτέμιδος Κνακεάτιδός ἐστι ναοῦ τὰ ἐρείπια.", "st": "8.53"}, {"sp": "N", "t": "Λακεδαιμονίοις δὲ καὶ Τεγεάταις ὅροι τῆς γῆς ὁ ποταμός ἐστιν ὁ Ἀλφειός. τούτου τὸ ὕδωρ ἄρχεται μὲν ἐν Φυλάκῃ, κάτεισι δὲ οὐ πόρρω τῆς πηγῆς καὶ ἄλλο ὕδωρ ἐς αὐτὸν ἀπὸ πηγῶν μεγέθει μὲν οὐ μεγάλων, πλεόνων δὲ ἀριθμόν· καὶ διὰ τοῦτο τῷ χωρίῳ Σύμβολα γέγονεν ὄνομα.", "st": "8.54"}, {"sp": "N", "t": "φαίνεται δὲ ὁ Ἀλφειὸς παρὰ τοὺς ἄλλους ποταμοὺς φύσιν τινὰ ἰδίαν παρεχόμενος τοιάνδε· ἀφανίζεσθαί τε γὰρ κατὰ γῆς ἐθέλει πολλάκις καὶ αὖθις ἀναφαίνεσθαι. προελθὼν μέν γε ἐκ Φυλάκης καὶ τῶν καλουμένων Συμβόλων ἐς τὸ πεδίον κατέδυ τὸ Τεγεατικόν· ἀνατείλας δὲ ἐν Ἀσέᾳ καὶ τὸ ῥεῦμα ἀναμίξας τῷ Εὐρώτᾳ τὸ δεύτερον ἤδη κάτεισιν ἐς τὴν γῆν·", "st": "8.54"}, {"sp": "N", "t": "ἀνασχὼν δὲ ἔνθα Πηγὰς ὀνομάζουσιν οἱ Ἀρκάδες καὶ παρὰ γῆν τε τὴν Πισαίαν καὶ παρὰ Ὀλυμπίαν ἐξελθών, ἐκδίδωσιν ὑπὲρ Κυλλήνης ἐπινείου τοῦ Ἠλείων ἐς τὴν θάλασσαν. ἔμελλε δὲ ἄρα μηδὲ Ἀδρίας ἐπισχήσειν αὐτὸν τοῦ πρόσω· διανηξάμενος δὲ καὶ τοῦτον, μέγα οὕτω καὶ βίαιον πέλαγος, ἐν Ὀρτυγίᾳ τῇ πρὸ Συρακουσῶν ἐπιδείκνυσιν Ἀλφειός τε ὢν καὶ πρὸς Ἀρέθουσαν τὸ ὕδωρ ἀνακοινούμενος.", "st": "8.54"}, {"sp": "N", "t": "ἡ δὲ εὐθεῖα ⟨ἡ⟩ ἐπὶ Θυρέαν τε καὶ κώμας τὰς ἐν τῇ Θυρεάτιδι ἐκ Τεγέας παρείχετο ἐς συγγραφὴν Ὀρέστου τοῦ Ἀγαμέμνονος μνῆμα, καὶ ὑφελέσθαι Σπαρτιάτην τὰ ὀστᾶ αὐτόθεν οἱ Τεγεᾶται λέγουσι· καθ’ ἡμᾶς δὲ οὐκέτι πυλῶν ἐντὸς ἐγίνετο ὁ τάφος. ῥεῖ δὲ καὶ Γαράτης ποταμὸς κατὰ τὴν ὁδόν· διαβάντι δὲ τὸν Γαράτην καὶ προελθόντι σταδίους δέκα Πανός ἐστιν ἱερὸν καὶ πρὸς αὐτῷ δρῦς, ἱερὰ καὶ αὕτη τοῦ Πανός.", "st": "8.54"}, {"sp": "N", "t": "ἡ δὲ ἐς Ἄργος ἐκ Τεγέας ὀχήματι ἐπιτηδειοτάτη καὶ τὰ μάλιστά ἐστι λεωφόρος. ἔστι δὲ ἐπὶ τῆς ὁδοῦ πρῶτα μὲν ναὸς καὶ ἄγαλμα Ἀσκληπιοῦ· μετὰ δὲ ἐκτραπεῖσιν ἐς ἀριστερὰ ὅσον στάδιον Ἀπόλλωνος ἐπίκλησιν Πυθίου καταλελυμένον ἐστὶν ἱερὸν καὶ ἐρείπια ἐς ἅπαν. κατὰ δὲ τὴν εὐθεῖαν αἵ τε δρῦς εἰσι πολλαὶ καὶ Δήμητρος ἐν τῷ ἄλσει τῶν δρυῶν ναὸς ἐν Κορυθεῦσι καλουμένης· πλησίον δὲ ἄλλο ἐστὶν ἱερὸν Διονύσου Μύστου.", "st": "8.54"}, {"sp": "N", "t": "τὸ ἀπὸ τούτου δὲ ἄρχεται τὸ ὄρος τὸ Παρθένιον· ἐν δὲ αὐτῷ τέμενος δείκνυται Τηλέφου, καὶ ἐνταῦθα παῖδα ἐκκείμενόν φασιν αὐτὸν ὑπὸ ἐλάφου τραφῆναι. ἀπωτέρω δὲ ὀλίγον Πανός ἐστιν ἱερόν, ἔνθα Φιλιππίδῃ φανῆναι τὸν Πᾶνα καὶ εἰπεῖν ἃ πρὸς αὐτὸν Ἀθηναῖοί τε καὶ κατὰ ταὐτὰ Τεγεᾶται λέγουσι·", "st": "8.54"}, {"sp": "N", "t": "παρέχεται δὲ τὸ Παρθένιον καὶ ἐς λύρας ποίησιν χελώνας ἐπιτηδειοτάτας, ἃς οἱ περὶ τὸ ὄρος ἄνθρωποι καὶ αὐτοὶ λαμβάνειν δεδοίκασιν ἀεὶ καὶ ξένους οὐ περιορῶσιν αἱροῦντας· ἱερὰς γὰρ σφᾶς εἶναι τοῦ Πανὸς ἥγηνται. ὑπερβαλόντι δὲ τὴν κορυφὴν τοῦ ὄρους ἔστιν ἐν τοῖς ἤδη γεωργουμένοις Τεγεατῶν ὅρος καὶ Ἀργείων κατὰ Ὑσιὰς τὰς ἐν τῇ Ἀργολίδι. αἵδε μὲν Πελοποννήσου μοῖραι καὶ πόλεις τε ἐν ταῖς μοίραις καὶ ἐν ἑκάστῃ πόλει τὰ ἀξιολογώτατά ἐστιν ἐς μνήμην.", "st": "8.54"}], []);})();
